async function loadStuPanel(sid){
  const s=DB.stus().find(x=>x.id===sid);if(!s)return;
  if(!(_cache.vocab_cards||[]).some(c=>c.sid===sid)){
    await loadVocabCards(sid);
  }
  await syncClassTbsToStudent(sid).catch(()=>{});
  const les=DB.less().filter(l=>l.sid===sid);
  const tsts=DB.tsts().filter(t=>t.sid===sid);
  const rds=DB.rds().filter(r=>r.sid===sid);
  const bks=rds.length;
  const avg=ppAvgPct(tsts,'vocab');                  // 미응시 제외, 없으면 null
  const absCount=les.filter(l=>l.att==='absent').length;
  const lateCount=les.filter(l=>l.att==='late').length;
  const makeupCount=les.filter(l=>l.att==='makeup').length;
  const payments=s.payments||[];
  const lastPay=payments.length?payments[payments.length-1]:null;

  document.getElementById('sp-name').textContent=s.name+(s.inactive?' (퇴원)':'');
  {const av=document.getElementById('sp-avatar');if(av)av.textContent=(s.name||'').trim().slice(0,1)||'학';}
  // 일정은 소속 클래스에서 파생 (학생 개별 요일·시간 입력 제거됨)
  const myClasses=DB.classes().filter(c=>c.active!==false&&(c.studentIds||[]).includes(sid));
  const schedStr=myClasses.map(c=>`${c.name} ${classSchedStr(c)}`).join(' | ');
  const parentStr=s.parentName||s.parentPhone?(s.parentName||'')+(s.parentPhone?(s.parentName?' ':'')+s.parentPhone:''):'';
  document.getElementById('sp-meta').textContent=(s.grade||s.lv||'')+(s.school?' · '+s.school:'')+(s.enrollDate?' · 입회 '+s.enrollDate:'')+(schedStr?' · '+schedStr:'')+(parentStr?' · 📱'+parentStr:'');

  // 이번 달 수업 수
  const today2=new Date();
  const thisMonth=today2.getFullYear()+'-'+String(today2.getMonth()+1).padStart(2,'0');
  const thisMonthLesCount=les.filter(l=>l.date&&l.date.startsWith(thisMonth)&&l.att!=='absent').length;
  const lastLesDate=les.length?les[0].date:'';

  // ── 요약 (기간별) ──
  renderSpSummary(sid,'month');

  // ── 수업 (날짜 정렬·월 필터 지원 — renderSpLessons) ──
  if(_spLesSid!==sid){_spLesSort='desc';_spLesMonth='';_spLesSid=sid;}
  renderSpLessons(sid);

  // ── 테스트 (최근 5개) ──
  const tstListHtml=!tsts.length
    ?`<div class="empty boxed"><div class="empty-i">${luIcon('pencil',15)||''}</div><div class="empty-t">아직 테스트 기록이 없습니다</div><div class="empty-s">회차별 점수를 입력하면 단어·어법 추이 그래프가 표시됩니다</div><button class="btn bt bsm" onclick="closeStuPanel();swTab('t-tst');setTimeout(()=>{const el=document.getElementById('ts-stu');if(el){el.value='${sid}';el.dispatchEvent(new Event('change'));}},200)">+ 테스트 입력하기</button></div>`
    :tsts.slice(0,5).map(t=>{
      const _ar=(typeof ppAreasOf==='function')?ppAreasOf(t):[['vocab','단어'],['grammar','어법']];
      return `<div style="padding:10px 0;border-bottom:1px solid var(--border)">
        <div style="font-size:12px;color:var(--slate);font-family:var(--fm);margin-bottom:6px">${t.date||''}${
          t.absent?' · <span style="font-weight:700">미응시</span>':''}${
          t.extApp&&t.extScore?` · <span class="tst-ext inline">${escAttr(t.extApp)} ${escAttr(t.extScore)}</span>`:''}</div>
        <div style="display:flex;gap:16px">
          ${_ar.map(([f,l])=>{const p=pct(t[f+'Correct'],t[f+'Total']);
            return `<div><div class="ring ${rcls(p)}">${t[f+'Correct']||0}/${t[f+'Total']}</div><div style="font-size:11.5px;color:var(--slate);text-align:center;margin-top:2px">${l} ${p}%</div></div>`;}).join('')}
          ${t.wrongWords&&t.wrongWords.length?`<div style="flex:1"><div style="font-size:11.5px;color:var(--slate);margin-bottom:3px">틀린 단어</div><div class="wl">${t.wrongWords.slice(0,4).map(w=>`<span class="wc" style="font-size:11.5px;padding:2px 8px">${w}</span>`).join('')}</div></div>`:''}
        </div>
      </div>`;
    }).join('');
  // ── NELT 결과 ──
  const neltList=(s.neltResults||[]).slice().reverse();
  const neltHtml=`<div class="sp-card" style="margin-top:20px">
    <div class="sp-card-head">
      <span class="sp-card-title">${luIcon('trophy',15)||''} NELT 결과</span>
      <button class="btn bo bsm" onclick="openNeltModal('${sid}')">+ 결과 입력</button>
    </div>
    ${neltList.length?neltList.map(n=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)">
      <span style="font-size:11.5px;color:var(--slate);font-family:var(--fm);white-space:nowrap">${n.date||''}</span>
      <span class="badge bteal" style="font-size:11.5px;flex-shrink:0">${n.term||''}</span>
      <span style="font-size:16px;font-weight:700;color:var(--navy);font-family:var(--fd)">${n.score!=null?n.score:''}</span>
      ${n.level?`<span style="font-size:12px;color:var(--teal);font-weight:600">${n.level}</span>`:''}
      ${n.memo?`<span style="font-size:12px;color:var(--slate);flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${n.memo}</span>`:''}
      <button onclick="delNeltResult('${sid}','${n.id}')" style="margin-left:auto;background:none;border:1px solid var(--border);border-radius:4px;padding:1px 7px;cursor:pointer;font-size:12px;color:var(--slate);flex-shrink:0">삭제</button>
    </div>`).join(''):`<div class="empty boxed sm"><div class="empty-i" style="font-size:24px">🏆</div><div class="empty-t">NELT 결과가 없습니다</div></div>`}
  </div>`;
  document.getElementById('sp-tests').innerHTML=`<div class="sp-tests-wrap">${tstListHtml}${neltHtml}</div>`;

  // ── 결제 ──
  const payToday=new Date();
  const thisMonth2=payToday.getFullYear()+'-'+String(payToday.getMonth()+1).padStart(2,'0');
  const thisMonthPay=payments.filter(p=>p.date&&p.date.startsWith(thisMonth2));
  const paidAmt=thisMonthPay.reduce((a,p)=>a+Number(p.amt||0),0);
  const feeAmt=Number(s.fee||0);
  let payChip='';
  if(feeAmt){
    if(paidAmt>=feeAmt) payChip=`<span class="pay-status-chip paid">✓ ${thisMonth2.slice(5)}월 완납 ${paidAmt.toLocaleString()}원</span>`;
    else if(paidAmt>0) payChip=`<span class="pay-status-chip partial">△ 부분납 ${paidAmt.toLocaleString()}/${feeAmt.toLocaleString()}원</span>`;
    else payChip=`<span class="pay-status-chip unpaid">✕ ${thisMonth2.slice(5)}월 미납</span>`;
  }
  document.getElementById('sp-payment').innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:${payChip?'8px':'12px'}">
      <span style="font-size:14px;font-weight:700">결제 기록</span>
      <button class="btn bo bsm" onclick="openQuickPayFor('${sid}')">+ 추가</button>
    </div>
    ${payChip?`<div style="margin-bottom:12px">${payChip}</div>`:''}
    ${!payments.length?'<div style="color:var(--slate);font-size:13px">결제 기록 없음</div>'
    :`<table style="width:100%;border-collapse:collapse;font-size:13px">
        <thead><tr style="border-bottom:1px solid var(--border)">
          <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px;font-weight:700">날짜</th>
          <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px;font-weight:700">금액</th>
          <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px;font-weight:700">방식</th>
          <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px;font-weight:700">영수증</th>
          <th></th>
        </tr></thead>
        <tbody>${[...payments].reverse().map((p,ri)=>{
          const origIdx=payments.length-1-ri;
          return `<tr style="border-bottom:1px solid var(--border)">
            <td style="padding:5px 6px;font-family:var(--fm)">${p.date||''}</td>
            <td style="padding:5px 6px;font-weight:700">${Number(p.amt||0).toLocaleString()}원</td>
            <td style="padding:5px 6px"><span class="badge bnavy">${PAY_METHOD_LBL[p.method]||'—'}</span></td>
            <td style="padding:5px 6px"><span class="badge ${p.receipt==='issued'?'bteal':p.receipt==='requested'?'bamber':'bslate'}">${PAY_RECEIPT_LBL[p.receipt]||'—'}</span></td>
            <td style="padding:5px 6px"><button class="btn bd bxxs" onclick="reqRemovePay('${sid}',${origIdx},true)">삭제</button></td>
          </tr>`;
        }).join('')}</tbody>
      </table>`}`;

  // ── 과제 탭 (선생님: 숙제 할당 + 제출 확인) ──
  const sHws=ppLive(_cache.homeworks).filter(h=>h.sid===sid).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  setTimeout(()=>{try{irWeakCard(sid,'stu-weak-card');irPaintAsgnScores();}catch(e){}},0);   // 약점 카드 · 과제 옆 점수
  const sAssigns=ppLive(_cache.assignments).filter(a=>a.sid===sid).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const unread=sHws.filter(h=>!h.checked).length;
  const tomorrowStr=(()=>{ // 마감 기본값: 다음 실제 수업일(휴강 제외), 클래스 없으면 내일
    const c0=DB.classes().find(c=>c.active!==false&&(c.studentIds||[]).includes(sid));
    const n=c0?_nextClassDay(ppToday(),c0.days||[],new Set(c0.skipDates||[]),new Set(c0.extraDates||[])):'';
    if(n)return n;
    const d=new Date();d.setDate(d.getDate()+1);return ppYmd(d);
  })();
  const _hwchBox=(()=>{
    const stu=DB.stus().find(x=>x.id===sid);
    const p=(typeof hwChallengeProgress==='function')?hwChallengeProgress(stu):null;
    if(p){
      const st=`${p.roundNo}번째 판 <b style="color:var(--warnt)">${p.count}/${p.goal}</b>${p.carry?` <span style="font-size:11.5px;color:var(--slate)">(이월 ${p.carry} 포함)</span>`:''} · 오늘 ${p.todayStamp?'✅':'아직'}${p.pendingGifts>0?` · <b style="color:var(--warnt)">🎁 전달할 선물 ${p.pendingGifts}개</b>`:''}${p.rounds?` · 완성 ${p.rounds}판`:''}`;
      return `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:#FFFBEB;border:1.5px solid var(--warn);border-radius:var(--rs);padding:8px 12px;margin-bottom:12px;font-size:13px">
        <span>🎁 <b>도장 챌린지</b> (${p.goal}일 · ${escAttr(p.reward)} · 시작 ${p.start})</span><span>${st}</span>
        <span style="margin-left:auto;display:flex;gap:4px">
          ${p.pendingGifts>0?`<button class="btn bt bsm" style="font-size:11.5px;padding:2px 8px" onclick="dashChallengeComplete('${sid}')">🎁 선물 전달</button>`:''}
          <button class="btn bo bsm" style="font-size:11.5px;padding:2px 8px" title="목표·선물·시작일을 새로 설정 (도장 0부터)" onclick="document.getElementById('hwch-setup-${sid}').style.cssText='display:flex;width:100%;margin-top:6px;gap:6px;align-items:center;flex-wrap:wrap';this.style.display='none'">재설정</button>
          <button class="btn bo bsm" style="font-size:11.5px;padding:2px 8px" onclick="spChallengeStop('${sid}')">중지</button>
        </span>
        <span id="hwch-setup-${sid}" style="display:none">
          목표 <input type="number" id="hwch-goal-${sid}" value="${p.goal}" style="width:52px">일 ·
          선물 <input type="text" id="hwch-reward-${sid}" value="${escAttr(p.reward)}" style="width:110px"> ·
          시작 <input type="date" id="hwch-start-${sid}" value="${ppToday()}"> ·
          이월 <input type="number" id="hwch-carry-${sid}" value="0" title="시작 전 이미 모은 도장 수" style="width:44px">개
          <button class="btn bt bsm" style="font-size:11.5px;padding:2px 8px" onclick="spChallengeStart('${sid}')">시작</button>
        </span>
      </div>`;
    }
    return `<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;background:var(--cream2);border:1px dashed var(--border);border-radius:var(--rs);padding:8px 12px;margin-bottom:12px;font-size:13px">
      🎁 <b>숙제 도장 챌린지</b> — 목표 <input type="number" id="hwch-goal-${sid}" value="20" style="width:52px">일 ·
      선물 <input type="text" id="hwch-reward-${sid}" value="작은 선물" style="width:110px"> ·
      시작 <input type="date" id="hwch-start-${sid}" value="${ppToday()}"> ·
      이월 <input type="number" id="hwch-carry-${sid}" value="0" title="시작 전 이미 모은 도장 수 (종이로 세던 몫) — 판을 만들기 전 날짜는 자동으로 세지 않습니다" style="width:44px">개
      <button class="btn bt bsm" style="font-size:11.5px;padding:2px 8px" onclick="spChallengeStart('${sid}')">시작</button>
      <span style="width:100%;font-size:12px;color:var(--slate)">숙제를 전부 체크한 날마다 도장 1개 (누적 — 하루 빠져도 리셋 없음). 목표 달성 시 대시보드·학생 앱에 알림</span>
    </div>`;
  })();
  document.getElementById('sp-hw').innerHTML=`
  ${_hwchBox}
  <div style="margin-bottom:12px">
    <div style="font-size:13px;font-weight:700;color:var(--navy);margin-bottom:8px">${luIcon('clipboard-list',15)||''} 숙제 할당</div>
    <div class="fg" style="margin-bottom:8px">
      <div class="f" style="margin-bottom:0"><label>날짜</label><input type="date" id="asgn-date-${sid}" value="${ppToday()}"></div>
      <div class="f" style="margin-bottom:0"><label>마감일</label><input type="date" id="asgn-due-${sid}" value="${tomorrowStr}"></div>
      <div class="f s2" style="margin-bottom:0"><label>구분</label>
        <select id="asgn-cat-${sid}" onchange="spHwCatChange('${sid}')">
          <option value="">— 구분 없음 (자유 입력) —</option>
          <option value="phonics">파닉스</option><option value="vocab">어휘</option><option value="grammar">어법</option>
          <option value="reading">리딩</option><option value="listening">리스닝</option><option value="writing">라이팅</option>
          <option value="naesin">내신</option><option value="book">원서</option>
          <option value="class5">클래스5</option><option value="other">기타</option>
          <option value="__custom__">✏️ 직접 입력</option>
        </select>
        <input type="text" id="asgn-cat-custom-${sid}" placeholder="구분 직접 입력 (예: 스피킹, 발표 준비)" style="display:none;margin-top:6px">
      </div>
      <div class="f s2" style="margin-bottom:0"><label>교재/원서</label><input type="text" id="asgn-book-${sid}" list="dl-asgn-${sid}" placeholder="교재 또는 원서 (자동완성)" autocomplete="off" onchange="spAsgnBookChange(this,'${sid}')"><datalist id="dl-asgn-${sid}"></datalist></div>
      <div class="f s2" style="margin-bottom:0"><label>범위/내용</label><input type="text" id="asgn-range-${sid}" list="dl-asgn-r-${sid}" autocomplete="off" placeholder="예: Unit 3 p.24-28 / Ch.1~3"><datalist id="dl-asgn-r-${sid}"></datalist></div>
    </div>
    <div id="asgn-extra-${sid}"></div>
    <button class="btn bt bsm" style="width:100%" onclick="saveStudentAssign('${sid}')">할당</button>
  </div>
  <div id="stu-weak-card"></div>
  <div class="div-line"></div>
  ${sAssigns.length?`<div style="margin-bottom:8px">
    <div style="font-size:13px;font-weight:700;color:var(--navy);margin-bottom:6px">할당된 숙제 (${sAssigns.length}건)</div>
    ${sAssigns.map(a=>{
      const hw=sHws.find(h=>h.assignmentId===a.id);
      const submitted=!!hw;
      const today2=ppToday();
      // 끝났나·밀렸나는 공용 hwState — 일정형은 completedAt 이 안 찍혀 영원히 '미완'으로 보였다
      const _st=hwState(a,today2);
      const completed=_st.finished;
      const _stamp=!!a.completedAt;          // '완료 취소'는 도장이 찍힌 것만
      const overdue=_st.overdueRows14>0;
      return `<div id="asgn-row-${a.id}" style="padding:8px 0;border-bottom:1px solid var(--border)${completed?';opacity:.72':''}">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px">
          <div style="flex:1">
            <div style="font-size:12px;color:${overdue?'var(--red)':'var(--slate)'};font-family:var(--fm)">${(typeof ppTrackChipHtml==='function')?ppTrackChipHtml(a.track):''}${a.date||''}${a.due?' · 마감 '+a.due:''}${_stamp?' · 완료 '+(a.completedAt||'').slice(0,10):''}${completed&&!_stamp?' · 일정 '+_st.doneCount+'/'+_st.total+' 완료':''}${a.paperId?`<span data-asg-paper="${escAttr(a.paperId)}" data-asg-sid="${escAttr(sid)}"></span>`:''}</div>
            <div style="font-size:13px;font-weight:700;margin-top:2px">${
              a.type==='reading'?`${_catPill('원서')}${[a.bookTitle,a.range].filter(Boolean).join(' · ')||'원서 읽기'}`:
              a.type==='vocab'?`${_catPill('어휘')}${(a.words||[]).length?'단어: '+(a.words||[]).join(', '):(a.range||a.bookTitle||'단어 학습')}`:
              (a.category==='class5'||a.category==='recur')?(()=>{
                const pill=a.category==='recur'?'🔁 반복':'클래스5';
                const sc=a.schedule||[];
                if(!sc.length)return`${_catPill(pill)}${[a.bookTitle&&a.bookTitle!=='클래스5'?a.bookTitle:'',a.range].filter(Boolean).join(' · ')||'학습'}`;
                const today=ppToday();
                const upcoming=sc.filter(s=>(s.date||'')>=today);
                const show=(upcoming.length?upcoming:sc).slice(0,5);
                return`${_catPill(pill)}${a.category==='recur'?`<span style="font-weight:600">${a.bookTitle||''}</span> <span style="font-size:11.5px;font-weight:normal;color:var(--slate)">(${sc.length}일)</span>`:''}<div style="margin-top:3px">${show.map(s=>`<div style="font-size:12px;font-weight:normal;color:var(--slate);line-height:1.7;padding-left:2px">${s.date||''} ${[s.book!==a.bookTitle?s.book:'',s.unit].filter(Boolean).join(' · ')}</div>`).join('')}${sc.length>show.length?`<div style="font-size:11.5px;font-weight:normal;color:var(--slate);padding-left:2px">외 ${sc.length-show.length}일...</div>`:''}</div>`;
              })():
              (()=>{ // 구분(직접 입력 포함)을 필로 표시하고, 빈 교재명일 때 고아 '·'가 남지 않게 join
                const KC={phonics:'파닉스',vocab:'어휘',grammar:'어법',reading:'리딩',listening:'리스닝',writing:'라이팅',naesin:'내신',book:'원서',other:'기타'};
                const cat=a.category?(KC[a.category]||a.category):'';
                const main=[a.bookTitle||a.text,a.range].filter(Boolean).join(' · ')||'과제';
                return `${_catPill(cat)}${main}`;
              })()
            }</div>
          </div>
          <div style="display:flex;align-items:center;gap:4px;flex-shrink:0">
            ${completed?(_stamp
              ?`<span class="hw-status-badge" style="background:#dcfce7;color:#166534;cursor:pointer" title="클릭: 완료 취소" onclick="teacherUncompleteAssign('${a.id}','${sid}')">✓ 완료</span>`
              :`<span class="hw-status-badge" style="background:#dcfce7;color:#166534" title="일정 ${_st.total}일을 모두 끝냈어요">✓ 완료</span>`):''}
            ${a.requireRecording&&submitted?`<span class="hw-status-badge checked">제출완료</span>`:''}
            <button class="btn bo bsm" style="font-size:11.5px;padding:2px 6px" onclick="toggleAssignEdit('${a.id}','${sid}')">수정</button>
            <button class="btn bd bsm" style="font-size:11.5px;padding:2px 6px" onclick="deleteStudentAssign('${a.id}','${sid}')">삭제</button>
          </div>
        </div>
        ${submitted&&hw.audioUrl?`<audio controls src="${hw.audioUrl}" style="width:100%;height:26px;margin-top:6px"></audio>`:''}
        ${submitted&&hw.aiScore?`<div style="font-size:12px;color:var(--tealt);background:var(--tl);border-radius:6px;padding:6px 10px;margin-top:4px">🤖 AI 평가: ${hw.aiScore}</div>`:''}
        ${submitted?(!hw.checked?`<button class="btn ba bsm" style="font-size:11.5px;margin-top:4px" onclick="markHwChecked('${hw.id}','${sid}')">확인 완료</button>`:`<span class="hw-status-badge checked" style="cursor:pointer;margin-top:4px;display:inline-block" title="클릭: 미확인으로 되돌리기" onclick="unmarkHwChecked('${hw.id}','${sid}')">✓ 확인됨</span>`):''}
      </div>`;
    }).join('')}
  </div>`:''}
  ${sHws.filter(h=>!h.assignmentId).length?`<div>
    <div style="font-size:13px;font-weight:700;color:var(--navy);margin-bottom:6px">기타 제출 (${sHws.filter(h=>!h.assignmentId).length}건)</div>
    ${sHws.filter(h=>!h.assignmentId).map(h=>`
    <div style="padding:8px 0;border-bottom:1px solid var(--border)">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
        <span style="font-size:12px;font-family:var(--fm);color:var(--slate)">${h.date||''}</span>
        <div style="display:flex;gap:4px;align-items:center">
          <span class="hw-status-badge ${h.checked?'checked':'pending'}"${h.checked?` style="cursor:pointer" title="클릭: 미확인으로 되돌리기" onclick="unmarkHwChecked('${h.id}','${sid}')"`:''}>${h.checked?'✓ 확인됨':'미확인'}</span>
          ${!h.checked?`<button class="btn ba bsm" style="font-size:11.5px;padding:2px 6px" onclick="markHwChecked('${h.id}','${sid}')">확인</button>`:''}
        </div>
      </div>
      ${h.audioUrl?`<audio controls src="${h.audioUrl}" style="width:100%;height:26px"></audio>`:''}
      ${h.memo?`<div style="font-size:12px;color:var(--slate);margin-top:3px">💬 ${h.memo}</div>`:''}
    </div>`).join('')}
  </div>`:''}
  ${!sAssigns.length&&!sHws.length?`<div class="empty boxed"><div class="empty-i">📤</div><div class="empty-t">할당된 과제가 없습니다</div><div class="empty-s">과제를 할당하면 제출·확인 현황이 여기에 표시됩니다</div><button class="btn bt bsm" onclick="openAssignModal('${sid}')">+ 과제 할당하기</button></div>`:''}
  `;

  {const bf=document.getElementById('sp-brief');
   if(bf)bf.innerHTML=(typeof ppStudentBriefHtml==='function')?ppStudentBriefHtml(s):'';}
  swSpTab(_spTab||'sp-summary');
}

function openQuickPayFor(sid){
  closeM('m-edit-stu');
  document.getElementById('qp-stu').value=sid;
  openM('m-quick-pay');
}
async function saveQuickPay(){
  if(_saving['saveQuickPay'])return; _saving['saveQuickPay']=true;
  try{
  const sid=document.getElementById('qp-stu').value;
  const date=document.getElementById('qp-date').value;
  const amt=document.getElementById('qp-amt').value;
  if(!sid){toast('학생을 선택해 주세요');return;}
  if(!date||!amt){toast('날짜와 금액을 입력해 주세요');return;}
  const idx=_cache.students.findIndex(s=>s.id===sid);if(idx<0)return;
  if(!_cache.students[idx].payments)_cache.students[idx].payments=[];
  _cache.students[idx].payments.push({date,amt:parseInt(amt),method:document.getElementById('qp-method').value,receipt:document.getElementById('qp-receipt').value,memo:document.getElementById('qp-memo').value.trim()});
  await supaUpsert('students',sid,_cache.students[idx],null);
  closeM('m-quick-pay');
  document.getElementById('qp-amt').value='';document.getElementById('qp-memo').value='';
  toast('결제 기록이 추가되었습니다');
  renderStus();
  if(currentSpStuId===sid)loadStuPanel(sid);
  }catch(e){
    console.error('saveQuickPay:',e);
    toast('저장 중 오류가 발생했습니다. 다시 시도해 주세요.');
  }finally{
    showLoading(false);
    _saving['saveQuickPay']=false;
  }
}

// ── LAST LESSON HINT ──
let _lastLessonRef=null;
function checkLesDuplicate(){
  const sid=document.getElementById('ls-stu')?.value;
  const date=document.getElementById('ls-date')?.value;
  const w=document.getElementById('les-dup-warn');if(!w)return;
  if(!sid||!date){w.style.display='none';return;}
  const existing=DB.less().filter(l=>l.sid===sid&&l.date===date);
  if(!existing.length){w.style.display='none';return;}
  const hasClass=existing.some(l=>l.classId);
  w.innerHTML=`⚠️ ${date}에 ${hasClass?'클래스 수업 포함 ':''}<strong>${existing.length}건</strong> 수업 기록이 이미 있습니다. 계속 입력하면 추가 기록이 됩니다.&nbsp;<button class="btn bo bsm" style="font-size:11.5px;padding:1px 8px" onclick="openEditLes('${existing[0].id}')">기존 기록 수정 →</button>`;
  w.style.display='block';
}
function fillLastLesson(sid){
  const hint=document.getElementById('ls-last-hint');if(!hint)return;
  if(!sid){hint.style.display='none';_lastLessonRef=null;checkLesDuplicate();return;}
  checkLesDuplicate();
  const les=DB.less().filter(l=>l.sid===sid);
  if(!les.length){hint.style.display='none';_lastLessonRef=null;return;}
  const last=les[0];
  _lastLessonRef=last;
  const mats=matsToHtml(last.materials);
  hint.style.display='flex';
  const txtEl=document.getElementById('ls-last-hint-text');
  if(txtEl)txtEl.innerHTML=`${luIcon('book',15)||''} 직전 수업 (${last.date||''}): ${mats||'진도 없음'}${last.cmt?` · ${last.cmt}`:''}`;
}

// ── STUDENTS ──
function renderStus(){
  let stus=DB.stus();
  const g=document.getElementById('stu-grid');
  const q=(document.getElementById('stu-search')?.value||'').trim().toLowerCase();
  const filterGrade=document.getElementById('stu-filter-grade')?.value||'';
  const filterSchool=document.getElementById('stu-filter-school')?.value||'';
  const filterStatus=document.getElementById('stu-filter-status')?.value||'active';

  // 상태 필터
  if(filterStatus==='active') stus=stus.filter(s=>!s.inactive);
  else if(filterStatus==='inactive') stus=stus.filter(s=>s.inactive);

  // 학교 필터 드롭다운 + 학생 추가/수정용 학교 datalist 채우기 (DB 재사용)
  const allSchools=[...new Set(DB.stus().filter(s=>s.school).map(s=>s.school))].sort();
  const schoolSel=document.getElementById('stu-filter-school');
  if(schoolSel){
    const curSchool=schoolSel.value;
    schoolSel.innerHTML='<option value="">전체 학교</option>'+allSchools.map(sc=>`<option value="${sc}"${sc===curSchool?' selected':''}>${sc}</option>`).join('');
  }
  const schoolDl=document.getElementById('dl-schools');
  if(schoolDl)schoolDl.innerHTML=allSchools.map(sc=>`<option value="${escAttr(sc)}">`).join('');

  // 학년/학교/검색 필터
  if(filterGrade) stus=stus.filter(s=>(s.grade||s.lv||'')=== filterGrade);
  if(filterSchool) stus=stus.filter(s=>s.school===filterSchool);
  if(q) stus=stus.filter(s=>s.name.toLowerCase().includes(q)||(s.school||'').toLowerCase().includes(q));

  // 카운트
  const cnt=document.getElementById('stu-count');
  if(cnt)cnt.textContent=`${stus.length}명`;

  if(!stus.length){
    const noFilter=!q&&!filterGrade&&!filterSchool&&filterStatus==='active';
    g.innerHTML=`<div class="empty boxed"><div class="empty-i">👦</div><div class="empty-t">${noFilter?'등록된 학생이 없습니다':'조건에 맞는 학생이 없습니다'}</div>${noFilter?`<button class="btn bt bsm" onclick="openAddStu()">+ 첫 학생 추가하기</button>`:''}</div>`;
    return;
  }
  // ── 표 형태 목록 (시안) — 학년 그룹 머리글 + 7열.
  //    행 클래스 .sc 와 onclick="selStu(id,this)" 는 그대로 둔다(selStu 가 .sc 를 찾는다).
  //    768px 이하에서는 CSS 가 같은 마크업을 카드처럼 쌓아 보여 준다.
  const _esc=t=>String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  const _less=DB.less(), _tsts=(typeof DB.tsts==='function')?DB.tsts():[];
  const lastLes=sid=>{let d='';_less.forEach(l=>{if(l.sid===sid&&(l.date||'')>d)d=l.date||'';});return d;};
  const vocabPct=sid=>{
    const r=_tsts.filter(t=>t.sid===sid&&t.vocabTotal>0)
      .sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5);
    if(!r.length)return null;
    return Math.round(r.reduce((a,t)=>a+t.vocabCorrect/t.vocabTotal,0)/r.length*100);
  };
  const clsOf=sid=>{const c=(DB.classes()||[]).find(x=>x.active!==false&&(x.studentIds||x.sids||[]).includes(sid));return c?c.name:'';};
  const GRP=g=>/^초/.test(g||'')?'초등':/^중/.test(g||'')?'중등':'기타';
  const groups={};
  stus.forEach(s=>{const k=GRP(s.grade||s.lv);(groups[k]=groups[k]||[]).push(s);});
  const rowOf=s=>{
    const pct=vocabPct(s.id), ld=lastLes(s.id);
    const pay=s.inactive?{t:'퇴원',c:'is-neutral'}:(hasUnpaid(s)?{t:'미납',c:'is-warn'}:{t:'완료',c:'is-ok'});
    return '<tr class="sc'+(s.inactive?' inactive':'')+'" onclick="selStu(\''+s.id+'\',this)" tabindex="0">'
      +'<td class="sl-name"><span class="sc-avatar">'+(_esc((s.name||'').trim().slice(0,1))||'학')+'</span>'
        +'<span class="sl-nm">'+_esc(s.name)+'</span>'
        +((typeof ppTrackBadgeHtml==='function')?ppTrackBadgeHtml(s):'')
        +((typeof ppRetestChipHtml==='function')?ppRetestChipHtml(s.id):'')+'</td>'
      +'<td class="sl-dim" data-h="학년">'+_esc(s.grade||s.lv||'')+'</td>'
      +'<td class="sl-dim" data-h="학교">'+_esc(s.school||'')+'</td>'
      +'<td class="sl-dim" data-h="클래스">'+_esc(clsOf(s.id))+'</td>'
      +'<td class="sl-dim sl-num" data-h="최근 수업">'+(ld?_esc(ld.slice(5).replace('-','/')):'—')+'</td>'
      +'<td class="sl-bar" data-h="단어 테스트">'+(pct==null?'<span class="sl-dim">—</span>'
        :'<span class="sl-bar-t"><span style="width:'+pct+'%"></span></span><span class="sl-pct">'+pct+'%</span>')+'</td>'
      +'<td class="sl-pay" data-h="결제"><span class="pp-dot '+pay.c+'"></span>'+pay.t+'</td>'
      +'</tr>';
  };
  const body=['초등','중등','기타'].filter(k=>groups[k]&&groups[k].length).map(k=>
    '<tr class="sl-grp"><td colspan="7"><span class="sl-grp-t">'+k+'</span>'
      +'<span class="sl-grp-n">'+groups[k].length+'</span></td></tr>'
    +groups[k].map(rowOf).join('')).join('');
  g.innerHTML='<div class="sl-wrap"><table class="sl-tbl"><thead><tr>'
    +['이름','학년','학교','클래스','최근 수업','단어 테스트','이번 달 결제']
      .map((h,i)=>'<th'+(i>=4?' class="sl-num"':'')+'>'+h+'</th>').join('')
    +'</tr></thead><tbody>'+body+'</tbody></table></div>';
}


// 수동 지정 칸의 안내문 — 지금 자동 판정이 무엇인지 함께 보여 준다
// 목표 점수 — 비운 칸은 넣지 않는다. 전부 비면 null.
function _esReadGoals(){
  const g=k=>{const v=parseInt((document.getElementById('es-goal-'+k)||{}).value,10);return (v>=1)?v:null;};
  const o={};
  const ih=g('inhouse'),sc=g('school'),mk=g('mock');
  if(ih>=1&&ih<=100)o.inhouse=ih;
  if(sc>=1&&sc<=100)o.school=sc;
  if(mk>=1&&mk<=9)o.mock=mk;
  return Object.keys(o).length?o:null;
}
// 수동 지정 입력을 읽어 저장 모양으로. 자동이면 null(필드를 비운다).
function _esReadTrack(){
  const g=k=>{const el=document.getElementById(k);return el?String(el.value||'').trim():'';};
  const track=g('es-track');
  if(track!=='jg'&&track!=='ch')return null;
  return {track,until:g('es-track-until'),reason:g('es-track-reason'),
    at:(typeof ppToday==='function')?ppToday():''};
}
function esTrackToggle(stu){
  const sel=document.getElementById('es-track'), hint=document.getElementById('es-track-hint');
  if(!sel||!hint)return;
  const s=stu||DB.stus().find(x=>x.id===(document.getElementById('es-id')||{}).value);
  let auto='';
  if(s&&typeof ppTrackOf==='function'){
    const a=ppTrackOf({...s,trackOverride:null});
    auto='자동 판정: '+PP_TRACK[a.track].name+' ('+a.reason+')';
  }
  const on=!!sel.value;
  ['es-track-until','es-track-reason'].forEach(k=>{const el=document.getElementById(k);if(el)el.disabled=!on;});
  hint.textContent=on
    ? '지정한 날까지 자동 판정을 무시합니다. 날을 비우면 직접 바꿀 때까지 계속 적용됩니다. '+auto
    : (auto||'학교·학년과 시험 일정으로 자동 판정합니다.');
}
function openEditStu(id){
  const s=DB.stus().find(x=>x.id===id);if(!s)return;
  document.getElementById('es-id').value=s.id;
  document.getElementById('es-name').value=s.name||'';
  document.getElementById('es-grade').value=s.grade||s.lv||'초3';document.getElementById('es-school').value=s.school||'';
  document.getElementById('es-pin').value=s.pin||'';
  document.getElementById('es-enroll').value=s.enrollDate||'';
  document.getElementById('es-fee').value=s.fee||'';
  document.getElementById('es-payday').value=s.payday||'';
  document.getElementById('es-memo').value=s.memo||'';
  // 목표 점수 (없으면 비움)
  {const g=s.scoreGoals||{};
   const sv=(k,v)=>{const el=document.getElementById(k);if(el)el.value=(v>=1)?v:'';};
   sv('es-goal-inhouse',parseInt(g.inhouse,10));
   sv('es-goal-school',parseInt(g.school,10));
   sv('es-goal-mock',parseInt(g.mock,10));}
  // 기간 수동 지정 (없으면 자동 판정)
  {const ov=s.trackOverride||{};
   const t=document.getElementById('es-track'); if(t)t.value=(ov.track==='jg'||ov.track==='ch')?ov.track:'';
   const u=document.getElementById('es-track-until'); if(u)u.value=ov.until||'';
   const rs=document.getElementById('es-track-reason'); if(rs)rs.value=ov.reason||'';
   if(typeof esTrackToggle==='function')esTrackToggle(s);}
  // 소속 클래스 표시 (요일·시간의 원천 = 클래스, 변경은 클래스 탭에서)
  {const ec=document.getElementById('es-classes');
   if(ec){const myCls=DB.classes().filter(c=>c.active!==false&&(c.studentIds||[]).includes(s.id));
     ec.innerHTML=myCls.length
       ?myCls.map(c=>`<span class="badge bteal">${c.name} · ${classSchedStr(c)}</span>`).join('')
       :'<span style="font-size:13px;color:var(--slate)">소속 클래스 없음 — 클래스 탭에서 배정해 주세요</span>';}}
  document.getElementById('es-parent-name').value=s.parentName||'';
  document.getElementById('es-parent-phone').value=s.parentPhone||'';
  document.getElementById('es-paid-date').value=ppToday();
  document.getElementById('es-paid-amt').value=s.fee||'';
  document.getElementById('es-paid-method').value='transfer';
  document.getElementById('es-paid-receipt').value='none';
  document.getElementById('es-paid-memo').value='';
  renderPayList(s.id, s.payments||[]);
  openM('m-edit-stu');
}
const PAY_METHOD_LBL={transfer:'계좌이체',cash:'현금',card:'카드',kakaopay:'카카오페이',other:'기타',wonju:'원주사랑상품권',gangwon:'강원상품권'};
const PAY_RECEIPT_LBL={none:'—',issued:'발급 완료',requested:'요청 중'};

function renderPayList(stuId, payments){
  const el=document.getElementById('es-pay-list');
  if(!payments.length){el.innerHTML='<div style="color:var(--slate);font-size:13px;padding:4px 0">결제 기록 없음</div>';return;}
  el.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:4px">
    <thead><tr style="border-bottom:1px solid var(--border)">
      <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px">날짜</th>
      <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px">금액</th>
      <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px">방식</th>
      <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px">영수증</th>
      <th style="text-align:left;padding:4px 6px;color:var(--slate);font-size:12px">메모</th>
      <th></th>
    </tr></thead>
    <tbody>${[...payments].reverse().map((p,ri)=>{
      const origIdx=payments.length-1-ri;
      return `<tr style="border-bottom:1px solid var(--border)">
        <td style="padding:5px 6px;font-family:var(--fm)">${p.date||''}</td>
        <td style="padding:5px 6px;font-weight:700">${Number(p.amt||0).toLocaleString()}원</td>
        <td style="padding:5px 6px"><span class="badge bnavy">${PAY_METHOD_LBL[p.method]||p.method||'—'}</span></td>
        <td style="padding:5px 6px"><span class="badge ${p.receipt==='issued'?'bteal':p.receipt==='requested'?'bamber':'bslate'}">${PAY_RECEIPT_LBL[p.receipt]||'—'}</span></td>
        <td style="padding:5px 6px;color:var(--slate)">${p.memo||''}</td>
        <td style="padding:5px 6px"><button class="btn bd bxxs" onclick="reqRemovePay('${stuId}',${origIdx})">삭제</button></td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;
}
async function addPayment(){
  const id=document.getElementById('es-id').value;
  const date=document.getElementById('es-paid-date').value;
  const amt=document.getElementById('es-paid-amt').value;
  const method=document.getElementById('es-paid-method').value;
  const receipt=document.getElementById('es-paid-receipt').value;
  const memo=document.getElementById('es-paid-memo').value.trim();
  if(!date||!amt){toast('날짜와 금액을 입력해 주세요');return;}
  const idx=_cache.students.findIndex(s=>s.id===id);if(idx<0)return;
  if(!_cache.students[idx].payments)_cache.students[idx].payments=[];
  _cache.students[idx].payments.push({date,amt:parseInt(amt),method,receipt,memo});
  await supaUpsert('students',id,_cache.students[idx],null);
  renderPayList(id, _cache.students[idx].payments);
  document.getElementById('es-paid-memo').value='';
  toast('결제 기록이 추가되었습니다');
}
function reqRemovePay(stuId, idx, fromPanel=false){
  askConfirm('결제 기록 삭제','이 결제 기록을 삭제할까요?','삭제','bd',async()=>{
    const si=_cache.students.findIndex(s=>s.id===stuId);if(si<0)return;
    _cache.students[si].payments.splice(idx,1);
    await supaUpsert('students',stuId,_cache.students[si]);
    if(fromPanel){loadStuPanel(stuId);}
    else{renderPayList(stuId, _cache.students[si].payments);}
    toast('삭제되었습니다');
  });
}
// 학생 추가 모달의 클래스 목록 렌더 — checkId를 주면 해당 클래스를 자동 선택 (기존 체크 상태 보존)
function renderNsClasses(checkId){
  const nsClasses=document.getElementById('ns-classes');if(!nsClasses)return;
  const prevChecked=new Set([...nsClasses.querySelectorAll('input:checked')].map(cb=>cb.value));
  if(checkId)prevChecked.add(checkId);
  const classes=DB.classes().filter(c=>c.active!==false);
  const addBtn='<button type="button" class="btn badd bsm" style="align-self:flex-start" onclick="openEditClass()">+ 새 클래스 만들기</button>';
  if(classes.length){
    nsClasses.innerHTML=classes.map(c=>`<label style="display:flex;align-items:center;gap:10px;padding:8px 10px;border:1.5px solid var(--border);border-radius:var(--rs);cursor:pointer;background:var(--cream)">
      <input type="checkbox" value="${c.id}"${prevChecked.has(c.id)?' checked':''} style="flex-shrink:0;width:16px;height:16px;cursor:pointer">
      <div style="flex:1;min-width:0">
        <div style="font-size:14px;font-weight:600;color:var(--navy)">${c.name}</div>
        <div style="font-size:12px;color:var(--slate);margin-top:2px">${classSchedStr(c)}</div>
      </div>
    </label>`).join('')+addBtn;
  }else if(_cache.globalClasses!==undefined){
    nsClasses.innerHTML='<span style="font-size:13px;color:var(--slate)">아직 클래스가 없어요 — 여기서 바로 만들 수 있어요</span>'+addBtn;
  }else{
    nsClasses.innerHTML='<span style="font-size:13px;color:var(--slate)">데이터 로딩 중...</span>';
  }
}
function openAddStu(){
  // 입력칸도 비운다 — 연달아 추가하면 앞 학생의 학년·학교·PIN 이 남아 있었다
  ['ns-name','ns-pin','ns-school','ns-fee','ns-memo','ns-enroll','ns-payday'].forEach(id=>{
    const el=document.getElementById(id);if(el)el.value='';
  });
  {const g=document.getElementById('ns-grade');if(g)g.selectedIndex=0;}
  // 이전 세션의 체크 잔존 방지 — 매 열기마다 미체크로 시작 (모달 열려 있는 동안의 보존은 renderNsClasses가 담당)
  document.querySelectorAll('#ns-classes input:checked').forEach(cb=>cb.checked=false);
  renderNsClasses();
  openM('m-add-stu');
}
async function addStu(){
  const name=document.getElementById('ns-name').value.trim();
  const pin=document.getElementById('ns-pin').value.trim();
  if(!name){toast('이름을 입력해 주세요');return;}
  if(!pin||pin.length!==4){toast('PIN은 4자리여야 합니다');return;}
  const newStu={id:uid(),name,grade:document.getElementById('ns-grade').value,school:document.getElementById('ns-school')?.value.trim()||'',pin,enrollDate:document.getElementById('ns-enroll').value,fee:parseInt(document.getElementById('ns-fee').value)||0,payday:parseInt(document.getElementById('ns-payday').value)||0,memo:document.getElementById('ns-memo').value.trim(),parentName:document.getElementById('ns-parent-name')?.value.trim()||'',parentPhone:document.getElementById('ns-parent-phone')?.value.trim()||'',payments:[],inactive:false};
  await supaUpsert('students',newStu.id,newStu,null);
  _cache.students.unshift(newStu);
  // 선택된 클래스에 학생 추가
  const checkedClasses=[...document.querySelectorAll('#ns-classes input:checked')].map(cb=>cb.value);
  for(const cid of checkedClasses){
    const c=DB.classes().find(x=>x.id===cid);if(!c)continue;
    if(!(c.studentIds||[]).includes(newStu.id)){
      c.studentIds=[...(c.studentIds||[]),newStu.id];
      await supaUpsert('classes',cid,c,null);
      const idx=(_cache.globalClasses||[]).findIndex(x=>x.id===cid);
      if(idx>=0)_cache.globalClasses[idx]=c;
    }
  }
  closeM('m-add-stu');
  ['ns-name','ns-pin','ns-enroll','ns-fee','ns-payday','ns-memo','ns-school','ns-parent-name','ns-parent-phone'].forEach(i=>{const el=document.getElementById(i);if(el)el.value='';});
  renderStus();populateSels();populateFilterSels();renderClassTab();toast(name+' 학생이 추가되었습니다');
}
async function updStu(){
  const id=document.getElementById('es-id').value;
  const idx=_cache.students.findIndex(s=>s.id===id);if(idx<0)return;
  _cache.students[idx]={..._cache.students[idx],name:document.getElementById('es-name').value.trim(),grade:document.getElementById('es-grade').value,school:document.getElementById('es-school').value.trim(),pin:document.getElementById('es-pin').value.trim(),enrollDate:document.getElementById('es-enroll').value,fee:parseInt(document.getElementById('es-fee').value)||0,payday:parseInt(document.getElementById('es-payday').value)||0,memo:document.getElementById('es-memo').value.trim(),trackOverride:_esReadTrack(),scoreGoals:_esReadGoals(),parentName:document.getElementById('es-parent-name').value.trim(),parentPhone:document.getElementById('es-parent-phone').value.trim()};
  await supaUpsert('students',id,_cache.students[idx],null);
  closeM('m-edit-stu');renderStus();populateSels();toast('수정되었습니다');
}
function reqWithdrawStu(){
  const id=document.getElementById('es-id').value;
  const s=DB.stus().find(x=>x.id===id);
  askConfirm('퇴원 처리',`${s?s.name:'이 학생'}을 퇴원 처리할까요? 기록은 유지되며 학생 카드에 퇴원 표시가 됩니다.`,'퇴원 처리','bd',async()=>{
    const idx=_cache.students.findIndex(x=>x.id===id);if(idx<0)return;
    _cache.students[idx].inactive=true;_cache.students[idx].withdrawDate=ppToday();
    await supaUpsert('students',id,_cache.students[idx],null);
    closeM('m-edit-stu');renderStus();populateSels();toast('퇴원 처리되었습니다');
  });
}
function reqDelStu(){
  const id=document.getElementById('es-id').value;
  const s=DB.stus().find(x=>x.id===id);
  askConfirm('학생 삭제',`${s?s.name:'이 학생'}과 모든 수업·테스트·원서 기록을 휴지통으로 이동합니다. 백업·일괄 탭 휴지통에서 30일 내 통째로 복원할 수 있어요.`,'휴지통으로 이동','bd',async()=>{
    const ts=new Date().toISOString();
    await supaTrash('students',_cache.students,id);
    // 연관 기록도 함께 표식 (_deletedWith=학생 id → 복원/영구 삭제 시 한 묶음으로 처리)
    // vocab_cards·textbooks·counsels 가 빠져 있어, 학생을 지워도 서버에 그대로 남았다 (2026-11-06 점검)
    for(const tbl of ['lessons','tests','readings','logs','homeworks','assignments','vocab_cards','textbooks','counsels']){
      const items=(_cache[tbl]||[]).filter(x=>x.sid===id);
      for(const it of items) await supaUpsert(tbl,it.id,{...it,_deleted:true,_deletedAt:ts,_deletedWith:id},id).catch(()=>{});
      _cache[tbl]=(_cache[tbl]||[]).filter(x=>x.sid!==id);
    }
    // (위 목록에 vocab_cards 가 들어가 함께 휴지통으로 간다 — 복원하면 _deletedWith 로 같이 돌아온다)
    _cache.students=_cache.students.filter(x=>x.id!==id);
    closeM('m-edit-stu');renderStus();populateSels();toast('휴지통으로 이동했습니다');
  });
}

// ── SUBJECTS (수업 입력용) ──
const aSubjs=new Set();
function togSubj(el){
  const s=el.dataset.s;
  if(aSubjs.has(s)){
    if(s==='naesin'){addSRowTo('subj-rows',s);return;}
    aSubjs.delete(s);el.classList.remove('active');document.querySelectorAll('#subj-rows .sr').forEach(r=>{if((r.dataset.s||'').replace(/_\d+$/,'')===s)r.remove();});
  }else{aSubjs.add(s);el.classList.add('active');addSRowTo('subj-rows',s);}
}
// 수업 수정용 별도 Set
const aEditSubjs=new Set();
function togEditSubj(el){
  const s=el.dataset.s;
  if(aEditSubjs.has(s)){aEditSubjs.delete(s);el.classList.remove('active');document.querySelectorAll('#el-subj-rows .sr').forEach(r=>{if((r.dataset.s||'').replace(/_\d+$/,'')===s)r.remove();});}
  else{aEditSubjs.add(s);el.classList.add('active');addSRowTo('el-subj-rows',s);}
}
function _mkUnitInputsHtml(unitVal,dlId,dlOptsHtml,placeholder){
  const vals=(unitVal||'').split(', ').filter(Boolean);
  if(!vals.length)vals.push('');
  const st='flex:1;min-width:0;padding:7px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-size:13px;font-family:var(--fb);color:var(--navy);background:var(--cream);outline:none';
  const ph=placeholder||'유닛/진도';
  const rows=vals.map((v,i)=>`<div class="unit-irow" style="display:flex;align-items:center;gap:3px"><input type="text" data-f="unit"${dlId?` list="${dlId}"`:''}placeholder="${ph}" value="${escAttr(v)}" autocomplete="off" style="${st}">${i===0?`<button type="button" onclick="addUnitInput(this,'${dlId||''}')" title="과 추가" style="flex-shrink:0;width:22px;height:22px;background:var(--teal);color:#fff;border:none;border-radius:50%;cursor:pointer;font-size:17px;line-height:1;padding:0;display:flex;align-items:center;justify-content:center">+</button>`:`<button type="button" onclick="this.closest('.unit-irow').remove()" style="flex-shrink:0;width:22px;height:22px;background:none;border:1px solid var(--border);border-radius:50%;cursor:pointer;font-size:16px;color:var(--slate);line-height:1;padding:0">×</button>`}</div>`).join('');
  return `${dlId?`<datalist id="${dlId}">${dlOptsHtml||''}</datalist>`:''}<div class="unit-inputs-wrap" style="display:flex;flex-direction:column;gap:3px;width:100%;min-width:0">${rows}</div>`;
}
function addSRowTo(wrapperId,s,bookVal,unitVal,bookId,daysVal,runVal){
  const wrap=document.getElementById(wrapperId);if(!wrap)return;
  const d=document.createElement('div');d.className='sr';d.dataset.s=s;
  const isBook=s==='_book'||s.startsWith('_book_');
  const baseKey=isBook?'_book':s.replace(/_\d+$/,'');
  const label=isBook?'원서':(SLBL[baseKey]||'');
  const cls=isBook?'srd':(SCLS[baseKey]||'');
  // 내신은 어디서나, 클래스 수정(ec-subj-rows)에선 모든 과목에 '+' — 같은 과목 교재 여러 권 = 커리큘럼 체인 (앞 책 끝나면 다음 책)
  const canAdd=baseKey==='naesin'||(wrapperId==='ec-subj-rows'&&!isBook&&baseKey!=='pencil_down'&&baseKey!=='sing_together');
  const addBtn=canAdd?`<button class="btn-xadd" title="${baseKey==='naesin'?'내신 교재 추가':'다음 교재 추가 — 이 교재가 끝나면 이어서 나갈 책 (교재 흐름 미리 등록)'}" onclick="addSRowTo('${wrapperId}','${baseKey}')">+</button>`:'';
  const noUnit=wrapperId==='ec-subj-rows';
  let unitInput=noUnit?'':_mkUnitInputsHtml(unitVal,'','','유닛/진도');
  if(baseKey==='pencil_down'||baseKey==='sing_together'){
    const rawVal=baseKey==='sing_together'?bookVal:(bookVal==='Pencil Down Day'||!bookVal)?'':bookVal;
    const PD_ACTS=[
      {v:'Sing Together',lbl:'🎵 싱 투게더'},
      {v:'Story Time',lbl:'📖 스토리 타임'},
      {v:'Movie/Video',lbl:'🎬 영화·영상'},
      {v:'Game',lbl:'🎮 게임'},
      {v:'Arts & Crafts',lbl:'🎨 만들기·공예'},
      {v:'Free Talk',lbl:'💬 프리톡'},
    ];
    // 자료 DB에 등록된 펜슬다운 자료(노래 등). 하드코딩 활동과 제목이 같은 건 제외(중복 방지 — 예: Sing Together).
    // 그 자료의 단원(곡·주제)은 아래 '세부 내용' 자동완성으로 붙는다.
    const allPdBooks=(_cache.globalTextbooks||[]).filter(b=>b.category==='펜슬다운'&&b.title);
    const pdBooks=allPdBooks.filter(b=>!PD_ACTS.some(a=>a.v===b.title));
    const pdUnits=[...new Set(allPdBooks.flatMap(b=>(typeof tbUnitKeys==='function'?tbUnitKeys(b):Object.keys(b.units||{}))))];
    const dlId='dl-pdu-'+escAttr(String(s));
    const isKnown=!rawVal||PD_ACTS.some(a=>a.v===rawVal)||pdBooks.some(b=>b.title===rawVal);
    const iS='padding:6px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-size:13px;font-family:var(--fb);color:var(--navy);background:var(--cream2);outline:none;width:100%;box-sizing:border-box';
    const opts=`<option value="">-- 활동 선택 --</option>`
      +PD_ACTS.map(a=>`<option value="${escAttr(a.v)}"${rawVal===a.v?' selected':''}>${a.lbl}</option>`).join('')
      +(pdBooks.length?`<optgroup label="🎵 등록된 자료">${pdBooks.map(b=>`<option value="${escAttr(b.title)}" data-bk-id="${escAttr(b.id)}"${rawVal===b.title?' selected':''}>${escAttr(b.title)}</option>`).join('')}</optgroup>`:'')
      +`<option value="__other__"${!isKnown&&rawVal?' selected':''}>✏️ 기타 (직접 입력)</option>`;
    d.style.gridTemplateColumns='80px 1fr 1fr auto';
    d.innerHTML=`<span class="sl spd" style="line-height:1.4">✏️<br>Pencil Down</span>
      <div style="min-width:0">
        <select ${isKnown?'data-f="book"':''} class="pd-act-sel" onchange="pdSelChange(this)" style="${iS}${isKnown?'':';display:none'}">${opts}</select>
        <input ${!isKnown?'data-f="book"':''} class="pd-cus-inp" type="text" placeholder="활동명 직접 입력" value="${escAttr(!isKnown?rawVal:'')}" style="${iS}${isKnown?';display:none':''}">
      </div>
      ${noUnit?'':`<input type="text" data-f="unit" list="${dlId}" placeholder="세부 내용 (곡명·주제)" value="${escAttr(unitVal||'')}" style="${iS}"><datalist id="${dlId}">${pdUnits.map(u=>`<option value="${escAttr(u)}"></option>`).join('')}</datalist>`}
      <button class="btn-xr" onclick="rmSRowFrom('${wrapperId}','${s}',this)">×</button>`;
    wrap.appendChild(d);return;
  }
  // cl/subj/el-subj-rows: 교재 DB select 드롭다운, 나머지: text input with datalist
  const _bkSelSt='flex:1;min-width:0;padding:7px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-size:13px;font-family:var(--fb);color:var(--navy);background:var(--cream)';
  let bookInput;
  const _selMatch=(b)=>bookId?b.id===bookId:b.title===bookVal;
  if(wrapperId==='cl-subj-rows'&&!isBook){
    const catFilter=_CAT_KO[baseKey];
    let books=(_cache.globalTextbooks||[]).filter(b=>catFilter?b.category===catFilter:true);
    const noMatch=catFilter&&!books.length;
    if(noMatch)books=_cache.globalTextbooks||[];
    books=tbSortByUsage(books); // 최근 사용 교재 우선
    const placeholder=noMatch?`-- 교재 선택 (${catFilter} 교재 없음, 전체 표시) --`:'-- 교재 선택 --';
    const opts=`<option value="">${placeholder}</option>`+books.map(b=>`<option value="${escAttr(b.title)}" data-bk-id="${escAttr(b.id||'')}"${_selMatch(b)?' selected':''}>${b.title}${b.level?' ('+b.level+')':''}</option>`).join('')+BK_ADD_OPT;
    bookInput=`<select data-f="book" data-basekey="${baseKey}" onfocus="this.dataset.prev=this.value" onchange="if(bkSelAddNew(this))return;this.dataset.prev=this.value;clUpdateUnitHint(this)" style="${_bkSelSt}">${opts}</select>`;
    if(!noUnit){
      const initTbCl=books.find(_selMatch)||null;
      const initUnitsCl=initTbCl?tbUnitKeys(initTbCl):[];
      const initTitlesCl=initTbCl?.unitTitles||{};
      const dlCUId='dl-clu-'+Math.random().toString(36).slice(2,7);
      const dlOptsCl=initUnitsCl.map(k=>`<option value="${escAttr(k)}">${k}${initTitlesCl[k]?' — '+initTitlesCl[k]:''}</option>`).join('');
      unitInput=_mkUnitInputsHtml(unitVal,dlCUId,dlOptsCl,'유닛/진도');
    }
  }else if((wrapperId==='subj-rows'||wrapperId==='el-subj-rows')&&!isBook){
    const catFilter=_CAT_KO[baseKey];
    let books=(_cache.globalTextbooks||[]).filter(b=>catFilter?b.category===catFilter:true);
    const noMatch=catFilter&&!books.length;
    if(noMatch)books=_cache.globalTextbooks||[];
    books=tbSortByUsage(books); // 최근 사용 교재 우선
    const placeholder=noMatch?`-- 교재 선택 (${catFilter} 교재 없음, 전체 표시) --`:'-- 교재 선택 --';
    const opts=`<option value="">${placeholder}</option>`+books.map(b=>`<option value="${escAttr(b.title)}" data-bk-id="${escAttr(b.id||'')}"${_selMatch(b)?' selected':''}>${b.title}${b.level?' ('+b.level+')':''}</option>`).join('')+BK_ADD_OPT;
    bookInput=`<select data-f="book" data-basekey="${baseKey}" onfocus="this.dataset.prev=this.value" onchange="if(bkSelAddNew(this))return;this.dataset.prev=this.value;lesUpdateUnitSel(this)" style="${_bkSelSt}">${opts}</select>`;
    if(!noUnit){
      const initTb=books.find(_selMatch)||null;
      const initUnits=initTb?tbUnitKeys(initTb):[];
      const initTitles=initTb?.unitTitles||{};
      const dlUId='dl-u-'+Math.random().toString(36).slice(2,7);
      const dlOptsU=initUnits.map(k=>`<option value="${escAttr(k)}">${k}${initTitles[k]?' — '+initTitles[k]:''}</option>`).join('');
      unitInput=_mkUnitInputsHtml(unitVal,dlUId,dlOptsU,initUnits.length?'단원 선택 또는 직접 입력':'유닛/진도');
    }
  }else if(isBook){
    // 원서 행: 원서 목록 datalist + 챕터 자동 힌트
    const seenLibIds=new Set((_cache.library||[]).map(b=>b.id));
    const allLibCombined=[...(_cache.library||[]).filter(b=>!b._deleted)];
    const sortedLib=allLibCombined.sort((a,b2)=>(a.title||'').localeCompare(b2.title||''));
    const dlLibId='dl-lib-'+Math.random().toString(36).slice(2,7);
    const dlChId='dl-ch-'+Math.random().toString(36).slice(2,7);
    bookInput=`<datalist id="${dlLibId}">${sortedLib.map(b=>`<option value="${escAttr(b.title)}">`).join('')}</datalist><input type="text" placeholder="원서 제목" data-f="book" list="${dlLibId}" autocomplete="off" value="${escAttr(bookVal||'')}" oninput="libUpdateChapterHint(this)" onchange="libOfferAdd(this)" style="${_bkSelSt}">`;
    if(!noUnit){
      const initLibBk=bookVal?allLibCombined.find(b=>b.title===bookVal):null;
      const initChs=[...new Set((initLibBk?.vocab||[]).map(w=>w.chapter||w.unit).filter(Boolean))];
      const dlOptsCh=initChs.map(c=>`<option value="${escAttr(c)}">`).join('');
      unitInput=_mkUnitInputsHtml(unitVal,dlChId,dlOptsCh,initChs.length?'챕터 선택 또는 직접 입력':'챕터/진도');
    }
  }else{
    // ec-subj-rows: select 드롭다운 (레벨 표시, bookId로 정확 매칭)
    const catF=_CAT_KO[baseKey];
    let filtBooks=catF?(_cache.globalTextbooks||[]).filter(b=>b.category===catF):(_cache.globalTextbooks||[]);
    if(!filtBooks.length)filtBooks=_cache.globalTextbooks||[];
    filtBooks=[...filtBooks].sort((a,b)=>(a.title||'').localeCompare(b.title||''));
    const opts2=`<option value="">-- 교재 선택 --</option>`+filtBooks.map(b=>`<option value="${escAttr(b.title)}" data-bk-id="${escAttr(b.id||'')}"${_selMatch(b)?' selected':''}>${b.title}${b.level?' ('+b.level+')':''}</option>`).join('')+BK_ADD_OPT;
    bookInput=`<select data-f="book" data-basekey="${baseKey}" onfocus="this.dataset.prev=this.value" onchange="if(bkSelAddNew(this))return;this.dataset.prev=this.value" style="${_bkSelSt}">${opts2}</select>`;
  }
  if(wrapperId==='ec-subj-rows'){
    // 클래스 편집: 같은 과목 교재 여러 권 = 커리큘럼 체인 (행 순서 = 진행 순서).
    // 첫 행만 과목 라벨+요일을 갖고, 이후 행은 '↳ N번째'로 들여써서 앞 책이 끝나면 이어짐을 표시.
    const prevSame=[...wrap.querySelectorAll('.sr')].filter(r=>(r.dataset.s||'').replace(/_\d+$/,'')===baseKey);
    const isNext=prevSame.length>0;
    const dv=Array.isArray(daysVal)?daysVal:[];
    // 요일은 '요일별 배치판'에서 다루므로 칩은 숨긴 채 저장 입력값으로만 둔다 (CSS: #ec-subj-rows .pg-days)
    const dayChips=isNext?''
      :`<div class="pg-days" title="이 교재를 나가는 요일 — 비우면 수업일마다 진행">${['월','화','수','목','금','토','일'].map(dd=>`<span class="pg-day-chip${dv.includes(dd)?' on':''}" data-d="${dd}" onclick="this.classList.toggle('on')">${dd}</span>`).join('')}</div>`;
    // 진행 방식 — 같은 영역에서도 교재가 동시에 돌 수 있다 (1200은 수업 중, 요즘 초등 영단어는 과제)
    const rv=String(runVal||'');
    const runSel=`<select data-f="run" class="sr-run${rv?' on':''}" onchange="_ecRunChange(this)"
      title="기본 = 앞 교재가 끝나면 이어서 진행 (한 줄)&#10;동시·수업 = 이 교재부터 새 줄을 열어 수업일마다 1과&#10;동시·과제 = 이 교재부터 새 줄을 열어 수업 없는 날 1과씩&#10;새 줄은 다른 줄을 기다리지 않고 함께 진행됩니다">
      <option value=""${rv===''?' selected':''}>${isNext?'↳ 앞 교재 끝나면':'기본 진행'}</option>
      <option value="class"${rv==='class'?' selected':''}>⇵ 동시 · 수업</option>
      <option value="hw"${rv==='hw'?' selected':''}>⇵ 동시 · 과제</option>
    </select>`;
    const cell3=`<div class="sr-c3">${dayChips}${runSel}</div>`;
    if(rv)d.classList.add('sr-par');
    const ecAdd=`<button class="btn bo bxxs" style="white-space:nowrap;font-size:13px;padding:6px 11px" title="이 교재가 끝나면 이어서 나갈 다음 교재 추가 — 커리큘럼을 쭉 등록해두면 예정 캘린더가 끝까지 채워져요" onclick="addSRowTo('${wrapperId}','${baseKey}')">+ 다음 교재</button>`
      +`<button class="btn bo bxxs" style="white-space:nowrap;font-size:13px;padding:6px 9px" title="이 교재 뒤로 같은 시리즈의 다음 권들을 순서대로 자동 등록 (이미 있는 권은 건너뜀)" onclick="ecChainSeries(this)">${luIcon('book-open',15)||''} 시리즈</button>`;
    // 순서 변경은 드래그(마우스·터치 공용 pointer 이벤트) — 같은 과목 안에서만 이동
    const orderBtns=`<span class="sr-grip" title="끌어서 순서 변경" onpointerdown="ecGripDown(event,this)">⠿</span>`;
    const lbl=isNext
      ?`<span class="sl" style="background:var(--cream2);color:var(--slate)">↳ ${prevSame.length+1}번째</span>`
      :`<span class="sl ${cls}">${label}</span>`;
    d.innerHTML=`${lbl}${bookInput}${cell3}<div style="display:flex;gap:4px;align-items:center">${orderBtns}${ecAdd}<button class="btn-xr" onclick="rmSRowFrom('${wrapperId}','${s}',this)">×</button></div>`;
    if(isNext){
      d.style.marginLeft='14px';
      prevSame[prevSame.length-1].insertAdjacentElement('afterend',d); // 같은 과목 그룹 바로 아래에 (체인이 뭉쳐 보이게)
    }else wrap.appendChild(d);
    _ecBoardRender();
    return;
  }
  d.innerHTML=`<span class="sl ${cls}">${label}</span>${bookInput}${unitInput} ${addBtn}<button class="btn-xr" onclick="rmSRowFrom('${wrapperId}','${s}',this)">×</button>`;
  wrap.appendChild(d);
}
// 시리즈 내 자연 순서 — YLE 레벨 단어(Pre-Starters→Starters→Movers→Flyers) 우선, 그 외엔 숫자 자연 정렬
function _seriesSortBooks(list){
  // Pre-Starters < Starters < (무표기 숫자권) < Movers < Flyers — Easy Link(Starter 1~3 → 1~6), 1200 Words(Starters → Movers) 모두 커버
  const rank=t=>{const s=String(t).toLowerCase();if(/pre[- ]?starter/.test(s))return 0;if(/starter/.test(s))return 1;if(/mover/.test(s))return 3;if(/flyer/.test(s))return 4;return 2;};
  return [...list].sort((a,b)=>rank(a.title)-rank(b.title)||String(a.title).localeCompare(String(b.title),undefined,{numeric:true}));
}
// 시리즈 이어서 등록 — 이 행의 교재 뒤로 같은 시리즈의 다음 권들을 순서대로 체인에 자동 추가
// (이미 체인에 있는 권은 건너뜀. 사이에 다른 교재 끼우기는 '+ 다음 교재'와 ⠿ 드래그로 커스터마이징)
function ecChainSeries(btn){
  const row=btn.closest('.sr');if(!row)return;
  const sel=row.querySelector('select[data-f="book"]');
  const title=sel?.value||'';
  const bkId=sel?.options[sel.selectedIndex]?.dataset?.bkId||'';
  const tb=(_cache.globalTextbooks||[]).find(b=>bkId?b.id===bkId:b.title===title);
  if(!tb){toast('교재를 먼저 선택해 주세요');return;}
  if(!tb.series){toast(`'${tb.title}'에 시리즈 정보가 없어요 — 자료 DB에서 시리즈를 지정해 주세요`);return;}
  const base=(row.dataset.s||'').replace(/_\d+$/,'');
  const existing=new Set([...document.querySelectorAll('#ec-subj-rows .sr')]
    .filter(r=>(r.dataset.s||'').replace(/_\d+$/,'')===base)
    .map(r=>r.querySelector('select[data-f="book"]')?.value).filter(Boolean));
  // 현재 책을 포함해 정렬 → 정렬상 뒤에 오는 권들만 (현재 책이 단원 미등록이어도 위치 기준으로 동작)
  const sers=_seriesSortBooks([tb,...(_cache.globalTextbooks||[]).filter(b=>!b._deleted&&b.id!==tb.id&&b.series===tb.series&&tbUnitKeys(b).length)]);
  const idx=sers.findIndex(b=>b.id===tb.id);
  const nexts=sers.slice(idx+1).filter(b=>!existing.has(b.title));
  if(!nexts.length){toast('이어 붙일 다음 권이 없어요 (이미 등록됐거나 시리즈 마지막 권)');return;}
  askConfirm('📚 시리즈 이어서 등록',`'${tb.series}' 시리즈의 다음 권 ${nexts.length}권을 순서대로 이어 붙일까요?\n\n${nexts.map((b,i)=>`${i+1}. ${b.title}`).join('\n')}\n\n(사이에 다른 교재를 끼우려면 등록 후 ⠿ 손잡이를 끌어 조정하세요)`,'이어 붙이기','bt',()=>{
    nexts.forEach(b=>addSRowTo('ec-subj-rows',base,b.title,'',b.id));
    toast(`${nexts.length}권을 이어 붙였어요 — 저장하면 반영됩니다`);
  });
}
// 커리큘럼 체인 순서 바꾸기 — 같은 과목 안에서 위/아래 행과 교재 선택값을 맞바꿈
// (행 구조·라벨·요일 칩은 그대로 두고 값만 교환 → 첫 행=현재 책 규칙 유지, 저장 시 새 순서로 반영)
// 같은 과목(base) 체인 행들 — DOM 순서대로
function _ecChainRows(base){
  return [...document.querySelectorAll('#ec-subj-rows .sr')].filter(r=>(r.dataset.s||'').replace(/_\d+$/,'')===base&&r.querySelector('select[data-f="book"]'));
}
// 행 자체는 그대로 두고 **교재 선택값만** 재배치한다 — '↳ N번째' 라벨·요일 칩은 자리(첫 행)에 묶여 있어야 하므로
function _ecApplyOrder(base,from,to){
  const rows=_ecChainRows(base);
  if(from===to||from<0||to<0||from>=rows.length||to>=rows.length)return false;
  const vals=rows.map(r=>r.querySelector('select[data-f="book"]').value);
  vals.splice(to,0,vals.splice(from,1)[0]);
  rows.forEach((r,i)=>{
    const el=r.querySelector('select[data-f="book"]');
    if(el.value===vals[i])return;
    el.value=vals[i];
    el.style.transition='background .15s';el.style.background='var(--warnl)';
    setTimeout(()=>{el.style.background='';},450);
  });
  _ecBoardRender();
  return true;
}
// ── 교재 순서 드래그 (pointer 이벤트 — 마우스·터치 동일 동작) ──
let _ecDrag=null;
function _ecClearDropMark(){document.querySelectorAll('#ec-subj-rows .sr').forEach(r=>r.classList.remove('sr-drop-before','sr-drop-after'));}
function ecGripDown(ev,grip){
  const row=grip.closest('.sr');if(!row)return;
  ev.preventDefault();
  const base=(row.dataset.s||'').replace(/_\d+$/,'');
  if(_ecChainRows(base).length<2){toast('이 과목은 교재가 한 권이에요');return;}
  _ecDrag={row,base,target:null,after:false};
  row.classList.add('sr-dragging');
  document.addEventListener('pointermove',_ecDragMove);
  document.addEventListener('pointerup',_ecDragUp,{once:true});
  document.addEventListener('pointercancel',_ecDragUp,{once:true});
}
function _ecDragMove(ev){
  if(!_ecDrag)return;
  ev.preventDefault();
  _ecClearDropMark();
  _ecDrag.target=null;
  const over=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.sr');
  if(!over||over===_ecDrag.row)return;
  if((over.dataset.s||'').replace(/_\d+$/,'')!==_ecDrag.base)return; // 다른 과목으로는 못 옮김
  const r=over.getBoundingClientRect();
  const after=ev.clientY>r.top+r.height/2;
  over.classList.add(after?'sr-drop-after':'sr-drop-before');
  _ecDrag.target=over;_ecDrag.after=after;
}
function _ecDragUp(){
  document.removeEventListener('pointermove',_ecDragMove);
  const d=_ecDrag;_ecDrag=null;
  _ecClearDropMark();
  if(!d)return;
  d.row.classList.remove('sr-dragging');
  if(!d.target)return;
  const rows=_ecChainRows(d.base);
  const from=rows.indexOf(d.row);
  let to=rows.indexOf(d.target)+(d.after?1:0);
  if(to>from)to--;
  if(_ecApplyOrder(d.base,from,to))toast('순서를 바꿨어요 — 저장하면 반영됩니다');
}
function rmSRowFrom(wrapperId,s,btn){
  btn.closest('.sr').remove();
  if(wrapperId==='ec-subj-rows')_ecBoardRender();
  // 같은 wrapperId에 해당 subject 행이 남아있는지 확인 후 chip 비활성화
  const remaining=document.querySelectorAll(`#${wrapperId} .sr[data-s="${s}"]`).length;
  if(remaining>0)return;
  const baseKey=s.replace(/_\d+$/,'');
  const isSubjRows=wrapperId==='subj-rows';
  const isEditRows=wrapperId==='el-subj-rows';
  const isEcRows=wrapperId==='ec-subj-rows';
  const isClRows=wrapperId==='cl-subj-rows';
  if(isSubjRows){aSubjs.delete(baseKey);document.querySelectorAll('#subj-chips .chip').forEach(c=>{if(c.dataset.s===baseKey)c.classList.remove('active');});}
  else if(isEditRows){aEditSubjs.delete(baseKey);document.querySelectorAll('#el-subj-chips .chip').forEach(c=>{if(c.dataset.s===baseKey)c.classList.remove('active');});}
  else if(isEcRows){ecSubjs.delete(baseKey);document.querySelectorAll('#ec-subj-chips .chip').forEach(c=>{if(c.dataset.s===baseKey)c.classList.remove('active');});}
  else if(isClRows){clSubjs.delete(baseKey);document.querySelectorAll('#cl-subj-chips .chip').forEach(c=>{if(c.dataset.s===baseKey)c.classList.remove('active');});}
}
function addSRow(s){addSRowTo('subj-rows',s);}
function rmSRow(s,btn){rmSRowFrom('subj-rows',s,btn);}

// ── 교재 퀵 추가 — select에 원하는 교재가 없을 때 그 자리에서 추가 (자료 DB와 연동) ──
const BK_ADD_OPT='<option value="__addnew__">➕ 새 교재 추가…</option>';
let _qtbTargetSel=null,_qtbSaving=false;
function bkSelAddNew(sel){
  if(sel.value!=='__addnew__')return false;
  // 직전 선택값 복원 (onfocus에서 저장) — 퀵 추가를 취소해도 기존 선택이 유실되지 않음
  sel.value=sel.dataset.prev||'';
  openQuickTbook(sel);
  return true;
}
function openQuickTbook(sel){
  _qtbTargetSel=sel||null;
  document.getElementById('qtb-title').value='';
  document.getElementById('qtb-level').value='';
  document.getElementById('qtb-category').value=sel?(_CAT_KO[sel.dataset.basekey]||''):'';
  openM('m-quick-tbook');
  setTimeout(()=>document.getElementById('qtb-title')?.focus(),80);
}
async function saveQuickTbook(){
  const title=document.getElementById('qtb-title').value.trim();
  if(!title){toast('교재명을 입력하세요');return;}
  if(_qtbSaving)return; // 더블클릭·IME Enter 중복 실행 방지
  _qtbSaving=true;
  try{
    const category=document.getElementById('qtb-category').value||'';
    const level=document.getElementById('qtb-level').value.trim();
    let tb=(_cache.globalTextbooks||[]).find(b=>(b.title||'').trim().toLowerCase()===title.toLowerCase());
    if(tb){
      toast('이미 등록된 교재예요 — 바로 선택했습니다');
    }else{
      tb={id:uid(),type:'textbook',title,publisher:'',level,category,grade:'',totalUnits:0};
      try{await supaUpsert('global_textbooks',tb.id,tb,null);}
      catch(e){toast(e.message?.includes('404')?'global_textbooks 테이블이 없습니다. supabase_missing_tables.sql을 실행해 주세요.':'저장 실패: '+e.message);return;}
      if(!_cache.globalTextbooks)_cache.globalTextbooks=[];
      _cache.globalTextbooks.push(tb);
      // 자료 DB 탭 화면도 동기화
      try{renderTbookTable();renderBookDB();renderMasterDB();updateTbookDatalist();}catch(e){}
      toast('교재가 추가되었습니다 (자료 DB에도 등록)');
    }
    // 열려 있는 교재 select에 새 옵션 반영 — 트리거 select는 항상, 나머지는 분류가 맞을 때만
    document.querySelectorAll('select[data-f="book"][data-basekey]').forEach(s=>{
      if([...s.options].some(o=>o.dataset&&o.dataset.bkId===tb.id))return;
      const isTrigger=s===_qtbTargetSel;
      const catOk=!tb.category||_CAT_KO[s.dataset.basekey]===tb.category||!_CAT_KO[s.dataset.basekey];
      if(!isTrigger&&!catOk)return;
      const opt=document.createElement('option');
      opt.value=tb.title;opt.dataset.bkId=tb.id;
      opt.textContent=tb.title+(tb.level?' ('+tb.level+')':'');
      const addOpt=[...s.options].find(o=>o.value==='__addnew__');
      s.insertBefore(opt,addOpt||null);
    });
    // 트리거한 select에서 새 교재를 곧바로 선택 + 유닛 힌트 갱신
    if(_qtbTargetSel&&document.contains(_qtbTargetSel)){
      const opt=[..._qtbTargetSel.options].find(o=>o.dataset&&o.dataset.bkId===tb.id);
      if(opt){opt.selected=true;_qtbTargetSel.dispatchEvent(new Event('change'));}
    }
    closeM('m-quick-tbook');
    _qtbTargetSel=null;
  }finally{_qtbSaving=false;}
}
// 원서 제목이 원서 DB에 없으면 추가 제안 (입력 확정 시)
const _libOfferDeclined=new Set(); // 세션 내 '취소'한 제목은 다시 묻지 않음
function libOfferAdd(inp){
  const title=(inp.value||'').trim();
  if(!title)return;
  const key=title.toLowerCase();
  if(_libOfferDeclined.has(key))return;
  if((_cache.library||[]).some(b=>(b.title||'').trim().toLowerCase()===key))return;
  // blur 직후 버튼 클릭이 confirm 오버레이에 먹히지 않도록 클릭 완료 후에 띄운다
  setTimeout(()=>{
    if(_libOfferDeclined.has(key))return;
    if((_cache.library||[]).some(b=>(b.title||'').trim().toLowerCase()===key))return;
    // 그 사이 입력값이 바뀌었으면(원서목록 선택으로 덮어쓰기 등) 버려진 값 — 제안하지 않음
    if(document.contains(inp)){const cur=(inp.value||'').trim().toLowerCase();if(cur&&cur!==key)return;}
    // 다른 확인창(삭제 확인 등)이 떠 있으면 덮어쓰지 않고 양보 (closeM은 display:none만 걸므로 둘 다 검사)
    const mc=document.getElementById('m-confirm');
    if(mc&&mc.classList.contains('open')&&mc.style.display!=='none')return;
    _libOfferDeclined.add(key); // confirm을 실제로 보여준 제목만 재확인하지 않음
    askConfirm('원서 DB에 추가',`"${title}" — 원서 목록에 없는 책이에요. 자료 DB에 추가할까요? (AR·시리즈·오디오는 나중에 보완 가능)`,'추가','bt',async()=>{
      const newLib={id:uid(),type:'library',title,series:'',arLevel:'',pages:'',publisher:'',description:''};
      try{await supaUpsert('global_textbooks',newLib.id,newLib,null);}
      catch(e){toast('저장 실패: '+e.message);return;}
      if(!_cache.library)_cache.library=[];
      _cache.library.push(newLib);
      try{renderLib();renderBookDB();renderMasterDB();populateLibSel();populateDataLists();updateTbookDatalist();}catch(e){}
      toast('원서 목록에 추가되었습니다');
    });
  },250);
}
// 클래스 기록 과제 행: 구분이 '원서'일 때만 원서 DB 추가 제안
function clHwBookOffer(inp){
  const row=inp.closest('.cl-hw-row');if(!row)return;
  if((row.querySelector('.cl-hw-cat')?.value||'')==='book')libOfferAdd(inp);
}
// 제목 매처: "제목" 또는 "제목 (레벨)" 표기 모두 같은 교재로 인식
function _tbSame(t){
  const s=(t||'').trim().toLowerCase();
  return x=>{
    const bt=(x.title||'').trim();
    return bt.toLowerCase()===s||((bt+(x.level?' ('+x.level+')':'')).toLowerCase()===s);
  };
}
// 교재 datalist 값: 동명 교재를 구분할 수 있게 레벨을 값에 포함
function _tbVal(b){return (b.title||'')+(b.level?' ('+b.level+')':'');}
// "제목 (레벨)" → base 제목 (실제 교재의 레벨 접미일 때만 제거 — 중복 비교용)
function _tbBase(t){
  t=(t||'').trim();
  const m=t.match(/^(.*)\s\(([^()]*)\)$/);
  if(m&&(_cache.globalTextbooks||[]).some(b=>(b.title||'').trim()===m[1].trim()&&String(b.level||'')===m[2]))return m[1].trim();
  return t;
}
// 구분+책 제목 → 범위 입력용 단원/과/챕터 datalist 옵션 생성 (교재·원서 공용 — 클래스5도 교재 단원 사용)
function _bookUnitOpts(cat,title){
  const t=(title||'').trim();
  if(!t)return '';
  const same=x=>(x.title||'').trim().toLowerCase()===t.toLowerCase();
  if(cat==='book'||(!cat&&(_cache.library||[]).some(same))){
    // 원서: 어휘 데이터의 챕터 목록
    const b=(_cache.library||[]).find(same);
    const chs=[...new Set((b?.vocab||[]).map(w=>w.chapter||w.unit).filter(Boolean))];
    return chs.map(c=>`<option value="${escAttr(c)}">`).join('');
  }
  // 교재: 단원 키 (+단원 제목 라벨) — "제목 (레벨)" 값도 매칭
  const tb=(_cache.globalTextbooks||[]).find(_tbSame(t));
  if(!tb)return '';
  const titles=tb.unitTitles||{};
  return tbUnitKeys(tb)
    .map(k=>`<option value="${escAttr(k)}">${k}${titles[k]?' — '+titles[k]:''}</option>`).join('');
}
// 책 선택 시 범위 입력에 단원/과/챕터 datalist 제공 (전 구분)
function clHwFillRangeDl(row){
  const dl=row.querySelector('datalist[data-role="range"]');if(!dl)return;
  let cat=row.querySelector('.cl-hw-cat')?.value||'';
  if(cat==='__custom__')cat='';
  dl.innerHTML=_bookUnitOpts(cat,row.querySelector('.cl-hw-book')?.value||'');
}
function clHwBookChange(inp){
  clHwBookOffer(inp);
  const row=inp.closest('.cl-hw-row');if(!row)return;
  clHwFillRangeDl(row);
}
// 학생 패널 과제 폼: 구분이 '원서'일 때만 원서 DB 추가 제안
function spAsgnBookOffer(inp,sid){
  if((document.getElementById('asgn-cat-'+sid)?.value||'')==='book')libOfferAdd(inp);
}
// 책 변경 시: 원서 제안 + 과 목록 datalist 채움 (learn 인자는 구 호출부 호환용)
function spAsgnBookChange(inp,sid,learn=true){
  spAsgnBookOffer(inp,sid);
  const t=(inp.value||'').trim();
  const dl=document.getElementById('dl-asgn-r-'+sid);if(!dl)return;
  let cat=document.getElementById('asgn-cat-'+sid)?.value||'';
  if(cat==='__custom__')cat='';
  dl.innerHTML=_bookUnitOpts(cat,t); // 교재 단원·원서 챕터 공용 (클래스5는 교재 단원)
}
function togglePdSing(btn){
  const row=btn.closest('.sr');
  const input=row.querySelector('input[data-f="unit"]');
  if(btn.classList.contains('active')){
    btn.classList.remove('active');
    if(input){input.style.display='none';input.value='';}
  }else{
    btn.classList.add('active');
    if(input){input.style.display='';setTimeout(()=>input.focus(),0);}
  }
}
// 진행 방식 바꾸면 그 자리에서 표시도 바뀌게 (동시 줄은 색으로 구분)
function _ecRunChange(sel){
  sel.classList.toggle('on',!!sel.value);
  const row=sel.closest('.sr');
  if(row)row.classList.toggle('sr-par',!!sel.value);
  if(sel.value)toast(sel.value==='hw'?'이 교재부터 새 줄 — 과제로 진행':'이 교재부터 새 줄 — 수업 중 진행');
}
// ── 접히는 사용법 ──
// 캘린더 밑에 한 줄로 늘어놓던 조작 설명(최대 272자)은 읽히지 않고 화면만 눌렀다.
// 범례는 색칩으로 남기고, 조작법은 접어두되 펼치면 '동작 → 결과' 표로 보이게 한다.
function _ppHelp(title,rows){
  return `<details class="pp-help">
    <summary class="pp-help-s">사용법 ${rows.length}가지</summary>
    <div class="pp-help-b">${rows.map(r=>`<span class="pp-help-r">
      <i>${r[0]}</i><b>${escAttr(r[1])}</b><em>${escAttr(r[2])}</em></span>`).join('')}</div>
  </details>`;
}

// ── 요일 배치판 ──
// 교재별 요일(mat.days)을 행마다 7개 칩으로 켜고 끄면 "화요일엔 무슨 교재를 나가지?"가 한눈에 안 보인다.
// 요일을 열로 세우고 교재를 칩으로 올려, 끌어서 옮기는 판으로 바꾼다.
// 이 판은 행의 .pg-day-chip을 그대로 읽고 쓰는 '보기'일 뿐이라 저장 로직(getSMatsFrom)은 손대지 않는다.
const _EC_DOW=['월','화','수','목','금','토','일'];
function _ecClassDays(){
  return [...document.querySelectorAll('#m-edit-class .day-check input:checked')].map(cb=>cb.value)
    .sort((a,b)=>_EC_DOW.indexOf(a)-_EC_DOW.indexOf(b));
}
// 요일을 가진 행(= 각 과목 체인의 첫 교재)만 판에 올린다
function _ecHeadRows(){
  return [...document.querySelectorAll('#ec-subj-rows .sr')].filter(r=>r.querySelector('.pg-days'));
}
function _ecRowDays(row){
  return [...row.querySelectorAll('.pg-day-chip.on')].map(x=>x.dataset.d);
}
function _ecSetRowDays(row,days){
  row.querySelectorAll('.pg-day-chip').forEach(ch=>ch.classList.toggle('on',days.indexOf(ch.dataset.d)>=0));
}
function _ecRowInfo(row){
  const base=(row.dataset.s||'').replace(/_\d+$/,'');
  const sel=row.querySelector('[data-f="book"]');
  const title=sel?(sel.value||'').trim():'';
  const chain=_ecChainRows(base).length;
  return {row,base,title,chain,days:_ecRowDays(row),
    label:SLBL[base]||base,color:_PG_CAT_COLORS[base]||'var(--text-muted)'};
}
function _ecBoardRender(){
  const wrap=document.getElementById('ec-board');if(!wrap)return;
  const cds=_ecClassDays();
  const infos=_ecHeadRows().map(_ecRowInfo).filter(x=>x.title);
  if(!cds.length||!infos.length){
    wrap.innerHTML=!infos.length?''
      :`<div class="ec-board-empty">요일을 먼저 고르면 교재를 요일별로 배치할 수 있어요</div>`;
    return;
  }
  const chip=(x,day)=>`<span class="ec-bchip" data-sub="${escAttr(x.base)}" data-day="${escAttr(day||'')}"
     style="--bc:${x.color}" title="${escAttr(x.title+(x.chain>1?` (체인 ${x.chain}권)`:''))}"
     onpointerdown="ecBChipDown(event,this)">
     <b>${escAttr(x.label)}</b><i>${escAttr(x.title)}</i>${x.chain>1?`<u>+${x.chain-1}</u>`:''}
     <em onpointerdown="event.stopPropagation()" onclick="ecBChipOff(this)" title="이 요일에서 빼기">×</em></span>`;
  const everyday=infos.filter(x=>!x.days.length);
  // 수업 없는 요일에만 지정된 교재 — 어느 열에도 안 떠서 손댈 수 없게 되는 걸 막는다
  // (저장 시 수업 요일과 교집합을 내므로 그대로 두면 '매 수업'으로 풀려 버린다)
  const orphan=infos.filter(x=>x.days.length&&!x.days.some(d=>cds.indexOf(d)>=0));
  const cols=cds.map(d=>{
    const on=infos.filter(x=>x.days.indexOf(d)>=0);
    const rest=infos.filter(x=>x.days.length&&x.days.indexOf(d)<0&&orphan.indexOf(x)<0);
    return `<div class="ec-bcol" data-day="${d}">
      <div class="ec-bcol-h">${d}<span>${on.length+everyday.length}과목</span></div>
      <div class="ec-bcol-b">${on.map(x=>chip(x,d)).join('')
        ||`<span class="ec-bnone">${everyday.length?'매 수업 교재만':'비어 있음'}</span>`}</div>
      ${rest.length?`<select class="ec-badd" onchange="ecBChipAdd(this,'${d}')" title="이 요일에 교재 추가">
        <option value="">+ 추가</option>${rest.map(x=>`<option value="${escAttr(x.base)}">${escAttr(x.label)} · ${escAttr(x.title)}</option>`).join('')}</select>`:''}
    </div>`;
  }).join('');
  wrap.innerHTML=`<div class="ec-board-head">
      <span class="ec-board-t">${luIcon('calendar',15)||''} 요일별 배치</span>
      <span class="ec-board-hint">칩을 끌어 다른 요일로 옮기세요</span>
      <button type="button" class="btn bo bxxs" onclick="ecBoardAuto()" title="어휘·파닉스는 매 수업, 어법·라이팅·내신은 주 첫 수업, 리딩·리스닝은 나머지 수업일에 배치합니다">✨ 자동 배치</button>
    </div>
    <div class="ec-bgrid" style="grid-template-columns:repeat(${cds.length},minmax(78px,1fr))">${cols}</div>
    <div class="ec-blane" data-day="">
      <span class="ec-blane-h">매 수업</span>
      <div class="ec-bcol-b">${everyday.map(x=>chip(x,'')).join('')||`<span class="ec-bnone">여기로 끌어오면 수업마다 진행해요</span>`}</div>
    </div>
    ${orphan.length?`<div class="ec-blane ec-blane-warn">
      <span class="ec-blane-h">⚠️ 수업 없는 요일</span>
      <div class="ec-bcol-b">${orphan.map(x=>chip(x,x.days[0])).join('')}</div>
      <span class="ec-blane-note">${orphan.map(x=>escAttr((SLBL[x.base]||x.base)+' → '+x.days.join('·'))).join(' / ')} — 수업 요일로 끌어 옮기거나 '매 수업'으로 보내 주세요</span>
    </div>`:''}`;
}
// from 요일의 칩을 to 요일로 옮긴 결과. to=''면 '매 수업'(요일 지정 없음)
function _ecMoveDays(days,from,to){
  if(!to)return [];
  const out=(days||[]).filter(x=>x!==from);
  if(out.indexOf(to)<0)out.push(to);
  return _EC_DOW.filter(d=>out.indexOf(d)>=0);
}
// 칩 끌어 옮기기 — 터치 공용(pointer), 드롭 대상은 요일 열 또는 '매 수업' 레인
let _ecBDrag=null;
function ecBChipDown(ev,chip){
  if(ev.button&&ev.button!==0)return;
  ev.preventDefault();
  const base=chip.dataset.sub,from=chip.dataset.day;
  _ecBDrag={base,from,chip,moved:false};
  chip.classList.add('ec-bchip-drag');
  chip.setPointerCapture&&chip.setPointerCapture(ev.pointerId);
  document.addEventListener('pointermove',_ecBMove);
  document.addEventListener('pointerup',_ecBUp,{once:true});
}
function _ecBZone(x,y){
  const el=document.elementFromPoint(x,y);
  return el?el.closest('.ec-bcol,.ec-blane'):null;
}
function _ecBMove(ev){
  if(!_ecBDrag)return;
  _ecBDrag.moved=true;
  document.querySelectorAll('#ec-board .ec-bover').forEach(z=>z.classList.remove('ec-bover'));
  const z=_ecBZone(ev.clientX,ev.clientY);
  if(z)z.classList.add('ec-bover');
  _ecBDrag.to=z?z.dataset.day:null;
}
function _ecBUp(ev){
  document.removeEventListener('pointermove',_ecBMove);
  const d=_ecBDrag;_ecBDrag=null;
  document.querySelectorAll('#ec-board .ec-bover').forEach(z=>z.classList.remove('ec-bover'));
  if(!d)return;
  d.chip.classList.remove('ec-bchip-drag');
  if(!d.moved)return;
  const z=_ecBZone(ev.clientX,ev.clientY);
  const to=z?(z.dataset.day||''):null;
  if(to===null||to===d.from)return;
  const row=_ecHeadRows().find(r=>(r.dataset.s||'').replace(/_\d+$/,'')===d.base);
  if(!row)return;
  const days=_ecMoveDays(_ecRowDays(row),d.from,to);
  _ecSetRowDays(row,days);
  _ecBoardRender();
  toast(to?`${SLBL[d.base]||d.base} → ${to}요일 (저장하면 반영)`:`${SLBL[d.base]||d.base} → 매 수업 (저장하면 반영)`);
}
function ecBChipOff(btn){
  const chip=btn.closest('.ec-bchip');if(!chip)return;
  const base=chip.dataset.sub,day=chip.dataset.day;
  const row=_ecHeadRows().find(r=>(r.dataset.s||'').replace(/_\d+$/,'')===base);
  if(!row)return;
  if(!day){toast('매 수업 교재예요 — 요일 열로 끌어 옮겨 주세요');return;}
  const days=_ecRowDays(row).filter(x=>x!==day);
  _ecSetRowDays(row,days);
  _ecBoardRender();
  toast(days.length?`${day}요일에서 뺐어요`:`${SLBL[base]||base}는 매 수업으로 바뀌었어요`);
}
function ecBChipAdd(sel,day){
  const base=sel.value;if(!base)return;
  const row=_ecHeadRows().find(r=>(r.dataset.s||'').replace(/_\d+$/,'')===base);
  if(!row){sel.value='';return;}
  const days=_ecRowDays(row);
  if(days.indexOf(day)<0)days.push(day);
  _ecSetRowDays(row,days);
  _ecBoardRender();
  toast(`${day}요일에 ${SLBL[base]||base} 추가`);
}
// 자동 배치 — 지금까지 쓰던 운영 방식을 기본값으로:
//   어휘·파닉스 = 매 수업 (수업 없는 날 숙제로도 나감)
//   어법·라이팅·내신 = 주 첫 수업 (호흡이 긴 과목을 한 날에 모음)
//   리딩·리스닝 = 나머지 수업일 전부 (같은 날 함께 — 진도량을 줄이지 않는다)
const _EC_EVERY=['vocab','phonics'];
const _EC_FIRST=['grammar','writing','naesin'];
// bases(과목 순서) × cds(수업 요일) → 과목별 요일 배정
function _ecAutoPlan(bases,cds){
  const plan={};
  if(!cds.length)return plan;
  const rest=cds.length>1?cds.slice(1):cds;
  bases.forEach(b=>{
    if(_EC_EVERY.indexOf(b)>=0)plan[b]=[];
    else if(_EC_FIRST.indexOf(b)>=0)plan[b]=[cds[0]];
    else plan[b]=rest.slice();
  });
  return plan;
}
function ecBoardAuto(){
  const cds=_ecClassDays();
  if(!cds.length){toast('요일을 먼저 골라 주세요');return;}
  const infos=_ecHeadRows().map(_ecRowInfo).filter(x=>x.title);
  if(!infos.length){toast('교재를 먼저 선택해 주세요');return;}
  const plan=_ecAutoPlan(infos.map(x=>x.base),cds);
  infos.forEach(x=>_ecSetRowDays(x.row,plan[x.base]||[]));
  _ecBoardRender();
  toast('자동 배치했어요 — 칩을 끌어 조정하고 저장하세요');
}
// 폼이 아는 칸 — 수정 저장 때 이 칸만 폼 값으로 덮고, 나머지(ar 등)는 기존 값을 지킨다
const _MAT_FORM_FIELDS=['book','unit','bookId','days','run'];
// 수정 저장 때 기존 materials 의 키 이름과 폼에 없는 필드를 지킨다.
// getSMatsFrom 은 화면의 행만 보고 키를 vocab, vocab_2 … 로 다시 번호 붙인다. 그래서 코멘트만
// 고쳐 저장해도 vocab_5 → vocab, _book_0 → _book 으로 키가 바뀌고, _pgMergeBook 이 넣어 둔
// ar(원서 AR 레벨)이 함께 사라졌다. 읽는 쪽은 모두 키 뒤 숫자를 떼고 보므로 화면은 멀쩡했지만,
// 같은 기록이 저장할 때마다 다른 모양이 되고 AR 은 돌아오지 않았다.
// 책(bookId 우선, 없으면 교재명)으로 짝을 찾아 원래 키와 남은 필드를 그대로 둔다.
function _mergeMatsKeepKeys(oldMats,newMats){
  const old=oldMats||{};
  const norm=s=>String(s||'').trim().toLowerCase();
  const usedOld=new Set(),takenKeys=new Set(),out={};
  Object.entries(newMats||{}).map(([nk,nv])=>{
    const base=nk.replace(/_\d+$/,'');
    const hit=Object.entries(old).find(([ok,ov])=>{
      if(usedOld.has(ok)||!ov)return false;
      if(ok.replace(/_\d+$/,'')!==base)return false;
      return (nv.bookId&&ov.bookId)?nv.bookId===ov.bookId:norm(nv.book)===norm(ov.book);
    });
    if(hit)usedOld.add(hit[0]);
    return {nk,nv,ok:hit?hit[0]:null,ov:hit?hit[1]:null};
  }).forEach(m=>{
    let key=m.ok||m.nk;
    if(takenKeys.has(key)){const base=key.replace(/_\d+$/,'');let i=2;key=base+'_'+i;while(takenKeys.has(key))key=base+'_'+(++i);}
    takenKeys.add(key);
    if(!m.ov){out[key]={...m.nv};return;}
    const merged={...m.ov};
    _MAT_FORM_FIELDS.forEach(f=>{if(f in m.nv)merged[f]=m.nv[f];else delete merged[f];});
    out[key]=merged;
  });
  return out;
}
// 칸이 들고 있던 키를 그대로 지킨다.
// 전에는 채워진 칸만 1번부터 다시 번호를 매겨, 앞 칸을 비워 두면 vocab_5 가 vocab 으로
// 바뀌었다 — 그 기록이 가리키던 교재 자리(체인 다섯째 권)가 첫째 권으로 바뀐다.
// 같은 키가 겹칠 때만(체인 '+' 로 같은 과목을 더했을 때) 빈 번호를 찾아 붙인다.
function getSMatsFrom(wrapperId){
  const r={},picked=[],used=new Set();
  document.querySelectorAll('#'+wrapperId+' .sr').forEach(row=>{
    const raw=String(row.dataset.s||'');
    const baseS=raw.replace(/_\d+$/,'');
    const bkEl=row.querySelector('[data-f="book"]');
    const b=bkEl.value.trim();
    const units=[...row.querySelectorAll('[data-f="unit"]')].map(el=>el.value.trim()).filter(Boolean);
    const u=units.join(', ');
    const bkId=bkEl.tagName==='SELECT'?(bkEl.options[bkEl.selectedIndex]?.dataset?.bkId||''):'';
    const daysEl=row.querySelector('.pg-days');
    const days=daysEl?[...daysEl.querySelectorAll('.pg-day-chip.on')].map(x=>x.dataset.d):null;
    const runEl=row.querySelector('[data-f="run"]');
    const run=runEl?String(runEl.value||''):'';
    if(b||u)picked.push({raw:raw,base:baseS||raw,key:'',
      v:{book:b,unit:u,...(bkId&&{bookId:bkId}),...(days&&days.length&&days.length<7?{days}:{}),...(run&&{run})}});
  });
  picked.forEach(x=>{if(x.raw&&!used.has(x.raw)){x.key=x.raw;used.add(x.raw);}});
  picked.forEach(x=>{
    if(x.key)return;
    let k=x.base,n=2;
    while(used.has(k))k=x.base+'_'+(n++);
    x.key=k;used.add(k);
  });
  picked.forEach(x=>{r[x.key]=x.v;});
  return r;
}
function getSMats(){return getSMatsFrom('subj-rows');}
function addUnitInput(btn,dlId){
  const wrap=btn.closest('.unit-inputs-wrap');if(!wrap)return;
  const st='flex:1;min-width:0;padding:7px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-size:13px;font-family:var(--fb);color:var(--navy);background:var(--cream);outline:none';
  const irow=document.createElement('div');
  irow.className='unit-irow';
  irow.style.cssText='display:flex;align-items:center;gap:3px';
  irow.innerHTML=`<input type="text" data-f="unit"${dlId?` list="${dlId}"`:''}placeholder="유닛/진도" autocomplete="off" style="${st}"><button type="button" onclick="this.closest('.unit-irow').remove()" style="flex-shrink:0;width:22px;height:22px;background:none;border:1px solid var(--border);border-radius:50%;cursor:pointer;font-size:16px;color:var(--slate);line-height:1;padding:0">×</button>`;
  wrap.appendChild(irow);
  irow.querySelector('input').focus();
}
function pdSelChange(sel){
  const row=sel.closest('.sr');
  const cus=row.querySelector('.pd-cus-inp');
  if(!cus)return;
  if(sel.value==='__other__'){
    sel.removeAttribute('data-f');sel.style.display='none';
    cus.setAttribute('data-f','book');cus.style.removeProperty('display');
    cus.value='';cus.focus();
  }else{
    sel.setAttribute('data-f','book');
    cus.removeAttribute('data-f');cus.style.display='none';
  }
}
function clearSRows(){aSubjs.clear();document.querySelectorAll('#subj-chips .chip').forEach(c=>c.classList.remove('active'));document.getElementById('subj-rows').innerHTML='';}
function clearEditSRows(){aEditSubjs.clear();document.querySelectorAll('#el-subj-chips .chip').forEach(c=>c.classList.remove('active'));document.getElementById('el-subj-rows').innerHTML='';}
function escAttr(s){return(s||'').replace(/"/g,'&quot;');}
function _catPill(txt){return txt?`<span style="display:inline-block;font-size:11.5px;font-weight:700;color:var(--slate);background:var(--cream2);border:1px solid var(--border);border-radius:8px;padding:1px 7px;margin-right:6px;vertical-align:1px">${txt}</span>`:'';}
function escJsA(s){return escAttr(String(s==null?'':s).replace(/\\/g,'\\\\').replace(/'/g,"\\'"));} // onclick 속성 안 JS 문자열 인자용 — Kipper's Diary 등 아포스트로피 안전
let _elCmtDirtyP=false,_elCmtDirtyS=false; // 수정 모달: 원문 변경 후 미리보기 미갱신 여부
function addElCmtChip(text){const ta=document.getElementById('el-cmt');if(!ta)return;ta.value=ta.value?(ta.value.trimEnd()+'. '+text):text;ta.focus();}
async function previewElPolishedCmt(){
  const raw=document.getElementById('el-cmt')?.value.trim()||'';
  const mats=getSMatsFrom('el-subj-rows');
  const matsText=_getMatsTextFromMaterials(mats);
  if(!raw&&!matsText){toast('키워드를 입력하거나 교재 진도를 먼저 선택해 주세요');return;}
  const status=document.getElementById('el-cmt-preview-status');
  if(status)status.textContent='변환 중...';
  const polished=await polishCmt(raw,matsText);
  if(status)status.textContent='';
  const box=document.getElementById('el-cmt-preview-box');
  const txt=document.getElementById('el-cmt-preview-text');
  if(box)box.style.display='block';
  if(txt)txt.value=polished||raw;
  _elCmtDirtyP=false; // 미리보기가 현재 원문과 일치
}
async function previewElStuCmt(){
  const raw=document.getElementById('el-cmt')?.value.trim()||'';
  const mats=getSMatsFrom('el-subj-rows');
  const matsText=_getMatsTextFromMaterials(mats);
  if(!raw&&!matsText){toast('키워드를 입력하거나 교재 진도를 먼저 선택해 주세요');return;}
  const status=document.getElementById('el-cmt-preview-status');
  if(status)status.textContent='학생 코멘트 생성 중...';
  const stuPolished=await polishStuCmt_teacher(raw,matsText,'');
  _elCmtDirtyS=false; // 학생 미리보기가 현재 원문과 일치
  if(status)status.textContent='';
  const box=document.getElementById('el-stu-cmt-preview-box');
  const txt=document.getElementById('el-stu-cmt-preview-text');
  if(box)box.style.display='block';
  if(txt)txt.value=stuPolished||'';
}
// 교재 진도 표시 — 앱 전체 공통 스타일
// [구분 배지] 교재명(굵게) + 진도 줄(들여쓰기, 한 줄씩)
function matLineHtml(label,cls,book,unitStr,ar){
  const units=(unitStr||'').split(', ').filter(Boolean);
  const unitHtml=units.length
    ?`<div style="margin-top:3px;padding-left:3px">${units.map(u=>`<div style="font-size:13px;color:var(--slate);line-height:1.7">${u}</div>`).join('')}</div>`
    :'';
  return `<div style="margin-bottom:9px">
    <div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap">
      ${label?`<span class="spill ${cls}" style="flex-shrink:0">${label}</span>`:''}
      <span style="font-weight:700;color:var(--navy);font-size:15px;font-family:var(--fd)">${book||''}</span>
      ${ar?`<span style="flex-shrink:0;font-size:11.5px;font-weight:700;color:var(--tealt);background:var(--tl);border-radius:6px;padding:1px 6px">AR ${ar}</span>`:''}
    </div>${unitHtml}
  </div>`;
}
function matsToHtml(materials){
  if(!materials)return '';
  return Object.entries(materials).map(([k,v])=>{
    const isBook=k==='_book'||k.startsWith('_book_');
    const baseKey=k.replace(/_\d+$/,'');
    const label=isBook?'원서':(SLBL[baseKey]||'');
    const cls=isBook?'srd':(SCLS[baseKey]||'');
    if(!label&&!v.book)return '';
    return matLineHtml(label,cls,v.book,v.unit,isBook?v.ar:'');
  }).filter(Boolean).join('');
}

// ── RUBRIC ──
const RUBRIC_DEF={
  speaking:{label:'🗣 말하기',cats:['발음','유창성','어휘','어법','내용'],levels:['1·시작','2·발전','3·능숙','4·우수']},
  writing:{label:'✍️ 쓰기',cats:['아이디어','구성','어휘','어법','맞춤법'],levels:['1·시작','2·발전','3·능숙','4·우수']}
};
let _rubricActive=false,_rubricType='speaking',_rubricScores={};
function toggleRubric(){
  _rubricActive=!_rubricActive;
  const sec=document.getElementById('rubric-section');if(sec)sec.style.display=_rubricActive?'block':'none';
  const arrow=document.getElementById('rubric-arrow');if(arrow)arrow.textContent=_rubricActive?'▲':'▼';
  if(_rubricActive)renderRubricRows();
}
function setRubricType(type){
  _rubricType=type;
  const sp=document.getElementById('rbtn-sp');const wr=document.getElementById('rbtn-wr');
  if(sp){sp.className='btn bsm '+(type==='speaking'?'bt':'bo');sp.style.fontSize='11px';}
  if(wr){wr.className='btn bsm '+(type==='writing'?'bt':'bo');wr.style.fontSize='11px';}
  renderRubricRows();
}
function renderRubricRows(){
  const el=document.getElementById('rubric-rows');if(!el)return;
  const{cats,levels}=RUBRIC_DEF[_rubricType];
  el.innerHTML=cats.map(cat=>{
    const cur=_rubricScores[cat]||0;
    return`<div style="display:flex;align-items:center;gap:4px;margin-bottom:5px">
      <span style="width:48px;font-size:12px;font-weight:600;color:var(--navy);flex-shrink:0">${cat}</span>
      ${levels.map((lbl,i)=>{const v=i+1,a=cur===v;return`<button type="button" onclick="setRubricScore('${cat}',${v})" style="flex:1;padding:4px 2px;border-radius:4px;font-size:11.5px;cursor:pointer;white-space:nowrap;border:1.5px solid ${a?'var(--teal)':'var(--border)'};background:${a?'var(--teal)':'#fff'};color:${a?'#fff':'var(--slate)'};font-family:var(--fb)">${lbl}</button>`;}).join('')}
    </div>`;
  }).join('');
}
function setRubricScore(cat,val){_rubricScores[cat]=(_rubricScores[cat]===val?0:val);renderRubricRows();}
function clearRubric(){_rubricScores={};renderRubricRows();}
function getRubricData(){
  const{cats}=RUBRIC_DEF[_rubricType];
  const scored=cats.filter(c=>_rubricScores[c]>0);
  if(!_rubricActive||!scored.length)return null;
  const scores={};scored.forEach(c=>scores[c]=_rubricScores[c]);
  return{type:_rubricType,scores};
}
function _resetRubric(){
  _rubricActive=false;_rubricScores={};
  const s=document.getElementById('rubric-section');if(s)s.style.display='none';
  const a=document.getElementById('rubric-arrow');if(a)a.textContent='▼';
}
// ── LESSONS ──
async function saveLes(){
  if(_saving['saveLes'])return; _saving['saveLes']=true;
  try{
  const sid=document.getElementById('ls-stu').value;if(!sid){toast('학생을 선택해 주세요');return;}
  const _lesDate=document.getElementById('ls-date').value;
  if(_lesDate>ppToday()){toast('미래 날짜예요 — 수업 계획은 진도 캘린더의 점선(예정)으로 관리하고, 기록은 수업 당일부터 저장해 주세요');return;}
  const _existingLes=(_cache.lessons||[]).filter(l=>l.sid===sid&&l.date===_lesDate);
  if(_existingLes.length){
    toast('이 날 수업 기록이 이미 있습니다. 기존 기록 수정 창을 엽니다.');
    setTimeout(()=>openEditLes(_existingLes[0].id),900);
    return;
  }
  const _sStu=DB.stus().find(x=>x.id===sid);
  const rawCmt=document.getElementById('ls-cmt').value.trim();
  toast('저장 중...');
  const mats=getSMats();
  const matsText=_getMatsTextFromMaterials(mats);
  // 미리보기에서 편집된 텍스트 우선 사용, 없으면 생성
  const previewTxt=(document.getElementById('cmt-preview-box')?.style.display!=='none')
    ?(document.getElementById('cmt-preview-text')?.value?.trim()||''):'';;
  // 미리보기로 직접 만든 글이 있으면 그것을, 없으면 코멘트를 쓴 경우에만 AI 를 부른다
  const polishedCmt=previewTxt
    || (_polishedCmtCache.raw===rawCmt&&_polishedCmtCache.polished ? _polishedCmtCache.polished : '')
    || (String(rawCmt||'').trim() ? await polishCmt(rawCmt,matsText) : '');
  // 학생 응원 코멘트 - 미리보기 편집본 우선, 없으면 생성
  const stuPreviewTxt=(document.getElementById('stu-cmt-preview-box')?.style.display!=='none')
    ?(document.getElementById('stu-cmt-preview-text')?.value?.trim()||''):'';
  const stuCmt=stuPreviewTxt||_polishedCmtCache.stuCmt
    ||(String(rawCmt||'').trim()?await polishStuCmt_teacher(rawCmt,matsText,_sStu?.name||''):'');
  if(rawCmt&&polishedCmt)_saveCmtExample(rawCmt,polishedCmt);
  const _sStuGrade=(_sStu&&(_sStu.grade||_sStu.lv))||'';
  const _rubric=getRubricData();
  const newLes={id:uid(),sid,date:document.getElementById('ls-date').value,grade:_sStuGrade,att:document.getElementById('ls-att').value,materials:mats,cmt:rawCmt,polishedCmt,stuCmt,...(_rubric?{rubric:_rubric}:{})};
  await supaUpsert('lessons',newLes.id,newLes,sid);
  _cache.lessons.unshift(newLes);
  (async()=>{
    await addUnitWordsToVocab(sid,newLes.materials,newLes.date).catch(e=>console.error('vocab sync:',e));
    await autoSyncBookReads(sid,newLes.materials,newLes.date).catch(e=>console.warn('autoSyncBookReads 실패:',e));
  })();
  document.getElementById('ls-cmt').value='';clearSRows();
  document.getElementById('ls-last-hint').style.display='none';
  _polishedCmtCache={raw:'',polished:'',stuCmt:'',matsText:''};
  const _pb=document.getElementById('cmt-preview-box');if(_pb)_pb.style.display='none';
  const _sb=document.getElementById('stu-cmt-preview-box');if(_sb)_sb.style.display='none';
  const _ph=document.getElementById('polished-ready-hint');if(_ph)_ph.style.display='none';
  _resetRubric();renderLes();
  if(typeof renderStus==='function')renderStus();   // 목록의 '최근 수업' 칸
  toast('수업 기록이 저장되었습니다');
  checkNewBadges(sid);
  const _dupW=document.getElementById('les-dup-warn');if(_dupW)_dupW.style.display='none';
  showLesFollowup(sid,newLes.date,_sStu?.name||'');
  setTimeout(()=>{const fu=document.getElementById('les-followup');if(fu&&fu.style.display!=='none')fu.scrollIntoView({behavior:'smooth',block:'nearest'});},200);
  }catch(e){
    console.error('save error:',e);
    toast('저장 중 오류가 발생했습니다. 입력 내용은 유지됩니다.');
    document.querySelectorAll('button[disabled]').forEach(b=>b.disabled=false);
  }finally{
    showLoading(false);
    Object.keys(_saving).forEach(k=>_saving[k]=false);
  }
}
