// ── QR CODE ──
function renderQRCode(){
  const el=document.getElementById('qr-result');if(!el)return;
  const sid=document.getElementById('qr-stu-sel')?.value;
  if(!sid){el.innerHTML='';return;}
  const s=DB.stus().find(x=>x.id===sid);if(!s){el.innerHTML='';return;}
  const role=document.querySelector('input[name="qr-role"]:checked')?.value||'student';
  const pin=s.pin||'';
  if(!pin){el.innerHTML='<div style="color:var(--slate);font-size:13px">PIN이 설정되지 않은 학생입니다</div>';return;}
  const baseUrl='https://page-and-pencil.github.io/page-pencil/';
  // QR 은 PIN 대신 무작위 토큰을 쓴다 — 주소·캡처에 PIN 이 남지 않고, 새로 만들면 옛 링크가 막힌다.
  // 토큰이 없는 학생은 이 화면을 열 때 만들어 저장한다 (기존 행 일괄 변경은 하지 않는다).
  const tok=s.qrToken||'';
  if(!tok){qrEnsureToken(sid);el.innerHTML='<div style="color:var(--slate);font-size:13px">QR 링크를 만드는 중…</div>';return;}
  const target=`${baseUrl}?t=${encodeURIComponent(tok)}&role=${role}`;
  const qrUrl=`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(target)}`;
  el.innerHTML=`<div>
    <div style="font-size:13px;color:var(--slate);margin-bottom:8px;white-space:nowrap">${s.name} (${role==='student'?'학생':'학부모'})</div>
    <img src="${qrUrl}" alt="QR" style="width:200px;height:200px;border:1px solid var(--border);border-radius:var(--rs)">
    <div style="margin-top:8px;display:flex;gap:6px;justify-content:center;flex-wrap:wrap">
      <a href="${qrUrl}" download="${s.name}_QR.png" class="btn bo bsm">⬇ 이미지 저장</a>
      <button class="btn ba bsm" onclick="window.print()">🖨 인쇄</button>
      <button class="btn bo bsm" onclick="navigator.clipboard.writeText('${target}').then(()=>toast('링크 복사됨'))">🔗 링크 복사</button>
      <button class="btn bo bsm" onclick="qrRenewToken('${escAttr(sid)}')" title="새로 만들면 지금까지 보낸 링크는 열리지 않습니다">♻ QR 새로 만들기</button>
    </div>
    <div style="font-size:11.5px;color:var(--slate);margin-top:6px;word-break:break-all">${target}</div>
    <div style="font-size:11.5px;color:var(--slate);margin-top:6px;line-height:1.6">예전에 보낸 <b>?pin=</b> 링크는 아직 열리지만 곧 막힙니다 — 새 링크로 다시 보내 주세요.</div>
  </div>`;
}
// QR 토큰 — 없으면 만들어 저장 (학생 행의 선택 필드, 옛 행을 일괄로 고치지 않는다)
function _qrNewToken(){
  const a=new Uint8Array(24);crypto.getRandomValues(a);
  return Array.from(a).map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,32);
}
async function qrEnsureToken(sid){
  const s=DB.stus().find(x=>x.id===sid);if(!s)return '';
  if(s.qrToken)return s.qrToken;
  s.qrToken=_qrNewToken();
  try{await supaUpsert('students',sid,s,null);}catch(e){console.warn('QR 토큰 저장 실패:',e);toast('QR 링크 저장에 실패했어요');return '';}
  renderQRCode();
  return s.qrToken;
}
async function qrRenewToken(sid){
  askConfirm('QR 새로 만들기','지금까지 보낸 링크는 더 이상 열리지 않습니다. 새로 만들까요?','새로 만들기','bd',async()=>{
    const s=DB.stus().find(x=>x.id===sid);if(!s)return;
    s.qrToken=_qrNewToken();
    try{await supaUpsert('students',sid,s,null);}catch(e){toast('저장에 실패했어요');return;}
    renderQRCode();toast('새 QR 링크를 만들었어요 — 옛 링크는 막혔습니다');
  });
}

// ── CLASSES ──
const clSubjs=new Set();

let _currentClsId=null;
function renderClassTab(){
  const classes=DB.classes().filter(c=>c.active!==false);
  const allStus=DB.stus().filter(s=>!s.inactive);
  const DAYS=['일','월','화','수','목','금','토'];
  const todayDay=DAYS[new Date().getDay()];
  const todayStr=ppToday();

  // 상단 주간 시간표
  const ttEl=document.getElementById('cls-timetable');
  if(ttEl){
    const WEEKDAYS=['월','화','수','목','금','토'];
    const ttCols=WEEKDAYS.map(day=>{
      const dayCls=classes.filter(c=>(c.days||[]).includes(day))
        .sort((a,b)=>(classTimeFor(a,day).start||'99').localeCompare(classTimeFor(b,day).start||'99'));
      const isToday=day===todayDay;
      return`<div style="min-width:0">
        <div style="font-size:12px;font-weight:600;text-align:center;padding:6px 2px;background:${isToday?'var(--row-selected)':'var(--bg)'};color:${isToday?'var(--avatar-text)':'var(--text-muted)'};border:1px solid ${isToday?'var(--accent)':'var(--border)'};border-bottom:none;border-radius:var(--r-ctl) var(--r-ctl) 0 0">${day}${isToday?' <span style="font-size:8.5px;font-weight:600;opacity:.95">오늘</span>':''}</div>
        <div style="border:1px solid ${isToday?'var(--accent)':'var(--border)'};border-top:none;border-radius:0 0 var(--r-ctl) var(--r-ctl);min-height:48px;padding:4px;background:var(--surface)">
          ${dayCls.map(c=>`<div style="background:${isToday?'var(--row-selected)':'var(--bg)'};border-radius:5px;padding:4px 6px;margin-bottom:2px;cursor:pointer;line-height:1.3" onclick="openClsDetail('${c.id}')">
            <div style="font-size:9.5px;font-weight:600;color:var(--navy);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${c.name}</div>
            ${classTimeStr(c,day)?`<div style="font-size:8.5px;color:var(--slate);opacity:.85">${classTimeStr(c,day)}</div>`:''}
          </div>`).join('')}
        </div>
      </div>`;
    }).join('');
    ttEl.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
      <span style="font-size:12px;font-weight:700;color:var(--navy)">${luIcon('calendar',15)||''} 주간 시간표</span>
      <span style="font-size:11.5px;color:var(--slate)">탭하면 상세 보기</span>
    </div>
    <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:3px">${ttCols}</div>`;
  }

  // 왼쪽 클래스 카드 목록
  const listEl=document.getElementById('cls-list-inner');
  if(listEl){
    if(!classes.length){
      listEl.innerHTML=`<div style="padding:20px;text-align:center;color:var(--slate);font-size:13px">클래스 없음<br><button class="btn bt bsm" style="margin-top:8px" onclick="openEditClass()">+ 만들기</button></div>`;
    }else{
      listEl.innerHTML=classes.map(c=>{
        const stus=allStus.filter(s=>(c.studentIds||[]).includes(s.id));
        const isToday=(c.days||[]).includes(todayDay);
        const done=isToday&&DB.less().some(l=>l.date===todayStr&&l.classId===c.id);
        const isActive=_currentClsId===c.id;
        return`<div class="cls-card${isToday?' today-cls':''}${isActive?' active':''}" onclick="openClsDetail('${c.id}')">
          <div style="display:flex;align-items:center;gap:4px;margin-bottom:2px">
            <span style="font-size:14px;font-weight:700;color:var(--navy);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${c.name}</span>
            ${isToday&&!done?'<span style="font-size:9.5px;padding:1px 5px;background:var(--teal);color:#fff;border-radius:8px;flex-shrink:0">오늘</span>':''}
            ${done?'<span style="font-size:9.5px;padding:1px 5px;background:var(--okt);color:#fff;border-radius:8px;flex-shrink:0">✓완료</span>':''}
          </div>
          <div style="font-size:11.5px;color:var(--slate)">${[classSchedStr(c),stus.length+'명'].filter(Boolean).join(' · ')}</div>
        </div>`;
      }).join('');
    }
  }

  // 열려있는 클래스 detail 새로고침
  if(_currentClsId)renderClsLessons(_currentClsId);
}
function openClsDetail(classId){
  _currentClsId=classId;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const allStus=DB.stus().filter(s=>!s.inactive);
  const stus=allStus.filter(s=>(c.studentIds||[]).includes(s.id));
  const todayStr=ppToday();
  const DAYS=['일','월','화','수','목','금','토'];
  const todayDay=DAYS[new Date().getDay()];
  const isToday=((c.days||[]).includes(todayDay)||(c.extraDates||[]).includes(todayStr))&&!(c.skipDates||[]).includes(todayStr); // 휴강 제외, 추가 수업일 포함
  const done=isToday&&DB.less().some(l=>l.date===todayStr&&l.classId===classId);
  // active card 표시
  document.querySelectorAll('#cls-list-inner .cls-card').forEach(el=>el.classList.toggle('active',el.getAttribute('onclick')===`openClsDetail('${classId}')`));
  // header
  const hdr=document.getElementById('cls-detail-header');
  if(hdr)hdr.innerHTML=`<div style="flex:1;min-width:0">
    <button class="sp-back-btn cls-back-btn" style="display:none" onclick="closeClsDetail()">← 목록</button>
    <div style="font-size:16px;font-weight:700;color:var(--navy)">${c.name}</div>
    <div style="font-size:13px;color:var(--slate);margin-top:2px">${[classSchedStr(c),'학생 '+stus.length+'명'].filter(Boolean).join(' · ')}</div>
    <div style="margin-top:6px;display:flex;flex-wrap:wrap;gap:4px">${stus.map(s=>`<span class="class-stu-chip" onclick="loadStuPanel('${s.id}')">${s.name}</span>`).join('')||'<span style="font-size:12px;color:var(--slate)">학생 없음</span>'}</div>
  </div>
  <div style="display:flex;gap:6px;align-items:flex-start;flex-shrink:0;flex-wrap:wrap">
    ${isToday&&!done?`<button class="btn bt bsm" onclick="openClassLesson('${classId}','${todayStr}')">수업 기록</button>`:''}
    ${done?`<button class="btn bo bsm" onclick="openClassLessonEdit('${classId}','${todayStr}')">오늘 수정</button>`:''}
    ${!isToday?`<button class="btn bt bsm" onclick="openClassLesson('${classId}')">수업 기록</button>`:''}
    <button class="btn bo bsm" onclick="openEditClass('${classId}')">클래스 수정</button>
  </div>`;
  // show detail pane
  document.getElementById('cls-no-sel').style.display='none';
  const wrap=document.getElementById('cls-detail-wrap');
  if(wrap){wrap.style.display='flex';}
  document.getElementById('cls-split')?.classList.add('detail-open');
  renderClsLessons(classId);
}
function closeClsDetail(){
  document.getElementById('cls-split')?.classList.remove('detail-open');
}
function cmtToPills(cmt){
  // 코멘트 문자열을 구분자(. / , ; 줄바꿈)로 분리해 각각 pill로 렌더. 단어 내 ·는 보존.
  return String(cmt||'').split(/\s*[\/.,;\n]+\s*/).map(s=>s.trim()).filter(Boolean)
    .map(p=>`<span class="cls-cmt-pill">${p}</span>`).join('');
}
function renderClsLessons(classId){
  const el=document.getElementById('cls-lessons-body');if(!el)return;
  if(_pgCalClsId!==classId){_pgCalClsId=classId;_pgCalMonth='';}
  pgMoveCancel();
  // 이 반이 어느 교재 어디쯤 왔는지 — 진도판 위에 한 장으로 (반 전체 수업 기록 합산)
  const _c0=(DB.classes()||[]).find(x=>x.id===classId);
  const _sids=_c0?((_c0.studentIds||_c0.sids||[]).filter(x=>(DB.stus()||[]).some(st=>st.id===x&&!st.inactive))):[];
  const bpHtml=(typeof ppBookPathHtml==='function'&&_sids.length)
    ? ppBookPathHtml(_sids,{bare:true,cid:classId}) : '';
  const bpCard=bpHtml?('<details class="dash-fold" style="margin-bottom:12px"><summary class="dash-fold-sum">🗺️ 교재 여정 — 끝낸 책 · 지금 · 다음</summary>'
    +'<div style="padding:12px 2px 2px">'+bpHtml+'</div></details>'):'';
  const calHtml=bpCard+_pgTrackBoardHtml(classId)+_pgHwPanelHtml(classId)+_pgCalHtml(classId);
  const allStus=DB.stus().filter(s=>!s.inactive);
  const todayStr=ppToday();
  // group lessons by date
  const rawLes=(DB.less()||[]).filter(l=>l.classId===classId).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const byDate=new Map();
  rawLes.forEach(l=>{
    if(!byDate.has(l.date))byDate.set(l.date,[]);
    byDate.get(l.date).push(l);
  });
  if(!byDate.size){
    el.innerHTML=calHtml+`<div class="empty boxed sm"><div class="empty-i">${luIcon('book-open',15)||''}</div><div class="empty-t">아직 수업 기록이 없습니다</div></div>`;
    return;
  }
  const rows=[...byDate.entries()].map(([date,les])=>{
    // collect materials across all student records for this date
    const commonMats=new Map();
    les.forEach(l=>{
      Object.entries(l.materials||{}).forEach(([k,v])=>{
        if(!v.book)return;
        const isBook=k==='_book'||k.startsWith('_book_');
        const baseKey=k.replace(/_\d+$/,'');
        const label=isBook?'원서':(SLBL[baseKey]||'');
        const cls=isBook?'srd':(SCLS[baseKey]||'');
        const key=`${label}::${v.book}`;
        if(!commonMats.has(key))commonMats.set(key,{label,cls,book:v.book,units:new Set()});
        (v.unit||'').split(', ').filter(Boolean).forEach(u=>commonMats.get(key).units.add(u));
      });
    });
    const matsHtml=[...commonMats.values()].map(m=>{
      const units=[...m.units];
      return`<div class="cls-les-mat-l"><span class="cls-les-mat-book">${m.book}</span><span class="spill ${m.cls}" style="font-size:11.5px">${m.label}</span></div><div class="cls-les-mat-prog">${units.length?units.join(', '):'<span class="none">진도 미기록</span>'}</div>`;
    }).join('');
    // per-student attendance — 정상 출석은 헤더에 이미 노출되므로 예외(지각·결석 등)만 표시
    const attRows=les.filter(l=>l.att&&l.att!=='normal').map(l=>{
      const stu=allStus.find(s=>s.id===l.sid);
      return`<span>${stu?.name||'—'} <span class="att-chip ${ATTCLS[l.att]}" style="font-size:9.5px;padding:0 5px">${ATTLBL[l.att]}</span></span>`;
    }).join(' · ');
    const cmtPills=cmtToPills(les[0]?.cmt);
    const isTodayDate=date===todayStr;
    return`<div class="cls-les-card">
      <div class="cls-les-head">
        <span class="cls-les-date">${date}${isTodayDate?' · <span class="cls-today-lbl">오늘</span>':''}</span>
        <button class="btn bo bxxs" onclick="openClassLessonEdit('${classId}','${date}')">✏️ 수정</button>
      </div>
      ${matsHtml?`<div class="cls-les-mats">${matsHtml}</div>`:''}
      ${attRows?`<div class="cls-les-att">${attRows}</div>`:''}
      ${cmtPills?`<div class="cls-les-cmt">${cmtPills}</div>`:''}
    </div>`;
  }).join('');
  el.innerHTML=calHtml+`<div class="cls-lessons-wrap">${rows}</div>`;
}

// ═════════ 클래스 진도 자동화: 다음 단원 계산 + 진도 캘린더 + 드래그 이동 ═════════
let _pgCalMonth='',_pgCalClsId='',_pgDrag=null,_pgMoveSel=null;
const _PG_DOW=['일','월','화','수','목','금','토'];
const _pgYmd=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
// 과목(카테고리)별 칩 색 — 과목 pill(spill) 색 계열과 통일. 원서는 보라 한 색.
const _PG_CAT_COLORS={phonics:'#0EA5E9',vocab:'#1D4ED8',grammar:'#5B21B6',reading:'var(--okt)',listening:'#D97706',writing:'#DB2777',naesin:'#EA580C'};
const _PG_ORT_COLOR='#7C3AED';
function _pgNorm(x){return String(x||'').toLowerCase().replace(/[^a-z0-9가-힣]/g,'');}
// 'unit1' vs 'unit1newfriends' 표기 차이 흡수 — 숫자 경계 보호로 unit11 오매칭 방지
function _pgUMatch(a,b){
  if(!a||!b)return false;if(a===b)return true;
  const p=(x,y)=>x.startsWith(y)&&!/^\d/.test(x.slice(y.length));
  return p(a,b)||p(b,a);
}
// 교재 찾기·마지막 기록·줄 나누기는 공용(utils.js ppTbOf/ppLastRec/ppTracksOf)으로 옮겼다.
// 학생·학부모 화면도 같은 판정을 써야 해서다. 이름은 부르는 곳이 많아 그대로 둔다.
function _pgTbOf(mat){return ppTbOf(mat);}
// 진도 문자열("DAY 01, DAY 02")에서 가장 뒤쪽 단원의 목차 인덱스 (-1=매칭 없음)
function _pgUnitIdx(tb,unitStr,ctx){
  // 공용 매칭(ppMatchUnit)으로 옮김 (2026-11-08) — 쉼표 분해·소제목·별칭·Review 범위까지 같은 규칙
  // ctx(클래스·날짜)를 주면 번호 없는 'Review' 도 정해진다 (2026-11-09). 안 주면 종전과 같다.
  if(ctx&&typeof ppUnitIdxCtx==='function')return ppUnitIdxCtx(tb,unitStr,ctx);
  return (typeof ppUnitIdx==='function')?ppUnitIdx(tb,unitStr):-1;
}
// 클래스에서 이 교재의 마지막 기록 {idx,date} — 최신 수업일 우선 (미래 기록은 진도 계산 제외)
// 이 교재의 진도 = **가장 멀리 나간 단원**. '마지막 날짜의 단원'으로 잡으면 복습으로 앞 단원을
// 한 번 더 한 날이 진도를 되감아 이미 나간 단원이 예정에 다시 깔린다
// (345 Grammar 1: 10/20 Unit 14 → 10/27 Unit 13 기록 → 11월 첫 수업이 Unit 14로 잡히던 문제).
// 숙제 쪽 recurRebase는 원래부터 maxIdx 기준이라 둘이 어긋나 있었음 — 같은 기준으로 맞춤.
// c.doneUpto[교재id]='단원' = 선생님이 진도 보드에서 직접 지정한 '여기까지 끝냄' (기록 없는 진도 보정)
function _pgLastRec(classId,tb){return ppLastRec(classId,tb);}
// 이 교재가 기록된 날짜 집합 (예정 칩이 기록 있는 날을 건너뛰게)
function _pgRecDates(classId,tb){
  const s=new Set();
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.date||!l.materials)return;
    if(Object.values(l.materials).some(m=>m&&m.book&&(m.bookId?m.bookId===tb.id:m.book===tb.title)))s.add(l.date);
  });
  return s;
}
// 다음에 나갈 단원 키 — 기록 있으면 그 다음, 없으면 클래스에 저장된 시작 단원(또는 첫 단원). 완강이면 ''
function _pgNextUnit(classId,tb,storedUnit){
  const keys=tbUnitKeys(tb);if(!keys.length)return '';
  const rec=_pgLastRec(classId,tb);
  if(rec)return keys[rec.idx+1]||'';
  const si=_pgUnitIdx(tb,storedUnit);
  return si>=0?keys[si]:keys[0];
}
// **줄(track)마다** 지금 진행 중인 교재를 하나씩 — 같은 영역에 줄이 둘이면(과제 줄·수업 줄) 둘 다.
// 전에는 영역당 한 권만 돌려줘서, 수업 기록 창에 어휘 줄 하나가 통째로 빠졌다.
// opts.date 를 주면 그 날 도는 책만 (교재에 요일이 정해져 있으면 mat.days 로 거른다).
// 범례·수업 폼·학생 교재 동기화·과제 자동 채움이 공유한다.
function _pgActiveMats(classId,c,opts){
  const o=opts||{};
  const out={};
  const dow=o.date?_PG_DOW[new Date(o.date+'T12:00:00').getDay()]:'';
  const okDay=mat=>{
    if(!dow)return true;
    const ds=mat&&mat.days;
    return !(Array.isArray(ds)&&ds.length)||ds.indexOf(dow)>=0;
  };
  const flow=(typeof ppFlow==='function')?ppFlow(classId):[];
  const seen=new Set();
  flow.forEach(area=>{
    (area.tracks||[]).forEach(t=>{
      (t.books||[]).forEach(b=>seen.add(b.key));
      const b=t.now||((t.books||[]).length?t.books[t.books.length-1]:null); // 전부 완강이면 마지막 책
      if(b&&okDay(b.mat))out[b.key]=b.mat;
    });
  });
  // 흐름에 못 들어간 교재 — 내신(병행)과 교재 DB에 없는 책은 종전대로
  const groups={};
  Object.entries(c.commonMaterials||{}).forEach(([k,v])=>{
    if(!v||seen.has(k))return;
    const base=k.replace(/_\d+$/,'');
    if(base==='naesin'){if(okDay(v))out[k]=v;return;}
    (groups[base]=groups[base]||[]).push([k,v]);
  });
  Object.entries(groups).forEach(([base,list])=>{
    if(Object.keys(out).some(k=>k===base||k.startsWith(base+'_')))return;  // 그 영역은 흐름이 이미 채웠다
    const pick=list[0];
    if(pick&&okDay(pick[1]))out[pick[0]]=pick[1];
  });
  return out;
}
// 한 권만 필요한 곳(단어 시험지·과제 자동 채움)은 **과제로 도는 줄**의 책을 먼저 고른다
function _pgActiveMatPick(classId,c,base){
  const flow=(typeof ppFlow==='function')?ppFlow(classId):[];
  const area=flow.find(a=>a.area===base||a.key===base);
  if(area){
    const live=(area.tracks||[]).filter(t=>t.now);
    const t=live.find(x=>x.mode==='hw')||live[0];
    if(t&&t.now)return [t.now.key,t.now.mat];
  }
  const am=_pgActiveMats(classId,c);
  return Object.entries(am).find(([k])=>k===base||k.startsWith(base+'_'))||null;
}
// 오늘~uptoDate의 예정 진도 {날짜:단원키} — 앵커(드래그로 옮긴 기준점) 반영, skipDates=펜슬다운 등 제외일
// 다중 핀 배치 (2026-08-04): 유닛별 핀은 지정 날짜에 고정(같은 날 여러 개면 합쳐 표시),
// 핀 없는 유닛은 핀 날짜를 제외한 수업일에 순서대로 — 방향 무관·소실 없음·여러 번 드래그해도 각 핀 유지
function _pgPlacePinned(remaining,slots,pins,todayStr,normFn,matchFn){
  const placed={};
  const pinByIdx={};
  (pins||[]).forEach(pn=>{
    if(!pn||!pn.unit||!pn.date||pn.date<todayStr)return;
    const parts=String(pn.unit).split(',').map(x=>x.trim()).filter(Boolean);
    const list=(parts.length>1&&parts.every(pt=>remaining.some(k=>matchFn(normFn(k),normFn(pt)))))?parts:[pn.unit];
    list.forEach(u=>{const i=remaining.findIndex(k=>matchFn(normFn(k),normFn(u)));if(i>=0&&!(i in pinByIdx))pinByIdx[i]=pn.date;});
  });
  Object.entries(pinByIdx).forEach(([i,d])=>{(placed[d]=placed[d]||[]).push(remaining[i]);}); // 같은 날 여러 유닛도 개별 항목(칩 하나씩)
  const pinDates=new Set(Object.values(pinByIdx));
  const free=slots.filter(d=>!pinDates.has(d));
  // 핀 안 걸린 유닛을 빈 슬롯에 순서대로 — 단 **순서 역전 금지**: 앞 유닛을 뒤로 밀었으면
  // 뒤 유닛이 그보다 앞 슬롯을 채우지 않는다 (U4를 다음 주로 밀었는데 U6이 이번 주에 오던 문제)
  const pinIdxs=Object.keys(pinByIdx).map(Number);
  let si=0;
  remaining.forEach((u,idx)=>{
    if(idx in pinByIdx)return;
    let after=''; // 이 유닛보다 앞선 핀 유닛들이 잡은 가장 늦은 날짜
    pinIdxs.forEach(pi=>{if(pi<idx&&pinByIdx[pi]>after)after=pinByIdx[pi];});
    while(si<free.length&&after&&free[si]<=after)si++;
    if(si<free.length)placed[free[si++]]=[u];
  });
  return placed;
}
function _pgAncPins(anc){
  if(!anc)return[];
  if(Array.isArray(anc.pins))return anc.pins;
  return anc.unit?[{unit:anc.unit,date:anc.date}]:[];
}
// slotPick(d,i): 병행(교대) 배치용 — 이 책이 쓸 슬롯만 고르는 필터 (i=과목 공통 슬롯 순번)
// 이 교재를 그 날짜에서 빼뒀는가 (예정 편집 모달 ✕ — c.slotSkip={tbId:[날짜,…]})
function _pgSlotSkipped(c,tbId,ds){
  const l=((c&&c.slotSkip)||{})[tbId];
  return !!(l&&l.indexOf(ds)>=0);
}
// 그 날이 이 클래스의 수업일인가 (요일 + 추가 수업일). 교재별 지정 요일(mat.days)과는 별개 조건 —
// 클래스 요일에서 빠진 날엔 교재 요일이 남아 있어도 예정을 깔지 않는다 (요일 변경이 예정에 반영되게)
function _pgIsClassDay(c,ds,extraSet){
  const dow=_PG_DOW[new Date(ds+'T12:00:00').getDay()];
  return (c&&(c.days||[]).includes(dow))||(extraSet&&extraSet.has(ds));
}
function _pgProjection(classId,c,tb,mat,uptoDate,skipDates,fromDate,occupied,slotPick){
  const todayStr=ppToday();
  const keys=tbUnitKeys(tb);if(!keys.length)return{};
  const rec=_pgLastRec(classId,tb);
  let start;
  if(rec)start=rec.idx+1;
  else{const si=_pgUnitIdx(tb,mat?.unit);start=si>=0?si:0;}
  let remaining=keys.slice(start);
  // 딕테이션 분리(리스닝): 한 유닛을 '본책 날 + 딕테이션 날' 두 칸으로 — 하루에 다 못 하는 날에 씀
  const dset=_pgDictSet(c,tb.id);
  if(dset.size){
    // 본책은 이미 기록됐는데 딕테이션이 아직이면 그것부터 (rec.idx는 본책·딕테이션 구분을 못 하므로 별도 확인)
    if(rec&&dset.has(_pgNorm(keys[rec.idx]))&&!_pgDictDone(classId,tb,keys[rec.idx]))remaining=[_pgDictLbl(keys[rec.idx]),...remaining];
    remaining=remaining.flatMap(k=>dset.has(_pgNorm(k))?[k,_pgDictLbl(k)]:[k]);
  }
  if(!remaining.length)return{};
  const bDays=(mat?.days&&mat.days.length)?mat.days:(c.days||[]);
  if(!bDays.length)return{};
  const recDates=_pgRecDates(classId,tb);
  const extraSet=new Set(c.extraDates||[]); // 추가 수업일 (특강 등 — 요일 외 매일 수업)
  const slots=[];
  const wd=mat?.weekly?_PG_DOW.indexOf(mat.weekly):-1;
  if(wd>=0){
    // 주 1회 진도 (mat.weekly='월' 등): 매주 지정 요일에 1과 — 그날이 휴강·기록됨·비수업이면
    // 그 주 안의 다음 수업일로 밀림, 한 주 전체가 휴강(방학)이면 그 주는 건너뜀
    const anchor=new Date();anchor.setHours(12,0,0,0);
    anchor.setDate(anchor.getDate()+((wd-anchor.getDay()+7)%7)); // 오늘 이후 첫 지정 요일부터
    let stopW=false;
    for(let wk=0;wk<80&&!stopW;wk++){
      for(let o=0;o<7;o++){
        const d2=new Date(anchor);d2.setDate(anchor.getDate()+wk*7+o);
        const ds=_pgYmd(d2);
        if(ds>uptoDate){stopW=true;break;}
        if(o===0&&fromDate&&ds<fromDate)break; // 이 주의 지정 요일을 앞 교재가 썼으면 통째로 다음 주로 (인수인계 주에 2회 방지)
        if(ds<todayStr)continue;
        if(fromDate&&ds<fromDate)continue;
        if(!_pgIsClassDay(c,ds,extraSet))continue;
        if(!bDays.includes(_PG_DOW[d2.getDay()])&&!extraSet.has(ds))continue;
        if(_pgSlotSkipped(c,tb.id,ds))continue; // 이 날은 이 교재를 뺌
        if(recDates.has(ds))continue;
        if(skipDates&&skipDates.has(ds))continue;
        if(occupied&&occupied.has(ds))continue; // 같은 과목의 다른 칩이 이미 있는 날 — 겹쳐 쌓이지 않게
        slots.push(ds);break;
      }
    }
  }else{
    const cur=new Date();cur.setHours(12,0,0,0);
    const end=new Date(uptoDate+'T12:00:00');
    for(;cur<=end;cur.setDate(cur.getDate()+1)){
      const ds=_pgYmd(cur);
      if(ds<todayStr)continue;
      if(fromDate&&ds<fromDate)continue; // 체인: 앞 교재가 끝난 뒤부터 시작
      // 클래스 수업일이면서 이 교재의 지정 요일인 날만 — 클래스 요일을 바꾸면 없어진 요일의 예정이 사라지게
      if(!_pgIsClassDay(c,ds,extraSet))continue;
      if(!bDays.includes(_PG_DOW[cur.getDay()])&&!extraSet.has(ds))continue;
      if(_pgSlotSkipped(c,tb.id,ds))continue; // 이 날은 이 교재를 뺌
      if(recDates.has(ds))continue;
      if(skipDates&&skipDates.has(ds))continue;
      if(occupied&&occupied.has(ds))continue; // 같은 과목의 다른 칩이 이미 있는 날 — 겹쳐 쌓이지 않게
      slots.push(ds);
    }
  }
  const placed={};
  const useSlots=slotPick?slots.filter(slotPick):slots; // 교대 배치면 내 차례 슬롯만
  const anc=(c.progressAnchors||{})[tb.id];
  const pins=_pgAncPins(anc);
  if(pins.length)return _pgPlacePinned(remaining,useSlots,pins,todayStr,_pgNorm,_pgDictMatch);
  useSlots.forEach((d,i)=>{if(remaining[i])placed[d]=[remaining[i]];});
  return placed;
}
// ── 딕테이션 분리 (클래스 c.dictSplit={tbId:[유닛,...]}) ──
// 유닛 하나를 '본책'과 '딕테이션' 두 칸으로 나눠 서로 다른 날에 배치. 리스닝에서 하루에 다 못 할 때 사용.
const _PG_DICT_SFX=' 딕테이션';
function _pgDictLbl(unit){return unit+_PG_DICT_SFX;}
function _pgIsDict(u){return String(u||'').includes(_PG_DICT_SFX.trim());}
function _pgDictSet(c,tbId){
  const list=((c&&c.dictSplit)||{})[tbId]||[];
  return new Set(list.map(u=>_pgNorm(u)));
}
// 유닛 매칭 — 딕테이션 항목은 '유닛5'가 '유닛5 딕테이션'에 앞부분 매칭으로 잘못 붙지 않게 정확 비교
function _pgDictMatch(a,b){
  if(_pgIsDict(a)||_pgIsDict(b))return a===b;
  return _pgUMatch(a,b);
}
// 이 유닛의 딕테이션이 이미 수업 기록에 있는가
function _pgDictDone(classId,tb,unit){
  const want=_pgNorm(_pgDictLbl(unit));
  return (_cache.lessons||[]).some(l=>l.classId===classId&&l.materials&&Object.values(l.materials).some(m=>
    m&&m.book&&(m.bookId?m.bookId===tb.id:m.book===tb.title)
    &&String(m.unit||'').split(',').some(u=>_pgNorm(u)===want)));
}
// 학생의 남은 ORT 원서 (순서대로, 읽음 기록 제외) — 시리즈를 시작한 학생만
function _pgOrtRemaining(sid){
  const n=x=>String(x||'').toLowerCase().replace(/[^a-z0-9가-힣]/g,'');
  const readIds=new Set(),readTitles=new Set();
  (_cache.readings||[]).forEach(r=>{if(r.sid!==sid)return;if(r.bookId)readIds.add(r.bookId);if(r.title)readTitles.add(n(r.title));if(r.bookTitle)readTitles.add(n(r.bookTitle));});
  (_cache.textbooks||[]).forEach(t=>{if(t.sid===sid&&t.type==='원서'&&t.title)readTitles.add(n(t.title));});
  const ort=(_cache.library||[]).filter(b=>b.ortSeq!=null).sort((a,b)=>a.ortSeq-b.ortSeq);
  let started=0;const remaining=[];
  ort.forEach(b=>{if(readIds.has(b.id)||readTitles.has(n(b.title)))started++;else remaining.push(b.title);});
  return started?remaining:[];
}
// 학생별 ORT 원서 예정 {날짜:제목} — 교재 투영과 같은 슬롯·앵커('ort:sid') 규칙
function _pgOrtProjection(classId,c,sid,uptoDate,skipDates){
  const todayStr=ppToday();
  const remaining=_pgOrtRemaining(sid);
  if(!remaining.length||!(c.days||[]).length)return{};
  const recDates=new Set(); // 이 학생의 원서가 이미 기록된 날
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||l.sid!==sid||!l.date||!l.materials)return;
    if(Object.entries(l.materials).some(([k,v])=>k.replace(/_\d+$/,'')==='_book'&&v&&v.book))recDates.add(l.date);
  });
  const slots=[];
  const extraSet=new Set(c.extraDates||[]);
  const cur=new Date();cur.setHours(12,0,0,0);
  const end=new Date(uptoDate+'T12:00:00');
  for(;cur<=end;cur.setDate(cur.getDate()+1)){
    const ds=_pgYmd(cur);
    if(ds<todayStr)continue;
    if(!(c.days||[]).includes(_PG_DOW[cur.getDay()])&&!extraSet.has(ds))continue;
    if(recDates.has(ds))continue;
    if(skipDates&&skipDates.has(ds))continue;
    slots.push(ds);
  }
  const placed={};
  const anc=(c.progressAnchors||{})['ort:'+sid];
  const pins=_pgAncPins(anc);
  // 원서는 순서(ortSeq)가 엄격 — 핀은 '이 책을 이 날부터' 뜻(순연). 교재 유닛 핀처럼 자리를 바꾸면
  // 못 읽어서 뒤로 뺀 날 뒤 책이 앞으로 튀어나와 순서가 뒤집힘 (2026-08-09 원장 지적)
  if(pins.length){
    // 유효 핀 중 가장 이른 날짜 하나만 기준으로 삼음 (드래그할수록 쌓인 옛 핀은 무시)
    let base=null;
    pins.forEach(pn=>{
      if(!pn||!pn.unit||!pn.date||pn.date<todayStr)return;
      const i=remaining.findIndex(t=>_pgNorm(t)===_pgNorm(pn.unit));
      if(i<0)return;
      if(!base||pn.date<base.date||(pn.date===base.date&&i<base.i))base={i,date:pn.date};
    });
    if(base){
      const after=slots.filter(d=>d>=base.date);
      remaining.slice(base.i).forEach((t,k)=>{if(after[k])placed[after[k]]=[t];}); // 핀 책부터 그 날 이후로 순서대로
      const before=slots.filter(d=>d<base.date);
      const head=remaining.slice(0,base.i);
      head.slice(-before.length||undefined).forEach((t,k)=>{ // 핀 앞 책들은 핀 날 직전에 붙여서
        const d=before[before.length-Math.min(head.length,before.length)+k];
        if(d)placed[d]=[t];
      });
      return placed;
    }
  }
  slots.forEach((d,i)=>{if(remaining[i])placed[d]=[remaining[i]];});
  return placed;
}
// 클래스5 앱 과제 예정 {날짜:{unit,title}} — 시작일부터 매일 한 유닛씩 (수업일·휴강과 무관, 매일 나감)
const _PG_C5_COLOR='#7C4DD6';
function _pgClass5Plan(c,uptoDate){
  const cfg=c&&c.class5;if(!cfg||!cfg.bookId)return{};
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===cfg.bookId);if(!tb)return{};
  const keys=tbUnitKeys(tb);if(!keys.length)return{};
  let i=cfg.startUnit?keys.findIndex(k=>_pgUMatch(_pgNorm(k),_pgNorm(cfg.startUnit))):0;
  if(i<0)i=0;
  const start=cfg.startDate||ppToday();
  const placed={};
  const cur=new Date(start+'T12:00:00');
  const end=new Date(uptoDate+'T12:00:00');
  const wkOnly=!!cfg.weekdaysOnly; // 평일만 (주말은 리딩앤 등 다른 숙제로 대체)
  let guard=0;
  while(cur<=end&&i<keys.length&&guard++<2000){
    const dow=cur.getDay();
    if(!(wkOnly&&(dow===0||dow===6))){
      placed[_pgYmd(cur)]={unit:keys[i],title:tb.unitTitles?.[keys[i]]||''};
      i++;
    }
    cur.setDate(cur.getDate()+1);
  }
  return placed;
}
// 클래스5가 이미 과제로 할당된 날짜 집합 (이 클래스5 책 기준)
function _pgClass5Assigned(classId,bookId){
  const s=new Set();
  ppLive(_cache.assignments).forEach(a=>{
    if(a.category!=='class5'||a.classId!==classId||a.c5BookId!==bookId)return;
    (a.schedule||[]).forEach(sc=>{if(sc.date)s.add(sc.date);});
  });
  return s;
}
// 어떤 날짜 이후 첫 '실제 수업일' — 휴강·결석일(skipSet)은 건너뜀 (수업 안 한 날에 숙제 마감이 잡히지 않게)
function _nextClassDay(dateStr,days,skipSet,extraSet){
  if((!days||!days.length)&&!(extraSet&&extraSet.size))return'';
  const cur=new Date(dateStr+'T12:00:00');
  for(let i=0;i<60;i++){
    cur.setDate(cur.getDate()+1);
    const ds=_pgYmd(cur);
    const isCls=((days||[]).includes(_PG_DOW[cur.getDay()])||(extraSet&&extraSet.has(ds)))&&!(skipSet&&skipSet.has(ds));
    if(isCls)return ds;
  }
  return'';
}
// 수업 내용 연계 숙제 예정 {마감일:[{subject,book,bookId,unit,assigned}]}
// 규칙: 실제로 배운(기록된) 교재 단원 → 복습·워크북 숙제, 마감=다음 수업일. 원서·펜슬다운 제외
function _pgHomeworkPlan(classId,c){
  if(c&&c.autoHw===false)return{}; // 수업 연계 숙제 자동 제안 끔 (반복·클래스5는 그대로)
  const days=c.days||[];
  const todayStr=ppToday();
  const skipSet=new Set(c.skipDates||[]); // 휴강일엔 숙제 마감을 잡지 않음 — 다음 실제 수업일로
  const dismissed=new Set(c.hwDismissed||[]); // 취소한 제안 ('책|단원' 정규화 키) — 다시 띄우지 않음
  const classSids=new Set(c.studentIds||[]);
  const asgs=ppLive(_cache.assignments).filter(a=>classSids.has(a.sid)&&a.category!=='class5'&&a.bookTitle);
  const isAssigned=(book,unit,due)=>asgs.some(a=>_pgNorm(a.bookTitle)===_pgNorm(book)&&(!unit||_pgUMatch(_pgNorm(a.range||''),_pgNorm(unit))))
    // 클래스5·반복 스케줄이 그 마감일에 같은 책·단원을 이미 커버하면 제안하지 않음
    ||(due&&[...classSids].some(sid=>schedCoversHw(sid,due,book,unit)));
  const byDate={},seen=new Set();
  const extraSet=new Set(c.extraDates||[]);
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.date||!l.materials)return;
    const due=_nextClassDay(l.date,days,skipSet,extraSet);
    if(!due||due<todayStr)return; // 마감이 이미 지난 제안은 표시하지 않음 (할당 불가한 잔재)
    Object.entries(l.materials).forEach(([k,v])=>{
      const bk=k.replace(/_\d+$/,'');
      if(bk==='pencil_down'||bk==='sing_together'||bk==='_book')return;
      if(!v||!v.book||!v.unit)return;
      // 반복·클래스5 숙제로 자체 진행 중인 책(단어가 읽기다 등)은 복습 제안하지 않음 — 이미 진도로 나가는 걸 또 제안하던 문제
      if([...classSids].some(sid=>bookIsRecurHw(sid,v.book)))return;
      String(v.unit).split(',').map(u=>u.trim()).filter(Boolean).forEach(unit=>{
        if(dismissed.has(_pgNorm(v.book)+'|'+_pgNorm(unit)))return;
        const key=due+'|'+_pgNorm(v.book)+'|'+_pgNorm(unit);
        if(seen.has(key))return;seen.add(key);
        (byDate[due]=byDate[due]||[]).push({subject:bk,book:v.book,bookId:v.bookId||'',unit,assigned:isAssigned(v.book,unit,due)});
      });
    });
  });
  return byDate;
}
// 숙제 제안 취소 — 그 책·단원 제안을 캘린더에서 제거 (클래스에 저장, 언제든 클래스 데이터에서 복원 가능)
async function pgDismissHw(classId,book,unit){
  pgMenuClose();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const key=_pgNorm(book)+'|'+_pgNorm(unit);
  const set=new Set(c.hwDismissed||[]);set.add(key);
  c.hwDismissed=[...set];
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgDismissHw:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
  renderAssignCal();
  toast(`${unit} 숙제 제안을 취소했어요`);
}
// 점선 숙제 제안 칩 클릭 → 할당/취소 선택 메뉴
function hwChipMenu(ev,classId,subject,book,bookId,unit,due){
  if(ev&&ev.stopPropagation)ev.stopPropagation();
  pgCellMenu(ev,classId,due,[
    {ico:'📕',label:'반 전체 숙제로 할당',sub:`${book} ${unit} · 마감 ${due}`,run:()=>pgHwDbl(null,classId,subject,book,bookId,unit,due)},
    {ico:'🚫',label:'제안 취소',sub:'캘린더에서 보이지 않게',run:()=>pgDismissHw(classId,book,unit)},
  ]);
}
// ── 동시 진행 줄(track) ──
// 같은 영역(어휘 등) 안에서도 교재가 동시에 돌아가는 경우가 있다 (1200은 수업 중, 요즘 초등 영단어는 과제).
// 체인 하나로는 '앞 책이 끝나야 다음 책'밖에 표현할 수 없으니, 줄을 여러 개로 나눈다.
// mat.run이 있는 책이 그 자리에서 새 줄을 시작하고, 뒤따르는 기본('') 책들이 그 줄을 이어받는다.
//   run:'class' = 수업 중 진행(수업일마다 1과)   run:'hw' = 과제로 진행(수업 없는 날 1과 → 다음 수업일에 표시)
// 줄끼리는 서로 기다리지 않고 각자 진행한다 (커서·날짜 선점이 줄 단위).
function _pgTracksOf(group){return ppTracksOf(group);}
// 클래스 예정 전체 구성(교재·원서·싱투게더) — 캘린더·예정 편집 모달·폼 자동 채움이 공유하는 단일 계산
function _pgComposePlan(classId,c,uptoDate){
  const todayStr=ppToday();
  const skipSet=new Set(c.skipDates||[]); // 휴강·결석으로 수업 안 한 날 — 교재·원서 진도는 이 날을 건너뛰어 하루씩 밀림 (클래스5 과제는 제외)
  const lessonDates=new Set();
  (_cache.lessons||[]).forEach(l=>{if(l.classId===classId&&l.date)lessonDates.add(l.date);});
  const books=Object.entries(c.commonMaterials||{})
    .map(([s,mat])=>({s,mat,tb:_pgTbOf(mat)}))
    .filter(e=>e.tb&&tbUnitKeys(e.tb).length)
    .map(e=>({...e,color:_PG_CAT_COLORS[e.s.replace(/_\d+$/,'')]||'var(--text-muted)'}));
  const clsStus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  // 리딩 계열은 하나의 체인: 책 A 완주 → Sing Together 한 번 → 책 B 시작 (다른 과목 진도는 그대로)
  const singDates=new Set();
  const singBy={}; // 날짜 → 그 씽의 주인 책 id (칩 드래그가 어느 책의 씽인지 알아야 핀을 저장할 수 있음)
  const ghostBy={};
  const readingBooks=books.filter(b=>b.tb.category==='리딩'||b.s.replace(/_\d+$/,'')==='reading'); // commonMaterials 키 순서 = 체인 순서
  const usedDates=new Set(); // 리딩 계열 슬롯이 이미 기록으로 소비된 날 (리딩 기록·펜슬다운)
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.date||!l.materials)return;
    Object.entries(l.materials).forEach(([k,v])=>{
      const bk=k.replace(/_\d+$/,'');
      if(bk==='pencil_down'||bk==='sing_together'){usedDates.add(l.date);return;}
      if(!v||!v.book)return;
      if(readingBooks.some(b=>v.bookId?v.bookId===b.tb.id:v.book===b.tb.title))usedDates.add(l.date);
    });
  });
  const _addDay=ds=>{const d=new Date(ds+'T12:00:00');d.setDate(d.getDate()+1);return _pgYmd(d);};
  const _extraSet=new Set(c.extraDates||[]); // 추가 수업일 (특강 — 요일 외 매일 수업 기간)
  const _slotFrom=(fromInclusive,bDays)=>{ // fromInclusive부터 첫 가용 수업일 (휴강일 건너뜀, 추가 수업일 포함)
    const cur=new Date(fromInclusive+'T12:00:00');
    for(let i=0;i<220;i++){
      const ds=_pgYmd(cur);
      if(ds>uptoDate)return'';
      if(ds>=todayStr&&(bDays.includes(_PG_DOW[cur.getDay()])||_extraSet.has(ds))&&!usedDates.has(ds)&&!skipSet.has(ds))return ds;
      cur.setDate(cur.getDate()+1);
    }
    return'';
  };
  let chainCursor=todayStr;
  // ── 리딩 외 과목 그룹 (같은 과목 여러 권 = 커리큘럼 체인) ──
  const _subjGroups={};
  books.filter(b=>!readingBooks.includes(b)).forEach(b=>{
    const base=b.s.replace(/_\d+$/,'');
    const gk=base==='naesin'?b.s:base; // 내신은 여러 교재 병행 — 체인 아님, 각자 투영
    (_subjGroups[gk]=_subjGroups[gk]||[]).push(b); // commonMaterials 키 순서 = 체인 순서
  });
  const _procTrack=(group0,subjSkip,runMode)=>{
    let group=group0;
    let cursor=todayStr; // 이 과목 체인에서 다음 교재가 시작 가능한 날
    const base0=(group[0]?.s||'').replace(/_\d+$/,''); // 어휘 과목은 전체가 '수업 없는 날 숙제' 방식
    // 같은 과목이 이미 차지한 날 선점: 모든 책의 유효 핀 + 배치된 날 누적 — 앞 책의 남은 유닛·만료 핀 유닛이
    // 다른 책 핀 날짜 위로 겹쳐 쌓이던 문제 방지 (리스닝처럼 짧은 책이 촘촘한 체인에서 발생)
    const groupOcc=new Set();
    for(const b of group)_pgAncPins((c.progressAnchors||{})[b.tb.id]).forEach(pn=>{if(pn&&pn.unit&&pn.date&&pn.date>=todayStr)groupOcc.add(pn.date);});
    // 병행(교대) 배치: mat.alt='트랙명'인 책들은 트랙별로 진행 중인 첫 책끼리 같은 과목 슬롯을 번갈아 나눠 씀
    // (예: 리스닝 두 시리즈를 매일 번갈아 — 한 권이 끝날 때까지 기다리지 않음). 트랙 안에서는 기존처럼 순차 체인
    const altTracks={};
    group.forEach(b=>{
      const t=b.mat&&b.mat.alt;if(!t)return;
      const rec=_pgLastRec(classId,b.tb);
      if(rec&&rec.idx>=tbUnitKeys(b.tb).length-1)return; // 완강한 책은 트랙 대표가 아님
      if(!altTracks[t])altTracks[t]=b; // commonMaterials 키 순서 = 트랙 내 순서
    });
    // 트랙 키 순서가 곧 교대 순번 — 'A' 트랙이 첫 슬롯, 'B'가 다음 슬롯
    const altBooks=Object.keys(altTracks).sort((x,y)=>String(x).localeCompare(String(y),undefined,{numeric:true})).map(k=>altTracks[k]);
    const altIdx=new Map(altBooks.map((b,i)=>[b,i]));
    // 교대 패턴 — 트랙당 1칸씩 단순 번갈아 (원장 지시 2026-09: 스마트 리스닝 ↔ 리스닝 스테이지 한 번씩)
    // 딕테이션 분리 책은 자기 트랙 슬롯에 '본책 → 다음 차례에 딕테이션' 순서로 들어간다
    const altPat=altBooks.map((b,i)=>i);
    let altEnd='',altFrom=null; // 교대 책들의 공통 시작일 — 책마다 다르면 슬롯 순번이 어긋남
    let pcEnd=''; // 병행(perClass) 어휘책들이 끝나는 가장 늦은 날
    // ⚠️ 교대 책들은 **슬롯 목록이 완전히 같아야** 순번(i)이 어긋나지 않는다.
    // _pgProjection은 자기 책의 기록일(recDates)만 슬롯에서 빼므로, 한 책만 기록된 날이 있으면
    // 두 책의 배열 길이가 달라져 같은 날에 겹친다 → 교대 그룹 전체의 기록일을 서로 빼준다
    const altRec=new Set();
    altBooks.forEach(b=>_pgRecDates(classId,b.tb).forEach(d=>{if(d>=todayStr)altRec.add(d);}));
    // 병행 책을 먼저 처리해야 pcEnd가 확정된 뒤 체인 뒷 책이 그 다음부터 깔린다 (안 그러면 겹쳐 쌓임).
    // Array.sort는 안정 정렬이라 그룹 내 체인 순서는 그대로 유지된다
    group=[...group].sort((x,y)=>((x.mat&&x.mat.perClass)?0:1)-((y.mat&&y.mat.perClass)?0:1));
    for(const b of group){
      const isPerClass=base0==='vocab'&&b.mat&&b.mat.perClass;
      // 이 줄이 '과제 흐름'인가 — 어휘는 기본이 과제, run:'class'면 수업 중 진행으로 돌린다
      const isHwFlow=runMode==='hw'||(base0==='vocab'&&runMode!=='class');
      // 커서 보정은 **모든 분기보다 먼저** — 어휘 숙제흐름·묶음 분기도 cursor를 쓰므로 뒤에 두면 겹쳐 깔림
      if(!isPerClass&&altEnd&&_addDay(altEnd)>cursor)cursor=_addDay(altEnd); // 교대가 끝난 뒤 트랙 다음 책
      if(!isPerClass&&pcEnd&&_addDay(pcEnd)>cursor)cursor=_addDay(pcEnd);    // 병행 어휘가 끝난 뒤 다음 어휘책
      // 이 책의 **교재형 숙제**를 직접 찾는다 (auto 무관).
      // 전에는 bookIsRecurHw 로 '교재형 숙제가 있나'를 먼저 물었는데, 그 함수는 **다른 숙제의
      // schedule[].book** 에 이름이 있어도 true 를 돌려줬다. 그래서 이 책의 숙제가 없는데도
      // 숙제 흐름 분기로 들어가 continue 만 하고 — 책 한 권이 예정에서 통째로 빠졌다.
      const a=(typeof ppBookHw==='function')?ppBookHw(clsStus.map(s=>s.id),b.tb):null;
      if(a&&(a.schedule||[]).length){
        {
          const sch=_hwSchedOf(a);
          const rec=_pgLastRec(classId,b.tb);
          const keys=tbUnitKeys(b.tb);
          const remain=new Set(keys.slice(rec?rec.idx+1:0).map(k=>_pgNorm(k))); // 아직 수업 기록 안 된 단원만
          // 유효 핀(오늘 이후·미기록 단원): 핀 유닛은 핀 날짜에 배치, 숙제 흐름 그룹핑에서 제외 (드래그·예정편집 조정 지원)
          const vPins=_pgAncPins((c.progressAnchors||{})[b.tb.id]).filter(pn=>pn&&pn.unit&&pn.date&&pn.date>=todayStr&&pn.date<=uptoDate&&remain.has(_pgNorm(pn.unit)));
          const vPinned=new Set(vPins.map(pn=>_pgNorm(pn.unit)));
          const byDay={};
          sch.forEach(s2=>{
            if(!s2.unit||!remain.has(_pgNorm(s2.unit))||vPinned.has(_pgNorm(s2.unit)))return;
            let d=_nextClassDay(s2.date,(c.days||[]),subjSkip,_extraSet);
            // 밀린 몫(정리일이 이미 지난 단원)은 사라지지 않게 다음 수업일로 모아서 표시
            if(d&&d<todayStr)d=_nextClassDay(todayStr,(c.days||[]),subjSkip,_extraSet);
            let _g=0;
            while(d&&_pgSlotSkipped(c,b.tb.id,d)&&_g++<30)d=_nextClassDay(d,(c.days||[]),subjSkip,_extraSet); // 뺀 날이면 다음 수업일로
            if(!d||d>uptoDate)return;
            (byDay[d]=byDay[d]||[]).push(s2.unit);
          });
          vPins.forEach(pn=>(byDay[pn.date]=byDay[pn.date]||[]).push(pn.unit));
          Object.entries(byDay).forEach(([d,units])=>{ // 같은 날 여러 유닛 = 개별 칩 (한 유닛씩 따로 조정)
            units.forEach(u=>(ghostBy[d]=ghostBy[d]||[]).push({tbId:b.tb.id,unit:u,color:b.color,title:b.tb.title,s:b.s}));
          });
          // 다음 교재는 이 반복 숙제가 끝난 다음 날부터 (남은 단원이 있을 때만)
          if(remain.size){const last=(sch[sch.length-1]||{}).date||'';if(last&&_addDay(last)>cursor)cursor=_addDay(last);}
        }
        continue; // 교재형 숙제가 있는 책은 매 수업 1과 투영 안 함 (숙제 일정이 곧 진도)
      }
      const keys=tbUnitKeys(b.tb);
      const rec=_pgLastRec(classId,b.tb);
      if(rec&&rec.idx>=keys.length-1)continue; // 완강한 책 — 다음 교재가 이어서
      // 주간 묶음 배치(mat.perWeek): 매주 첫 수업일에 N과씩 — 어휘를 '한 주치 한 번에' 정리하는 방식
      // mat.startDate가 있으면 그 날부터 시작. 핀은 우선(그 날짜에 그대로), 나머지가 주 단위로 채워짐
      // perClass(위에서 판정): 어휘를 일반 교재처럼 '매 수업 1과'로 — vocab 특수 분기를 건너뛰고 공용 투영 사용
      if(base0==='vocab'&&!isPerClass&&b.mat&&+b.mat.perWeek>0){
        const per=+b.mat.perWeek;
        const st=rec?rec.idx+1:(()=>{const si=_pgUnitIdx(b.tb,b.mat?.unit);return si>=0?si:0;})();
        const remaining=keys.slice(st);
        if(!remaining.length)continue;
        const vPins=_pgAncPins((c.progressAnchors||{})[b.tb.id]).filter(pn=>pn&&pn.unit&&pn.date&&pn.date>=todayStr&&pn.date<=uptoDate&&remaining.some(k=>_pgNorm(k)===_pgNorm(pn.unit)));
        const vPinned=new Set(vPins.map(pn=>_pgNorm(pn.unit)));
        const byDay={};
        vPins.forEach(pn=>(byDay[pn.date]=byDay[pn.date]||[]).push(pn.unit));
        let from=b.mat.startDate||cursor;
        if(from<todayStr)from=todayStr;
        const d2=new Date(from+'T12:00:00');
        const wkKey=dt=>{const x=new Date(dt);x.setDate(x.getDate()-((x.getDay()+6)%7));return _pgYmd(x);}; // 그 주 월요일
        const doneWk=new Set();
        let ui=0,guard=0,maxD='';
        while(ui<remaining.length&&guard++<500){
          const ds=_pgYmd(d2);
          if(ds>uptoDate)break;
          const dow=_PG_DOW[d2.getDay()];
          const isCls=((c.days||[]).includes(dow)||_extraSet.has(ds))&&!subjSkip.has(ds);
          if(isCls&&!_pgSlotSkipped(c,b.tb.id,ds)&&!doneWk.has(wkKey(d2))){
            doneWk.add(wkKey(d2));
            for(let n=0;n<per&&ui<remaining.length;n++){
              while(ui<remaining.length&&vPinned.has(_pgNorm(remaining[ui])))ui++; // 핀 유닛은 자기 날짜에
              if(ui>=remaining.length)break;
              (byDay[ds]=byDay[ds]||[]).push(remaining[ui++]);
            }
            if(ds>maxD)maxD=ds;
          }
          d2.setDate(d2.getDate()+1);
        }
        Object.entries(byDay).forEach(([dd,units])=>{
          units.forEach(u=>(ghostBy[dd]=ghostBy[dd]||[]).push({tbId:b.tb.id,unit:u,color:b.color,title:b.tb.title,s:b.s}));
        });
        cursor=(ui>=remaining.length&&maxD)?_addDay(maxD):'9999-12-31';
        continue;
      }
      if(isHwFlow&&!isPerClass){
        // 과제 흐름: 수업 없는 날마다 1과씩 진행 → 다음 수업일에 일괄 진도로 표시
        // (어휘 기본값이자 run:'hw'로 지정한 줄의 방식. run:'class' 줄은 아래 공용 투영으로 간다)
        // (아직 반복 숙제로 할당 전인 다음 교재도 같은 방식으로 미리 계산 — 매일 수업 나가는 것처럼 깔리지 않게)
        const start=rec?rec.idx+1:(()=>{const si=_pgUnitIdx(b.tb,b.mat?.unit);return si>=0?si:0;})();
        const remaining=keys.slice(start);
        if(!remaining.length)continue;
        // 유효 핀: 핀 유닛은 핀 날짜에 배치, 숙제일 흐름에서 제외 (핀 자리는 다음 유닛이 앞당겨 채움)
        const vPins=_pgAncPins((c.progressAnchors||{})[b.tb.id]).filter(pn=>pn&&pn.unit&&pn.date&&pn.date>=todayStr&&pn.date<=uptoDate&&remaining.some(k=>_pgNorm(k)===_pgNorm(pn.unit)));
        const vPinned=new Set(vPins.map(pn=>_pgNorm(pn.unit)));
        const byDay={};
        vPins.forEach(pn=>(byDay[pn.date]=byDay[pn.date]||[]).push(pn.unit));
        const d=new Date((cursor>todayStr?cursor:todayStr)+'T12:00:00');
        let ui=0,guard=0,lastHw='',overflow=false;
        while(ui<remaining.length&&guard++<450){
          const ds=_pgYmd(d);
          if(ds>uptoDate){overflow=true;break;}
          const dow=_PG_DOW[d.getDay()];
          const isCls=((c.days||[]).includes(dow)||_extraSet.has(ds))&&!subjSkip.has(ds);
          if(!isCls){ // 수업 없는 날 = 숙제일
            while(ui<remaining.length&&vPinned.has(_pgNorm(remaining[ui])))ui++; // 핀 유닛은 숙제일을 소비하지 않음
            if(ui>=remaining.length)break;
            let showD=_nextClassDay(ds,(c.days||[]),subjSkip,_extraSet);
            let _g2=0;
            while(showD&&_pgSlotSkipped(c,b.tb.id,showD)&&_g2++<30)showD=_nextClassDay(showD,(c.days||[]),subjSkip,_extraSet); // 뺀 날이면 다음 수업일로
            if(showD&&showD<=uptoDate)(byDay[showD]=byDay[showD]||[]).push(remaining[ui]);
            lastHw=ds;ui++;
          }
          d.setDate(d.getDate()+1);
        }
        Object.entries(byDay).forEach(([dd,units])=>{ // 같은 날 여러 유닛 = 개별 칩 (한 유닛씩 따로 조정)
          units.forEach(u=>(ghostBy[dd]=ghostBy[dd]||[]).push({tbId:b.tb.id,unit:u,color:b.color,title:b.tb.title,s:b.s}));
        });
        if(!overflow&&ui>=remaining.length&&lastHw)cursor=_addDay(lastHw);
        else cursor='9999-12-31'; // 범위 밖까지 이어짐 — 뒤 교재는 이 화면에선 안 그림
        continue;
      }
      const isAlt=altIdx.has(b)&&altBooks.length>1;
      if(isAlt&&altFrom===null)altFrom=cursor; // 교대 시작점은 한 번만 확정 (앞 책이 끝난 다음 날)
      const ai=altIdx.get(b);
      // 교대 책: 같은 시작점·같은 슬롯 목록을 altPat 패턴대로 나눠 가짐 — 서로 다른 날에 번갈아
      const placed=isAlt
        ?_pgProjection(classId,c,b.tb,b.mat,uptoDate,subjSkip,altFrom,new Set([...groupOcc,...altRec]),(d,i)=>altPat[i%altPat.length]===ai)
        :isPerClass
        ?_pgProjection(classId,c,b.tb,b.mat,uptoDate,subjSkip,(b.mat.startDate&&b.mat.startDate>todayStr)?b.mat.startDate:todayStr,null)
        :_pgProjection(classId,c,b.tb,b.mat,uptoDate,subjSkip,cursor,groupOcc);
      let maxD='';
      Object.entries(placed).forEach(([d,us])=>{ // 같은 날 여러 유닛 = 개별 칩 (한 유닛씩 따로 옮길 수 있게)
        (Array.isArray(us)?us:[us]).forEach(u=>(ghostBy[d]=ghostBy[d]||[]).push({tbId:b.tb.id,unit:u,color:b.color,title:b.tb.title,s:b.s}));
        if(!isAlt&&!isPerClass)groupOcc.add(d); // 이 날은 이 과목이 차지 — 뒤 책 자동 흐름이 겹치지 않게
        //  (perClass 어휘는 여러 책을 같은 날 각 1과씩 병행하므로 날짜를 선점하지 않음)
        //  (교대 책은 서로의 배치일을 슬롯에서 빼면 순번이 어긋나므로 넣지 않음 — 대신 slotPick이 날짜를 나눔)
        if(d>maxD)maxD=d;
      });
      if(isAlt){ // 교대 중엔 체인 커서를 밀지 않음 (다른 트랙 책도 같은 시작점을 써야 함)
        if(maxD&&maxD>altEnd)altEnd=maxD;
        continue;
      }
      if(isPerClass){ // 병행 어휘: 커서를 밀지 않고, 다 끝난 뒤부터 체인 뒷 책이 이어지게
        if(maxD&&maxD>pcEnd)pcEnd=maxD;
        continue;
      }
      if(maxD)cursor=_addDay(maxD);
      else{cursor='9999-12-31';} // 표시 범위 밖 — 뒤 교재는 이 화면에선 안 그림
    }
  };
  // 과목 그룹을 동시 진행 줄로 쪼개 각 줄을 독립 체인으로 처리 (줄이 하나면 기존과 완전히 동일)
  const _procGroup=(group0,subjSkip)=>{
    _pgTracksOf(group0).forEach(t=>_procTrack(t.books,subjSkip,t.run));
  };
  // 1차: 리스닝 외 과목 먼저 — 단어·어법 수업일이 확정돼야 리딩·리스닝이 그 날을 비켜감 (원장 규칙 2026-08-08)
  Object.entries(_subjGroups).forEach(([gk,group])=>{if(gk!=='listening')_procGroup(group,skipSet);});
  // 단어 수업일(일괄 진도 표시일)·어법 수업일 수집 — 예정 고스트 + 오늘 이후 실제 기록
  const vocabDays=new Set(),grammarDays=new Set();
  Object.entries(ghostBy).forEach(([d,arr])=>arr.forEach(g=>{
    const base=String(g.s||'').replace(/_\d+$/,'');
    if(base==='vocab')vocabDays.add(d);
    else if(base==='grammar')grammarDays.add(d);
  }));
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.date||l.date<todayStr||!l.materials)return;
    Object.keys(l.materials).forEach(k=>{
      const bk=k.replace(/_\d+$/,'');
      if(bk==='vocab')vocabDays.add(l.date);
      else if(bk==='grammar')grammarDays.add(l.date);
    });
  });
  // 단어 수업 있는 날은 리딩 배제 — 리딩 슬롯 소비 집합에 넣어 자동으로 건너뜀 (핀으로 옮긴 유닛은 수동 우선이라 유지)
  // 교차 배제(c.crossSkip!==false): 단어일엔 리딩 배제, 어법일엔 리스닝 배제.
  // ⚠️ 어법·어휘가 매 수업일에 깔리는 구성에선 리딩·리스닝이 전부 막히므로 클래스 옵션으로 끌 수 있다
  const _cross=c.crossSkip!==false;
  if(_cross)vocabDays.forEach(d=>usedDates.add(d));
  {
    const isFin=b=>{const rec=_pgLastRec(classId,b.tb);const keys=tbUnitKeys(b.tb);return !!(rec&&rec.idx>=keys.length-1);};
    const finished=readingBooks.filter(isFin);
    const unfinished=readingBooks.filter(b=>!isFin(b));
    // 리딩 계열 전체의 유효 핀 날짜 — 다른 책의 자동 흐름 유닛이 그 위로 겹쳐 쌓이지 않게
    const rdPinned=new Set();
    readingBooks.forEach(b=>_pgAncPins((c.progressAnchors||{})[b.tb.id]).forEach(pn=>{if(pn&&pn.unit&&pn.date&&pn.date>=todayStr)rdPinned.add(pn.date);}));
    // 씽 투게더 핀 — progressAnchors['sing:'+tbId] (드래그·탭으로 옮긴 날짜). 지난 핀은 자동 만료
    const _singPin=tbId=>{
      const p=_pgAncPins((c.progressAnchors||{})['sing:'+tbId]).filter(pn=>pn&&pn.date&&pn.date>=todayStr).sort((a,b2)=>a.date.localeCompare(b2.date))[0];
      return p?p.date:'';
    };
    readingBooks.forEach(b=>{const sp=_singPin(b.tb.id);if(sp)rdPinned.add(sp);}); // 옮긴 씽 날짜 위로 유닛이 겹치지 않게
    // 직전에 완주한 책의 싱투게더가 아직이면 체인 맨 앞에 배치 (다음 책을 이미 시작했으면 생략)
    if(finished.length){
      const lastFin=finished.map(b=>({b,rec:_pgLastRec(classId,b.tb)})).sort((a,b2)=>(b2.rec.date||'').localeCompare(a.rec.date||''))[0];
      const nextStarted=unfinished.some(b=>_pgLastRec(classId,b.tb));
      // 완주일 직전 1주 내의 펜슬다운도 이 책의 씽으로 인정 — 마지막 단원 정리 전에 씽을 먼저 한 경우 8월에 또 잡히지 않게
      const singFrom=(()=>{const d=new Date(lastFin.rec.date+'T12:00:00');d.setDate(d.getDate()-7);return _pgYmd(d);})();
      const singDone=(_cache.lessons||[]).some(l=>l.classId===classId&&(l.date||'')>=singFrom&&l.materials
        &&Object.keys(l.materials).some(k=>{const bk=k.replace(/_\d+$/,'');return bk==='pencil_down'||bk==='sing_together';}));
      if(!singDone&&!nextStarted){
        const sp=_singPin(lastFin.b.tb.id);
        // 핀으로 옮겨도 체인은 원래 슬롯(auto)을 그대로 소비 — 씽만 움직이고 뒤 진도·순서는 그대로
        const auto=_slotFrom(chainCursor,(c.days||[]));
        const d=sp||auto;
        if(d){singDates.add(d);singBy[d]=lastFin.b.tb.id;}
        chainCursor=auto?_addDay(auto):'9999-12-31';
      }
    }
    // 미완주 리딩 책을 키 순서대로 이어서: 단원들 → (완주하면) 싱투게더 → 다음 책
    unfinished.forEach(b=>{
      const keys=tbUnitKeys(b.tb);
      const rec=_pgLastRec(classId,b.tb);
      let start;
      if(rec)start=rec.idx+1;
      else{const si=_pgUnitIdx(b.tb,b.mat?.unit);start=si>=0?si:0;}
      let remaining=keys.slice(start);
      if(!remaining.length)return;
      const bDays=(b.mat?.days&&b.mat.days.length)?b.mat.days:(c.days||[]);
      let segCursor=chainCursor;
      // 다중 핀 (2026-08-04): 핀 유닛은 지정 날짜 고정, 나머지는 핀 날짜를 제외한 수업일에 순서대로 (_pgPlacePinned와 동일 규칙)
      const pinOf={};
      _pgAncPins((c.progressAnchors||{})[b.tb.id]).forEach(pn=>{
        if(!pn||!pn.unit||!pn.date||pn.date<todayStr)return;
        const parts=String(pn.unit).split(',').map(x=>x.trim()).filter(Boolean);
        const list=(parts.length>1&&parts.every(pt=>remaining.some(k=>_pgUMatch(_pgNorm(k),_pgNorm(pt)))))?parts:[pn.unit];
        list.forEach(u=>{const i=remaining.findIndex(k=>_pgUMatch(_pgNorm(k),_pgNorm(u)));if(i>=0&&!(i in pinOf))pinOf[i]=pn.date;});
      });
      const pinDates=new Set(Object.values(pinOf));
      let segEnd=segCursor,overflow=false;
      for(let i=0;i<remaining.length;i++){
        let d;
        if(i in pinOf)d=pinOf[i];
        else{
          d=_slotFrom(segCursor,bDays);
          while(d&&(pinDates.has(d)||rdPinned.has(d)))d=_slotFrom(_addDay(d),bDays); // 이 책·다른 리딩 책의 핀 날은 건너뜀
          if(!d){overflow=true;break;}
          segCursor=_addDay(d);
        }
        if(d<=uptoDate)(ghostBy[d]=ghostBy[d]||[]).push({tbId:b.tb.id,unit:remaining[i],color:b.color,title:b.tb.title,s:b.s});
        if(_addDay(d)>segEnd)segEnd=_addDay(d);
      }
      if(overflow){chainCursor='9999-12-31';return;}
      // 이 책 완주 → 싱투게더 → 다음 책은 그 다음 수업일부터
      // 핀으로 옮겨도 체인은 원래 슬롯(auto)을 그대로 소비 — 씽만 움직이고 뒤 진도·순서는 그대로
      const sp=_singPin(b.tb.id);
      const auto=_slotFrom(segEnd,(c.days||[]));
      const sd=sp||auto;
      if(!sd){chainCursor='9999-12-31';return;}
      singDates.add(sd);singBy[sd]=b.tb.id;
      chainCursor=auto?_addDay(auto):'9999-12-31';
    });
  }
  // 2차: 리스닝 — 어법 수업 있는 날은 리스닝 배제 (확장 스킵으로 그 날을 휴강처럼 건너뜀)
  if(_subjGroups.listening)_procGroup(_subjGroups.listening,_cross?new Set([...skipSet,...grammarDays]):skipSet);
  const ortGhostBy={};
  // 원서 예정 끔(c.ortPlan===false) — 원서 읽기를 리딩앤 등 외부 프로그램으로 돌린 반. 읽은 책 기록은 그대로 남음
  if(c.ortPlan!==false)clsStus.forEach(s=>{
    const placed=_pgOrtProjection(classId,c,s.id,uptoDate,skipSet);
    Object.entries(placed).forEach(([d,ts])=>{
      (Array.isArray(ts)?ts:[ts]).forEach(t=>(ortGhostBy[d]=ortGhostBy[d]||[]).push({sid:s.id,name:s.name,title:t}));
    });
  });
  return {books,clsStus,singDates,singBy,ghostBy,ortGhostBy,skipSet};
}
// 수업 기록 폼: 다음 단원 자동 채움 (손으로 고친 값·수정 모드는 건드리지 않음)
function _pgAutoFillRow(sr){
  const idEl=document.getElementById('cl-class-id');
  const classId=idEl?.value;if(!classId||idEl.dataset.editMode==='true')return;
  if(!sr.closest('#cl-subj-rows'))return;
  const sel=sr.querySelector('select[data-f="book"]');if(!sel||!sel.value)return;
  const unitInp=sr.querySelector('[data-f="unit"]');if(!unitInp)return;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const stored=c.commonMaterials?.[sr.dataset.s]||null;
  const curVal=[...sr.querySelectorAll('[data-f="unit"]')].map(x=>x.value.trim()).filter(Boolean).join(', ');
  if(curVal&&unitInp.dataset.auto!=='1'&&curVal!==(stored?.unit||''))return;
  const bkId=sel.options[sel.selectedIndex]?.getAttribute('data-bk-id')||'';
  const tb=_pgTbOf({book:sel.value,bookId:bkId});
  sr.querySelector('.pg-auto-chip')?.remove();
  if(!tb)return; // 교재 DB에 없으면 기존 값 유지
  const mat=(stored&&stored.book===sel.value)?stored:{book:sel.value,bookId:bkId};
  const dateVal=document.getElementById('cl-date')?.value||ppToday();
  // 캘린더와 같은 계산으로 그 날짜의 계획 단원을, 없으면 순서상 다음 단원
  const _plan=_pgComposePlan(classId,c,dateVal);
  const _plannedUs=(_plan.ghostBy[dateVal]||[]).filter(x=>x.tbId===tb.id).map(x=>x.unit); // 개별 칩이어도 폼엔 그날 유닛 전부
  const next=(_plannedUs.length?_plannedUs.join(', '):'')||_pgNextUnit(classId,tb,mat.unit||'');
  if(!next)return;
  const wrapU=sr.querySelector('.unit-inputs-wrap');
  if(wrapU)[...wrapU.querySelectorAll('.unit-irow')].slice(1).forEach(x=>x.remove());
  unitInp.value=next;unitInp.dataset.auto='1';
  const chip=document.createElement('span');
  chip.className='pg-auto-chip';chip.textContent='자동';
  chip.title='마지막 기록의 다음 단원이 자동으로 채워졌어요. 다르면 그냥 고치면 됩니다.';
  unitInp.insertAdjacentElement('afterend',chip);
  unitInp.addEventListener('input',function h(){unitInp.dataset.auto='';chip.remove();unitInp.removeEventListener('input',h);});
}
function pgCalNav(d){
  const cur=_pgCalMonth||ppToday().slice(0,7);
  let[y,m]=cur.split('-').map(Number);m+=d;if(m<1){m=12;y--;}if(m>12){m=1;y++;}
  _pgCalMonth=`${y}-${String(m).padStart(2,'0')}`;
  if(_pgCalClsId)renderClsLessons(_pgCalClsId);
  if(_pgMoveSel)setTimeout(()=>toast('이동 중 — 옮길 날짜를 눌러주세요 (다른 달도 가능)'),80);
}
// 드래그 중 ◀▶ 위에 올리면 달이 넘어감 — 다음·이전 달 날짜로도 진도를 끌어올 수 있게 (월 경계 드래그)
let _pgNavFlipAt=0;
function pgNavDragOver(ev,d){
  if(!_pgDrag)return;
  ev.preventDefault();
  const now=Date.now();
  if(now-_pgNavFlipAt<600)return; // 올려둔 채 머물면 600ms마다 한 달씩
  _pgNavFlipAt=now;
  pgCalNav(d);
}
// ── 진도 손보기 (웹에서 바로) ──
// 진도가 틀어지는 원인은 대개 둘 — ① 수업 기록에 없는 진도(구두로만 나간 단원),
// ② 줄이 마르거나 교재가 체인에 없어 예정이 끊김. 둘 다 이 모달에서 바로 고친다.
let _pgFixCtx=null;
function _pgFixOpen(ctx){
  _pgFixCtx=ctx;
  document.getElementById('pgfix-title').textContent=ctx.title;
  document.getElementById('pgfix-desc').innerHTML=ctx.desc;
  document.getElementById('pgfix-label').textContent=ctx.label;
  document.getElementById('pgfix-hint').innerHTML=ctx.hint||'';
  document.getElementById('pgfix-sel').innerHTML=ctx.options;
  openM('m-pg-fix');
}
// ① 진도 기준점 수정 — '여기까지 끝냈어요'
function pgEditProgress(classId,bookId){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===bookId);if(!tb)return;
  const keys=tbUnitKeys(tb);
  const rec=_pgLastRec(classId,tb);
  const du=((c.doneUpto||{})[bookId])||'';
  const recOnly=(()=>{ // 기록만으로 본 진도 (직접 지정을 뺀 값)
    let best=-1;
    (_cache.lessons||[]).forEach(l=>{
      if(l.classId!==classId||!l.materials||(l.date||'')>ppToday())return;
      Object.values(l.materials).forEach(m=>{
        if(!m||!m.book)return;
        if(m.bookId?m.bookId!==tb.id:m.book!==tb.title)return;
        const i=_pgUnitIdx(tb,m.unit,{classId:classId,date:l.date});if(i>best)best=i;
      });
    });
    return best;
  })();
  const cur=du||(recOnly>=0?keys[recOnly]:'');
  _pgFixOpen({
    mode:'done',classId,bookId,
    title:'진도 수정',
    desc:`<b>${escAttr(tb.title)}</b> — 어디까지 끝냈는지 고르면 그 다음 단원부터 예정이 다시 깔려요`,
    label:'여기까지 끝냈어요',
    options:`<option value="">— 수업 기록 그대로 (${recOnly>=0?escAttr(keys[recOnly]):'기록 없음'}) —</option>`
      +keys.map(k=>`<option value="${escAttr(k)}"${_pgNorm(k)===_pgNorm(cur)&&du?' selected':''}>${escAttr(k)}${tb.unitTitles&&tb.unitTitles[k]?' — '+escAttr(tb.unitTitles[k]):''}</option>`).join(''),
    hint:'수업 기록은 그대로 두고 진도 기준점만 옮깁니다. 숙제 자동 진행도 같은 기준을 씁니다.'
      +(du?`<br>지금은 <b>${escAttr(du)}</b>까지로 직접 지정돼 있어요.`:''),
  });
}
// ② 다음 교재 고르기 — 그 줄의 마지막 교재 뒤에 끼워 넣는다
function pgPickNext(classId,afterKey){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const cm=c.commonMaterials||{};
  const mat=cm[afterKey];if(!mat)return;
  const curTb=_pgTbOf(mat);
  const base=afterKey.replace(/_\d+$/,'');
  const inChain=new Set(Object.values(cm).map(v=>v&&(v.bookId||v.book)).filter(Boolean));
  const cat=curTb?curTb.category:_CAT_KO[base];
  let cand=(_cache.globalTextbooks||[]).filter(b=>!b._deleted&&tbUnitKeys(b).length
    &&!inChain.has(b.id)&&!inChain.has(b.title)&&(!cat||b.category===cat));
  // 같은 시리즈의 뒤 권을 맨 앞에 — 선생님이 거의 늘 고르는 값
  let head=[];
  if(curTb&&curTb.series){
    const sers=_seriesSortBooks([curTb,...cand.filter(b=>b.series===curTb.series)]);
    const i=sers.findIndex(b=>b.id===curTb.id);
    head=i>=0?sers.slice(i+1):[];
    const hid=new Set(head.map(b=>b.id));
    cand=cand.filter(b=>!hid.has(b.id));
  }
  cand=[...head,...cand.sort((a,b)=>String(a.title).localeCompare(String(b.title)))];
  // 같은 영역의 **다른 줄**에 있는 교재 — 이 줄로 옮겨올 수 있게
  // (예: 요즘 초등 영단어 3이 수업 줄에 있는데 과제 줄로 이어가고 싶을 때)
  const subjKeys=Object.keys(cm).filter(k=>k.replace(/_\d+$/,'')===base);
  const subjBooks=subjKeys.map(k=>({s:k,mat:cm[k],tb:_pgTbOf(cm[k])}));
  const myTrack=_pgTracksOf(subjBooks).find(t=>t.books.some(b=>b.s===afterKey));
  const mine=new Set((myTrack?myTrack.books:[]).map(b=>b.s));
  const movable=subjBooks.filter(b=>{
    if(mine.has(b.s)||!b.tb)return false;
    const r=_pgLastRec(classId,b.tb),kk=tbUnitKeys(b.tb);
    return !(r&&r.idx>=kk.length-1);              // 완강한 책은 옮길 이유가 없음
  });
  if(!cand.length&&!movable.length){toast('추가할 수 있는 교재가 없어요 — 자료 DB에 먼저 등록해 주세요');return;}
  const optAdd=cand.map((b,i)=>`<option value="new:${escAttr(b.id)}"${i===0?' selected':''}>${escAttr(b.title)}${b.category?' ('+escAttr(b.category)+')':''}${head.length&&i<head.length?' · 같은 시리즈':''}</option>`).join('');
  const optMove=movable.map(b=>`<option value="move:${escAttr(b.s)}">${escAttr(b.tb.title)}</option>`).join('');
  _pgFixOpen({
    mode:'next',classId,afterKey,
    title:'다음 교재 고르기',
    desc:`<b>${escAttr(curTb?curTb.title:mat.book)}</b>가 끝난 뒤 이 줄에서 이어서 나갈 교재예요`,
    label:'다음 교재',
    options:(optAdd?`<optgroup label="새로 추가">${optAdd}</optgroup>`:'')
           +(optMove?`<optgroup label="다른 줄에서 옮겨오기">${optMove}</optgroup>`:''),
    hint:`${SLBL[base]||base} 영역 · <b>${escAttr(curTb?curTb.title:mat.book)}</b> 바로 뒤에 들어갑니다. 진행 방식(수업/과제)은 그 줄을 그대로 따릅니다.`
      +(optMove?'<br>옮겨오면 원래 줄에서는 빠집니다.':''),
  });
}
async function pgFixSave(){
  const ctx=_pgFixCtx;if(!ctx)return;
  const val=document.getElementById('pgfix-sel').value;
  const c=DB.classes().find(x=>x.id===ctx.classId);if(!c)return;
  let msg='';
  if(ctx.mode==='done'){
    const du={...(c.doneUpto||{})};
    if(val)du[ctx.bookId]=val;else delete du[ctx.bookId];
    if(Object.keys(du).length)c.doneUpto=du;else delete c.doneUpto;
    msg=val?`진도를 ${val}까지로 맞췄어요`:'수업 기록 기준으로 되돌렸어요';
  }else if(ctx.mode==='next'){
    const cm=c.commonMaterials||{};
    const base=ctx.afterKey.replace(/_\d+$/,'');
    const isMove=val.indexOf('move:')===0;
    const arg=val.replace(/^(new|move):/,'');
    let ins=null,title='';
    if(isMove){
      if(!cm[arg]){toast('옮길 교재를 찾지 못했어요');return;}
      ins={...cm[arg]};
      delete ins.run;                                   // 이 줄을 이어받으므로 줄 시작 표식은 떼어낸다
      title=ins.book||'';
    }else{
      const tb=(_cache.globalTextbooks||[]).find(b=>b.id===arg);
      if(!tb){toast('교재를 고르세요');return;}
      ins={book:tb.title,unit:'',bookId:tb.id};
      title=tb.title;
    }
    // 그 영역의 체인 순서를 유지하면서 afterKey 바로 뒤에 끼우고 연번을 다시 매긴다
    const list=[],others={};
    Object.keys(cm).forEach(k=>{
      if(k.replace(/_\d+$/,'')===base){
        if(!(isMove&&k===arg))list.push(cm[k]);          // 옮기는 책은 원래 자리에서 뺀다
        if(k===ctx.afterKey)list.push(ins);
      }else others[k]=cm[k];
    });
    const out={};
    list.forEach((v,i)=>{out[i===0?base:base+'_'+(i+1)]=v;});
    Object.keys(others).forEach(k=>{out[k]=others[k];});
    c.commonMaterials=out;
    const _j=(typeof ppJosa==='function')?ppJosa(title,'을','를'):'을(를)';
    msg=isMove?`${title}${_j} 이 줄로 옮겼어요`:`${title}${_j} 다음 교재로 넣었어요`;
  }
  try{await supaUpsert('classes',ctx.classId,c,null);}
  catch(e){console.error('pgFixSave:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===ctx.classId);if(i>=0)_cache.globalClasses[i]=c;
  closeM('m-pg-fix');
  _pgFixCtx=null;
  renderClsLessons(ctx.classId);
  toast(msg);
}
// 미등록 교재를 영역 체인에 '동시 진행 줄'로 추가 — 교재 카테고리로 영역을 정한다
async function pgAddMissingBook(classId,bookId,run){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const tb=(_cache.globalTextbooks||[]).find(x=>x.id===bookId);if(!tb)return;
  const base=Object.keys(_CAT_KO).find(k=>_CAT_KO[k]===tb.category)||'reading';
  const lbl=run==='hw'?'과제':'수업';
  askConfirm('교재 체인에 추가',
    tb.title+' → '+(SLBL[base]||base)+' 영역의 「동시 · '+lbl+'」 줄로 추가할까요?'+'\n'+'\n'
    +(run==='hw'?'수업 없는 날마다 1과씩 진행해 다음 수업일에 진도로 표시됩니다.':'수업일마다 1과씩 진행합니다.')
    +'\n'+'기존 교재를 기다리지 않고 함께 진행돼요.','추가','bt',async()=>{
    const cm={...(c.commonMaterials||{})};
    // 연속 클릭(재렌더 전)으로 같은 책이 두 번 들어가지 않게
    if(Object.values(cm).some(v=>v&&(v.bookId?v.bookId===tb.id:v.book===tb.title))){
      toast('이미 교재 체인에 있어요');renderClsLessons(classId);return;
    }
    let key=base,n=1;
    while(cm[key]){n++;key=base+'_'+n;}
    const rec=_pgLastRec(classId,tb);
    const keys=tbUnitKeys(tb);
    cm[key]={book:tb.title,unit:(!rec&&keys.length)?keys[0]:'',bookId:tb.id,run};
    c.commonMaterials=cm;
    try{await supaUpsert('classes',classId,c,null);}
    catch(e){console.error('pgAddMissingBook:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
    const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
    renderClsLessons(classId);
    toast(tb.title+' — '+lbl+' 줄로 추가했어요');
  });
}
// ── 알림 구독 현황 (선생님용) ──
// push_subs는 endpoint가 담겨 있어 익명 읽기를 막아 뒀다. 역할·학생만 담은 push_subs_pub 뷰를 읽는다.
// 테이블·뷰를 아직 안 만든 환경에서도 조용히 넘어가게 실패는 무시한다.
let _pgPushSubs=null,_pgPushSubsAt=0;
async function _pgLoadPushSubs(){
  if(_pgPushSubs&&Date.now()-_pgPushSubsAt<120000)return _pgPushSubs;
  try{
    const r=await fetch(SUPA_URL+'/rest/v1/push_subs_pub?select=sid,role',{headers:SUPA_HEADERS});
    if(!r.ok)throw new Error('HTTP '+r.status);
    const rows=await r.json();
    _pgPushSubs={};
    rows.forEach(x=>{if(!x.sid)return;(_pgPushSubs[x.sid]=_pgPushSubs[x.sid]||new Set()).add(x.role||'student');});
  }catch(e){_pgPushSubs={};}   // 미설정·권한 없음 — 표시만 생략
  _pgPushSubsAt=Date.now();
  return _pgPushSubs;
}
// 숙제 패널을 그린 뒤 학생별 🔔 상태만 채워 넣는다 (렌더를 기다리게 하지 않음)
async function _pgPushBadges(){
  const map=await _pgLoadPushSubs();
  document.querySelectorAll('.hw-bell[data-sid]').forEach(el=>{
    const r=map[el.dataset.sid];
    if(!r||!r.size){el.textContent='🔕';el.title='숙제 알림이 꺼져 있어요 — 학생·학부모 앱에서 켤 수 있습니다';el.classList.remove('on');return;}
    const who=[r.has('student')?'학생':'',r.has('parent')?'학부모':''].filter(Boolean).join('·');
    el.textContent='🔔';el.title='숙제 알림 켜짐 ('+who+')';el.classList.add('on');
  });
}
// ── 클래스 안 숙제 패널 ──
// 숙제가 과제 탭에만 있어서 "이 반 아이가 어제 숙제를 했나"를 보려면 탭을 옮겨야 했다.
// 수업 준비는 클래스 화면에서 하므로, 그 자리에서 보고 체크하고 할당까지 되게 한다.
// 그 학생 그 날의 숙제 항목 (스케줄형 + 단건) — 체크에 필요한 과제 id까지 함께
function _pgHwItemsOn(sid,ds){
  const out=[];
  (_cache.assignments||[]).forEach(a=>{
    if(a._deleted||a.sid!==sid)return;
    if((a.schedule||[]).length){
      const sch=_hwSchedOf(a);
      sch.forEach(sc=>{
        if(sc.date!==ds)return;
        out.push({aid:a.id,sched:true,date:ds,cat:a.category,
          title:[sc.book||a.bookTitle||a.text||'숙제',sc.unit||''].filter(Boolean).join(' '),
          done:!!sc.done,by:sc.doneBy||''});
      });
      return;
    }
    const d=(a.due||a.date||'').slice(0,10);
    if(d!==ds)return;
    if(typeof schedCoversHw==='function'&&schedCoversHw(sid,ds,a.bookTitle||'',a.range||''))return;
    out.push({aid:a.id,sched:false,date:ds,cat:a.category,
      title:[a.bookTitle||a.text||'숙제',a.range||''].filter(Boolean).join(' '),
      done:!!a.completedAt,by:a.completedBy||''});
  });
  return out;
}
const _PG_HW_BY={student:'학생',teacher:'선생님',lesson:'수업'};
function _pgHwPanelHtml(classId){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return'';
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length)return'';
  const today=ppToday();
  const days=[];
  for(let i=6;i>=0;i--)days.push(_pgAddDays(today,-i));
  const rows=stus.map(stu=>{
    const items=_pgHwItemsOn(stu.id,today);
    // 최근 7일 점 — 숙제가 있던 날만 (없는 날은 빈 칸)
    let miss=0,counted=0,hit=0;
    const dots=days.map(ds=>{
      const st=hwDayStatus(stu.id,ds);
      if(!st.total)return `<i class="hwd none" title="${ds} · 숙제 없음"></i>`;
      counted++;
      const cls=st.perfect?'full':st.done?'part':'zero';
      if(st.done)hit++;
      return `<i class="hwd ${cls}" title="${ds} · ${st.done}/${st.total}"></i>`;
    }).join('');
    // 연속 미완료 (오늘 제외 — 아직 할 시간이 남았으므로)
    for(let i=1;i<=30;i++){
      const ds=_pgAddDays(today,-i);
      const st=hwDayStatus(stu.id,ds);
      if(!st.total)continue;
      if(st.done>0)break;
      miss++;
    }
    const lines=items.length
      ?items.map(it=>`<button class="hw-it${it.done?' on':''}" title="${it.done?'완료 '+(_PG_HW_BY[it.by]||'')+' — 눌러서 취소':'눌러서 완료 표시'}"
          onclick="pgHwToggle('${classId}','${it.aid}','${it.date}',${it.sched})">
          <span class="hw-ck">${it.done?'✓':''}</span><span class="hw-tt">${escAttr(it.title)}</span>
          ${it.done&&it.by?`<em>${_PG_HW_BY[it.by]||it.by}</em>`:''}</button>`).join('')
      :`<span class="hw-empty">오늘 배정된 숙제가 없어요</span>`;
    return `<div class="hw-row">
      <span class="hw-stu">${escAttr(stu.name)}<i class="hw-bell" data-sid="${stu.id}" title="알림 상태 확인 중"></i>${miss>=3?`<b title="숙제가 있던 날 기준 ${miss}일 연속 미완료">${miss}일 밀림</b>`:''}</span>
      <div class="hw-items">${lines}</div>
      <span class="hw-dots" title="최근 7일 — 진한 점=전부, 중간=일부, 연한=안 함">${dots}<em>${counted?hit+'/'+counted:''}</em></span>
    </div>`;
  }).join('');
  setTimeout(_pgPushBadges,0);   // 구독 현황은 네트워크라 렌더 후 채운다
  return `<details class="tb-card hw-card" open>
    <summary class="tb-head"><span class="tb-t">📕 숙제 <span class="hw-date">${today.slice(5).replace('-','/')}</span></span>
      <span class="tb-hint">눌러서 완료 체크 · 최근 7일 점으로 흐름 확인</span></summary>
    <div class="hw-body">${rows}
      <div class="hw-acts">
        <button class="btn bo bxxs" onclick="pgHwAdd('${classId}')">+ 숙제 추가</button>
        <button class="btn bo bxxs" onclick="openBulkAssign('${classId}')">일괄 할당</button>
        <button class="btn bo bxxs" onclick="swTab('t-assign')">${luIcon('calendar',15)||''} 숙제 캘린더</button>
      </div>
    </div>
  </details>`;
}
// 패널에서 바로 완료 토글 (과제 탭의 토글과 같은 저장, 화면만 이 패널을 다시 그린다)
async function pgHwToggle(classId,aid,ds,sched){
  const a=(_cache.assignments||[]).find(x=>x.id===aid);if(!a)return;
  let on;
  if(sched){
    const sc=(a.schedule||[]).find(x=>x.date===ds);if(!sc)return;
    if(sc.done){delete sc.done;delete sc.doneBy;delete sc.doneAt;on=false;}
    else{sc.done=true;sc.doneBy='teacher';sc.doneAt=new Date().toISOString();on=true;}
  }else{
    if(a.completedAt){delete a.completedAt;delete a.completedBy;on=false;}
    else{a.completedAt=new Date().toISOString();a.completedBy='teacher';on=true;}
  }
  try{await supaUpsert('assignments',a.id,a,a.sid);}
  catch(e){console.error('pgHwToggle:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  toast(on?'완료로 표시했어요 ✓':'완료 표시를 취소했어요');
}
// 숙제 칩의 ✕ — 스케줄형(반복·클래스5)은 그 날 한 칸만 빼고, 단건 과제는 휴지통으로 보낸다
async function pgHwDel(ev,classId,aid,ds,sched){
  if(ev){ev.stopPropagation();ev.preventDefault();}
  pgMenuClose();
  const a=(_cache.assignments||[]).find(x=>x.id===aid);if(!a)return;
  const name=[a.bookTitle||a.text||'숙제'].filter(Boolean).join(' ');
  if(sched){
    const sc=(a.schedule||[]).find(x=>x.date===ds);if(!sc)return;
    askConfirm('이 날 숙제 빼기',
      name+(sc.unit?' '+sc.unit:'')+'\n'+ds+' 몫만 빼고 나머지 일정은 그대로 둘까요?','빼기','bd',async()=>{
      a.schedule=(a.schedule||[]).filter(x=>x.date!==ds);
      try{await supaUpsert('assignments',a.id,a,a.sid);}
      catch(e){console.error('pgHwDel:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
      renderClsLessons(classId);
      toast(ds+' 숙제를 뺐어요');
    });
    return;
  }
  askConfirm('숙제 지우기',name+'\n'+'이 과제를 휴지통으로 보낼까요? (백업 탭에서 되살릴 수 있어요)','지우기','bd',async()=>{
    try{await supaTrash('assignments',_cache.assignments,aid);}
    catch(e){console.error('pgHwDel trash:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
    renderClsLessons(classId);
    toast('휴지통으로 보냈어요');
  });
}
// 이 반 학생을 미리 고른 상태로 과제 추가 모달 열기
function pgHwAdd(classId){
  const c=DB.classes().find(x=>x.id===classId);
  openM('m-add-assign');
  const dEl=document.getElementById('modal-assign-date'),uEl=document.getElementById('modal-assign-due');
  const t=ppToday();
  if(dEl)dEl.value=t;
  if(uEl)uEl.value=_nextClassDay(t,(c&&c.days)||[],new Set((c&&c.skipDates)||[]),new Set((c&&c.extraDates)||[]))||t;
}
const _pgAddDays=(ds,n)=>{const d=new Date(ds+'T12:00:00');d.setDate(d.getDate()+n);return _pgYmd(d);};
// ── 영역별 진도 보드 ──
// 같은 영역에서 교재가 동시에 돌면(1200은 수업 중, 요즘 초등 영단어는 과제) 캘린더 칩만으로는
// "지금 뭘 어디까지 하고 있는지"가 안 보인다. 영역 × 줄로 접어 진행률·방식·예상 완료를 한 줄에 둔다.
function _pgTrackBoardHtml(classId){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return'';
  const today=ppToday();
  const horizon=(()=>{const d=new Date(today+'T12:00:00');d.setFullYear(d.getFullYear()+1);return _pgYmd(d);})();
  let plan;try{plan=_pgComposePlan(classId,c,horizon);}catch(e){console.error('_pgTrackBoardHtml:',e);return'';}
  if(!plan||!plan.books||!plan.books.length)return'';
  const {books,ghostBy}=plan;
  // 교재별 예정 마지막 날 = 예상 완료일
  const lastBy={};
  Object.entries(ghostBy||{}).forEach(([d,list])=>{
    (list||[]).forEach(g=>{if(!lastBy[g.tbId]||d>lastBy[g.tbId])lastBy[g.tbId]=d;});
  });
  const checks=[];   // 점검 목록 — 선생님이 바로 조처할 것들
  // 되감긴 기록: 앞 단원을 뒤 날짜에 또 기록한 경우. 진도는 '가장 멀리 나간 단원' 기준이라
  // 복습으로 처리되는데, 왜 그 단원이 예정에 안 나오는지 안 보이면 오류처럼 느껴진다
  books.forEach(b=>{
    const recs=[];
    (_cache.lessons||[]).forEach(l=>{
      if(l.classId!==classId||!l.materials||!l.date||l.date>today)return;
      Object.values(l.materials).forEach(m=>{
        if(!m||!m.book)return;
        if(m.bookId?m.bookId!==b.tb.id:m.book!==b.tb.title)return;
        const i=_pgUnitIdx(b.tb,m.unit);
        if(i>=0)recs.push({date:l.date,idx:i,unit:m.unit});
      });
    });
    recs.sort((x,y)=>x.date.localeCompare(y.date));
    let mx=-1,back=null;
    recs.forEach(r=>{if(r.idx<mx&&(!back||r.date>back.date))back={...r,max:mx};else if(r.idx>mx)mx=r.idx;});
    // 진도를 직접 지정해 둔 책은 선생님이 이미 확인한 것으로 보고 알리지 않는다
    if(back&&!((c.doneUpto||{})[b.tb.id])){
      const keys=tbUnitKeys(b.tb);
      checks.push({ico:'📉',kind:'되감김',title:b.tb.title,
        msg:`${back.date.slice(5).replace('-','/')} ${back.unit} 기록이 앞선 ${escAttr(keys[back.max]||'')} 뒤에 있어요 — 복습으로 보고 진도는 ${escAttr(keys[back.max]||'')}까지로 셉니다`,
        act:`<button class="btn bo bxxs" title="그 날 수업 기록의 단원을 고칩니다" onclick="openClassLessonEdit('${classId}','${back.date}')">${back.date.slice(5).replace('-','/')} 기록 수정</button>`
           +`<button class="btn bo bxxs" title="기록은 두고 진도 기준점만 맞춥니다" onclick="pgEditProgress('${classId}','${b.tb.id}')">진도 수정</button>`});
    }
  });
  // 지금 책·진행 숫자·줄 판정은 **공용 ppFlow 하나**로 — 교재 여정·대시보드·수업 창이 같은 값을 본다
  const flow=(typeof ppFlow==='function')?ppFlow(classId,{etaBy:lastBy}):[];
  const MODE_LBL={hw:'과제',class:'수업',alt:'교대',perClass:'매 수업'};
  const rows=[];
  flow.forEach(area=>{
    const base=area.area;
    const color=_PG_CAT_COLORS[base]||'var(--text-muted)';
    const tr=[];
    (area.tracks||[]).forEach(t=>{
      const cur=t.now;
      if(!cur)return;                               // 줄 전체 완강 — 보드에서 생략
      const done=cur.doneIdx+1,total=cur.total;
      const pct=total?Math.round(done*100/total):0;
      const mode=MODE_LBL[t.mode]||'수업';
      const modeCls=t.mode==='hw'?'hw':t.mode==='alt'?'alt':'cls';
      const eta=cur.eta||'';
      const next=t.books[t.nowIdx+1];
      // 점검: 이 줄이 곧 마른다 (60일 안에 끝나는데 다음 교재가 없음)
      if(!next&&eta&&eta<=_pgAddDays(today,60))
        checks.push({ico:'🔚',kind:'마름',title:cur.tb.title,
          msg:`${eta.slice(5).replace('-','/')} 완료 예정인데 이 줄에 다음 교재가 없어요`,
          act:`<button class="btn bt bxxs" onclick="pgPickNext('${classId}','${escAttr(cur.key)}')">다음 교재 고르기</button>`});
      tr.push(`<div class="tb-track">
        <span class="tb-mode ${modeCls}">${mode}</span>
        <span class="tb-book" title="${escAttr(cur.tb.title)}">${escAttr(cur.tb.title)}</span>
        <span class="tb-bar" title="${done}/${total}과"><i style="width:${pct}%;background:${color}"></i></span>
        <span class="tb-num">${done}<em>/${total}</em></span>
        <span class="tb-eta">${eta?'~'+eta.slice(5).replace('-','/'):'<span style="opacity:.5">1년 내 미완</span>'}</span>
        <span class="tb-next">${next?'다음 '+escAttr(next.tb.title):'<span class="tb-end">다음 교재 없음</span>'}</span>
        <button class="tb-fix" title="진도 수정 — 어디까지 끝냈는지 직접 맞추기" onclick="pgEditProgress('${classId}','${cur.tb.id}')">✏️</button>
      </div>`);
    });
    if(!tr.length)return;
    rows.push(`<div class="tb-row">
      <span class="tb-subj"><i style="background:${color}"></i>${escAttr(area.label||base)}${tr.length>1?`<b>${tr.length}줄</b>`:''}</span>
      <div class="tb-tracks">${tr.join('')}</div>
    </div>`);
  });
  // 수업 기록엔 있는데 교재 체인엔 없는 교재 — 예정이 전혀 안 잡혀 진도가 비어 보인다.
  // 최근(60일) 기록이 있고 아직 끝나지 않은 책만 — 오래 전에 뺀 책까지 들추지 않게
  const have=new Set(books.map(b=>b.tb.id));
  const cut=(()=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-60);return _pgYmd(d);})();
  const miss={};
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.materials||!l.date||l.date<cut||l.date>today)return;
    Object.entries(l.materials).forEach(([k,v])=>{
      const bk=k.replace(/_\d+$/,'');
      if(bk==='pencil_down'||bk==='sing_together'||bk==='_book')return;
      if(!v||!v.book)return;
      const tb=v.bookId?(_cache.globalTextbooks||[]).find(x=>x.id===v.bookId)
                       :(_cache.globalTextbooks||[]).find(x=>x.title===v.book);
      if(!tb||have.has(tb.id)||!tbUnitKeys(tb).length)return;
      const r=_pgLastRec(classId,tb);
      if(r&&r.idx>=tbUnitKeys(tb).length-1)return;   // 완강한 책은 알릴 필요 없음
      const m=miss[tb.id]||(miss[tb.id]={tb,n:0,date:''});
      m.n++;if(l.date>m.date)m.date=l.date;
    });
  });
  Object.values(miss).sort((a,b)=>b.date.localeCompare(a.date)).forEach(m=>{
    const r=_pgLastRec(classId,m.tb),keys=tbUnitKeys(m.tb);
    checks.push({ico:'⚠️',kind:'미등록',title:m.tb.title,
      msg:`수업 기록 ${m.n}회(최근 ${m.date.slice(5).replace('-','/')}, ${r?r.idx+1:0}/${keys.length}과)인데 교재 체인에 없어 <b>예정이 잡히지 않아요</b>`,
      act:`<button class="btn bo bxxs" title="수업일마다 1과씩 진행하는 줄로 추가" onclick="pgAddMissingBook('${classId}','${m.tb.id}','class')">수업 줄로</button>`
         +`<button class="btn bo bxxs" title="수업 없는 날 1과씩 진행하는 줄로 추가" onclick="pgAddMissingBook('${classId}','${m.tb.id}','hw')">과제 줄로</button>`});
  });
  const checksHtml=checks.length?`<details class="tb-card tb-chk" open>
    <summary class="tb-head"><span class="tb-t">${luIcon('wrench',15)||''} 손봐야 할 진도<span class="tb-cnt">${checks.length}</span></span>
      <span class="tb-hint">여기서 바로 고칠 수 있어요</span></summary>
    <div class="tb-chk-body">${checks.map(k=>`<div class="tb-chk-r">
      <span class="tb-chk-i">${k.ico}</span>
      <span class="tb-chk-k">${k.kind}</span>
      <span class="tb-chk-t"><b>${escAttr(k.title)}</b><em>${k.msg}</em></span>
      <span class="tb-chk-a">${k.act}</span>
    </div>`).join('')}</div>
  </details>`:'';
  if(!rows.length)return checksHtml;
  return checksHtml+`<details class="tb-card" open>
    <summary class="tb-head"><span class="tb-t">${luIcon('bar-chart-3',15)||''} 영역별 진도</span>
      <span class="tb-hint">같은 영역에서 동시에 도는 교재는 줄로 나뉘어 보여요 · ✏️로 진도 수정</span></summary>
    <div class="tb-body">${rows.join('')}</div>
  </details>`;
}
// ── 숙제 칩 계산 (진도 캘린더·숙제 캘린더 공용) ──
// 한 학생의 날짜별 숙제 칩을 만든다. 2026-07-15에 숙제를 과제 탭으로 떼어낸 건 진도 칩과 섞여
// 헷갈렸기 때문인데, 한 화면에서 보려면 '레이어'로 켜고 끌 수 있어야 한다 → 계산을 공용으로 둔다.
// 반환: {날짜:[{ord,color,label,tip,done,aid,sched,kind}]}  kind: 'recur'|'class5'|'single'
function _pgHwChips(sid,ym){
  const out={};
  (_cache.assignments||[]).forEach(a=>{
    if(a._deleted||a.sid!==sid)return;
    const sch=_hwSchedOf(a);
    if((sch||[]).length){
      const isRecur=a.category==='recur';
      sch.forEach(sc=>{
        if(!sc.date||(ym&&!sc.date.startsWith(ym)))return;
        const app=_hwAppOf(a,sc);
        (out[sc.date]=out[sc.date]||[]).push({
          ord:app?15:(isRecur?10:20),kind:(app||!isRecur)?'class5':'recur',aid:a.id,sched:true,
          color:app?_PG_C5_COLOR:(isRecur?'#2F7D63':_PG_C5_COLOR),
          label:app?app.lbl:(sc.unit||sc.book||a.bookTitle||''),
          tip:`${asgSrcLabel(a)} — ${[a.bookTitle&&a.bookTitle!==sc.book?a.bookTitle:'',sc.book,sc.unit].filter(Boolean).join(' · ')}`,
          done:!!sc.done,by:sc.doneBy||''});
      });
      return;
    }
    const due=a.due||'';
    if(!due||(ym&&!due.startsWith(ym)))return;
    (out[due]=out[due]||[]).push({
      ord:30,kind:'single',aid:a.id,sched:false,
      color:_PG_CAT_COLORS[a.category]||'var(--text-muted)',
      label:[a.bookTitle||a.text||'',a.range].filter(Boolean).join(' ').trim()||'과제',
      tip:`${asgSrcLabel(a)} — ${[a.bookTitle||a.text,a.range].filter(Boolean).join(' · ')} (마감 ${due})`,
      done:!!a.completedAt,by:a.completedBy||''});
  });
  return out;
}
// 진도 캘린더에서 어떤 레이어를 보여줄지 (기기별로 기억)
const _PG_LAYERS=[
  {k:'prog',lbl:'진도',ico:'📘'},
  {k:'hw',lbl:'숙제',ico:'📕'},
  {k:'c5',lbl:'클래스5·리딩앤',ico:'🎮'},
];
function pgLayerOn(k){
  try{
    const v=localStorage.getItem('pp_pg_layers');
    if(v===null)return true;                 // 처음엔 전부 켜짐
    return JSON.parse(v).indexOf(k)>=0;
  }catch(e){return true;}
}
function pgLayerToggle(k,classId){
  const on=_PG_LAYERS.map(x=>x.k).filter(x=>x===k?!pgLayerOn(x):pgLayerOn(x));
  try{localStorage.setItem('pp_pg_layers',JSON.stringify(on));}catch(e){}
  renderClsLessons(classId);
}
// 숙제 레이어를 볼 학생 (여러 명이면 고를 수 있게)
let _pgHwStuId='';
function pgHwStuPick(sid,classId){_pgHwStuId=sid;renderClsLessons(classId);}
function _pgCalHtml(classId){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return'';
  const todayStr=ppToday();
  const ym=_pgCalMonth||todayStr.slice(0,7);
  const[y,m]=ym.split('-').map(Number);
  // 예정 구성은 캘린더·예정 편집 모달·폼 자동 채움이 같은 계산을 공유 (내용 불일치 방지)
  const dim=new Date(y,m,0).getDate();
  const endDow=new Date(y,m-1,dim).getDay();
  // 마지막 주 잔여 칸(다음 달 머리)까지 예정을 계산해야 연속 표시 칩이 그려짐
  const planEnd=endDow<6?_pgYmd(new Date(y,m,6-endDow)):`${ym}-${String(dim).padStart(2,'0')}`;
  const {books,clsStus,singDates,singBy,ghostBy,ortGhostBy,skipSet}=_pgComposePlan(classId,c,planEnd);
  // ── 레이어: 진도 / 숙제 / 클래스5·리딩앤 ── (2026-11-01 숙제 캘린더를 이 캘린더로 합침)
  const LY={prog:pgLayerOn('prog'),hw:pgLayerOn('hw'),c5:pgLayerOn('c5')};
  const hwStu=(clsStus.find(s=>s.id===_pgHwStuId)||clsStus[0]||null);
  const hwChips=(LY.hw||LY.c5)&&hwStu?_pgHwChips(hwStu.id,ym):{};
  const hwPlan=LY.hw?_pgHomeworkPlan(classId,c):{};   // 아직 할당 전 📕 제안 (점선)
  const colorOf=(tbId,cat)=>_PG_CAT_COLORS[cat]||books.find(b=>b.tb.id===tbId)?.color||'var(--text-muted)';
  // (숙제·클래스5 칩은 과제 메뉴의 숙제 캘린더로 분리 — 이 캘린더는 '진도'만)
  // 실제 기록 칩: date → {tbKey:{tbId,book,units}} + 원서·펜슬다운 기록
  const recBy={},ortRecBy={},pdRecBy={},lessonDates=new Set();
  (_cache.lessons||[]).forEach(l=>{
    if(l.classId!==classId||!l.date)return;
    lessonDates.add(l.date);
    Object.entries(l.materials||{}).forEach(([k,v])=>{
      if(!v||!v.book)return;
      const bk=k.replace(/_\d+$/,'');
      if(bk==='pencil_down'||bk==='sing_together'){(pdRecBy[l.date]=pdRecBy[l.date]||new Set()).add(v.book||'Pencil Down');return;}
      if(bk==='_book'){(ortRecBy[l.date]=ortRecBy[l.date]||new Set()).add(v.book);return;}
      const tb=_pgTbOf(v);
      const key=tb?.id||'t:'+v.book;
      recBy[l.date]=recBy[l.date]||{};
      const e=recBy[l.date][key]=recBy[l.date][key]||{tbId:tb?.id||'',book:v.book,cat:bk,units:new Set()};
      (v.unit||'').split(',').map(s=>s.trim()).filter(Boolean).forEach(u=>e.units.add(u));
    });
  });
  // 원서(ORT) 툴팁용 섹션명
  const ortMeta={};
  (_cache.library||[]).forEach(b=>{if(b.ortSeq!=null)ortMeta[_pgNorm(b.title)]={group:b.ortGroup||''};});
  const ortGroupOf=t=>(ortMeta[_pgNorm(t)]||{}).group||'';
  // 달력 그리드
  const _extraCellSet=new Set(c.extraDates||[]); // 추가 수업일 (특강)
  const startDow=new Date(y,m-1,1).getDay();
  const cells=[];
  // 월 경계 연속 표시(2026-08-09): 첫 주 앞 칸=지난달 꼬리, 마지막 주 뒤 칸=다음 달 머리 —
  // 빈 칸 대신 실제 날짜 셀(om 흐림)로 렌더해 주 단위가 끊기지 않음. 칩·드래그·클릭 기능 동일.
  const _dayCell=(dt,inMonth)=>{
    const ds=_pgYmd(dt);
    const dd=dt.getDate();
    const dow=_PG_DOW[dt.getDay()];
    const isClassDay=(c.days||[]).includes(dow)||_extraCellSet.has(ds); // 추가 수업일 포함
    // 미래 날짜에 남은 기록은 완료(진한 칩)가 아니라 예정(점선)으로 표시
    const futRec=ds>todayStr;
    const recCls=futRec?'pg-chip ghost':'pg-chip rec';
    const futTip=futRec?' — 미래 기록(예정), 누르면 수정':'';
    // 셀 내 표시 순서: 어휘 → (파닉스·어법·리스닝·라이팅·내신) → 리딩 → 원서 → 펜슬다운 (기록·예정 각각 동일 규칙)
    const _prio=k=>({vocab:10,phonics:20,grammar:30,listening:40,writing:50,naesin:60,reading:70}[String(k||'').replace(/_\d+$/,'')]??65);
    let chips=Object.values(recBy[ds]||{}).sort((a,b)=>_prio(a.cat)-_prio(b.cat)).map(e=>{
      const us=[...e.units];
      return`<span class="${recCls} has-x" style="--pgc:${colorOf(e.tbId,e.cat)}" title="${escAttr((SLBL[e.cat]?SLBL[e.cat]+' · ':'')+e.book+(us.length?' — '+us.join(', '):'')+futTip+' · 우클릭=메뉴, ✕=이 진도만 지우기')}" oncontextmenu="pgChipMenu(event,'rec','${classId}','${ds}','${escAttr(e.tbId||'')}','','')" onclick="event.stopPropagation();openClassLessonEdit('${classId}','${ds}')">${us.length?us.join(', '):'✓'}<i class="pg-x" title="이 진도만 지우기" onclick="pgRecMatDel(event,'${classId}','${ds}','${escAttr(e.tbId||'')}','${escJsA(e.book)}')">✕</i></span>`;
    }).join('');
    chips+=[...(ortRecBy[ds]||[])].map(t=>
      `<span class="${recCls}" style="--pgc:${_PG_ORT_COLOR}" title="${escAttr('원서 — '+t+(ortGroupOf(t)?' ('+ortGroupOf(t)+')':'')+' · 클릭=AR·완독 편집')}" onclick="event.stopPropagation();pgOrtRecEdit('${classId}','${escJsA(t)}','${ds}')">📗 ${t}</span>`
    ).join('');
    chips+=[...(pdRecBy[ds]||[])].map(t=>
      `<span class="${recCls} has-x" style="--pgc:#7B1FA2" title="${escAttr('Pencil Down — '+t+futTip+' · 우클릭=메뉴, ✕=이 기록만 지우기')}" oncontextmenu="pgChipMenu(event,'rec','${classId}','${ds}','','${escJsA(t)}')" onclick="event.stopPropagation();openClassLessonEdit('${classId}','${ds}')">✏️ ${t}<i class="pg-x" title="이 기록만 지우기" onclick="pgRecMatDel(event,'${classId}','${ds}','','${escJsA(t)}')">✕</i></span>`
    ).join('');
    if(!chips&&lessonDates.has(ds))chips=`<span class="${recCls}" style="--pgc:var(--neutral)" onclick="event.stopPropagation();openClassLessonEdit('${classId}','${ds}')">수업</span>`;
    chips+=(ghostBy[ds]||[]).slice().sort((a,b)=>_prio(a.s)-_prio(b.s)).map(g=>
      `<span class="pg-chip ghost has-x" draggable="true" style="--pgc:${g.color}" title="${escAttr(g.title+' — '+g.unit+' (끌어서 이동 · 더블클릭=기록 확정 · 우클릭=메뉴 · ✕=이 날에서 빼기)')}" ondragstart="pgDragStart(event,'${classId}','${g.tbId}','${escJsA(g.unit)}','${escJsA(g.s)}')" oncontextmenu="pgChipMenu(event,'ghost','${classId}','${ds}','${g.tbId}','${escJsA(g.unit)}','${escJsA(g.s)}')" onclick="event.stopPropagation();pgChipTapDelayed(this,'${classId}','${g.tbId}','${escJsA(g.unit)}','${escJsA(g.s)}')" ondblclick="pgGhostDbl(event,'${classId}','${g.tbId}','${escJsA(g.unit)}','${ds}','${escJsA(g.s)}')">${g.unit}<i class="pg-x" title="이 날에서 빼기" onclick="pgChipSkip(event,'${classId}','${g.tbId}','${ds}','${escJsA(g.title)}')">✕</i></span>`
    ).join('');
    chips+=(ortGhostBy[ds]||[]).map(g=>
      `<span class="pg-chip ghost" draggable="true" style="--pgc:${_PG_ORT_COLOR}" title="${escAttr((clsStus.length>1?g.name+' — ':'')+g.title+(ortGroupOf(g.title)?' · '+ortGroupOf(g.title):'')+' (원서 예정 — 끌어서 옮기기, 더블클릭=읽음 기록)')}" ondragstart="pgDragStart(event,'${classId}','ort:${g.sid}','${escJsA(g.title)}')" onclick="event.stopPropagation();pgChipTapDelayed(this,'${classId}','ort:${g.sid}','${escJsA(g.title)}')" ondblclick="pgOrtDbl(event,'${classId}','${g.sid}','${escJsA(g.title)}','${ds}')">📗 ${clsStus.length>1?g.name+'·':''}${g.title}</span>`
    ).join('');
    if(singDates.has(ds)){ // 씽도 유닛 칩과 같은 핀 모델 — 드래그·탭으로 이동 (앵커 키 'sing:'+책id)
      const _sk='sing:'+(singBy[ds]||'');
      chips+=`<span class="pg-chip ghost" draggable="true" style="--pgc:#7B1FA2" title="리딩 책 완주 기념 Pencil Down — Sing Together (예정 — 미래 날짜로 끌면 이동, 오늘·지난 날짜에 놓으면 그날 수업으로 기록, 더블클릭=기록 확정)" ondragstart="pgDragStart(event,'${classId}','${_sk}','Sing Together','sing')" onclick="event.stopPropagation();pgChipTapDelayed(this,'${classId}','${_sk}','Sing Together','sing')" ondblclick="pgSingDbl(event,'${classId}','${ds}')">✏️🎵 Sing Together</span>`;
    }
    if(!LY.prog)chips='';   // 진도 레이어를 끄면 진도·원서·씽 칩을 비운다
    // ── 숙제 칩 ── 반복=청록 / 클래스5·리딩앤=마젠타 / 단건=과목색. 완료된 스케줄형은 ✓만
    (hwChips[ds]||[]).slice().sort((a,b)=>a.ord-b.ord).forEach(x=>{
      const isC5=x.kind==='class5';
      if(isC5?!LY.c5:!LY.hw)return;
      const compact=x.done&&x.sched;
      const lbl=compact?'✓':escAttr(String(x.label).length>12?String(x.label).slice(0,12)+'…':x.label)+(x.done?' ✓':'');
      chips+=`<span class="pg-chip rec pg-hw${compact?' hw-done':''} has-x" style="--pgc:${x.color}${x.done?';opacity:.55':''}" title="${escAttr('📕 숙제 · '+x.tip+(x.done?' · 제출완료'+(x.by?'('+(_PG_HW_BY[x.by]||x.by)+')':''):'')+' · 클릭=완료 토글, ✕=이 숙제 지우기')}" onclick="event.stopPropagation();pgHwToggle('${classId}','${x.aid}','${ds}',${x.sched})">${lbl}<i class="pg-x" title="이 숙제 지우기" onclick="pgHwDel(event,'${classId}','${x.aid}','${ds}',${x.sched})">✕</i></span>`;
    });
    // 아직 할당 전 수업 연계 숙제 제안 (점선 📕)
    if(LY.hw)(hwPlan[ds]||[]).filter(h=>!h.assigned).forEach(hw=>{
      const col=_PG_CAT_COLORS[hw.subject]||'var(--text-muted)';
      chips+=`<span class="pg-chip pg-hw ghost" style="--pgc:${col}" title="${escAttr((SLBL[hw.subject]?SLBL[hw.subject]+' ':'')+hw.book+' '+hw.unit+' 숙제 제안 (클릭=할당·취소 선택)')}" onclick="hwChipMenu(event,'${classId}','${hw.subject}','${escJsA(hw.book)}','${escAttr(hw.bookId)}','${escJsA(hw.unit)}','${ds}')">${hw.unit}</span>`;
    });
    const isSkip=skipSet.has(ds);
    const skipMark=isSkip?`<span class="pg-skip-mark" title="수업 안 함 (휴강·결석) — 이후 진도가 하루씩 밀렸어요. 누르면 되돌리기">🚫 수업 안 함</span>`:'';
    cells.push(`<div class="pg-cell${isClassDay?' cd':''}${ds===todayStr?' today':''}${ds<todayStr?' past':''}${isSkip?' skip':''}${inMonth?'':' om'}" data-ds="${ds}" ondragover="pgCellOver(event,'${ds}')" ondrop="pgCellDrop(event,'${classId}','${ds}')" onmousedown="pgRangeDown(event,'${classId}','${ds}')" onmouseover="pgRangeOver('${ds}')" onclick="pgCellClick(event,'${classId}','${ds}')"><div class="pg-dnum">${inMonth?dd:(dt.getMonth()+1)+'/'+dd}</div>${skipMark}${chips}</div>`);
  };
  for(let i=startDow;i>0;i--)_dayCell(new Date(y,m-1,1-i),false);
  for(let dd=1;dd<=dim;dd++)_dayCell(new Date(y,m-1,dd),true);
  for(let i=1;i<=(endDow<6?6-endDow:0);i++)_dayCell(new Date(y,m,i),false);
  // 범례: 과목 색 (같은 과목 교재는 같은 색) + 원서 한 색
  const hasOrt=Object.keys(ortGhostBy).length||Object.keys(ortRecBy).length;
  // 범례: 과목당 1개 — 현재 진행 중인 책 + '외 N권' (체인 전 권 나열 방지, 마우스 올리면 전체 커리큘럼)
  const _lgAm=_pgActiveMats(classId,c);
  const _lgGroups={};
  books.forEach(b=>{const base=b.s.replace(/_\d+$/,'');const gk=base==='naesin'?b.s:base;(_lgGroups[gk]=_lgGroups[gk]||[]).push(b);});
  const legend=Object.entries(_lgGroups).map(([gk,list])=>{
    const base=gk.replace(/_\d+$/,'');
    // 줄이 둘이면 지금 책도 둘 — 둘 다 적는다 (한 권만 적어 '빠진 책'처럼 보이던 문제)
    const acts=list.filter(b=>Object.prototype.hasOwnProperty.call(_lgAm,b.s));
    const act=acts[0]||list[0];
    const rest=list.length-(acts.length||1);
    const chain=list.map(x=>x.tb.title).join(' → ');
    return `<span class="pg-lg" title="${escAttr(list.length>1?'커리큘럼: '+chain:chain)}"><i style="background:${act.color}"></i>${SLBL[base]||''} ${(acts.length?acts:[act]).map(x=>x.tb.title).join(' · ')}${rest>0?` <span style="opacity:.55">외 ${rest}권</span>`:''}</span>`;
  }).join('')
    +(hasOrt?`<span class="pg-lg"><i style="background:${_PG_ORT_COLOR}"></i>📗 원서</span>`:'')
    +(singDates.size?`<span class="pg-lg"><i style="background:#7B1FA2"></i>✏️ Pencil Down</span>`:'');
  const hasAnchor=Object.keys(c.progressAnchors||{}).length>0;
  return`<div class="pg-cal-card${_pgMoveSel&&_pgMoveSel.classId===classId?' pg-moving':''}">
    <div class="pg-cal-head">
      <span style="font-size:14px;font-weight:800;color:var(--navy)">${luIcon('calendar',15)||''} 진도 캘린더</span>
      <button class="btn bo bxxs" onclick="pgCalNav(-1)" ondragover="pgNavDragOver(event,-1)" title="칩을 드래그한 채 올리면 이전 달로 넘어가요">◀</button>
      <span style="font-size:13.5px;font-weight:700;color:var(--navy)">${y}년 ${m}월</span>
      <button class="btn bo bxxs" onclick="pgCalNav(1)" ondragover="pgNavDragOver(event,1)" title="칩을 드래그한 채 올리면 다음 달로 넘어가요">▶</button>
      <span class="pg-ly">${_PG_LAYERS.map(L=>`<button class="pg-ly-b${LY[L.k]?' on':''}" title="${escAttr(L.lbl)} 칩 보이기/숨기기" onclick="pgLayerToggle('${L.k}','${classId}')">${L.ico} ${L.lbl}</button>`).join('')}</span>
      ${(LY.hw||LY.c5)&&clsStus.length>1?`<select class="filter-sel" style="font-size:12px;padding:3px 6px" title="숙제를 볼 학생" onchange="pgHwStuPick(this.value,'${classId}')">${clsStus.map(s=>`<option value="${s.id}"${hwStu&&s.id===hwStu.id?' selected':''}>${escAttr(s.name)} 숙제</option>`).join('')}</select>`:''}
      <button class="btn bo bxxs" title="만료된 핀·중복 핀·지난 제외일을 한 번에 정리합니다 (수업 기록은 건드리지 않아요)" onclick="pgTidyProgress('${classId}')">🧹 진도 정돈</button>
      ${hasAnchor?`<button class="btn bo bxxs" title="드래그로 옮긴 예정을 원래 순서로 되돌립니다" onclick="pgClearAnchors('${classId}')">예정 초기화</button>`:''}
      <span style="flex:1"></span>
      <details class="pg-lgw"><summary title="교재 범례 보기">${luIcon('palette',15)||''} 범례</summary><div class="pg-lgw-b">${legend}</div></details>
    </div>
    <div class="pg-cal-grid">${_PG_DOW.map(d=>`<div class="pg-cal-dow">${d}</div>`).join('')}${cells.join('')}</div>
    <div class="pp-key">
      <span class="pp-key-i"><i class="pp-sw rec"></i>기록</span>
      <span class="pp-key-i"><i class="pp-sw gho"></i>예정</span>
      <span class="pp-key-i"><i class="pp-sw om"></i>옆 달</span>
      ${LY.hw?`<span class="pp-key-i"><i class="pp-sw" style="background:#2F7D63"></i>반복 숙제</span>`:''}
      ${LY.c5?`<span class="pp-key-i"><i class="pp-sw" style="background:${_PG_C5_COLOR}"></i>클래스5·리딩앤</span>`:''}
      <span class="pp-key-sp"></span>
      <span class="pp-key-d">끌어서 이동 · ✕로 빼기 · 우클릭 메뉴</span>
    </div>
    ${_ppHelp('진도 캘린더 사용법',[
      ['🖐','칩 드래그','진도를 다른 날로 이동'],
      ['✕','칩 오른쪽 ✕','예정은 이 날에서 빼기 / 기록은 이 진도만 지우기'],
      ['🖱','칩 우클릭','기록 확정 · 📌 고정 · 빼기 · 예정 편집 메뉴'],
      ['⚡','예정 칩 더블클릭','그 날 수업으로 기록 확정'],
      ['◀▶','드래그 중 올려두기','달을 넘겨 다른 달로도 이동'],
      ['👆','칩 한 번 탭 → 날짜 탭','달을 넘겨도 유지되는 이동'],
      ['🗓','빈 수업일 클릭','수업 기록 · 예정 편집 · 수업 안 함'],
      ['🏖','빈 칸 드래그','기간 휴강·방학 한 번에'],
      ['📕','숙제 칩 클릭 / ✕','완료 토글 / 그 날 숙제 빼기'],
      ['🎚','위쪽 레이어 버튼','진도·숙제·클래스5를 켜고 끄기 (기기에 기억됨)'],
    ])}
  </div>`;
}
function pgDragStart(ev,classId,tbId,unit,s){
  _pgDrag={classId,tbId,unit,s:s||''};
  try{ev.dataTransfer.setData('text/plain',unit);ev.dataTransfer.effectAllowed='move';}catch(e){}
}
function pgCellOver(ev,date){
  if(!_pgDrag)return;
  ev.preventDefault(); // 미래=예정 이동, 오늘·과거=그날 수업으로 기록 — 모두 허용
}
function pgCellDrop(ev,classId,date){
  if(!_pgDrag)return;
  ev.preventDefault();ev.stopPropagation();
  const d=_pgDrag;_pgDrag=null;
  _pgPlaceChip(classId,d,date);
}
// 예정 칩을 날짜에 놓았을 때: 미래=예정 이동(앵커), 오늘·지난 날짜=그날 실제 한 수업으로 기록 확정
function _pgPlaceChip(classId,d,date){
  if(date<=ppToday()){
    if(String(d.tbId).startsWith('sing:'))pgSingConfirm(classId,date);
    else if(String(d.tbId).startsWith('ort:'))pgConfirmOrtBook(classId,String(d.tbId).slice(4),d.unit,date);
    else pgConfirmGhost(classId,d.tbId,d.unit,date,d.s||'');
    return;
  }
  pgSetAnchor(classId,d.tbId,d.unit,date);
}
// 싱글 클릭(이동 선택)은 살짝 지연 — 더블클릭(기록 확정)과 충돌하지 않게
let _pgTapTimer=null;
function pgChipTapDelayed(el,classId,tbId,unit,s){
  clearTimeout(_pgTapTimer);
  _pgTapTimer=setTimeout(()=>pgChipTap(el,classId,tbId,unit,s),260);
}
function pgGhostDbl(ev,classId,tbId,unit,date,subj){
  ev.stopPropagation();
  clearTimeout(_pgTapTimer);
  pgMoveCancel();
  pgConfirmGhost(classId,tbId,unit,date,subj);
}
// 예정 칩 → 실제 수업 기록으로 확정 (전원 정상 출석, 세부는 나중에 '수정'으로)
// 앞 단원이 아직 기록 안 된 채 뒷 단원을 확정하면 그 앞 단원들도 함께 기록 —
// (Unit 2만 기록하면 Unit 1이 예정에서 조용히 사라지던 문제 방지. 안 한 단원은 기록 후 수정에서 빼면 됨)
function pgConfirmGhost(classId,tbId,unit,date,subj){
  const todayStr=ppToday();
  if(date>todayStr){toast('아직 안 한 수업이에요 — 수업한 날에 확정해 주세요');return;}
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===tbId);if(!tb)return;
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length){toast('클래스에 학생이 없어요');return;}
  const keys=tbUnitKeys(tb);
  const ti=keys.findIndex(k=>_pgUMatch(_pgNorm(k),_pgNorm(unit)));
  let fromIdx=ti;
  const rec=_pgLastRec(classId,tb);
  if(rec)fromIdx=rec.idx+1;
  else{
    const mat=Object.values(c.commonMaterials||{}).find(m=>m&&(m.bookId?m.bookId===tb.id:m.book===tb.title));
    const si=(mat&&mat.unit)?_pgUnitIdx(tb,mat.unit):-1;
    fromIdx=si>=0?si:ti;
  }
  const units=(ti>=0&&fromIdx>=0&&ti>fromIdx)?[...keys.slice(fromIdx,ti),unit]:[unit];
  const gapNote=units.length>1?`\n(아직 기록 안 된 앞 단원 ${units.length-1}개 포함 — 안 했다면 기록 후 '수정'에서 빼주세요)`:'';
  askConfirm('진도 확정',`${tb.title} — ${units.join(', ')}${gapNote}\n학생 ${stus.length}명 전원 '정상 출석'으로 기록할까요?\n(출석·코멘트·과제는 기록 후 '수정'에서 채울 수 있어요)`,'기록','bt',async()=>{
    showLoading(true);
    try{
      for(const s of stus){
        const existing=(_cache.lessons||[]).find(l=>l.classId===classId&&l.date===date&&l.sid===s.id);
        let mats=existing?existing.materials:null;
        units.forEach(u=>{mats=_pgMergeMat(mats,subj,tb,u);});
        const les=existing
          ?{...existing,materials:mats}
          :{id:uid(),sid:s.id,date,grade:s.grade||'',att:'normal',materials:mats,cmt:'',polishedCmt:'',classId};
        await supaUpsert('lessons',les.id,les,s.id);
        if(existing){const i=_cache.lessons.findIndex(l=>l.id===les.id);if(i>=0)_cache.lessons[i]=les;}
        else _cache.lessons.unshift(les);
        for(const u of units)addUnitWordsToVocab(s.id,{[subj||'x']:{book:tb.title,unit:u,bookId:tb.id}},date).catch(()=>{});
      }
      renderLes();renderDash();renderClassTab();renderClsLessons(classId);
      toast(`${units.join(', ')} 기록 완료 (${stus.length}명) — 단어도 학생 단어장에 반영돼요`);
    }catch(e){
      console.error('pgConfirmGhost:',e);toast('기록 중 오류가 발생했습니다');
    }finally{showLoading(false);}
  });
}
// Sing Together(펜슬 다운) 예정 칩 더블클릭 → 전원 수업 기록으로 확정
function pgSingDbl(ev,classId,date){
  ev.stopPropagation();
  clearTimeout(_pgTapTimer);
  pgMoveCancel();
  pgSingConfirm(classId,date);
}
// 씽 기록 확정 본체 — 더블클릭·오늘/지난 날짜로 칩을 옮겼을 때 공유
function pgSingConfirm(classId,date){
  const todayStr=ppToday();
  if(date>todayStr){toast('아직 안 한 수업이에요 — 수업한 날에 확정해 주세요');return;}
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length){toast('클래스에 학생이 없어요');return;}
  askConfirm('Pencil Down 기록',`✏️🎵 Sing Together\n학생 ${stus.length}명 전원 '정상 출석'으로 기록할까요?`,'기록','bt',async()=>{
    showLoading(true);
    try{
      for(const s of stus){
        const existing=(_cache.lessons||[]).find(l=>l.classId===classId&&l.date===date&&l.sid===s.id);
        const mats={...(existing?existing.materials:{})};
        const hasPd=Object.keys(mats).some(k=>{const bk=k.replace(/_\d+$/,'');return bk==='pencil_down'||bk==='sing_together';});
        if(hasPd)continue;
        mats.pencil_down={book:'Sing Together',unit:''};
        const les=existing?{...existing,materials:mats}
          :{id:uid(),sid:s.id,date,grade:s.grade||'',att:'normal',materials:mats,cmt:'',polishedCmt:'',classId};
        await supaUpsert('lessons',les.id,les,s.id);
        if(existing){const i=_cache.lessons.findIndex(l=>l.id===les.id);if(i>=0)_cache.lessons[i]=les;}
        else _cache.lessons.unshift(les);
      }
      renderLes();renderDash();renderClassTab();renderClsLessons(classId);
      toast(`Sing Together 기록 완료 (${stus.length}명)`);
    }catch(e){
      console.error('pgSingDbl:',e);toast('기록 중 오류가 발생했습니다');
    }finally{showLoading(false);}
  });
}
// 원서 예정 칩 더블클릭 → 그 학생의 읽음 기록으로 확정
function pgOrtDbl(ev,classId,sid,title,date){
  ev.stopPropagation();
  clearTimeout(_pgTapTimer);
  pgMoveCancel();
  pgConfirmOrtBook(classId,sid,title,date);
}
// 원서 확정 — AR 자동 채움 + 읽는 중/완독 선택 대화상자 (제목만 넣던 불편 개선)
let _pgOrtDraft=null;
function pgOrtModalClose(){document.getElementById('pg-ort-modal')?.remove();document.getElementById('pg-ort-overlay')?.remove();}
function pgOrtSetDone(done){
  const dv=document.getElementById('pg-ort-donev');if(dv)dv.value=done?'1':'0';
  const r=document.getElementById('pg-ort-reading'),d=document.getElementById('pg-ort-done');
  if(r)r.className='btn '+(done?'bo':'bt')+' bsm';
  if(d)d.className='btn '+(done?'bt':'bo')+' bsm';
}
// 기록된 원서 칩 클릭 → 그 학생을 찾아 편집 대화상자로 (여럿이면 전체 수업 편집)
function pgOrtRecEdit(classId,title,date){
  const sids=[...new Set((_cache.lessons||[]).filter(l=>l.classId===classId&&l.date===date&&!l._deleted).filter(l=>Object.entries(l.materials||{}).some(([k,v])=>k.replace(/_\d+$/,'')==='_book'&&v&&_pgNorm(v.book)===_pgNorm(title))).map(l=>l.sid))];
  if(sids.length===1)pgConfirmOrtBook(classId,sids[0],title,date);
  else openClassLessonEdit(classId,date); // 학생 여럿이 같은 책 → 상세 편집으로
}
function pgConfirmOrtBook(classId,sid,title,date){
  const todayStr=ppToday();
  if(date>todayStr){toast('아직 안 한 수업이에요 — 수업한 날에 확정해 주세요');return;}
  const s=DB.stus().find(x=>x.id===sid);if(!s)return;
  const lb=[...DB.libs()].find(b=>_pgNorm(b.title)===_pgNorm(title));
  const ar=(lb&&(lb.arLevel||lb.ar))||'';
  const series=(lb&&lb.series)||'';
  // 이 수업에 이미 같은 책이 있으면 그 진행 상태를 기본값으로
  const existing=(_cache.lessons||[]).find(l=>l.classId===classId&&l.date===date&&l.sid===sid);
  let curProg='';
  if(existing)for(const[k,v]of Object.entries(existing.materials||{})){
    if(k.replace(/_\d+$/,'')==='_book'&&v&&_pgNorm(v.book)===_pgNorm(title)){curProg=v.unit||'';break;}
  }
  const doneDefault=(curProg||'').trim()==='완독';
  _pgOrtDraft={classId,sid,title,date,series};
  pgOrtModalClose();
  const overlay=document.createElement('div');
  overlay.id='pg-ort-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:1999';
  overlay.onclick=pgOrtModalClose;
  const el=document.createElement('div');
  el.id='pg-ort-modal';
  el.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border-radius:var(--rs);box-shadow:0 8px 32px rgba(0,0,0,.18);z-index:2000;padding:20px;min-width:280px;max-width:380px;width:90vw';
  el.innerHTML=`<div style="font-size:15px;font-weight:700;margin-bottom:4px">📗 원서 읽음 기록</div>
    <div style="font-size:15px;color:var(--navy);font-weight:700;font-family:var(--fd)">${escAttr(title)}</div>
    <div style="font-size:12px;color:var(--slate);margin-bottom:14px">${escAttr(s.name)}${series?' · '+escAttr(series):''} · ${date}</div>
    <div class="f" style="margin-bottom:12px"><label style="font-size:13px;font-weight:700;color:var(--slate)">AR 지수 ${ar?'':'<span style="font-weight:400">(자동값 없음 — 직접 입력)</span>'}</label>
      <input type="text" id="pg-ort-ar" value="${escAttr(ar)}" placeholder="예: 2.5" style="width:100%;box-sizing:border-box;margin-top:4px"></div>
    <div class="f" style="margin-bottom:2px"><label style="font-size:13px;font-weight:700;color:var(--slate)">진행 상태</label>
      <div style="display:flex;gap:8px;margin-top:4px">
        <button type="button" id="pg-ort-reading" class="btn ${doneDefault?'bo':'bt'} bsm" style="flex:1;border-radius:10px;padding:9px 0" onclick="pgOrtSetDone(false)">${luIcon('book',15)||''} 읽는 중</button>
        <button type="button" id="pg-ort-done" class="btn ${doneDefault?'bt':'bo'} bsm" style="flex:1;border-radius:10px;padding:9px 0" onclick="pgOrtSetDone(true)">✅ 완독</button>
      </div></div>
    <input type="hidden" id="pg-ort-donev" value="${doneDefault?'1':'0'}">
    <div style="display:flex;gap:6px;margin-top:16px;justify-content:flex-end">
      <button class="btn bo bsm" onclick="pgOrtModalClose()">취소</button>
      <button class="btn bt bsm" style="padding:6px 16px" onclick="pgOrtRecord()">기록</button>
    </div>`;
  document.body.appendChild(overlay);document.body.appendChild(el);
}
async function pgOrtRecord(){
  const dr=_pgOrtDraft;if(!dr)return;
  const ar=(document.getElementById('pg-ort-ar')?.value||'').trim();
  const done=document.getElementById('pg-ort-donev')?.value==='1';
  const prog=done?'완독':'';
  const {classId,sid,title,date,series}=dr;
  pgOrtModalClose();
  const s=DB.stus().find(x=>x.id===sid);if(!s)return;
  showLoading(true);
  try{
    const existing=(_cache.lessons||[]).find(l=>l.classId===classId&&l.date===date&&l.sid===sid);
    const mats=_pgMergeBook(existing?existing.materials:null,title,ar,prog);
    const les=existing?{...existing,materials:mats}
      :{id:uid(),sid,date,grade:s.grade||'',att:'normal',materials:mats,cmt:'',polishedCmt:'',classId};
    await supaUpsert('lessons',les.id,les,sid);
    if(existing){const i=_cache.lessons.findIndex(l=>l.id===les.id);if(i>=0)_cache.lessons[i]=les;}
    else _cache.lessons.unshift(les);
    // 원서 읽기 기록(readings) 생성·갱신 — AR·진행 상태 반영, 중복 정리
    const dups=(_cache.readings||[]).filter(r=>!r._deleted&&r.sid===sid&&r.date===date&&_pgNorm(r.title)===_pgNorm(title));
    const rd0=dups[0]||null;
    const rd={id:rd0?rd0.id:uid(),sid,date,title,
      series:series||rd0?.series||dups.find(r=>r.series)?.series||'',
      arLevel:ar||rd0?.arLevel||dups.find(r=>r.arLevel)?.arLevel||'',
      genre:rd0?.genre||'',progress:prog,classId};
    await supaUpsert('readings',rd.id,rd,sid);
    if(rd0){const i=_cache.readings.findIndex(r=>r.id===rd0.id);if(i>=0)_cache.readings[i]=rd;}
    else{_cache.readings=_cache.readings||[];_cache.readings.unshift(rd);}
    for(const extra of dups.slice(1)){ // 중복 읽기 기록 휴지통 처리
      await supaTrash('readings',_cache.readings,extra.id).catch(()=>{});
      _cache.readings=(_cache.readings||[]).filter(r=>r.id!==extra.id);
    }
    if(prog==='완독')await syncCompletedReadingToTextbooks(sid,title,date).catch(()=>{});
    renderLes();renderRd();renderDash();renderClassTab();renderClsLessons(classId);
    toast(`${s.name} · ${title}${prog==='완독'?' 완독':' 읽는 중'} 기록 완료`);
  }catch(e){
    console.error('pgOrtRecord:',e);toast('기록 중 오류가 발생했습니다');
  }finally{showLoading(false);}
}
// 기존 기록에 원서 병합 — 같은 책이 있으면 AR·진행 상태만 갱신, 없으면 새로 추가
function _pgMergeBook(mats,title,ar,prog){
  const r={...(mats||{})};
  for(const[k,v]of Object.entries(r)){
    if(k.replace(/_\d+$/,'')==='_book'&&v&&_pgNorm(v.book)===_pgNorm(title)){
      r[k]={...v,book:v.book,unit:prog||'',...(ar?{ar}:{})};
      return r;
    }
  }
  let key='_book',i=1;
  while(r[key]){i++;key='_book_'+i;}
  r[key]={book:title,unit:prog||'',...(ar?{ar}:{})};
  return r;
}
// 기존 기록에 교재·단원 병합 — 같은 교재 항목이 있으면 단원만 합침
function _pgMergeMat(mats,subj,tb,unit){
  const r={...(mats||{})};
  for(const[k,v]of Object.entries(r)){
    if(v&&v.book&&(v.bookId?v.bookId===tb.id:v.book===tb.title)){
      const us=(v.unit||'').split(',').map(x=>x.trim()).filter(Boolean);
      if(!us.includes(unit))us.push(unit);
      r[k]={...v,unit:us.join(', '),bookId:v.bookId||tb.id};
      return r;
    }
  }
  const base=subj||'reading';
  let key=base,n=1;
  while(r[key]){n++;key=`${base}_${n}`;}
  r[key]={book:tb.title,unit,bookId:tb.id};
  return r;
}
function pgChipTap(el,classId,tbId,unit,s){
  if(_pgMoveSel&&_pgMoveSel.tbId===tbId&&_pgMoveSel.unit===unit){pgMoveCancel();return;}
  pgMoveCancel();
  _pgMoveSel={classId,tbId,unit,s:s||''};
  el.classList.add('sel');
  el.closest('.pg-cal-card')?.classList.add('pg-moving');
  toast('옮길 날짜를 눌러주세요 — 오늘·지난 날짜면 그날 수업으로 기록돼요 (다시 누르면 취소)');
}
function pgMoveCancel(){
  _pgMoveSel=null;
  document.querySelectorAll('.pg-chip.sel').forEach(x=>x.classList.remove('sel'));
  document.querySelectorAll('.pg-cal-card.pg-moving').forEach(x=>x.classList.remove('pg-moving'));
}
// ── 드래그로 기간 휴강·방학 선택 ──
let _pgRangeSel=null;        // 드래그 중 {classId,start,cur,moved}
let _pgRangeStart=null;      // 클릭-클릭 모드(모바일) {classId,date}
let _pgRangeClickGuard=false;// 드래그 직후 따라오는 click 무시
function pgRangeDown(ev,classId,ds){
  if(ev.button!==0)return;
  if(ev.target.closest('.pg-chip'))return; // 칩 드래그(진도 이동)와 충돌 방지
  _pgRangeSel={classId,start:ds,cur:ds,moved:false};
  document.addEventListener('mouseup',_pgRangeUp,{once:true});
  ev.preventDefault(); // 드래그 중 텍스트 선택 방지
}
function pgRangeOver(ds){
  if(!_pgRangeSel||ds===_pgRangeSel.cur)return;
  _pgRangeSel.cur=ds;_pgRangeSel.moved=true;
  const [a,b]=[_pgRangeSel.start,_pgRangeSel.cur].sort();
  document.querySelectorAll('.pg-cell[data-ds]').forEach(c=>c.classList.toggle('rangesel',c.dataset.ds>=a&&c.dataset.ds<=b));
}
function _pgRangeUp(){
  const r=_pgRangeSel;_pgRangeSel=null;
  document.querySelectorAll('.pg-cell.rangesel').forEach(c=>c.classList.remove('rangesel'));
  if(!r||!r.moved||r.start===r.cur)return; // 제자리 → 일반 클릭이 처리
  _pgRangeClickGuard=true;setTimeout(()=>{_pgRangeClickGuard=false;},300);
  const [a,b]=[r.start,r.cur].sort();
  pgRangeConfirm(r.classId,a,b);
}
// 기간 내 휴강 대상 수업일 (이미 휴강·수업 기록이 있는 날 제외)
function _pgRangeClassDays(c,a,b){
  const skip=new Set(c.skipDates||[]);
  const out=[];
  const d=new Date(a+'T12:00:00'),end=new Date(b+'T12:00:00');
  let g=0;
  while(d<=end&&g++<370){
    const ds=_pgYmd(d),dow=_PG_DOW[d.getDay()];
    if((c.days||[]).includes(dow)&&!skip.has(ds)&&!(_cache.lessons||[]).some(l=>l.classId===c.id&&l.date===ds))out.push(ds);
    d.setDate(d.getDate()+1);
  }
  return out;
}
function pgRangeConfirm(classId,a,b){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const targets=_pgRangeClassDays(c,a,b);
  if(!targets.length){toast('선택 기간에 휴강으로 표시할 수업일이 없어요');return;}
  skipNoticeClose();
  const overlay=document.createElement('div');
  overlay.id='skip-notice-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:1999';
  overlay.onclick=skipNoticeClose;
  const el=document.createElement('div');
  el.id='skip-notice-modal';
  el.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border-radius:var(--rs);box-shadow:0 8px 32px rgba(0,0,0,.18);z-index:2000;padding:20px;min-width:280px;max-width:400px;width:90vw';
  el.innerHTML=`<div style="font-size:15px;font-weight:700;margin-bottom:8px">🏖 기간 휴강·방학 표시</div>
    <div style="font-size:14px;color:var(--navy);line-height:1.8"><b>${skipDateLbl(a)} ~ ${skipDateLbl(b)}</b> · 수업일 <b>${targets.length}일</b><br><span style="font-size:13px;color:var(--slate)">이 날들은 수업 안 함으로 표시되고 이후 진도가 그만큼 밀려요.</span></div>
    <div style="display:flex;gap:6px;margin-top:12px;justify-content:flex-end">
      <button class="btn bo bsm" onclick="skipNoticeClose()">취소</button>
      <button class="btn bt bsm" onclick="skipNoticeClose();pgRangeApply('${classId}','${a}','${b}')">🏖 휴강·방학 표시</button>
    </div>`;
  document.body.appendChild(overlay);document.body.appendChild(el);
}
async function pgRangeApply(classId,a,b){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const targets=_pgRangeClassDays(c,a,b);if(!targets.length)return;
  const set=new Set(c.skipDates||[]);targets.forEach(ds=>set.add(ds));
  c.skipDates=[...set].sort();
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgRangeApply:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
  renderClsLessons(classId);
  toast(`수업일 ${targets.length}일 휴강·방학 표시 — 진도를 그만큼 미뤘어요`);
  if(b>=ppToday())openSkipNotice(classId,[a,b]); // 안내 보내기 연결
}
function pgCellClick(ev,classId,date){
  if(_pgRangeClickGuard)return; // 드래그 선택 직후 따라오는 클릭 무시
  if(_pgRangeStart){ // 기간 선택 모드(모바일): 두 번째 클릭 = 끝 날짜
    const s=_pgRangeStart;_pgRangeStart=null;
    if(s.classId===classId){const [a,b]=[s.date,date].sort();pgRangeConfirm(classId,a,b);return;}
  }
  if(_pgMoveSel){const s=_pgMoveSel;pgMoveCancel();_pgPlaceChip(classId,s,date);return;}
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const has=(_cache.lessons||[]).some(l=>l.classId===classId&&l.date===date);
  if(has){openClassLessonEdit(classId,date);return;}
  const dow=_PG_DOW[new Date(date+'T12:00:00').getDay()];
  const isExtra=(c.extraDates||[]).includes(date);
  const isClassDay=(c.days||[]).includes(dow)||isExtra;
  const isSkip=(c.skipDates||[]).includes(date);
  const future=date>ppToday();
  // 이미 휴강 표시된 날 → 되돌리기만
  if(isSkip){pgCellMenu(ev,classId,date,[{ico:'↩️',label:'수업일로 되돌리기',run:()=>pgToggleSkip(classId,date)}]);return;}
  // 수업일이 아니면: 예정 편집·보강 기록 + '추가 수업일 지정' (특강 매일 수업 등)
  if(!isClassDay){
    pgCellMenu(ev,classId,date,[
      future?{ico:'🗓',label:'예정 편집 (교재·유닛 조정)',run:()=>openPgPlan(classId,date)}:{ico:'📝',label:'보강 수업 기록',run:()=>openClassLesson(classId,date)},
      {ico:'➕',label:'추가 수업일로 지정',sub:'요일 외 수업 (특강·보강) — 진도가 이 날에도 나가요',run:()=>pgToggleExtra(classId,date)},
    ]);
    return;
  }
  // 빈 수업일 → 선택 메뉴
  const opts=[];
  if(future){opts.push({ico:'🗓',label:'예정 편집 (교재·유닛 조정)',run:()=>openPgPlan(classId,date)});}
  else{opts.push({ico:'📝',label:'수업 기록',run:()=>openClassLesson(classId,date)});}
  opts.push({ico:'🚫',label:future?'휴강 예정 (수업 안 함)':'수업 안 함 (휴강·결석)',sub:future?'진도 하루씩 밀림 · 안내 보내기로 이어져요':'이후 진도가 하루씩 밀려요',run:()=>pgToggleSkip(classId,date)});
  opts.push({ico:'🏖',label:'기간 휴강·방학 (여기부터)',sub:'끝나는 날짜를 클릭하면 기간이 표시돼요 (드래그로도 가능)',run:()=>{_pgRangeStart={classId,date};toast(`${skipDateLbl(date)}부터 — 마지막 날짜를 클릭하세요`);}});
  if(isExtra)opts.push({ico:'↩️',label:'추가 수업일 해제',run:()=>pgToggleExtra(classId,date)});
  pgCellMenu(ev,classId,date,opts);
}
// 추가 수업일 토글 — c.extraDates (요일 외 특강·보강일: 진도·숙제 마감·수업일 판정에 수업일로 취급)
async function pgToggleExtra(classId,date){
  pgMenuClose();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const set=new Set(c.extraDates||[]);
  const adding=!set.has(date);
  if(adding)set.add(date);else set.delete(date);
  c.extraDates=[...set].sort();
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgToggleExtra:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
  renderClsLessons(classId);
  const md=`${Number(date.slice(5,7))}/${Number(date.slice(8,10))}`;
  toast(adding?`${md} 추가 수업일 지정 — 진도가 이 날에도 나가요`:`${md} 추가 수업일 해제`);
}
// 휴강일 토글 — c.skipDates에 넣거나 뺀다 (교재·원서 진도가 이 날을 건너뜀, 클래스5 과제는 그대로)
async function pgToggleSkip(classId,date){
  pgMenuClose();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const set=new Set(c.skipDates||[]);
  const adding=!set.has(date);
  if(adding)set.add(date);else set.delete(date);
  c.skipDates=[...set].sort();
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgToggleSkip:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
  renderClsLessons(classId);
  const md=`${Number(date.slice(5,7))}/${Number(date.slice(8,10))}`;
  toast(adding?`${md} 수업 안 함 — 이후 진도를 하루씩 미뤘어요`:`${md} 수업일로 되돌렸어요`);
  // 오늘·미래 휴강 등록이면 안내 보내기로 연결 (학생·학부모 앱에는 자동 표시)
  if(adding&&date>=ppToday())openSkipNotice(classId,date);
}
// ── 휴강 안내 보내기 — 공지 배너 등록 + 카톡용 복사 ──
function skipNoticeClose(){document.getElementById('skip-notice-modal')?.remove();document.getElementById('skip-notice-overlay')?.remove();}
function openSkipNotice(classId,date){
  skipNoticeClose();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const range=Array.isArray(date); // [시작,끝] = 기간 휴강·방학
  const lbl=range?`${skipDateLbl(date[0])}~${skipDateLbl(date[1])}`:skipDateLbl(date);
  const def=`${luIcon('megaphone',15)||''} ${c.name?c.name+' ':''}휴강 안내\n${lbl} ${range?'기간은 수업을 쉬어갑니다':'수업은 사정상 쉬어갑니다'}.\n과제는 평소처럼 진행해 주세요 💪`;
  const overlay=document.createElement('div');
  overlay.id='skip-notice-overlay';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:1999';
  overlay.onclick=skipNoticeClose;
  const el=document.createElement('div');
  el.id='skip-notice-modal';
  el.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#fff;border-radius:var(--rs);box-shadow:0 8px 32px rgba(0,0,0,.18);z-index:2000;padding:20px;min-width:280px;max-width:440px;width:90vw';
  el.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
      <span style="font-size:15px;font-weight:700">${luIcon('megaphone',15)||''} 휴강 안내 보내기 — ${lbl}${c.name?' · '+escAttr(c.name):''}</span>
      <button style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--slate)" onclick="skipNoticeClose()">×</button>
    </div>
    <textarea id="skip-notice-text" style="width:100%;box-sizing:border-box;min-height:110px;font-family:var(--fb);font-size:14px;line-height:1.7;padding:10px;border:1px solid var(--border);border-radius:var(--rs);resize:vertical">${def}</textarea>
    <div style="display:flex;gap:6px;margin-top:10px;flex-wrap:wrap">
      <button class="btn bt bsm" onclick="skipNoticeBanner()">${luIcon('megaphone',15)||''} 공지 배너 등록</button>
      <button class="btn bo bsm" onclick="skipNoticeCopy()">${luIcon('clipboard-list',15)||''} 복사 (카톡 붙여넣기)</button>
      <button class="btn bo bsm" style="margin-left:auto" onclick="skipNoticeClose()">닫기</button>
    </div>
    <div style="font-size:12px;color:var(--slate);line-height:1.7;margin-top:8px">공지 배너는 학부모 앱 상단에 떠요. 안 보내도 휴강 예정은 학생·학부모 앱 홈에 자동으로 표시됩니다.</div>`;
  document.body.appendChild(overlay);document.body.appendChild(el);
}
async function skipNoticeBanner(){
  const t=(document.getElementById('skip-notice-text')?.value||'').trim();
  if(!t){toast('안내문을 입력해 주세요');return;}
  await postNoticeText(t.replace(/\n/g,' '));
  skipNoticeClose();
}
async function skipNoticeCopy(){
  const ta=document.getElementById('skip-notice-text');if(!ta)return;
  try{await navigator.clipboard.writeText(ta.value);}
  catch(e){ta.select();document.execCommand('copy');}
  toast('복사 완료 — 카카오톡에 붙여넣어 보내세요');
}
// 캘린더 셀 미니 메뉴 (클릭 위치 근처에 뜨는 작은 선택창)
let _pgMenuEl=null;
function pgMenuClose(){if(_pgMenuEl){_pgMenuEl.remove();_pgMenuEl=null;document.removeEventListener('click',_pgMenuOutside,true);}}
function _pgMenuOutside(e){if(_pgMenuEl&&!_pgMenuEl.contains(e.target))pgMenuClose();}
function pgCellMenu(ev,classId,date,opts){
  pgMenuClose();
  if(ev&&ev.stopPropagation)ev.stopPropagation();
  const m=document.createElement('div');
  m.className='pg-cell-menu';
  const md=`${Number(date.slice(5,7))}/${Number(date.slice(8,10))}`;
  m.innerHTML=`<div class="pg-menu-date">${md}</div>`+opts.map((o,i)=>
    `<button class="pg-menu-item" data-i="${i}"><span>${o.ico}</span><div><div>${o.label}</div>${o.sub?`<div class="pg-menu-sub">${o.sub}</div>`:''}</div></button>`).join('');
  document.body.appendChild(m);
  const r=(ev&&ev.currentTarget&&ev.currentTarget.getBoundingClientRect)?ev.currentTarget.getBoundingClientRect():{left:(ev&&ev.clientX)||100,bottom:(ev&&ev.clientY)||100,right:0};
  const mw=Math.min(230,window.innerWidth-16);
  m.style.width=mw+'px';
  let left=r.left;if(left+mw>window.innerWidth-8)left=window.innerWidth-mw-8;
  m.style.left=Math.max(8,left)+'px';
  const mh=m.offsetHeight;
  let top=r.bottom+4;if(top+mh>window.innerHeight-8)top=Math.max(8,r.top-mh-4);
  m.style.top=top+'px';
  m.querySelectorAll('.pg-menu-item').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const o=opts[+btn.dataset.i];pgMenuClose();if(o)o.run();});
  _pgMenuEl=m;
  setTimeout(()=>document.addEventListener('click',_pgMenuOutside,true),0);
}
// ── 미래 날짜 예정 편집: 완료 기록 없이 계획(공통 교재 + 앵커)으로 저장 ──
let _pgPlanCtx=null; // {classId,date}
function openPgPlan(classId,date){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  _pgPlanCtx={classId,date};
  document.getElementById('pg-plan-title').textContent=`${Number(date.slice(5,7))}/${Number(date.slice(8,10))} 수업 예정`;
  // 이 날 예정 — 캘린더와 같은 계산(_pgComposePlan) 공유: 싱투게더·밀림까지 동일하게 반영
  const plan=_pgComposePlan(classId,c,date);
  const books=plan.books;
  const rows=[];
  if(plan.singDates.has(date)){ // 씽도 드래그로 옮길 수 있음 — 여기선 📌 고정/해제(자동 배치 복귀)만
    const sTb=(plan.singBy||{})[date]||'';
    const sPin=sTb&&_pgAncPins((c.progressAnchors||{})['sing:'+sTb]).some(pn=>pn.date===date);
    rows.push(`<div style="display:flex;align-items:center;gap:6px;padding:3px 0">
      <span style="font-size:13px;color:var(--navy);flex:1;min-width:0">✏️🎵 Sing Together (Pencil Down)</span>
      ${sTb?`<button class="btn ${sPin?'bt':'bo'} bsm" style="flex:none;padding:3px 7px;font-size:11.5px" title="${sPin?'옮긴 날짜 해제 — 원래 자동 배치로 돌아가요':'이 날에 고정 — 진도가 밀려도 안 움직여요'}" onclick="pgSingPinToggle('${sTb}')">📌${sPin?' 해제':''}</button>`:''}
    </div>`);
  }
  (plan.ortGhostBy[date]||[]).forEach(g=>rows.push(`<div style="font-size:13px;color:var(--navy);padding:2px 0">• 📗 ${plan.clsStus.length>1?escAttr(g.name)+' · ':''}${escAttr(g.title)} <span style="font-size:12px;color:var(--slate)">(캘린더에서 드래그로 이동)</span></div>`));
  // 교재 예정: 유닛 select로 그 자리 유닛 교체 + 📌 고정/해제 (즉시 저장)
  (plan.ghostBy[date]||[]).forEach(g=>{
    const cat=g.s.replace(/_\d+$/,'');
    const pill=SLBL[cat]?`<span class="spill ${SCLS[cat]}" style="font-size:12px;flex:none">${SLBL[cat]}</span>`:'';
    const b=books.find(x=>x.tb.id===g.tbId);
    let remU=[];
    if(b){
      const keys=tbUnitKeys(b.tb);
      const rec=_pgLastRec(classId,b.tb);
      const start=rec?rec.idx+1:(()=>{const si=_pgUnitIdx(b.tb,b.mat?.unit);return si>=0?si:0;})();
      remU=keys.slice(start);
      const dset=_pgDictSet(c,b.tb.id); // 딕테이션 분리 유닛은 목록에도 두 항목
      if(dset.size){
        if(rec&&dset.has(_pgNorm(keys[rec.idx]))&&!_pgDictDone(classId,b.tb,keys[rec.idx]))remU=[_pgDictLbl(keys[rec.idx]),...remU];
        remU=remU.flatMap(k=>dset.has(_pgNorm(k))?[k,_pgDictLbl(k)]:[k]);
      }
    }
    if(!b||!remU.includes(g.unit)){ // 목차에 없는 유닛 표기 등 — 여기선 조정 대상 아님 (어휘도 2026-08-09부터 유닛별 칩 = 편집형)
      rows.push(`<div style="display:flex;align-items:center;gap:6px;padding:2px 0;min-width:0">
        <span style="font-size:13px;color:var(--navy);flex:1;min-width:0">${pill} ${escAttr(g.title)} — ${escAttr(g.unit)}${cat==='vocab'?' <span style="font-size:12px;color:var(--slate)">(숙제 흐름 자동)</span>':''}</span>
        <button class="btn bd bsm" style="flex:none;padding:3px 7px;font-size:11.5px" title="이 날은 이 교재를 빼요 — 다음 수업일로 밀려요 (다시 넣으려면 같은 버튼)" onclick="pgSlotSkipToggle('${g.tbId}')">✕</button>
      </div>`);
      return;
    }
    const pinned=_pgAncPins((c.progressAnchors||{})[g.tbId]).some(pn=>pn.date===date&&_pgNorm(pn.unit)===_pgNorm(g.unit));
    const titles=b.tb.unitTitles||{};
    const baseU=_pgIsDict(g.unit)?g.unit.slice(0,-_PG_DICT_SFX.length):g.unit; // 딕테이션 칩도 본책 기준으로 토글
    const splitOn=_pgDictSet(c,g.tbId).has(_pgNorm(baseU));
    rows.push(`<div style="display:flex;align-items:center;gap:6px;padding:3px 0;min-width:0">${pill}
      <span style="font-size:12.5px;color:var(--navy);flex:none;max-width:104px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${escAttr(b.tb.title)}">${escAttr(b.tb.title)}</span>
      <select style="flex:1;min-width:0;font-size:12.5px;padding:4px 6px" onchange="pgPlanUnitSwap('${g.tbId}','${escJsA(g.unit)}',this.value)">${remU.map(k=>`<option value="${escAttr(k)}"${k===g.unit?' selected':''}>${k}${titles[k]?' — '+titles[k]:''}</option>`).join('')}</select>
      ${cat==='listening'?`<button class="btn ${splitOn?'bt':'bo'} bsm" style="flex:none;padding:3px 6px;font-size:11.5px" title="${splitOn?'다시 합치기 — 본책과 딕테이션을 하루에 함께':'딕테이션 분리 — 본책 날과 딕테이션 날을 따로'}" onclick="pgDictToggle('${g.tbId}','${escJsA(baseU)}')">✂️${splitOn?'↩':''}</button>`:''}
      <button class="btn ${pinned?'bt':'bo'} bsm" style="flex:none;padding:3px 7px;font-size:11.5px" title="${pinned?'고정 해제 — 원래 순서 자리로 돌아가요':'이 날에 고정 — 다른 유닛을 옮겨도 안 움직여요'}" onclick="pgPlanPinToggle('${g.tbId}','${escJsA(g.unit)}')">${luIcon('pin',15)||''}${pinned?' 해제':''}</button>
      <button class="btn bd bsm" style="flex:none;padding:3px 7px;font-size:11.5px" title="이 날은 이 교재를 빼요 — 진도는 다음 수업일로 밀려요 (다시 넣으려면 같은 버튼)" onclick="pgSlotSkipToggle('${g.tbId}')">✕</button>
    </div>`);
  });
  document.getElementById('pg-plan-cur').innerHTML=rows.length
    ?`<div style="font-size:12.5px;font-weight:700;color:var(--slate);margin-bottom:5px">이 날 예정</div>`+rows.join('')
      +`<div style="font-size:11.5px;color:var(--slate);margin-top:4px">유닛을 바꾸면 그 유닛이 이 날로 오고, 원래 유닛은 빈 수업일에 순서대로 다시 배치돼요.</div>`
    :`<div style="font-size:13px;color:var(--slate)">이 날 예정된 교재가 아직 없어요</div>`;
  // 교재 select: 클래스 공통 교재 먼저, 그 외 교재 DB 전체 (단원 있는 교재만)
  const inCls=new Set(books.map(b=>b.tb.id));
  const all=tbSortByUsage((_cache.globalTextbooks||[]).filter(b=>tbUnitKeys(b).length));
  const opt=b=>`<option value="${escAttr(b.id)}">${b.title}${b.level?' ('+b.level+')':''}</option>`;
  document.getElementById('pg-plan-book').innerHTML=`<option value="">-- 교재 선택 --</option>`
    +(books.length?`<optgroup label="클래스 공통 교재">${books.map(b=>opt(b.tb)).join('')}</optgroup>`:'')
    +`<optgroup label="전체 교재">${all.filter(b=>!inCls.has(b.id)).map(opt).join('')}</optgroup>`;
  document.getElementById('pg-plan-unit').value='';
  document.getElementById('dl-pg-plan-unit').innerHTML='';
  document.getElementById('pg-plan-unit').placeholder='교재를 먼저 선택하세요';
  openM('m-pg-plan');
}
function pgPlanBookChange(){
  const bkId=document.getElementById('pg-plan-book').value;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===bkId);
  const dl=document.getElementById('dl-pg-plan-unit');
  const inp=document.getElementById('pg-plan-unit');
  if(!tb){dl.innerHTML='';inp.value='';inp.placeholder='교재를 먼저 선택하세요';return;}
  const titles=tb.unitTitles||{};
  dl.innerHTML=tbUnitKeys(tb).map(k=>`<option value="${escAttr(k)}">${k}${titles[k]?' — '+titles[k]:''}</option>`).join('');
  inp.value=_pgPlanCtx?_pgNextUnit(_pgPlanCtx.classId,tb,''):'';
  inp.placeholder='단원 선택 또는 직접 입력';
}
async function pgPlanSave(){
  if(!_pgPlanCtx)return;
  const {classId,date}=_pgPlanCtx;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const bkId=document.getElementById('pg-plan-book').value;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===bkId);
  if(!tb){toast('교재를 선택해 주세요');return;}
  const typed=document.getElementById('pg-plan-unit').value.trim();
  const u=tbUnitKeys(tb).find(k=>_pgUMatch(_pgNorm(k),_pgNorm(typed)));
  if(!u){toast('단원 목록에서 선택해 주세요');return;}
  c.commonMaterials={...(c.commonMaterials||{})};
  const exists=Object.values(c.commonMaterials).some(v=>v&&(v.bookId?v.bookId===tb.id:v.book===tb.title));
  if(!exists){ // 새 교재면 카테고리에 맞는 과목 키로 공통 교재 등록
    const base=Object.keys(_CAT_KO).find(k=>_CAT_KO[k]===tb.category)||'reading';
    let key=base,n=1;
    while(c.commonMaterials[key]){n++;key=`${base}_${n}`;}
    c.commonMaterials[key]={book:tb.title,unit:'',bookId:tb.id};
  }
  if(!_pgLastRec(classId,tb)){ // 기록 없는 교재는 시작 단원 자체를 이 단원으로 (이전 단원 예정이 끼지 않게)
    for(const k in c.commonMaterials){const v=c.commonMaterials[k];if(v&&(v.bookId?v.bookId===tb.id:v.book===tb.title))c.commonMaterials[k]={...v,unit:u};}
  }
  {const prev=_pgAncPins((c.progressAnchors||{})[tb.id]).filter(pn=>pn.date>=ppToday()&&_pgNorm(pn.unit)!==_pgNorm(u));
  c.progressAnchors={...(c.progressAnchors||{}),[tb.id]:{pins:[...prev,{unit:u,date}]}};} // 이 날 이 단원 고정(핀)
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgPlanSave:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  const i=(_cache.globalClasses||[]).findIndex(x=>x.id===classId);if(i>=0)_cache.globalClasses[i]=c;
  closeM('m-pg-plan');
  renderClsLessons(classId);
  toast(`${tb.title} — ${u} · ${Number(date.slice(5,7))}/${Number(date.slice(8,10))}부터 예정으로 잡았어요`);
}
// 예정 편집 모달: 이 날 이 자리의 유닛을 다른 유닛으로 교체 (새 유닛을 이 날에 핀, 원래 유닛 핀은 해제)
async function pgPlanUnitSwap(tbId,oldUnit,newUnit){
  if(!_pgPlanCtx||!newUnit||_pgNorm(oldUnit)===_pgNorm(newUnit))return;
  const {classId,date}=_pgPlanCtx;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const todayStr=ppToday();
  const pins=_pgAncPins((c.progressAnchors||{})[tbId]).filter(pn=>pn.date>=todayStr
    &&!(pn.date===date&&_pgNorm(pn.unit)===_pgNorm(oldUnit))
    &&_pgNorm(pn.unit)!==_pgNorm(newUnit));
  pins.push({unit:newUnit,date});
  c.progressAnchors={...(c.progressAnchors||{}),[tbId]:{pins}};
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgPlanUnitSwap:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  openPgPlan(classId,date);
  toast(`${newUnit} → 이 날로 바꿨어요 — 원래 유닛은 순서대로 다시 배치돼요`);
}
// 예정 편집 모달: 이 날 이 교재 빼기/되돌리기 — 그 날 걸린 핀도 함께 풀어야 다시 안 나옴
// 이 날 이 교재를 예정에서 빼기/되돌리기 — 모달과 칩 ✕가 같은 경로를 쓴다
// on 생략 시 토글. 성공하면 최종 상태(true=빠짐)를 반환, 실패하면 null
async function _pgSlotSkipSet(classId,date,tbId,on){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return null;
  const map={...(c.slotSkip||{})};
  const list=(map[tbId]||[]).slice();
  const i=list.indexOf(date);
  if(on===undefined)on=i<0;
  if(on){if(i<0)list.push(date);}else if(i>=0)list.splice(i,1);
  if(list.length)map[tbId]=list;else delete map[tbId];
  c.slotSkip=map;
  if(on){ // 뺄 때는 이 날짜 핀도 해제 (핀이 남으면 빼도 그대로 배치됨)
    const anc={...(c.progressAnchors||{})};
    const pins=_pgAncPins(anc[tbId]).filter(pn=>pn.date!==date);
    if(pins.length)anc[tbId]={pins};else delete anc[tbId];
    c.progressAnchors=anc;
  }
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('_pgSlotSkipSet:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return null;}
  return on;
}
async function pgSlotSkipToggle(tbId){
  if(!_pgPlanCtx)return;
  const {classId,date}=_pgPlanCtx;
  const on=await _pgSlotSkipSet(classId,date,tbId);
  if(on===null)return;
  renderClsLessons(classId);
  openPgPlan(classId,date);
  toast(on?'이 날은 이 교재를 뺐어요 — 진도는 다음 수업일로':'다시 넣었어요');
}
// ── 칩에서 바로 조작 ──
// 예정 칩의 ✕ — 이 날 이 교재만 빼기 (진도는 사라지지 않고 다음 수업일로 밀림)
async function pgChipSkip(ev,classId,tbId,ds,label){
  if(ev){ev.stopPropagation();ev.preventDefault();}
  pgMenuClose();
  const on=await _pgSlotSkipSet(classId,ds,tbId,true);
  if(on===null)return;
  renderClsLessons(classId);
  toast((label||'이 교재')+' — 이 날에서 뺐어요 (진도는 다음 수업일로)');
}
// 기록 칩의 ✕ — 그 날 수업 기록에서 이 교재 진도만 지우기 (수업 기록 자체는 남김)
async function pgRecMatDel(ev,classId,ds,tbId,book){
  if(ev){ev.stopPropagation();ev.preventDefault();}
  pgMenuClose();
  const rows=(_cache.lessons||[]).filter(l=>l.classId===classId&&l.date===ds&&l.materials
    &&Object.values(l.materials).some(m=>m&&(tbId?(m.bookId===tbId||m.book===book):m.book===book)));
  if(!rows.length){toast('지울 진도를 찾지 못했어요');return;}
  const units=[];
  rows.forEach(l=>Object.values(l.materials).forEach(m=>{
    if(m&&(tbId?(m.bookId===tbId||m.book===book):m.book===book)&&m.unit&&units.indexOf(m.unit)<0)units.push(m.unit);
  }));
  askConfirm('진도 지우기',
    (book||'이 교재')+(units.length?' '+units.join(', '):'')+'\n'+ds+' 수업 기록에서 이 교재 진도만 지울까요?'+'\n'+'\n'
    +'수업 기록 자체와 다른 교재 진도는 그대로 남습니다.'+(rows.length>1?' (학생 '+rows.length+'명 기록)':''),
    '지우기','bd',async()=>{
    for(const l of rows){
      const mats={...l.materials};
      Object.keys(mats).forEach(k=>{
        const m=mats[k];
        if(m&&(tbId?(m.bookId===tbId||m.book===book):m.book===book))delete mats[k];
      });
      l.materials=mats;
      try{await supaUpsert('lessons',l.id,l,l.sid);}
      catch(e){console.error('pgRecMatDel:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
    }
    renderClsLessons(classId);
    toast('진도를 지웠어요 — 다음 수업일 예정에 다시 올라옵니다');
  });
}
// 칩 우클릭(또는 길게 누르기) 메뉴 — 옮기기 외의 조작을 한곳에
function pgChipMenu(ev,kind,classId,ds,tbId,unit,sKey){
  if(ev){ev.preventDefault();ev.stopPropagation();}
  const c=DB.classes().find(x=>x.id===classId);
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===tbId);
  const name=(tb?tb.title:'')||unit||'';
  if(kind==='rec'){
    const book=tb?tb.title:(unit||'');   // 펜슬다운처럼 교재 id가 없는 기록은 제목으로 찾는다
    pgCellMenu(ev,classId,ds,[
      {ico:'✏️',label:'수업 기록 수정',sub:book,run:()=>openClassLessonEdit(classId,ds)},
      {ico:'🗑',label:'이 기록만 지우기',sub:'수업 기록은 남겨요',run:()=>pgRecMatDel(null,classId,ds,tbId,book)},
    ]);
    return;
  }
  const pinned=_pgAncPins((c&&c.progressAnchors||{})[tbId]).some(pn=>pn.date===ds&&_pgNorm(pn.unit)===_pgNorm(unit));
  const items=[
    {ico:'✅',label:'이 날 수업으로 기록',sub:name+(unit?' '+unit:''),run:()=>pgGhostDbl(null,classId,tbId,unit,ds,sKey)},
    pinned
      ?{ico:'📌',label:'고정 해제',sub:'자동 배치로 되돌리기',run:()=>pgChipUnpin(classId,tbId,unit,ds)}
      :{ico:'📌',label:'이 날로 고정',sub:'다른 진도가 밀려도 이 날 유지',run:()=>pgChipPin(classId,tbId,unit,ds)},
    {ico:'🚫',label:'이 날에서 빼기',sub:'진도는 다음 수업일로',run:()=>pgChipSkip(null,classId,tbId,ds,name)},
    {ico:'📝',label:'예정 편집',sub:'이 날 전체 보기',run:()=>openPgPlan(classId,ds)},
  ];
  pgCellMenu(ev,classId,ds,items);
}
async function pgChipPin(classId,tbId,unit,ds){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const anc={...(c.progressAnchors||{})};
  const prev=_pgAncPins(anc[tbId]).filter(pn=>_pgNorm(pn.unit)!==_pgNorm(unit));
  anc[tbId]={pins:[...prev,{unit,date:ds}]};
  c.progressAnchors=anc;
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgChipPin:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  toast(unit+' — 이 날로 고정했어요 📌');
}
async function pgChipUnpin(classId,tbId,unit,ds){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const anc={...(c.progressAnchors||{})};
  const pins=_pgAncPins(anc[tbId]).filter(pn=>!(pn.date===ds&&_pgNorm(pn.unit)===_pgNorm(unit)));
  if(pins.length)anc[tbId]={pins};else delete anc[tbId];
  c.progressAnchors=anc;
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgChipUnpin:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  toast('고정을 풀었어요 — 자동 배치로 돌아갑니다');
}
// 예정 편집 모달: 딕테이션 분리/합치기 — 그 유닛을 '본책 날 + 딕테이션 날' 두 칸으로
async function pgDictToggle(tbId,unit){
  if(!_pgPlanCtx)return;
  const {classId,date}=_pgPlanCtx;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const map={...(c.dictSplit||{})};
  const list=(map[tbId]||[]).slice();
  const i=list.findIndex(u=>_pgNorm(u)===_pgNorm(unit));
  const on=i<0;
  if(on)list.push(unit);else list.splice(i,1);
  if(list.length)map[tbId]=list;else delete map[tbId];
  c.dictSplit=map;
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgDictToggle:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  openPgPlan(classId,date);
  toast(on?`✂️ ${unit} — 본책 날·딕테이션 날로 나눴어요 (뒤 진도는 하루씩 밀려요)`:`${unit} — 다시 하루에 함께 진행해요`);
}
// 예정 편집 모달: 씽 투게더 📌 고정/해제 (해제하면 완주 다음 수업일 자동 배치로 복귀)
async function pgSingPinToggle(tbId){
  if(!_pgPlanCtx)return;
  const {classId,date}=_pgPlanCtx;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const key='sing:'+tbId;
  const was=_pgAncPins((c.progressAnchors||{})[key]).some(pn=>pn.date===date);
  const anc={...(c.progressAnchors||{})};
  if(was)delete anc[key];else anc[key]={pins:[{unit:'Sing Together',date}]};
  c.progressAnchors=anc;
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgSingPinToggle:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  openPgPlan(classId,date);
  toast(was?'씽 투게더 고정을 해제했어요 — 자동 배치로 돌아가요':'✏️🎵 Sing Together — 이 날에 고정했어요');
}
// 예정 편집 모달: 이 날의 유닛 📌 고정/해제 토글
async function pgPlanPinToggle(tbId,unit){
  if(!_pgPlanCtx)return;
  const {classId,date}=_pgPlanCtx;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const todayStr=ppToday();
  const all=_pgAncPins((c.progressAnchors||{})[tbId]).filter(pn=>pn.date>=todayStr);
  const was=all.some(pn=>pn.date===date&&_pgNorm(pn.unit)===_pgNorm(unit));
  const pins=all.filter(pn=>_pgNorm(pn.unit)!==_pgNorm(unit));
  if(!was)pins.push({unit,date});
  c.progressAnchors={...(c.progressAnchors||{}),[tbId]:{pins}};
  try{await supaUpsert('classes',classId,c,null);}
  catch(e){console.error('pgPlanPinToggle:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  renderClsLessons(classId);
  openPgPlan(classId,date);
  toast(was?'고정을 해제했어요 — 원래 순서 자리로 돌아가요':`${unit} — 이 날에 고정했어요`);
}
async function pgSetAnchor(classId,tbId,unit,date){
  const todayStr=ppToday();
  if(date<todayStr){toast('지난 날짜로는 옮길 수 없어요');return;}
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const isOrt=String(tbId).startsWith('ort:');
  const isSpecial=isOrt||String(tbId).startsWith('sing:'); // 원서·씽은 제목에 쉼표가 있어도 한 덩어리
  const parts=isSpecial?[unit]:String(unit).split(',').map(x=>x.trim()).filter(Boolean);
  // 원서 핀은 '여기부터 순서대로' 기준점이라 항상 1개만 유지 (옛 핀이 쌓이면 기준이 흐려짐)
  const prev=isOrt?[]:_pgAncPins((c.progressAnchors||{})[tbId]).filter(pn=>pn.date>=todayStr&&!parts.some(pt=>_pgNorm(pn.unit)===_pgNorm(pt)));
  c.progressAnchors={...(c.progressAnchors||{}),[tbId]:{pins:[...prev,...parts.map(pt=>({unit:pt,date}))]}}; // 합쳐진 칩도 유닛별 핀으로 분해 누적
  await supaUpsert('classes',classId,c,null).catch(e=>{console.error('pgSetAnchor:',e);toast('저장 실패 — 네트워크를 확인해 주세요');});
  renderClsLessons(classId);
  const md=`${Number(date.slice(5,7))}/${Number(date.slice(8,10))}`;
  toast(String(tbId).startsWith('sing:')
    ?`✏️🎵 Sing Together → ${md}로 옮겼어요 (다른 진도는 그대로)`
    :isOrt?`📗 ${unit} → ${md}부터 — 다음 책들도 순서대로 하루 1권씩 뒤따라요`
    :`${unit} → ${md} 고정 — 나머지 유닛은 빈 수업일에 순서대로 배치돼요`);
}
// ── 진도 정돈 ──
// 조정을 반복하면 핀·제외일이 쌓여 예정이 뒤엉킨다. 더 이상 효과가 없는 것만 골라 한 번에 치운다.
// 대상: 지난 날짜 핀 / 이미 진도 나간 단원의 핀 / 목차에 없는 단원의 핀 / 같은 유닛 중복 핀 / 지난 제외일
// 수업 기록·교재 체인·요일 설정은 건드리지 않는다.
function _pgTidyPlan(c){
  const today=ppToday();
  const anc=JSON.parse(JSON.stringify(c.progressAnchors||{}));
  const skip=JSON.parse(JSON.stringify(c.slotSkip||{}));
  const rm=[];
  Object.keys(anc).forEach(key=>{
    const pins=_pgAncPins(anc[key]);
    if(!pins.length){delete anc[key];return;}
    const isSing=key.indexOf('sing:')===0,isOrt=key.indexOf('ort:')===0;
    const tb=(isSing||isOrt)?null:(_cache.globalTextbooks||[]).find(b=>b.id===key);
    const label=tb?tb.title:(isSing?'씽 투게더':isOrt?'원서':key);
    const keys=tb?tbUnitKeys(tb):null;
    const rec=tb?_pgLastRec(c.id,tb):null;
    const lastDate={},keep=[];
    pins.slice().sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))).forEach(pn=>{
      const d=String(pn.date||''),u=String(pn.unit||'');
      if(!d||!u){rm.push(label+': 빈 핀');return;}
      if(d<today){rm.push(label+' '+d+' '+u+' — 지난 날짜');return;}
      if(keys){
        const i=keys.findIndex(k=>_pgDictMatch(_pgNorm(k),_pgNorm(u)));
        if(i<0&&!_pgIsDict(u)){rm.push(label+' '+d+' '+u+' — 목차에 없는 단원');return;}
        if(rec&&i>=0&&i<=rec.idx){rm.push(label+' '+d+' '+u+' — 이미 진도 나감');return;}
        // 딕테이션 핀은 목차에 없으니 진행도 대신 기록 유무로 판정
        if(_pgIsDict(u)&&_pgDictDone(c.id,tb,String(u).replace(_PG_DICT_SFX,'').trim())){
          rm.push(label+' '+d+' '+u+' — 이미 진도 나감');return;
        }
      }
      const nk=_pgNorm(u);
      if(lastDate[nk]!=null){ // 같은 유닛이 여러 날짜에 — 가장 늦은 것만 남긴다
        rm.push(label+' '+lastDate[nk]+' '+u+' — 중복 핀');
        const prev=keep.findIndex(x=>x&&_pgNorm(x.unit)===nk);
        if(prev>=0)keep[prev]=null;
      }
      lastDate[nk]=d;
      keep.push(pn);
    });
    const left=keep.filter(Boolean);
    if(left.length)anc[key]={pins:left};else delete anc[key];
  });
  Object.keys(skip).forEach(k=>{
    const tb=(_cache.globalTextbooks||[]).find(b=>b.id===k);
    const label=tb?tb.title:k;
    const left=(skip[k]||[]).filter(d=>{
      if(String(d)>=today)return true;
      rm.push(label+' '+d+' — 지난 제외일');return false;
    });
    if(left.length)skip[k]=left;else delete skip[k];
  });
  return {anc:anc,skip:skip,rm:rm};
}
function pgTidyProgress(classId){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const t=_pgTidyPlan(c);
  if(!t.rm.length){toast('정리할 게 없어요 — 이미 깔끔합니다');return;}
  const list=t.rm.slice(0,12).map(x=>'· '+x).join('\n')+(t.rm.length>12?'\n'+'… 외 '+(t.rm.length-12)+'건':'');
  askConfirm('진도 정돈','더 이상 효과가 없는 조정 '+t.rm.length+'건을 정리할까요?'+'\n'+'\n'+list+'\n'+'\n'+'수업 기록·교재 순서·요일 설정은 그대로입니다.','정리','bt',async()=>{
    c.progressAnchors=t.anc;c.slotSkip=t.skip;
    try{await supaUpsert('classes',classId,c,null);}
    catch(e){console.error('pgTidyProgress:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
    renderClsLessons(classId);
    toast(t.rm.length+'건 정리했어요 — 예정이 순서대로 다시 깔렸습니다');
  });
}
function pgClearAnchors(classId){
  askConfirm('예정 초기화','드래그로 옮긴 예정 진도를 원래 순서로 되돌릴까요? (수업 기록은 그대로예요)','되돌리기','bt',async()=>{
    const c=DB.classes().find(x=>x.id===classId);if(!c)return;
    c.progressAnchors={};
    await supaUpsert('classes',classId,c,null).catch(()=>{});
    renderClsLessons(classId);toast('예정 진도를 원래대로 되돌렸어요');
  });
}
// 클래스5 일괄 할당 — 시작일부터 책 전체를 매일 한 유닛씩, 반 전체 학생에게 앱 과제로 (멱등: 다시 눌러도 갱신만)
async function pgAssignClass5(classId){
  pgMenuClose();
  const c=DB.classes().find(x=>x.id===classId);
  if(!c||!c.class5||!c.class5.bookId){toast('클래스 수정에서 클래스5 책을 먼저 지정하세요');return;}
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===c.class5.bookId);
  if(!tb){toast('클래스5 교재를 찾을 수 없어요');return;}
  const keys=tbUnitKeys(tb);
  let si=c.class5.startUnit?keys.findIndex(k=>_pgUMatch(_pgNorm(k),_pgNorm(c.class5.startUnit))):0;
  if(si<0)si=0;
  const start=c.class5.startDate||ppToday();
  const schedule=[];const cur=new Date(start+'T12:00:00');
  const wkOnly=!!c.class5.weekdaysOnly; // 평일만 — 주말은 건너뛰고 다음 평일에 이어짐
  for(const u of keys.slice(si)){
    let g=0;
    while(wkOnly&&(cur.getDay()===0||cur.getDay()===6)&&g++<10)cur.setDate(cur.getDate()+1);
    schedule.push({date:_pgYmd(cur),book:tb.title,unit:u});
    cur.setDate(cur.getDate()+1);
  }
  if(!schedule.length){toast('할당할 단원이 없어요');return;}
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length){toast('클래스에 학생이 없어요');return;}
  askConfirm('클래스5 일괄 할당',`${tb.title} — ${schedule.length}개 단원을 ${schedule[0].date}부터 ${c.class5.weekdaysOnly?'평일':'매일'} 하나씩\n학생 ${stus.length}명에게 앱 과제로 할당할까요? (이미 있으면 갱신)`,'할당','bt',async()=>{
    showLoading(true);
    try{
      let n=0;
      for(const s of stus){
        const exist=(_cache.assignments||[]).find(a=>a.sid===s.id&&a.category==='class5'&&a.classId===classId&&a.c5BookId===c.class5.bookId);
        const a=exist
          ?{...exist,schedule,due:schedule[schedule.length-1].date}
          :{id:uid(),sid:s.id,type:'class5',category:'class5',classId,c5BookId:c.class5.bookId,date:schedule[0].date,due:schedule[schedule.length-1].date,bookTitle:'클래스5',schedule,common:true};
        await supaUpsert('assignments',a.id,a,s.id);
        if(exist){const i=_cache.assignments.findIndex(x=>x.id===a.id);if(i>=0)_cache.assignments[i]=a;}
        else _cache.assignments.unshift(a);
        n++;
      }
      if(typeof renderAssignTab==='function')renderAssignTab();
      renderClsLessons(classId);
      toast(`클래스5 ${schedule.length}단원 × ${n}명 할당 완료`);
    }catch(e){console.error('pgAssignClass5:',e);toast('할당 중 오류가 발생했습니다');}
    finally{showLoading(false);}
  });
}
// 숙제 칩 더블클릭 → 그 단원을 반 전체 학생에게 숙제로 할당
function pgHwDbl(ev,classId,subject,book,bookId,unit,due){
  if(ev&&ev.stopPropagation)ev.stopPropagation();
  clearTimeout(_pgTapTimer);pgMoveCancel();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length){toast('클래스에 학생이 없어요');return;}
  askConfirm('숙제 할당',`${book} ${unit} 복습 — 마감 ${due}\n학생 ${stus.length}명에게 숙제로 할당할까요?`,'할당','bt',
    ()=>_pgDoAssignHw(classId,[{subject,book,bookId,unit,due}],stus));
}
// 실제 숙제 assignment 생성 (중복 건너뜀)
async function _pgDoAssignHw(classId,items,stus){
  showLoading(true);
  try{
    const allLib=[...(_cache.library||[])];
    const today=ppToday();
    let n=0;
    for(const it of items){
      const isReading=allLib.some(b=>_pgNorm(b.title)===_pgNorm(it.book));
      for(const s of stus){
        const dup=(_cache.assignments||[]).find(a=>a.sid===s.id&&_pgNorm(a.bookTitle||'')===_pgNorm(it.book)&&_pgUMatch(_pgNorm(a.range||''),_pgNorm(it.unit))&&a.due===it.due);
        if(dup)continue;
        const a={id:uid(),sid:s.id,type:isReading?'reading':'textbook',category:it.subject,classId,date:today,due:it.due,bookTitle:it.book,bookId:it.bookId||'',range:it.unit,note:'복습',common:true};
        await supaUpsert('assignments',a.id,a,s.id);
        _cache.assignments.unshift(a);n++;
      }
    }
    if(typeof renderAssignTab==='function')renderAssignTab();
    renderClsLessons(classId);
    toast(n?`숙제 할당 완료 (${n}건)`:'이미 모두 할당돼 있어요');
  }catch(e){console.error('_pgDoAssignHw:',e);toast('할당 중 오류가 발생했습니다');}
  finally{showLoading(false);}
}
// 아직 할당 안 된 숙제 칩 전체를 반 전체에게 한 번에
function pgAssignAllHomework(classId){
  pgMenuClose();
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const hwBy=_pgHomeworkPlan(classId,c);
  const items=[];
  Object.entries(hwBy).forEach(([due,arr])=>arr.forEach(h=>{if(!h.assigned)items.push({subject:h.subject,book:h.book,bookId:h.bookId,unit:h.unit,due});}));
  if(!items.length){toast('할당할 숙제가 없어요');return;}
  const stus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
  if(!stus.length){toast('클래스에 학생이 없어요');return;}
  askConfirm('숙제 일괄 할당',`배운 단원 복습 숙제 ${items.length}건을 학생 ${stus.length}명에게 한 번에 할당할까요?`,'할당','bt',
    ()=>_pgDoAssignHw(classId,items,stus));
}

let _ecStuIds=[];
const ecSubjs=new Set();
function ecTogSubj(el){
  const s=el.dataset.s;
  if(ecSubjs.has(s)){
    if(s==='naesin'){addSRowTo('ec-subj-rows',s);return;}
    ecSubjs.delete(s);el.classList.remove('active');document.querySelectorAll('#ec-subj-rows .sr').forEach(r=>{if((r.dataset.s||'').replace(/_\d+$/,'')===s)r.remove();});
  }else{ecSubjs.add(s);el.classList.add('active');addSRowTo('ec-subj-rows',s);}
  _ecBoardRender();
}
// 다음 원서 제안 칩 → 그 학생 행의 빈 원서 칸에 채움
function clFillNextBook(btn,title){
  const row=btn.closest('.cl-stu-row');if(!row)return;
  const inp=[...row.querySelectorAll('.cl-rd-title')].find(i=>!i.value.trim())||row.querySelector('.cl-rd-title');
  if(!inp)return;
  inp.value=title;
  clFillFromLib(inp); // AR·시리즈 자동 채움
}
function clFillFromLib(input){
  const title=input.value.trim();if(!title)return;
  const b=[...DB.libs()].find(x=>x.title===title);
  if(!b){libOfferAdd(input);return;} // DB에 없는 원서 → 그 자리에서 추가 제안
  const row=input.closest('.cl-book-row');if(!row)return;  // fix: was .cl-stu-row
  const ar=row.querySelector('.cl-rd-ar');const ser=row.querySelector('.cl-rd-series');
  if(ar&&!ar.value&&(b.ar||b.arLevel))ar.value=b.ar||b.arLevel||'';
  if(ser)ser.value=b.series||'';
}
// 교재 선택 시 유닛 datalist 업데이트 + 직전 진도 힌트
function clUpdateUnitHint(sel){
  const sr=sel.closest('.sr');if(!sr)return;
  const unitInp=sr.querySelector('[data-f="unit"]');if(!unitInp)return;
  const bookTitle=sel.value;
  const bkId=sel.options[sel.selectedIndex]?.getAttribute('data-bk-id')||'';
  const dlId=unitInp.getAttribute('list');
  const dl=dlId?document.getElementById(dlId):null;
  if(dl){
    const tb=bkId?(_cache.globalTextbooks||[]).find(b=>b.id===bkId):(_cache.globalTextbooks||[]).find(b=>b.title===bookTitle);
    const units=tb?tbUnitKeys(tb):[];
    const titlesMap=tb?.unitTitles||{};
    dl.innerHTML=units.map(k=>`<option value="${escAttr(k)}">${k}${titlesMap[k]?' — '+titlesMap[k]:''}</option>`).join('');
  }
  if(!bookTitle){unitInp.placeholder='유닛/진도';return;}
  const classId=document.getElementById('cl-class-id')?.value;
  const lessons=classId?(_cache.lessons||[]).filter(l=>l.classId===classId&&l.materials).sort((a,b)=>(b.date||'').localeCompare(a.date||'')):[];
  let lastUnit='';
  outer:for(const les of lessons){
    for(const m of Object.values(les.materials||{})){
      if(m.book===bookTitle&&m.unit){lastUnit=m.unit;break outer;}
    }
  }
  unitInp.placeholder=lastUnit?`직전: ${lastUnit}`:'단원 선택 또는 직접 입력';
  _pgAutoFillRow(sr); // 다음 단원 자동 채움 (신규 기록만, 손으로 적은 값은 보존)
}
function lesUpdateUnitSel(sel){
  const sr=sel.closest('.sr');if(!sr)return;
  const unitInp=sr.querySelector('[data-f="unit"]');if(!unitInp)return;
  const bkId=sel.options[sel.selectedIndex]?.getAttribute('data-bk-id')||'';
  const tb=bkId?(_cache.globalTextbooks||[]).find(b=>b.id===bkId):(_cache.globalTextbooks||[]).find(b=>b.title===sel.value);
  const units=tb?tbUnitKeys(tb):[];
  const titlesMap=tb?.unitTitles||{};
  const dlId=unitInp.getAttribute('list');
  const dl=dlId?document.getElementById(dlId):null;
  if(dl)dl.innerHTML=units.map(k=>`<option value="${escAttr(k)}">${k}${titlesMap[k]?' — '+titlesMap[k]:''}</option>`).join('');
  unitInp.placeholder=units.length?'단원 선택 또는 직접 입력':'유닛/진도';
  const wrap=sr.querySelector('.unit-inputs-wrap');
  if(wrap){[...wrap.querySelectorAll('.unit-irow')].slice(1).forEach(el=>el.remove());}
  unitInp.value='';
}
function libUpdateChapterHint(inp){
  const sr=inp.closest('.sr');if(!sr)return;
  const unitInp=sr.querySelector('[data-f="unit"]');if(!unitInp)return;
  const dlId=unitInp.getAttribute('list');
  const dl=dlId?document.getElementById(dlId):null;
  if(!dl)return;
  const title=(inp.value||'').trim();
  if(!title){dl.innerHTML='';unitInp.placeholder='챕터/진도';return;}
  const seenIds=new Set((_cache.library||[]).map(b=>b.id));
  const allLib=[...(_cache.library||[]).filter(b=>!b._deleted)];
  const book=allLib.find(b=>b.title===title);
  const chapters=[...new Set((book?.vocab||[]).map(w=>w.chapter||w.unit).filter(Boolean))];
  dl.innerHTML=chapters.map(c=>`<option value="${escAttr(c)}">`).join('');
  unitInp.placeholder=chapters.length?'챕터 선택 또는 직접 입력':'챕터/진도';
}
function ecRenderTags(){
  const allStus=DB.stus();
  document.getElementById('ec-stu-tags').innerHTML=_ecStuIds.map(sid=>{
    const s=allStus.find(x=>x.id===sid);if(!s)return'';
    return`<span class="ec-stu-tag">${s.name}<span style="font-size:12px;opacity:.7;margin-left:3px">${s.grade||s.lv||''}</span><button onclick="ecRemoveStu('${sid}')" style="background:none;border:none;cursor:pointer;font-size:15px;color:var(--slate);padding:0 0 0 4px;line-height:1">×</button></span>`;
  }).join('');
}
function ecRemoveStu(sid){_ecStuIds=_ecStuIds.filter(x=>x!==sid);ecRenderTags();}
function ecStuSearch(q){
  const dd=document.getElementById('ec-stu-dropdown');
  if(!q.trim()){dd.style.display='none';return;}
  const allStus=DB.stus().filter(s=>!s.inactive&&!_ecStuIds.includes(s.id));
  const hits=allStus.filter(s=>s.name.includes(q)||(s.grade||'').includes(q)||(s.school||'').includes(q));
  if(!hits.length){dd.style.display='none';return;}
  dd.style.display='block';
  dd.innerHTML=hits.map(s=>`<div class="ec-stu-opt" onclick="ecAddStu('${s.id}')">${s.name} <span style="font-size:12px;color:var(--slate)">${s.grade||s.lv||''} ${s.school?'· '+s.school:''}</span></div>`).join('');
}
function ecAddStu(sid){
  if(!_ecStuIds.includes(sid))_ecStuIds.push(sid);
  ecRenderTags();
  document.getElementById('ec-stu-search').value='';
  document.getElementById('ec-stu-dropdown').style.display='none';
}
document.addEventListener('click',e=>{
  if(!e.target.closest('#ec-stu-search')&&!e.target.closest('#ec-stu-dropdown'))
    document.getElementById('ec-stu-dropdown').style.display='none';
});

// ── 요일별 시간 (클래스 모달) ──
let _ecDayTimesInit={};
// 완강한 교재는 클래스 수정 폼에서 숨김 (체인이 길어져 지저분해지는 문제) — 저장 시 원래 자리로 복원
let _ecHiddenMats={};
function ecToggleDayTimes(){
  const on=document.getElementById('ec-daytime-toggle').checked;
  const s=document.getElementById('ec-common-time-start'),e=document.getElementById('ec-common-time-end');
  if(s)s.style.display=on?'none':'';
  if(e)e.style.display=on?'none':'';
  const wrap=document.getElementById('ec-daytimes');
  if(wrap)wrap.style.display=on?'flex':'none';
  if(on)ecSyncDayTimes();
}
function ecSyncDayTimes(){
  _ecBoardRender();   // 요일이 바뀌면 배치판의 열도 바뀐다
  const toggle=document.getElementById('ec-daytime-toggle');
  const wrap=document.getElementById('ec-daytimes');
  if(!toggle||!toggle.checked||!wrap)return;
  const days=[...document.querySelectorAll('#m-edit-class .day-check input:checked')].map(cb=>cb.value);
  // 이미 입력 중인 값 보존
  const cur={};
  wrap.querySelectorAll('[data-day]').forEach(r=>{cur[r.dataset.day]={start:r.querySelector('.ec-dt-start').value,end:r.querySelector('.ec-dt-end').value};});
  const defS=document.getElementById('ec-time-start').value,defE=document.getElementById('ec-time-end').value;
  const IS='padding:8px 10px;border:1.5px solid var(--border);border-radius:var(--rs);font-family:var(--fb);font-size:14px;color:var(--navy);background:var(--cream2);outline:none;min-width:0;flex:1';
  wrap.innerHTML=days.length?days.map(d=>{
    const v=cur[d]||_ecDayTimesInit[d]||{start:defS,end:defE};
    return `<div data-day="${d}" style="display:flex;align-items:center;gap:8px">
      <span style="width:22px;font-size:14px;font-weight:700;color:var(--navy);flex-shrink:0;text-align:center">${d}</span>
      <input type="time" class="ec-dt-start" value="${v.start||''}" style="${IS}">
      <span style="color:var(--slate);flex-shrink:0">~</span>
      <input type="time" class="ec-dt-end" value="${v.end||''}" style="${IS}">
    </div>`;
  }).join(''):'<span style="font-size:13px;color:var(--slate)">요일을 먼저 선택해 주세요</span>';
}
function openEditClass(id=null){
  const c=id?DB.classes().find(x=>x.id===id):null;
  document.getElementById('ec-id').value=c?c.id:'';
  document.getElementById('edit-class-title').textContent=c?'클래스 수정':'클래스 만들기';
  document.getElementById('ec-name').value=c?c.name:'';
  document.getElementById('ec-time-start').value=c?c.timeStart||c.time||'':'';
  document.getElementById('ec-time-end').value=c?c.timeEnd||'':'';
  document.getElementById('ec-del-btn').style.display=c?'block':'none';
  document.querySelectorAll('#m-edit-class .day-check input').forEach(cb=>{cb.checked=c?(c.days||[]).includes(cb.value):false;});
  // 요일별 시간 초기화 — 이전 모달 세션의 잔존 행이 cur로 수집되지 않도록 반드시 비운다
  _ecDayTimesInit=(c&&c.dayTimes)?{...c.dayTimes}:{};
  const dtWrap=document.getElementById('ec-daytimes');
  if(dtWrap)dtWrap.innerHTML='';
  const dtToggle=document.getElementById('ec-daytime-toggle');
  if(dtToggle){dtToggle.checked=Object.keys(_ecDayTimesInit).length>0;ecToggleDayTimes();}
  // 공통 교재 초기화 후 불러오기
  ecSubjs.clear();
  document.querySelectorAll('#ec-subj-chips .chip').forEach(ch=>ch.classList.remove('active'));
  document.getElementById('ec-subj-rows').innerHTML='';
  _ecHiddenMats={};
  if(c?.commonMaterials){
    const hidden=[];
    Object.entries(c.commonMaterials).forEach(([s,v])=>{
      ecSubjs.add(s);
      const ch=document.querySelector(`#ec-subj-chips .chip[data-s="${s}"]`);
      if(ch)ch.classList.add('active');
      // 완강(마지막 단원까지 기록)한 교재는 목록에서 숨김 — 데이터는 _ecHiddenMats로 보존
      const tb=_pgTbOf(v);
      const keys=tb?tbUnitKeys(tb):[];
      const rec=(tb&&c.id)?_pgLastRec(c.id,tb):null;
      if(tb&&keys.length&&rec&&rec.idx>=keys.length-1){_ecHiddenMats[s]=v;hidden.push(v.book||tb.title);return;}
      addSRowTo('ec-subj-rows',s,v.book,v.unit,v.bookId||'',v.days||[],v.run||'');
    });
    if(hidden.length){
      const wrap=document.getElementById('ec-subj-rows');
      const note=document.createElement('div');
      note.style.cssText='font-size:11.5px;color:var(--slate);padding:3px 2px 7px;line-height:1.6';
      note.innerHTML=`✅ 완료한 교재 ${hidden.length}권은 목록에서 숨겼어요 — 저장해도 그대로 유지됩니다`
        +`<br><span style="opacity:.75">${hidden.slice(0,4).map(escAttr).join(' · ')}${hidden.length>4?` 외 ${hidden.length-4}권`:''}</span>`;
      wrap.insertBefore(note,wrap.firstChild);
    }
  }
  // 클래스5 책 설정 복원
  ecFillC5Books(c?.class5?.bookId||'');
  const c5s=document.getElementById('ec-c5-start');if(c5s)c5s.value=c?.class5?.startDate||'';
  const c5w=document.getElementById('ec-c5-weekday');if(c5w)c5w.checked=!!(c?.class5?.weekdaysOnly);
  ecC5BookChange(c?.class5?.startUnit||'');
  const dhw=document.getElementById('ec-dailyhw');if(dhw)dhw.value=(c?.dailyHw||[]).join('\n');
  const ahw=document.getElementById('ec-autohw');if(ahw)ahw.checked=!(c&&c.autoHw===false); // 기본 켜짐
  _ecStuIds=c?[...(c.studentIds||[])]:[];
  ecRenderTags();
  document.getElementById('ec-stu-search').value='';
  document.getElementById('ec-stu-dropdown').style.display='none';
  const _ecRows=document.getElementById('ec-subj-rows');
  if(_ecRows&&!_ecRows.dataset.boardBound){
    _ecRows.dataset.boardBound='1';
    _ecRows.addEventListener('change',e=>{if(e.target.matches('[data-f="book"]'))_ecBoardRender();});
  }
  _ecBoardRender();
  openM('m-edit-class');
}
// 클래스5 책 드롭다운 채우기 (교재 DB 전체, 단원 있는 교재)
function ecFillC5Books(selId){
  const sel=document.getElementById('ec-c5-book');if(!sel)return;
  const books=tbSortByUsage((_cache.globalTextbooks||[]).filter(b=>tbUnitKeys(b).length));
  sel.innerHTML=`<option value="">— 사용 안 함 —</option>`+books.map(b=>`<option value="${escAttr(b.id)}"${b.id===selId?' selected':''}>${escAttr(b.title)}${b.category?' ('+b.category+')':''}</option>`).join('');
}
// 책 선택 시 시작 단원 목록 채우기
function ecC5BookChange(preUnit){
  const sel=document.getElementById('ec-c5-book');const wrap=document.getElementById('ec-c5-unit-wrap');const uSel=document.getElementById('ec-c5-unit');
  if(!sel||!wrap||!uSel)return;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===sel.value);
  if(!tb){wrap.style.display='none';uSel.innerHTML='';return;}
  const keys=tbUnitKeys(tb);
  wrap.style.display='flex';
  uSel.innerHTML=keys.map(k=>`<option value="${escAttr(k)}"${(typeof preUnit==='string'&&preUnit===k)?' selected':''}>${escAttr(k)}${tb.unitTitles?.[k]?' — '+tb.unitTitles[k]:''}</option>`).join('');
}

// 폼에서 숨겼던 완강 교재를 체인 앞쪽(원래 자리)으로 되살려 합침 — 과목별로 완강분 먼저, 그다음 폼 순서
function _ecRestoreFinished(fromForm){
  if(!Object.keys(_ecHiddenMats).length)return fromForm;
  const bySubj={},order=[];
  const push=(k,v)=>{const b=k.replace(/_\d+$/,'');if(!bySubj[b]){bySubj[b]=[];order.push(b);}bySubj[b].push(v);};
  Object.entries(_ecHiddenMats).forEach(([k,v])=>push(k,v)); // 완강분이 체인 앞
  Object.entries(fromForm).forEach(([k,v])=>push(k,v));
  const out={};
  order.forEach(b=>bySubj[b].forEach((v,i)=>{out[i===0?b:`${b}_${i+1}`]=v;}));
  return out;
}
async function saveClass(){
  const name=document.getElementById('ec-name').value.trim();
  if(!name){toast('클래스명을 입력하세요');return;}
  const days=[...document.querySelectorAll('#m-edit-class .day-check input:checked')].map(cb=>cb.value);
  let timeStart=document.getElementById('ec-time-start').value;
  let timeEnd=document.getElementById('ec-time-end').value;
  // 요일별 시간: 토글이 켜져 있으면 행 값 수집, 꺼져 있으면 null(공통 시간만 사용)
  let dayTimes=null;
  if(document.getElementById('ec-daytime-toggle')?.checked){
    dayTimes={};
    document.querySelectorAll('#ec-daytimes [data-day]').forEach(r=>{
      const d=r.dataset.day;if(!days.includes(d))return;
      const s=r.querySelector('.ec-dt-start').value,e=r.querySelector('.ec-dt-end').value;
      if(s||e)dayTimes[d]={start:s,end:e};
    });
    if(!Object.keys(dayTimes).length)dayTimes=null;
    // 공통 시간 필드는 숨겨진 상태 — 첫 요일 시간을 대표값으로 저장(하위 호환)
    if(dayTimes){const first=dayTimes[days.find(d=>dayTimes[d])]||{};timeStart=first.start||timeStart;timeEnd=first.end||timeEnd;}
  }
  const time=timeStart; // 기존 호환성 유지
  const studentIds=[..._ecStuIds];
  const existingId=document.getElementById('ec-id').value;
  const id=existingId||uid();
  const existing=DB.classes().find(x=>x.id===id);
  const _ecForm=getSMatsFrom('ec-subj-rows');
  // 요일은 과목 단위로 통일한다 — 요일 배치판에서 정한 값(비었으면 '매 수업')을 그 과목 체인 전체에 적용.
  // 교재마다 요일이 따로 붙어 있으면 앞 책이 완강돼 목록에서 숨겨질 때 요일이 끊겨
  // 다음 책이 슬그머니 '매 수업'으로 풀린다. 체인 전체에 같은 값을 써서 그 틈을 없앤다.
  const _ecFormDays={};
  Object.keys(_ecForm).forEach(k=>{
    const b=k.replace(/_\d+$/,'');
    if(!(b in _ecFormDays))_ecFormDays[b]=_ecForm[k].days||[];   // 폼 순서상 과목의 첫 행 = 요일 UI를 가진 행
  });
  const commonMaterials=_ecRestoreFinished(_ecForm);
  Object.keys(commonMaterials).forEach(k=>{
    const b=k.replace(/_\d+$/,'');
    if(!(b in _ecFormDays))return;                               // 전부 완강돼 폼에 없던 과목은 손대지 않는다
    const dv=_ecFormDays[b];
    if(dv.length)commonMaterials[k].days=[...dv];else delete commonMaterials[k].days;
  });
  // 폼에 UI가 없는 교재 옵션은 같은 책의 기존 값을 보존 — 클래스 수정이 지우지 않게
  // weekly=주1회 진도 요일, alt=교대(병행) 트랙명. 새 옵션을 만들면 여기에 추가할 것
  if(existing&&existing.commonMaterials){
    const KEEP=['weekly','alt'];
    const prevByBook={};
    Object.values(existing.commonMaterials).forEach(v=>{if(v&&(v.bookId||v.book))prevByBook[v.bookId||v.book]=v;});
    Object.values(commonMaterials).forEach(v=>{
      const old=prevByBook[v.bookId||v.book];
      if(!old)return;
      KEEP.forEach(f=>{if(old[f]!==undefined&&v[f]===undefined)v[f]=old[f];});
    });
  }
  // 클래스 요일이 바뀌면 교재별 지정 요일도 교집합으로 정리 — 없어진 요일에 예정이 남지 않게
  // (교집합이 비면 days를 지워 클래스 요일 전체를 쓰게 한다)
  Object.values(commonMaterials).forEach(v=>{
    if(!v||!v.days||!v.days.length)return;
    const f=v.days.filter(d=>days.includes(d));
    if(f.length)v.days=f;else delete v.days;
  });
  // 클래스5 책 설정 (매일 한 유닛씩 앱 과제 자동 할당)
  const c5BookId=document.getElementById('ec-c5-book')?.value||'';
  let class5=null;
  if(c5BookId){
    const c5tb=(_cache.globalTextbooks||[]).find(b=>b.id===c5BookId);
    class5={bookId:c5BookId,book:c5tb?.title||'',startUnit:document.getElementById('ec-c5-unit')?.value||'',startDate:document.getElementById('ec-c5-start')?.value||ppToday(),
      ...(document.getElementById('ec-c5-weekday')?.checked&&{weekdaysOnly:true})};
  }
  const dailyHw=(document.getElementById('ec-dailyhw')?.value||'').split('\n').map(x=>x.trim()).filter(Boolean);
  const autoHw=document.getElementById('ec-autohw')?document.getElementById('ec-autohw').checked:true; // 수업 연계 숙제 자동 제안
  const c={...(existing||{}),id,name,days,time,timeStart,timeEnd,dayTimes,studentIds,commonMaterials,class5,dailyHw,autoHw,active:true};
  await supaUpsert('classes',id,c,null);
  if(!_cache.globalClasses)_cache.globalClasses=[];
  const idx=_cache.globalClasses.findIndex(x=>x.id===id);
  if(idx>=0)_cache.globalClasses[idx]=c;else _cache.globalClasses.unshift(c);
  closeM('m-edit-class');
  renderClassTab();renderDash();
  if(_pgCalClsId===id&&document.getElementById('cls-detail-wrap')?.style.display!=='none')renderClsLessons(id);
  // 학생 추가 모달 위에서 만든 경우: 목록 갱신 + 방금 만든 클래스 자동 선택
  // (closeM은 'open' 클래스를 남기고 display:none만 걸므로 실제 가시 상태까지 확인)
  const stuModal=document.getElementById('m-add-stu');
  if(stuModal&&stuModal.classList.contains('open')&&stuModal.style.display!=='none')renderNsClasses(id);
  toast('저장되었습니다');
}

function deleteClass(){
  const id=document.getElementById('ec-id').value;if(!id)return;
  const c=DB.classes().find(x=>x.id===id);
  askConfirm(`'${c?.name}' 삭제`,'클래스를 삭제할까요? 기존 수업 기록은 유지됩니다.','삭제','bd',async()=>{
    await supaDelete('classes',id);
    _cache.globalClasses=(_cache.globalClasses||[]).filter(x=>x.id!==id);
    closeM('m-edit-class');renderClassTab();renderDash();
    toast('삭제되었습니다');
  });
}

function openClassLessonEdit(classId,dateStr){
  // 기존 수업 기록 로드 후 수정 모드로 열기
  openClassLesson(classId,dateStr);
  // 기존 레코드 로드
  const existingLes=DB.less().filter(l=>l.classId===classId&&l.date===dateStr);
  if(!existingLes.length)return;
  // 수정 모드 플래그 저장 (저장 시 upsert)
  document.getElementById('cl-class-id').dataset.editMode='true';
  document.getElementById('cl-modal-title').textContent+=' (수정)';if((_cache.assignments||[]).some(a=>!a._deleted&&a.classId===classId&&a.date===dateStr))clHwSetOpen(true);
  // 기존 데이터로 학생 행 채우기
  setTimeout(()=>{
    const allStus=DB.stus();
    // ① 공통 교재 진도: 클래스 기본값 대신 실제 저장된 수업 자료로 재구성
    //    (원래 수업에서 X로 뺐던 교재가 수정 때 되살아나지 않게)
    const first=existingLes[0];
    if(first){
      clSubjs.clear();
      document.querySelectorAll('#cl-subj-chips .chip').forEach(ch=>ch.classList.remove('active'));
      const srWrap=document.getElementById('cl-subj-rows');if(srWrap)srWrap.innerHTML='';
      Object.entries(first.materials||{}).forEach(([k,v])=>{
        if(k==='_book'||k.startsWith('_book_'))return; // 원서는 학생별 행에서 복원
        const baseKey=k.replace(/_\d+$/,'');
        clSubjs.add(baseKey);
        const ch=document.querySelector(`#cl-subj-chips .chip[data-s="${baseKey}"]`);
        if(ch)ch.classList.add('active');
        addSRowTo('cl-subj-rows',k,v.book,v.unit,v.bookId||'');
        // 교재가 그 사이 DB에서 삭제·분류 변경됐어도 저장된 제목이 유실되지 않게 옵션 주입
        const sel=document.querySelector('#cl-subj-rows .sr:last-child select[data-f="book"]');
        if(sel&&!sel.value&&v.book){
          const o=document.createElement('option');
          o.value=v.book;o.textContent=v.book+' (DB에 없음)';if(v.bookId)o.dataset.bkId=v.bookId;
          const addOpt=[...sel.options].find(x=>x.value==='__addnew__');
          sel.insertBefore(o,addOpt||null);sel.value=v.book;
        }
      });
    }
    // ② 과제: 자동 채움 대신 이 수업에 실제 저장된 과제로 재구성
    clHwRestoreFromSaved(classId,dateStr);
    existingLes.forEach(les=>{
      const row=document.querySelector(`.cl-stu-row[data-sid="${les.sid}"]`);if(!row)return;
      const attSel=row.querySelector('.cl-att');if(attSel)attSel.value=les.att||'normal';
      // 원서 복원
      const booksWrap=row.querySelector('.cl-books-wrap');
      const bookEntries=Object.entries(les.materials||{}).filter(([k])=>k==='_book'||k.startsWith('_book_'));
      if(booksWrap&&bookEntries.length){
        booksWrap.innerHTML='';// 기존 빈 행 제거
        bookEntries.forEach(([,v])=>{
          // AR·시리즈: 저장된 자료값 우선, 없으면 원서 DB(library)에서 채움
          const lb=[...DB.libs()].find(x=>_pgNorm(x.title)===_pgNorm(v.book||''));
          const ar=v.ar||lb?.ar||lb?.arLevel||'';
          const series=v.series||lb?.series||'';
          const br=document.createElement('div');
          br.className='cl-book-row';br.style.cssText='display:flex;gap:6px;margin-bottom:4px;flex-wrap:wrap;align-items:flex-start';
          br.innerHTML=clBookRowHtml({book:v.book,ar,series,unit:v.unit},true);
          booksWrap.appendChild(br);
        });
      }
      // 코멘트 복원 (공통 코멘트 제거 후 개인 코멘트만)
      const cmtEl=row.querySelector('.cl-ind-cmt');
      if(cmtEl&&les.cmt)cmtEl.value=les.cmt;
    });
  },100);
}
// 수정 모드: 자동 채움 대신 이 수업(classId+date)에 저장된 과제로 공통/개별 과제 UI를 재구성
function clHwRestoreFromSaved(classId,dateStr){
  const common=document.getElementById('cl-hw-common-rows');if(!common)return;
  const ind=document.getElementById('cl-hw-ind-rows');
  common.innerHTML='';
  if(ind)ind.innerHTML='';
  // '이 수업 폼이 만든 과제'만 복원 대상 — 스케줄형(반복·클래스5)은 date가 수업일과 겹쳐도 이 수업 과제가 아님
  // (앱 단어 반복 숙제 due=12/31이 마감일 그룹으로 잡혀 뜬금없는 12/31 그룹이 생기던 문제)
  const saved=ppLive(_cache.assignments).filter(a=>a.classId===classId&&a.date===dateStr
    &&!(a.schedule||[]).length&&['reading','textbook'].includes(a.type||''));
  const c=DB.classes().find(x=>x.id===classId);
  if(!saved.length){
    // 저장된 과제 없음 — 내용은 비우되 요일별 그룹 스캐폴드는 유지 (요일 묶음 디스플레이 보존)
    const dates=c?getClassLessonDates(c,dateStr):[dateStr];
    dates.forEach(d=>{const b=clHwMakeDateGroup(d,common);_clAppendAutoHwRows(b,_clAutoHwFor(classId,d,dateStr));});
    return;
  }
  // 레거시(출처 표식 없는) 과제의 공통 판별 기준: 당시 이 수업에 출석한 구성원(수업 기록 보유·결석 제외) 전원이 가진 과제
  // — 반원 변동이 있어도 그날 실제 대상 전원 기준이라 공통이 개별로 풀리지 않음
  const lessonSids=new Set((_cache.lessons||[]).filter(l=>l.classId===classId&&l.date===dateStr&&(l.att||'normal')!=='absent').map(l=>l.sid));
  const knownCats=HW_CATS.map(x=>x.v);
  // 같은 내용(마감·구분·교재·범위·메모)끼리 묶어 공통/개별 판별
  const groups=new Map();
  saved.forEach(a=>{
    const key=[a.due||dateStr,a.category||'',a.bookTitle||'',a.range||'',a.note||''].join('');
    if(!groups.has(key))groups.set(key,{a,sids:new Set(),hasCommon:false,hasInd:false});
    const g=groups.get(key);
    g.sids.add(a.sid);
    if(a.common===true)g.hasCommon=true;   // 공통 과제로 저장된 출처 표식
    if(a.common===false)g.hasInd=true;     // 개별 과제로 저장된 출처 표식
  });
  const fillRow=(nr,a)=>{
    if(!nr)return;
    if(!knownCats.includes(a.category||'')){ // 직접 입력 구분 복원
      const catSel=nr.querySelector('.cl-hw-cat');if(catSel)catSel.value='__custom__';
      const cEl=nr.querySelector('.cl-hw-cat-custom');if(cEl){cEl.style.display='';cEl.value=a.category||'';}
      fillClHwRowDl(nr);
    }
    const nEl=nr.querySelector('.cl-hw-note');if(nEl)nEl.value=a.note||'';
    clHwFillRangeDl(nr);
  };
  const dueGroups={};
  const indBySid={};
  [...groups.values()].forEach(g=>{
    // 저장 시 기록된 출처(common:true/false)를 우선 사용 — 결석·반원 변동에도 공통/개별이 그대로 유지됨.
    // 레거시 데이터는 '당시 출석 구성원 전원 보유'면 공통으로 판별
    const legacyCommon=lessonSids.size>0&&[...lessonSids].every(sid=>g.sids.has(sid));
    const isCommon=g.hasCommon?true:(g.hasInd?false:legacyCommon);
    if(isCommon){
      (dueGroups[g.a.due||dateStr]=dueGroups[g.a.due||dateStr]||[]).push(g.a);
    }else{
      // 일부 학생 과제 → 학생별로 모아 학생 그룹 구조로 복원
      [...g.sids].forEach(sid=>{(indBySid[sid]=indBySid[sid]||[]).push(g.a);});
    }
  });
  // 개별 과제: 학생 그룹 → 요일 그룹으로 복원
  Object.entries(indBySid).forEach(([sid,list])=>{
    const wrap=clHwAddStuGroup(sid);if(!wrap)return;
    const body=wrap.querySelector('.cl-hw-stu-body');if(!body)return;
    const byDue={};list.forEach(a=>{(byDue[a.due||dateStr]=byDue[a.due||dateStr]||[]).push(a);});
    Object.keys(byDue).sort().forEach(d=>{
      let gEl=[...body.children].find(x=>x.classList&&x.classList.contains('cl-hw-date-group')&&x.dataset.date===d);
      const gBody=gEl?gEl.querySelector('.cl-hw-group-body'):clHwMakeDateGroup(d,body);
      byDue[d].forEach(a=>{
        const cat=knownCats.includes(a.category||'')?(a.category||''):'';
        addClHwRow(d,true,cat,a.bookTitle||'',a.range||'',gBody);
        fillRow(gBody.lastElementChild,a);
      });
    });
  });
  // 저장된 마감일 + 이 수업 주기의 요일을 합쳐 요일별 그룹 UI를 온전히 유지
  const scaffold=c?getClassLessonDates(c,dateStr):[dateStr];
  const allDates=[...new Set([...Object.keys(dueGroups),...scaffold])].sort();
  allDates.forEach(d=>{
    const body=clHwMakeDateGroup(d,common);
    _clAppendAutoHwRows(body,_clAutoHwFor(classId,d,dateStr)); // 이미 나가 있는 숙제 표시 (또 내기 방지)
    (dueGroups[d]||[]).forEach(a=>{
      const cat=knownCats.includes(a.category||'')?(a.category||''):'';
      addClHwRow(d,true,cat,a.bookTitle||'',a.range||'',body);
      fillRow(body.lastElementChild,a);
    });
  });
}
function setClProgChip(btn,val){
  const inp=btn.closest('.cl-book-row').querySelector('.cl-rd-prog');if(!inp)return;
  inp.value=val==='진행 중'?'진행 중 ':val;
  inp.focus();const len=inp.value.length;inp.setSelectionRange(len,len);
}
const _CL_PROG_CHIPS_HTML=['완독','진행 중'].map(v=>`<button type="button" class="cmt-chip" style="font-size:11.5px;padding:1px 6px" onclick="setClProgChip(this,'${v}')">${v}</button>`).join('');
// 기록 대상 날짜(cl-date)의 요일 시간을 모달 서브 라벨에 표시 — 날짜 변경 시에도 호출됨
function clUpdateDaySub(){
  const c=DB.classes().find(x=>x.id===document.getElementById('cl-class-id').value);if(!c)return;
  const d=document.getElementById('cl-date').value||ppToday();
  const day=['일','월','화','수','목','금','토'][new Date(d+'T00:00:00').getDay()];
  const timeStr=classTimeStr(c,day);
  document.getElementById('cl-modal-sub').textContent=classSchedStr(c)+(timeStr&&(c.dayTimes&&Object.keys(c.dayTimes).length)?` — ${day}요일 ${timeStr}`:'');
}
function openClassLesson(classId,dateStr){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  document.getElementById('cl-class-id').dataset.editMode='';
  document.getElementById('cl-class-id').value=classId;
  document.getElementById('cl-modal-title').textContent=c.name+' 수업 기록';
  document.getElementById('cl-date').value=dateStr||ppToday();
  clUpdateDaySub();
  // 공통 교재: 클래스에 저장된 기본값으로 초기화
  clSubjs.clear();
  document.querySelectorAll('#cl-subj-chips .chip').forEach(ch=>ch.classList.remove('active'));
  document.getElementById('cl-subj-rows').innerHTML='';
  if(c.commonMaterials){
    // **그 날 예정**(진도 캘린더와 같은 계산)을 그대로 채운다 — 달력과 창이 다르던 문제.
    // 예정이 없으면 줄별 '지금 책' 중 그 요일에 도는 책으로.
    const _clDate=document.getElementById('cl-date').value||ppToday();
    const _addRow=(s,book,unit,bookId)=>{
      clSubjs.add(s.replace(/_\d+$/,''));
      const ch=document.querySelector(`#cl-subj-chips .chip[data-s="${s.replace(/_\d+$/,'')}"]`);
      if(ch)ch.classList.add('active');
      addSRowTo('cl-subj-rows',s,book,unit,bookId||'');
    };
    let _filled=0;
    try{
      const _plan=_pgComposePlan(classId,c,_clDate);
      const _gh=(_plan&&_plan.ghostBy&&_plan.ghostBy[_clDate])||[];
      const _byKey={};
      _gh.forEach(g=>{
        if(!g||!g.s)return;
        const e=_byKey[g.s]||(_byKey[g.s]={book:g.title||'',bookId:g.tbId||'',units:[]});
        if(g.unit)e.units.push(g.unit);
      });
      Object.entries(_byKey).forEach(([s,v])=>{_addRow(s,v.book,v.units.join(', '),v.bookId);_filled++;});
    }catch(e){console.error('openClassLesson plan:',e);}
    if(!_filled)Object.entries(_pgActiveMats(classId,c,{date:_clDate})).forEach(([s,v])=>_addRow(s,v.book,v.unit,v.bookId));
    // 기존 선택된 교재에 직전 진도 힌트 설정
    document.querySelectorAll('#cl-subj-rows select[data-f="book"]').forEach(clUpdateUnitHint);
  }
  // 과제 초기화 후 날짜별 공통 과제 행 자동 생성 (교재별 1행씩)
  document.getElementById('cl-hw-ind-rows').innerHTML='';
  // 개별 과제 학생 선택 드롭다운 채우기 (이 클래스 소속 학생)
  {const stuAddSel=document.getElementById('cl-hw-stu-add');
   if(stuAddSel){
     const cstus=DB.stus().filter(s=>!s.inactive&&(c.studentIds||[]).includes(s.id));
     stuAddSel.innerHTML='<option value="">학생 선택…</option>'+cstus.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');
   }}
  clHwSetOpen(false);clHwSyncFromSubj();if(clHwHasPending())clHwSetOpen(true);
  // 학생 rows (원서 상세 입력)
  const iStyle='padding:6px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-family:var(--fb);font-size:13px;color:var(--navy);background:var(--cream);outline:none';
  const allStus=DB.stus().filter(s=>!s.inactive);
  const students=allStus.filter(s=>(c.studentIds||[]).includes(s.id));
  document.getElementById('cl-students').innerHTML=students.length
    ?students.map(s=>{const nb=DB.ortNext(s.id);return`<div class="cl-stu-row" data-sid="${s.id}">
      ${clPrevHwHtml(s.id)}
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        <span style="font-size:15px;font-weight:700;min-width:56px">${s.name}</span>
        ${(typeof ppRetestChipHtml==='function')?ppRetestChipHtml(s.id):''}
        <select class="cl-att filter-sel" style="flex:0 0 auto" onchange="clMarkDirty()">
          <option value="normal">정상</option><option value="absent">결석</option>
          <option value="late">지각</option><option value="sick">병결</option>
          <option value="teacher_cancel">선생님 취소</option><option value="holiday">휴강</option>
          <option value="makeup">보강</option>
        </select>
        <span style="font-size:12px;color:var(--slate)">${s.grade||s.lv||''}</span>
      </div>
      ${nb?`<button type="button" class="cmt-chip" style="margin-bottom:6px" title="ORT 순서상 아직 안 읽은 첫 책 — 누르면 원서 칸에 채워져요" onclick="clFillNextBook(this,'${escJsA(nb.title)}')">📖 다음 원서: ${nb.title}${nb.ortGroup?` · ${nb.ortGroup}`:''}</button>`:''}
      <div class="cl-books-wrap" style="margin-bottom:6px">
        <div class="cl-book-row" style="display:flex;gap:6px;margin-bottom:4px;flex-wrap:wrap;align-items:flex-start">${clBookRowHtml({},false)}</div>
      </div>
      <button class="btn ba" style="font-size:12px;padding:3px 10px;margin-bottom:6px" onclick="addClBookRow(this)">+ 원서 추가</button>
      <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:5px">
        ${['집중도 좋음','이해도 높음','자신감 향상 중','적극 참여','질문 잘 함','예습 완료','숙제 성실','읽기 유창','단어 암기 우수','발표 잘 함','복습 필요','속도 향상 중','어휘 보완 필요','발음 교정 중','어법 점검 필요','쓰기 연습 필요','집중 유지 필요','리듬감·억양 개선','듣기 이해도 향상 중','문장 구성 능숙'].map(c=>`<button type="button" class="cmt-chip" onclick="clAddIndCmt(this,'${c}')">${c}</button>`).join('')}
      </div>
      <textarea class="cl-ind-cmt" placeholder="개인 코멘트 (선택)" rows="2" style="${iStyle};width:100%;box-sizing:border-box;resize:none"></textarea>
      <div style="display:flex;align-items:center;gap:8px;margin-top:5px">
        <button type="button" class="btn bo" style="font-size:12px;padding:3px 10px" onclick="clPreviewIndCmt(this,'${s.name}')">👁 학부모용 미리보기</button>
        <span class="cl-preview-status" style="font-size:12px;color:var(--slate)"></span>
      </div>
      <div class="cl-preview-cmt" style="display:none;margin-top:6px;padding:8px 10px;background:#f0fafb;border-radius:var(--rs);font-size:13px;color:var(--navy);line-height:1.6;border:1px solid var(--teal)"></div>
    </div>`;}).join('')
    :'<div style="color:var(--slate);font-size:14px">소속 학생이 없습니다</div>';
  openClsRecord();
}
// 지난 수업에서 못 끝낸 숙제 (B7) — 미완·미지참·일부·연기를 수업 기록 맨 위에 보여 준다.
// 연기분은 이번 수업 확인 목록(_clAutoHwFor)에도 들어가므로 여기서는 '무엇이 남았는지'만 알린다.
function clPrevHwHtml(sid){
  if(typeof ppUnfinishedBefore!=='function')return '';
  const ds=document.getElementById('cl-date')?.value||ppToday();
  const rows=ppUnfinishedBefore(sid,ds,4);
  const defer=(typeof ppDeferredHw==='function')?ppDeferredHw(sid,ds):[];
  if(!rows.length&&!defer.length)return '';
  const line=r=>{
    const a=r.a,sc=r.sc;
    const txt=[a.bookTitle||a.text||'',(sc?[sc.book,sc.unit].filter(Boolean).join(' · '):a.range)||''].filter(Boolean).join(' · ')||'과제';
    return `<div class="cl-prev-row"><span class="st">${escAttr(r.label||'')}</span>`
      +`<b>${escAttr(txt)}</b> <span style="font-family:var(--fm)">${escAttr(r.date||'')}</span></div>`;
  };
  const dLine=d=>{
    const txt=[d.a.bookTitle||d.a.text||'',(d.sc?[d.sc.book,d.sc.unit].filter(Boolean).join(' · '):d.a.range)||''].filter(Boolean).join(' · ')||'과제';
    return `<div class="cl-prev-row"><span class="st">연기</span><b>${escAttr(txt)}</b>`
      +` <span style="font-family:var(--fm)">${escAttr(d.from)}${d.to?' → '+escAttr(d.to):''}</span></div>`;
  };
  const n=rows.length+defer.length;
  return `<div class="cl-prev-hw">`
    +`<div class="cl-prev-h"><span class="n">${n}</span>지난 수업에서 못 끝낸 것`
    +(defer.length?`<span style="font-size:11.5px;font-weight:600;color:var(--text-muted)">· 연기 ${defer.length}건은 아래 확인 목록에도 올라와 있어요</span>`:'')
    +`</div>`
    +defer.map(dLine).join('')
    +rows.filter(r=>r.status!=='defer').map(line).join('')
    +`</div>`;
}
// 출결은 저장을 눌러야 들어간다 — 바꾼 뒤 안 누르고 나가는 일을 막는다 (B5)
function clMarkDirty(){
  const el=document.getElementById('cl-dirty');
  if(el)el.classList.add('on');
}
function clClearDirty(){
  const el=document.getElementById('cl-dirty');
  if(el)el.classList.remove('on');
}
function openClsRecord(){
  const col=document.getElementById('cls-record-col');if(col)col.classList.add('open');
  const r2=document.getElementById('cls-resizer-2');if(r2)r2.style.display='';
  document.getElementById('cls-split')?.classList.add('detail-open');
}
function closeClsRecord(){
  const col=document.getElementById('cls-record-col');if(col)col.classList.remove('open');
  const r2=document.getElementById('cls-resizer-2');if(r2)r2.style.display='none';
}
// ── 학생 상세 폭 조절 ────────────────────────────────────────
// 상세에 담기는 내용이 많아 400px 로는 좁다. 드래그로 넓히고 폭을 기억한다.
// (클래스 탭의 startClsResize 와 같은 방식)
const STU_W_KEY='pp_stu_detail_w';
function _stuApplyW(w){
  const col=document.getElementById('stu-detail-col');if(!col)return;
  col.style.width=w?w+'px':'';
  const btn=document.getElementById('sp-wide-btn');
  if(btn){
    const split=document.getElementById('stu-split');
    const wide=w&&split&&w>split.offsetWidth*0.62;
    btn.setAttribute('title',wide?'상세를 좁게 보기':'상세를 넓게 보기');
    const ic=btn.querySelector('svg,i');
    if(ic&&typeof lucide!=='undefined'){
      btn.innerHTML='';
      const el=document.createElement('i');
      el.setAttribute('data-lucide',wide?'chevrons-right':'chevrons-left');
      el.setAttribute('width','14');el.setAttribute('height','14');
      btn.appendChild(el);
      try{lucide.createIcons({attrs:{},nameAttr:'data-lucide'});}catch(e){}
    }
  }
}
function startStuResize(e){
  e.preventDefault();
  const col=document.getElementById('stu-detail-col');
  const split=document.getElementById('stu-split');
  if(!col||!split)return;
  const rz=document.getElementById('stu-resizer');
  if(rz)rz.classList.add('dragging');
  const startX=e.clientX, startW=col.offsetWidth;
  const onMove=ev=>{
    const maxW=split.offsetWidth-280;          // 목록이 280px 아래로 줄지 않게
    const w=Math.max(320,Math.min(maxW,startW-(ev.clientX-startX)));
    col.style.width=w+'px';
  };
  const onUp=()=>{
    document.removeEventListener('mousemove',onMove);
    document.removeEventListener('mouseup',onUp);
    if(rz)rz.classList.remove('dragging');
    try{localStorage.setItem(STU_W_KEY,String(col.offsetWidth));}catch(_){}
    _stuApplyW(col.offsetWidth);
  };
  document.addEventListener('mousemove',onMove);
  document.addEventListener('mouseup',onUp);
}
// 버튼: 넓게 ↔ 기본 토글
function toggleStuWide(){
  const col=document.getElementById('stu-detail-col');
  const split=document.getElementById('stu-split');
  if(!col||!split)return;
  const wide=col.offsetWidth>split.offsetWidth*0.62;
  const w=wide?400:Math.max(560,Math.round(split.offsetWidth*0.68));
  col.style.width=w+'px';
  try{localStorage.setItem(STU_W_KEY,String(w));}catch(_){}
  _stuApplyW(w);
}
function resetStuWidth(){
  const col=document.getElementById('stu-detail-col');if(!col)return;
  col.style.width='';
  try{localStorage.removeItem(STU_W_KEY);}catch(_){}
  _stuApplyW(0);
}
// 저장된 폭 복원 — 학생 탭을 열 때마다
function restoreStuWidth(){
  let w=0;
  try{w=parseInt(localStorage.getItem(STU_W_KEY)||'0',10)||0;}catch(_){}
  if(w)_stuApplyW(w);
}

function startClsResize(e,colId,invert=false){
  e.preventDefault();
  const col=document.getElementById(colId);if(!col)return;
  const startX=e.clientX;
  const startW=col.offsetWidth;
  const onMove=ev=>{
    const container=document.getElementById('cls-split');
    const maxW=container?(container.offsetWidth-200):9999; // 200px은 detail-col 최소 확보
    const dx=ev.clientX-startX;
    const newW=Math.max(160,Math.min(maxW,startW+(invert?-dx:dx)));
    col.style.flexShrink='0';col.style.flexGrow='0';col.style.flexBasis=newW+'px';col.style.width=newW+'px';
  };
  const onUp=()=>{document.removeEventListener('mousemove',onMove);document.removeEventListener('mouseup',onUp);};
  document.addEventListener('mousemove',onMove);document.addEventListener('mouseup',onUp);
}

const _CAT_KO={phonics:'파닉스',vocab:'어휘',grammar:'어법',reading:'리딩',listening:'리스닝',writing:'라이팅',naesin:'내신',pencil_down:'펜슬다운',sing_together:'펜슬다운'};
function fillAsgnBookDatalist(dlId,cat){
  const dl=document.getElementById(dlId);if(!dl)return;
  const tbooks=_cache.globalTextbooks||[];
  const allLib=[...(_cache.library||[])];
  let opts='';
  if(cat==='class5'){
    opts=tbooks.map(b=>`<option value="${escAttr(_tbVal(b))}">`).join(''); // 클래스5 자습도 교재 DB에서 선택
  }else if(cat==='book'){
    opts=[...new Set(allLib.map(b=>b.title).filter(Boolean))].map(t=>`<option value="${escAttr(t)}">`).join('');
  }else if(_CAT_KO[cat]){
    const filtered=tbooks.filter(b=>b.category===_CAT_KO[cat]);
    opts=filtered.map(b=>`<option value="${escAttr(_tbVal(b))}">`).join('');
  }else{
    opts=tbooks.map(b=>`<option value="${escAttr(_tbVal(b))}">`).join('')+
      [...new Set(allLib.map(b=>b.title).filter(Boolean))].map(t=>`<option value="${escAttr(t)}">`).join('');
  }
  dl.innerHTML=opts;
}
function spHwCatChange(sid){
  const cat=document.getElementById(`asgn-cat-${sid}`)?.value;
  const bookEl=document.getElementById(`asgn-book-${sid}`);
  // 직접 입력 구분 토글
  const custom=document.getElementById(`asgn-cat-custom-${sid}`);
  if(custom){custom.style.display=cat==='__custom__'?'':'none';if(cat==='__custom__')setTimeout(()=>custom.focus(),0);else custom.value='';}
  fillAsgnBookDatalist(`dl-asgn-${sid}`,cat);
  if(cat&&cat!=='other'&&cat!=='book'&&cat!=='class5'&&cat!=='__custom__'&&bookEl&&!bookEl.value){
    const stClasses=DB.classes().filter(c=>(c.studentIds||[]).includes(sid));
    for(const c of stClasses){
      const matched=_pgActiveMatPick(c.id,c,cat);   // 줄이 둘이면 과제로 도는 줄의 책
      if(matched){
        const m=matched[1];
        const tb=(_cache.globalTextbooks||[]).find(b=>m.bookId?b.id===m.bookId:b.title===m.book);
        bookEl.value=tb?_tbVal(tb):(m.book||'');break;
      }
    }
  }
  if(bookEl)spAsgnBookChange(bookEl,sid,false); // 자동 채움 이후 단원 datalist 동기화 (라이브러리 등록 없음)
  const extra=document.getElementById(`asgn-extra-${sid}`);
  if(cat==='vocab'&&extra){
    const recentCards=ppLive(_cache.vocab_cards).filter(c=>c.sid===sid).slice(0,20);
    extra.innerHTML=`<div class="f" style="margin-top:6px"><label>단어 선택</label>
      <div style="max-height:120px;overflow-y:auto;border:1px solid var(--border);border-radius:var(--rs);padding:6px">
        ${recentCards.length?recentCards.map(c=>`<label style="display:flex;align-items:center;gap:6px;padding:2px 0;cursor:pointer;font-size:13px"><input type="checkbox" class="asgn-vocab-chk" value="${c.word}"> ${c.word}<span style="font-size:11.5px;color:var(--slate)">${c.meaning||''}</span></label>`).join(''):'<span style="font-size:13px;color:var(--slate)">단어 카드 없음</span>'}
      </div></div>`;
  } else if(extra) extra.innerHTML='';
}
async function saveStudentAssign(sid){
  let cat=document.getElementById(`asgn-cat-${sid}`)?.value;
  if(cat==='__custom__')cat=document.getElementById(`asgn-cat-custom-${sid}`)?.value.trim()||''; // 직접 입력 구분
  const book=document.getElementById(`asgn-book-${sid}`)?.value.trim()||'';
  const range=document.getElementById(`asgn-range-${sid}`)?.value.trim()||'';
  const date=document.getElementById(`asgn-date-${sid}`)?.value||ppToday();
  const due=document.getElementById(`asgn-due-${sid}`)?.value||date;
  if(!cat&&!book&&!range){toast('구분을 고르거나 교재·범위를 입력해 주세요');return;}
  const allLib=[...(_cache.library||[])];
  const isReading=cat==='book'||allLib.some(b=>b.title===book);
  const KNOWN_CATS=['phonics','vocab','grammar','reading','listening','writing','naesin','book','class5','other',''];
  const type=isReading?'reading':cat==='vocab'?'vocab':(cat==='other'||!KNOWN_CATS.includes(cat))?'other':'textbook';
  const a={id:uid(),sid,type,category:cat,date,due,bookTitle:book,range};
  if(type==='vocab'){
    const checked=[...document.querySelectorAll('.asgn-vocab-chk:checked')].map(c=>c.value);
    const extra=(document.getElementById(`asgn-book-${sid}`)?.value||'').split(',').map(w=>w.trim()).filter(Boolean);
    a.words=[...new Set([...checked,...extra])];
    if(a.words.length)await syncVocabCards(sid,a.words,[],date,'과제','expose');
  }
  if(!book&&!range&&type!=='vocab'){toast('교재/원서 또는 범위를 입력해 주세요');return;}
  const isDup=ppLive(_cache.assignments).some(x=>x.sid===sid&&_tbBase(x.bookTitle||'')===_tbBase(book||'')&&(x.range||'')===range&&x.due===due);
  if(isDup){toast('이미 동일한 과제가 있습니다');return;}
  try{
    await supaUpsert('assignments',a.id,a,sid);
    if(!_cache.assignments)_cache.assignments=[];
    _cache.assignments.unshift(a);
    await loadStuPanel(sid);
    swSpTab('sp-hw');
    toast('과제가 할당되었습니다');
  }catch(e){toast('저장 실패: '+e.message);}
}
function toggleAssignEdit(aid,sid){
  const existing=document.getElementById(`asgn-edit-${aid}`);
  if(existing){existing.remove();return;}
  const a=(_cache.assignments||[]).find(x=>x.id===aid);
  if(!a)return;
  const row=document.getElementById(`asgn-row-${aid}`);
  if(!row)return;
  const div=document.createElement('div');
  div.id=`asgn-edit-${aid}`;
  div.style.cssText='padding:8px;background:var(--cream2);border-radius:8px;margin-top:4px';
  const rangeVal=(a.range||a.text||'').replace(/"/g,'&quot;');
  const bookVal=(a.bookTitle||'').replace(/"/g,'&quot;');
  div.innerHTML=`<div style="display:flex;gap:8px;margin-bottom:6px;flex-wrap:wrap">
    <div style="flex:1;min-width:140px"><label style="font-size:12px;display:block;margin-bottom:2px">교재/원서</label><input type="text" id="ae-book-${aid}" value="${bookVal}" list="dl-hw-books" autocomplete="off" placeholder="예: 공책, Easy Link Starter 2" style="width:100%"></div>
    <div style="flex:1;min-width:120px"><label style="font-size:12px;display:block;margin-bottom:2px">범위/내용</label><input type="text" id="ae-range-${aid}" value="${rangeVal}" style="width:100%"></div>
    <div style="flex:0 0 140px"><label style="font-size:12px;display:block;margin-bottom:2px">마감일</label><input type="date" id="ae-due-${aid}" value="${a.due||''}"></div>
    <div style="flex:0 0 130px"><label style="font-size:12px;display:block;margin-bottom:2px">학습 방향</label>
      <select id="ae-track-${aid}" style="width:100%">
        <option value=""${!a.track?' selected':''}>미분류</option>
        <option value="jg"${a.track==='jg'?' selected':''}>직결</option>
        <option value="ch"${a.track==='ch'?' selected':''}>체력</option>
        <option value="common"${a.track==='common'?' selected':''}>공통</option>
      </select></div>
  </div>
  <div style="display:flex;gap:6px">
    <button class="btn bt bsm" style="font-size:12px" onclick="saveAssignEdit('${aid}','${sid}')">저장</button>
    <button class="btn bo bsm" style="font-size:12px" onclick="document.getElementById('asgn-edit-${aid}')?.remove()">취소</button>
  </div>`;
  row.after(div);
}
async function saveAssignEdit(aid,sid){
  const a=(_cache.assignments||[]).find(x=>x.id===aid);
  if(!a)return;
  const due=document.getElementById(`ae-due-${aid}`)?.value||'';
  const range=document.getElementById(`ae-range-${aid}`)?.value.trim()||'';
  const book=document.getElementById(`ae-book-${aid}`)?document.getElementById(`ae-book-${aid}`).value.trim():(a.bookTitle||'');
  // 개별 수정으로 내용이 공통 배치본과 달라지면 공통 표식 해제 (수정 복원 시 전원 확산 방지)
  const _prevRange=(a.type==='other'&&a.text&&!a.range)?(a.text||''):(a.range||'');
  if(a.common===true&&((a.due||'')!==due||_prevRange!==range||(a.bookTitle||'')!==book))a.common=false;
  a.bookTitle=book;
  a.due=due;
  {const tk=document.getElementById('ae-track-'+aid);if(tk)a.track=(['jg','ch','common'].includes(tk.value)?tk.value:'');}
  // 레거시 'other'(text에만 내용 저장) 과제만 text 갱신 — 커스텀 구분(range 저장)은 range 갱신
  if(a.type==='other'&&a.text&&!a.range)a.text=range; else a.range=range;
  await supaUpsert('assignments',aid,a,sid);
  const idx=(_cache.assignments||[]).findIndex(x=>x.id===aid);
  if(idx>=0)_cache.assignments[idx]=a;
  await loadStuPanel(sid);swSpTab('sp-hw');toast('수정되었습니다');
}
async function deleteStudentAssign(aid,sid){
  askConfirm('과제 삭제','이 과제를 삭제할까요? (휴지통에서 복원할 수 있어요)','삭제','bd',async()=>{
    await supaTrash('assignments',_cache.assignments,aid);
    _cache.assignments=(_cache.assignments||[]).filter(a=>a.id!==aid);
    await loadStuPanel(sid);swSpTab('sp-hw');toast('휴지통으로 보냈어요');
  });
}
function clAddIndCmt(btn,chip){
  const row=btn.closest('.cl-stu-row');if(!row)return;
  const ta=row.querySelector('.cl-ind-cmt');if(!ta)return;
  ta.value=(ta.value?ta.value+' ':'')+chip;
}
async function clPreviewIndCmt(btn,stuName){
  const row=btn.closest('.cl-stu-row');if(!row)return;
  const ta=row.querySelector('.cl-ind-cmt');
  const preview=row.querySelector('.cl-preview-cmt');
  const status=row.querySelector('.cl-preview-status');
  const raw=ta?.value.trim();
  if(!raw){toast('코멘트를 먼저 입력하세요');return;}
  btn.disabled=true;if(status)status.textContent='변환 중...';
  try{
    // 저장 시와 동일한 입력으로 변환: 개별 코멘트 + 교재·원서 진도
    const cmt=raw;
    const mats={...getSMatsFrom('cl-subj-rows')};
    [...row.querySelectorAll('.cl-book-row')].forEach((br,i)=>{
      const t=br.querySelector('.cl-rd-title')?.value.trim();if(!t)return;
      mats[`_book_${i}`]={book:t,unit:br.querySelector('.cl-rd-prog')?.value.trim()||''};
    });
    const result=await polishCmt(cmt,_getMatsTextFromMaterials(mats));
    if(preview){
      preview.textContent=result;preview.style.display='block';
      // 선생님이 확인한 그 문장을 저장에 쓴다. 전에는 저장 때 AI 를 또 불러
      // 미리보기와 다른 글이 학부모에게 갔고 비용도 두 번 들었다.
      preview.dataset.cmt=result;
      preview.dataset.src=cmt;
    }
    if(status)status.textContent=`${result.length}자`;
  }catch(e){if(status)status.textContent='변환 실패';}
  finally{btn.disabled=false;}
}
// 원서 행 공용 HTML — 새 기록·원서 추가·수정 세 곳이 같은 구조(AR 미리채움 + 완독/진행중 칩)를 쓰도록 통일
function clBookRowHtml(v,withRemove){
  const IS='padding:6px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-family:var(--fb);font-size:13px;color:var(--navy);background:var(--cream);outline:none';
  v=v||{};
  return `<input type="text" class="cl-rd-title" placeholder="원서 제목" list="dl-library" autocomplete="off" value="${escAttr(v.book||'')}" onchange="clFillFromLib(this)" style="${IS};flex:2;min-width:120px">
    <input type="hidden" class="cl-rd-series" value="${escAttr(v.series||'')}">
    <input type="text" class="cl-rd-ar" placeholder="AR" value="${escAttr(v.ar||'')}" style="${IS};width:52px">
    <div style="flex:1;min-width:100px;display:flex;flex-direction:column;gap:3px">
      <div style="display:flex;gap:3px;flex-wrap:wrap">${_CL_PROG_CHIPS_HTML}</div>
      <input type="text" class="cl-rd-prog" placeholder="진도 (예: Ch.1~3)" value="${escAttr(v.unit||'')}" style="${IS};width:100%;box-sizing:border-box">
    </div>${withRemove?`<button onclick="this.closest('.cl-book-row').remove()" style="background:none;border:none;cursor:pointer;font-size:16px;color:var(--slate);padding:0;flex-shrink:0;margin-top:2px">×</button>`:''}`;
}
function addClBookRow(btn){
  const wrap=btn.previousElementSibling;if(!wrap||!wrap.classList.contains('cl-books-wrap'))return;
  const row=document.createElement('div');
  row.className='cl-book-row';
  row.style.cssText='display:flex;gap:6px;margin-bottom:4px;flex-wrap:wrap;align-items:flex-start';
  row.innerHTML=clBookRowHtml({},true);
  wrap.appendChild(row);
}
function clTogSubj(el){
  const s=el.dataset.s;
  if(clSubjs.has(s)){
    if(s==='naesin'){addSRowTo('cl-subj-rows',s);return;}
    clSubjs.delete(s);el.classList.remove('active');document.querySelectorAll('#cl-subj-rows .sr').forEach(r=>{if((r.dataset.s||'').replace(/_\d+$/,'')===s)r.remove();});
  }else{clSubjs.add(s);el.classList.add('active');addSRowTo('cl-subj-rows',s);}
}

// ── 자주 쓰는 교재 우선 정렬 — 수업 기록에서 최근 사용된 교재를 선택 목록 상단으로 ──
function _tbUsageMap(){
  const map={};
  (_cache.lessons||[]).forEach(l=>{Object.values(l.materials||{}).forEach(v=>{
    if(!v||!v.book)return;
    const key=_tbBase(v.book).trim().toLowerCase();
    if(!map[key]||String(l.date||'')>map[key])map[key]=String(l.date||'');
  });});
  return map;
}
function tbSortByUsage(books){
  const um=_tbUsageMap();
  return [...books].sort((a,b)=>{
    const ua=um[(a.title||'').trim().toLowerCase()]||'',ub=um[(b.title||'').trim().toLowerCase()]||'';
    if(ua!==ub)return ub.localeCompare(ua); // 최근 사용일이 늦을수록 앞으로
    return (a.title||'').localeCompare(b.title||'');
  });
}
// 과제 할당 대상 날짜: 수업 당일(당일에 내주는 과제) ~ 다음 수업 전날.
// 다음 수업 당일은 수업이 있으므로 과제 대상에서 제외
// 수업일부터 '다음 실제 수업일(휴강 제외)' 직전까지의 날짜 목록 — 과제 날짜 그룹의 뼈대.
// 휴강(skipDates)을 건너뛰므로 방학 중에도 다음 수업 때까지 전 기간 숙제를 낼 수 있다 (최대 30일).
function getClassLessonDates(classObj,fromDateStr){
  const DAYS=['일','월','화','수','목','금','토'];
  const classDays=classObj.days||[];
  const skip=new Set(classObj.skipDates||[]);
  const extra=new Set(classObj.extraDates||[]); // 추가 수업일 (특강 매일 수업 등)
  const dates=[fromDateStr];
  const d=new Date(fromDateStr+'T12:00:00');
  const max=classDays.length?30:7;
  for(let i=1;i<=max;i++){
    d.setDate(d.getDate()+1);
    const ds=_pgYmd(d);
    if((classDays.includes(DAYS[d.getDay()])||extra.has(ds))&&!skip.has(ds))break;
    dates.push(ds);
  }
  return dates;
}

const HW_CATS=[
  {v:'',l:'구분 선택'},
  {v:'phonics',l:'파닉스'},{v:'vocab',l:'어휘'},{v:'grammar',l:'어법'},
  {v:'reading',l:'리딩'},{v:'listening',l:'리스닝'},{v:'writing',l:'라이팅'},{v:'naesin',l:'내신'},
  {v:'book',l:'원서'},{v:'class5',l:'클래스5'},{v:'__custom__',l:'✏️ 직접 입력'}
];
const HW_CAT_SEL=HW_CATS.map(c=>`<option value="${c.v}">${c.l}</option>`).join('');
function fillClHwRowDl(rowEl){
  const cat=rowEl.querySelector('.cl-hw-cat')?.value||'';
  const dl=rowEl.querySelector('datalist:not([data-role="range"])');if(!dl)return;
  const tbooks=_cache.globalTextbooks||[];
  const allLib=[...(_cache.library||[])];
  const tbOpt=b=>`<option value="${escAttr(_tbVal(b))}">`; // 값에 레벨 포함 — 동명 교재 구분
  let opts='';
  if(cat==='class5'){
    opts=tbSortByUsage(tbooks).map(tbOpt).join(''); // 클래스5 자습도 교재 DB에서 선택
  }else if(cat==='book'){
    opts=[...new Set(allLib.map(b=>b.title).filter(Boolean))].map(t=>`<option value="${escAttr(t)}">`).join('');
  }else if(_CAT_KO[cat]){
    opts=tbSortByUsage(tbooks.filter(b=>b.category===_CAT_KO[cat])).map(tbOpt).join('');
  }else{
    opts=tbSortByUsage(tbooks).map(tbOpt).join('')+[...new Set(allLib.map(b=>b.title).filter(Boolean))].map(t=>`<option value="${escAttr(t)}">`).join('');
  }
  dl.innerHTML=opts;
}
function clHwCatChange(sel){
  const row=sel.closest('.cl-hw-row');if(!row)return;
  // 직접 입력 구분: 옆에 텍스트 입력 표시/숨김
  const custom=row.querySelector('.cl-hw-cat-custom');
  if(custom){custom.style.display=sel.value==='__custom__'?'':'none';if(sel.value==='__custom__')setTimeout(()=>custom.focus(),0);else custom.value='';}
  fillClHwRowDl(row);
  const cat=sel.value;
  const bookInput=row.querySelector('.cl-hw-book');
  if(cat&&bookInput&&!bookInput.value){
    // cl-subj-rows에서 당일 수업 내용 먼저 참조 (레벨 포함 표기로 채움)
    const subjRow=document.querySelector(`#cl-subj-rows .sr[data-s="${cat}"]`)||document.querySelector(`#cl-subj-rows .sr[data-s^="${cat}_"]`);
    if(subjRow){
      const bookEl=subjRow.querySelector('[data-f="book"]');
      if(bookEl&&bookEl.value){
        const bkId=bookEl.tagName==='SELECT'?(bookEl.options[bookEl.selectedIndex]?.dataset?.bkId||''):'';
        const tb=(_cache.globalTextbooks||[]).find(b=>bkId?b.id===bkId:b.title===bookEl.value);
        bookInput.value=tb?_tbVal(tb):bookEl.value;
      }
    }
    if(!bookInput.value){
      // fallback: 클래스 기본 교재 (bookId 우선 매칭 — 동명 교재 레벨 오표기 방지)
      const c=DB.classes().find(x=>x.id===document.getElementById('cl-class-id').value);
      if(c?.commonMaterials){
        const matched=Object.entries(c.commonMaterials).find(([k])=>k===cat||k.startsWith(cat+'_'));
        if(matched){
          const m=matched[1];
          const tb2=(_cache.globalTextbooks||[]).find(b=>m.bookId?b.id===m.bookId:b.title===m.book);
          bookInput.value=tb2?_tbVal(tb2):(m.book||'');
        }
      }
    }
  }
  clHwFillRangeDl(row); // 자동 채움 이후에 단원 datalist 갱신 (교재/원서/클래스5 공통)
}
// 수업에서 다룬 진도 전량을 복습 범위로 계산
// 직전 진도(prev)와 이번 진도(cur)가 같은 형식의 연속 숫자면 "Day 1-2"처럼 묶어서 반환
function clHwReviewRange(prev,cur){
  prev=(prev||'').trim();cur=(cur||'').trim();
  if(!cur)return prev;
  if(!prev)return cur;
  if(/[-~–]/.test(cur))return cur; // 이미 범위로 입력됨
  const curM=cur.match(/^(.*?)(\d+)\s*$/);
  const prevM=prev.match(/^(.*?)(\d+)\s*$/);
  if(!curM||!prevM)return cur;
  const curPrefix=curM[1].trim(),prevPrefix=prevM[1].trim();
  const curN=parseInt(curM[2]),prevN=parseInt(prevM[2]);
  if(curPrefix===prevPrefix&&prevN<curN)
    return (curPrefix?curPrefix+' ':'')+prevN+'-'+curN;
  return cur;
}
function clHwSetOpen(open){const b=document.getElementById('cl-hw-body'),h=document.getElementById('cl-hw-head'),l=document.getElementById('cl-hw-toggle-lbl');if(!b)return;b.style.display=open?'':'none';if(h)h.setAttribute('aria-expanded',String(open));if(l)l.textContent=open?'접기 ▴':'펼치기 ▾';} function clHwToggle(){const b=document.getElementById('cl-hw-body');if(b)clHwSetOpen(b.style.display==='none');} function clHwHasPending(){return [...document.querySelectorAll('#cl-hw-common-rows .cl-hw-row, #cl-hw-ind-rows .cl-hw-row')].some(row=>row.closest('.cl-hw-date-group')?.dataset.skip!=='true'&&['.cl-hw-book','.cl-hw-range','.cl-hw-note'].some(s=>(row.querySelector(s)?.value||'').trim()));} function clHwSyncFromSubj(){
  const classId=document.getElementById('cl-class-id').value;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const lessonDate=document.getElementById('cl-date')?.value||ppToday();
  const hwDates=getClassLessonDates(c,lessonDate);
  const mats=[];
  const _autoHwOn=!(c.autoHw===false); // 끔이면 교재 기반 자동 채움 없이 빈 행만 (반복·클래스5 표시는 유지)
  if(_autoHwOn)document.querySelectorAll('#cl-subj-rows .sr').forEach(row=>{
    const s=row.dataset.s;const baseKey=s.replace(/_\d+$/,'');
    const cat=baseKey==='_book'||baseKey.startsWith('_book')?'book':baseKey;
    const bookEl=row.querySelector('[data-f="book"]');
    const unitEl=row.querySelector('[data-f="unit"]');
    const unitTyped=(unitEl?.value||'').trim();
    // 진짜 힌트('직전: X')만 사용 — '단원 선택 또는 직접 입력' 같은 일반 placeholder가 범위로 새지 않게
    const ph=unitEl?.placeholder||'';
    const unitHint=ph.startsWith('직전: ')?ph.replace('직전: ','').trim():'';
    const unit=unitTyped||unitHint;
    const book=(bookEl?.value||'').trim();
    const bookId=bookEl?.tagName==='SELECT'?(bookEl.options[bookEl.selectedIndex]?.dataset?.bkId||''):'';
    const tb=(_cache.globalTextbooks||[]).find(b=>bookId?b.id===bookId:b.title===book);
    const bookDisplay=tb?.level?`${book} (${tb.level})`:book;
    const reviewRange=clHwReviewRange(unitHint,unitTyped);
    const range=cat==='book'?''
      :cat==='vocab'?(reviewRange?reviewRange+' 단어 암기, 워크북 풀기':'단어 암기, 워크북 풀기')
      :(reviewRange?reviewRange+' 복습, 워크북 풀기':'복습, 워크북 풀기');
    mats.push({cat,book:bookDisplay,range});
  });
  const container=document.getElementById('cl-hw-common-rows');
  container.innerHTML='';
  hwDates.forEach(d=>{
    const groupBody=clHwMakeDateGroup(d,container);
    if(mats.length){mats.forEach(m=>addClHwRow(d,true,m.cat,m.book,m.range,groupBody));}
    else{addClHwRow(d,true,'','','',groupBody);}
    // 이미 나가 있는 숙제(클래스5·반복 자동 + 단건 기할당)를 읽기전용으로 표시 — 같은 숙제 또 내는 것 방지
    const autos=_clAutoHwFor(classId,d,lessonDate);
    _clAppendAutoHwRows(groupBody,autos);
    if(!autos.sched.length)addClHwRow(d,true,'class5','','',groupBody); // 클래스5 자동이 없으면 기존처럼 빈 행 제공
  });
}
// 이 클래스 학생들에게 그 날짜에 이미 있는 숙제 (읽기전용 표시용 — 같은 숙제 또 내는 것 방지)
// sched: 스케줄형(클래스5·반복) 자동 할당 / singles: 숙제 캘린더·직접 할당 등으로 이미 나간 단건 과제(미완료)
// excludeLessonDate: 이 수업 기록 폼 자신이 만든 과제(classId+date 일치)는 편집 행으로 보이므로 제외
// 이 숙제는 '무슨 책을 읽었는지'를 적어야 기록이 되는가.
// 리딩앤 원서 읽기처럼 일정마다 책 제목이 비어 있는 숙제가 대상 — 지금은 24개 일정이 전부
// {book:'리딩앤', unit:'원서 읽기'}로 똑같아서 체크만 해도 아무 기록이 남지 않는다.
const _HW_BOOKISH=['리딩앤','원서','독서','reading&','readingand'];
function _hwAskTitle(a,sc){
  if(!a||!sc)return false;
  const hay=_hwKeyNorm([a.bookTitle,a.text,sc.book,sc.unit].filter(Boolean).join(' '));
  if(!_HW_BOOKISH.some(w=>hay.includes(_hwKeyNorm(w))))return false;
  // 일정 항목이 실제 책 제목을 담고 있으면 물을 필요가 없다
  return !sc.title;
}
// 읽은 책 입력의 자동완성 — 원서 목록(ortSeq 순)을 채운다. 등록된 216권에서 고르면 오타가 없다
function fillOrtBookDatalist(){
  const dl=document.getElementById('dl-ort-books');if(!dl)return;
  const ort=(_cache.library||[]).filter(b=>b&&b.title&&b.ortSeq!=null).sort((a,b)=>a.ortSeq-b.ortSeq);
  const rest=(_cache.library||[]).filter(b=>b&&b.title&&b.ortSeq==null).sort((a,b)=>String(a.title).localeCompare(String(b.title)));
  dl.innerHTML=[...ort,...rest].slice(0,600).map(b=>`<option value="${escAttr(b.title)}">`).join('');
}
function _clAutoHwFor(classId,ds,excludeLessonDate){
  const c=DB.classes().find(x=>x.id===classId);if(!c)return{sched:[],singles:[]};
  const sids=new Set(c.studentIds||[]);
  const sched=[],singles=[],seen=new Set(),seenS=new Set();
  (_cache.assignments||[]).forEach(a=>{
    if(a._deleted||!sids.has(a.sid))return;
    if((a.schedule||[]).length){
      if(a.category!=='class5'&&a.category!=='recur')return;
      const sch=_hwSchedOf(a);
      sch.forEach(s=>{
        // 연기로 이 날짜에 넘어온 칸도 올린다 (원래 그날 칸이 아니어도)
        const _dfHere=(s.hwStatus==='defer'&&s.hwDeferTo===ds);
        if(!_dfHere&&s.date!==ds)return;
        const label=a.category==='class5'?'🎮 클래스5':'🔁 '+(a.bookTitle||'반복 숙제');
        const txt=[s.book,s.unit].filter(Boolean).join(' · ')||a.bookTitle||'';
        const k=label+'|'+_hwKeyNorm(txt)+'|'+(_dfHere?('df'+(s.date||'')):'');
        // 리딩앤처럼 '무슨 책'이 비어 있는 숙제는 수업에서 물어 적을 수 있게 (s.title에 보관)
        if(!seen.has(k)){seen.add(k);sched.push({label,txt,aid:a.id,sid:a.sid,date:ds,sched:true,
          srcDate:s.date||ds,                    // 저장은 이 칸에 — 넘어온 줄은 원래 날짜 칸이다
          done:!!s.done,by:s.doneBy||s.hwBy||'',title:s.title||'',askTitle:_hwAskTitle(a,s),
          // 넘어온 줄은 '아직' 으로 보여 새로 확인받는다. '연기' 는 원래 그날 기록에 남는다
          status:_dfHere?'':((typeof ppHwStatusOf==='function')?ppHwStatusOf(a,s):''),
          statusLabel:_dfHere?'':((typeof ppHwStatusLabel==='function')?ppHwStatusLabel(a,s):''),
          pct:_dfHere?'':(s.hwPct||''),deferFrom:_dfHere?(s.date||''):''});}
      });
    }else{
      // 완료된 것도 목록에 남긴다 — 상태(완료/일부/연기)를 보고 되돌릴 수 있어야 한다
      // 연기로 이 날짜에 넘어온 것은 원래 날짜가 달라도 올린다 (전에는 아예 안 보였다)
      const _dfHere=(a.hwStatus==='defer'&&a.hwDeferTo===ds);
      if(!_dfHere&&(a.due||a.date)!==ds)return;
      if(excludeLessonDate&&a.classId===classId&&a.date===excludeLessonDate)return;
      const KC={phonics:'파닉스',vocab:'어휘',grammar:'어법',reading:'리딩',listening:'리스닝',writing:'라이팅',naesin:'내신',book:'원서',mission:'미션',worksheet:'워크시트'};
      const cat=KC[a.category]||a.category||'';
      const txt=[a.bookTitle||a.text||'',a.range].filter(Boolean).join(' · ')||'과제';
      const k=cat+'|'+_hwKeyNorm(txt)+'|'+(_dfHere?('df'+(a.due||a.date||'')):'');
      if(!seenS.has(k)){seenS.add(k);singles.push({label:'📕'+(cat?' ['+cat+']':''),txt,
        aid:a.id,sid:a.sid,date:ds,sched:false,done:!!a.completedAt,by:a.completedBy||'',
        srcDate:a.due||a.date||ds,
        status:_dfHere?'':((typeof ppHwStatusOf==='function')?ppHwStatusOf(a):''),
        statusLabel:_dfHere?'':((typeof ppHwStatusLabel==='function')?ppHwStatusLabel(a):''),
        pct:_dfHere?'':(a.hwPct||''),deferFrom:_dfHere?(a.due||a.date||''):''});}
    }
  });
  return {sched,singles};
}
// 날짜 그룹에 '이미 나가 있는 숙제' 읽기전용 행 추가 (공용)
// 이미 나가 있는 숙제를 '표시'만 하던 자리 — 수업 중에 바로 체크하고, 원서는 읽은 책까지 적는다.
// 학생이 매일 스스로 체크하길 기대하는 대신, 주 3회 수업에서 선생님이 확인하는 길을 연다
// (실측: 10월 체크율 클래스5 8% · 앱 단어 3% · 리딩앤 0%).
function _clAppendAutoHwRows(groupBody,autos){
  if(typeof fillOrtBookDatalist==='function')fillOrtBookDatalist();
  const row=(x,note,color)=>{
    const div=document.createElement('div');
    const st=x.status||'';
    div.className='cl-hw-chk'+(st==='done'?' on':'')+(st&&st!=='done'?' part':'');
    div.style.cssText=`--c:${color}`;
    div.dataset.aid=x.aid;div.dataset.date=x.date;div.dataset.sched=String(!!x.sched);
    div.dataset.src=x.srcDate||x.date;    // 두 줄(원래 줄·넘어온 줄)이 서로의 칸을 덮지 않게
    div.dataset.note=note;        // 되돌렸을 때 원래 안내로 돌아가기 위해 보관
    const by=st&&x.by?`<em>${_PG_HW_BY[x.by]||x.by}</em>`:'';
    const opt=(v,t)=>`<option value="${v}"${st===v?' selected':''}>${t}</option>`;
    // 체크 하나로는 '했다/안 했다' 밖에 못 적는다 — 일부·미지참·연기를 구분한다
    div.innerHTML=`<select class="cl-hw-st" title="숙제 상태"`
      +` onchange="clHwSetStatus(this,'${x.aid}','${x.date}',${!!x.sched},undefined,'${x.srcDate||x.date}')">`
      +opt('','아직')+opt('done','완료')+opt('part','일부')+opt('miss','미완')
      +opt('noshow','미지참')+opt('defer','연기')+`</select>`
      +`<input type="number" class="cl-hw-pct" min="1" max="99" placeholder="%"`
      +` value="${x.pct||''}" style="display:${st==='part'?'':'none'}"`
      +` onchange="clHwSetPct(this,'${x.aid}','${x.date}',${!!x.sched})">`
      +`<span class="cl-hw-t">${x.label} <b>${escAttr(x.txt)}</b>`
      +(x.deferFrom?` <span class="cl-hw-from">${escAttr(ppDowLabel(x.deferFrom))}에서 넘어옴</span>`:'')
      +(x.title?` <u>${escAttr(x.title)}</u>`:'')
      +`<span class="cl-hw-n" style="color:${color}">${x.statusLabel||note}</span>${by}</span>`
      +(st?`<button type="button" class="cl-hw-undo" title="미처리로 되돌리기"`
        +` onclick="clHwSetStatus(this.closest('.cl-hw-chk').querySelector('.cl-hw-st'),'${x.aid}','${x.date}',${!!x.sched},'','${x.srcDate||x.date}')">되돌리기</button>`:'')
      +(x.askTitle?`<input type="text" class="cl-hw-title" list="dl-ort-books" placeholder="읽은 책 (예: Floppy the Hero)"`
        +` value="${escAttr(x.title||'')}" onchange="clHwTitle(this,'${x.aid}','${x.date}')">`:'');
    groupBody.appendChild(div);
  };
  autos.sched.forEach(x=>row(x,'앱에 자동 할당됨 — 했으면 체크','var(--teal)'));
  autos.singles.forEach(x=>row(x,'이미 할당된 숙제 — 했으면 체크','var(--warnt)'));
}
// 숙제 상태 저장 (B6). 완료만 completedAt 을 채운다 — 일부·미지참·연기는 끝난 게 아니다.
// 연기는 다음 수업일을 hwDeferTo 에 적어 그날 확인 목록에 다시 올라오게 한다.
// src = 이 줄이 가리키는 칸의 날짜. 연기로 넘어온 줄은 ds(보고 있는 날)와 다르다 —
// src 없이 ds 로 찾으면 넘어온 줄이 그날의 다른 줄을 덮고, 원래 칸의 연기 표식도 안 풀린다.
async function clHwSetStatus(sel,aid,ds,sched,forced,src){
  const a=(_cache.assignments||[]).find(x=>x.id===aid);if(!a)return;
  const v=(forced!==undefined)?forced:String(sel.value||'');
  const o=sched?((a.schedule||[]).find(x=>x.date===(src||ds))||null):a;
  if(!o)return;
  const prev={hwStatus:o.hwStatus,hwPct:o.hwPct,hwDeferTo:o.hwDeferTo,
    completedAt:o.completedAt,completedBy:o.completedBy,done:o.done,doneBy:o.doneBy,doneAt:o.doneAt};
  // 표식 정리
  delete o.hwStatus;delete o.hwPct;delete o.hwDeferTo;
  if(sched){delete o.done;delete o.doneBy;delete o.doneAt;}
  else{delete o.completedAt;delete o.completedBy;}
  if(v){
    o.hwStatus=v;
    if(v==='done'){
      if(sched){o.done=true;o.doneBy='teacher';o.doneAt=new Date().toISOString();}
      else{o.completedAt=new Date().toISOString();o.completedBy='teacher';}
    }
    if(v==='part'){
      // 칸이 비어 있으면 50 을 쓰는데, 화면에도 같이 채워 넣는다
      // (전에는 빈 칸을 보여 주면서 50 을 저장해 '아직 안 정했다' 로 읽혔다)
      const pc=(sel.closest('.cl-hw-chk')||{}).querySelector?.('.cl-hw-pct');
      let n=parseInt(pc?pc.value:'',10);
      if(!(n>=1&&n<=99)){n=50;if(pc)pc.value=50;}
      o.hwPct=n;
    }
    if(v==='defer'){
      // 다음 수업일로 넘긴다 (클래스 요일 기준, 없으면 내일)
      const cid=document.getElementById('cl-class-id')?.value||'';
      const c=(DB.classes()||[]).find(x=>x.id===cid)||(DB.classes()||[]).find(x=>(x.studentIds||[]).includes(a.sid));
      const nd=c&&typeof _nextClassDay==='function'
        ?_nextClassDay(ds,c.days||[],new Set(c.skipDates||[]),new Set(c.extraDates||[])):'';
      o.hwDeferTo=nd||ppShiftDate(ds,1);
    }
  }
  try{await supaUpsert('assignments',a.id,a,a.sid);}
  catch(e){
    Object.assign(o,prev);                       // 저장 실패 시 되돌린다
    console.error('clHwSetStatus:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;
  }
  const wrap=sel.closest('.cl-hw-chk');
  if(wrap){
    if(sel.value!==v)sel.value=v;
    wrap.classList.toggle('on',v==='done');
    wrap.classList.toggle('part',!!v&&v!=='done');
    const pc=wrap.querySelector('.cl-hw-pct');if(pc)pc.style.display=(v==='part')?'':'none';
    const n=wrap.querySelector('.cl-hw-n');
    if(n)n.textContent=v?(ppHwStatusLabel(a,sched?o:null)||PP_HW_STATUS[v].name)
      :(wrap.dataset.note||'했으면 상태를 골라 주세요');
    let undo=wrap.querySelector('.cl-hw-undo');
    if(v&&!undo){
      undo=document.createElement('button');undo.type='button';undo.className='cl-hw-undo';
      undo.textContent='되돌리기';undo.title='미처리로 되돌리기';
      undo.onclick=()=>clHwSetStatus(sel,aid,ds,sched,'',src);
      wrap.appendChild(undo);
    }else if(!v&&undo)undo.remove();
  }
  toast(v==='defer'?('다음 수업('+(o.hwDeferTo||'')+')으로 넘겼어요')
    :(v?(PP_HW_STATUS[v].name+((typeof ppEuro==='function')?ppEuro(PP_HW_STATUS[v].name):'으로')+' 표시했어요')
        :'미처리로 되돌렸어요'));
}
async function clHwSetPct(inp,aid,ds,sched){
  const row=inp.closest('.cl-hw-chk');
  const sel=row?.querySelector('.cl-hw-st');
  if(sel)await clHwSetStatus(sel,aid,ds,sched,'part',row?.dataset.src||ds);
}
// 이 요일의 숙제를 전부 완료로 (B5) — 예외만 뒤에 바꾸면 된다
async function clHwAllDone(groupEl){
  const rows=[...groupEl.querySelectorAll('.cl-hw-chk')];
  if(!rows.length)return toast('확인할 숙제가 없어요');
  let n=0;
  for(const r of rows){
    const sel=r.querySelector('.cl-hw-st');
    if(!sel||sel.value==='done')continue;
    await clHwSetStatus(sel,r.dataset.aid,r.dataset.date,r.dataset.sched==='true','done',r.dataset.src||r.dataset.date);
    n++;
  }
  toast(n?(n+'건을 완료로 표시했어요 — 예외만 바꿔 주세요'):'이미 모두 완료예요');
}
// 수업 기록 폼에서 바로 완료 토글 (이전 방식 — 다른 곳에서 부를 수 있어 남겨 둔다)
async function clHwCheck(btn,aid,ds,sched){
  const a=(_cache.assignments||[]).find(x=>x.id===aid);if(!a)return;
  let on;
  if(sched){
    const sc=(a.schedule||[]).find(x=>x.date===ds);if(!sc)return;
    if(sc.done){delete sc.done;delete sc.doneBy;delete sc.doneAt;on=false;}
    else{sc.done=true;sc.doneBy='teacher';sc.doneAt=new Date().toISOString();on=true;}
  }else{
    if(a.completedAt){delete a.completedAt;delete a.completedBy;on=false;}
    else{a.completedAt=new Date().toISOString();a.completedBy='teacher';on=true;}
  }
  try{await supaUpsert('assignments',a.id,a,a.sid);}
  catch(e){console.error('clHwCheck:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  btn.textContent=on?'✓':'';
  const wrap=btn.closest('.cl-hw-chk');
  if(wrap){
    wrap.classList.toggle('on',on);
    const n=wrap.querySelector('.cl-hw-n');
    if(n&&on)n.textContent='확인 완료';
  }
  toast(on?'확인 완료로 표시했어요 ✓':'완료 표시를 취소했어요');
}
// 원서 숙제에 '읽은 책'을 적는다 — 체크만으론 아무 기록이 남지 않으므로
async function clHwTitle(inp,aid,ds){
  const a=(_cache.assignments||[]).find(x=>x.id===aid);if(!a)return;
  const sc=(a.schedule||[]).find(x=>x.date===ds);if(!sc)return;
  const t=(inp.value||'').trim();
  if(t)sc.title=t;else delete sc.title;
  try{await supaUpsert('assignments',a.id,a,a.sid);}
  catch(e){console.error('clHwTitle:',e);toast('저장 실패 — 네트워크를 확인해 주세요');return;}
  toast(t?`읽은 책: ${t}`:'읽은 책을 비웠어요');
}
function clHwMakeDateGroup(dateStr,parentEl){
  const DAYS=['일','월','화','수','목','금','토'];
  const d=new Date(dateStr);
  const dayLabel=DAYS[d.getDay()];
  const group=document.createElement('div');
  group.className='cl-hw-date-group';
  group.dataset.date=dateStr;
  group.style.cssText='margin-bottom:12px;border-radius:var(--rs);overflow:hidden;border:1.5px solid var(--navy)';
  const header=document.createElement('div');
  header.style.cssText='display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--navy);color:#fff';
  header.innerHTML=`<span style="font-size:16px;font-weight:700">${dayLabel}요일</span><span style="font-size:13px;opacity:.55;font-family:var(--fm)">${dateStr}</span><button type="button" onclick="clHwAddToGroup(this.closest('.cl-hw-date-group'))" class="cl-hw-add-btn" style="margin-left:auto;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;color:#fff;font-size:12px;padding:3px 10px;cursor:pointer;font-family:var(--fb);white-space:nowrap">+ 과제 추가</button><button type="button" onclick="clHwCopyGroupToOthers(this.closest('.cl-hw-date-group'))" class="cl-hw-copy-btn" title="이 요일의 과제 구성을 다른 모든 요일에 복사" style="background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;color:#fff;font-size:12px;padding:3px 10px;cursor:pointer;font-family:var(--fb);white-space:nowrap">⧉ 다른 요일에 복사</button><button type="button" onclick="clHwAllDone(this.closest('.cl-hw-date-group'))" class="cl-hw-alldone-btn" title="이 요일 숙제를 전부 완료로 — 예외만 뒤에 바꾸면 됩니다" style="background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.3);border-radius:20px;color:#fff;font-size:12px;padding:3px 10px;cursor:pointer;font-family:var(--fb);white-space:nowrap">✓ 모두 완료</button><button type="button" onclick="clHwToggleSkip(this.closest('.cl-hw-date-group'))" class="cl-hw-skip-btn" style="background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.25);border-radius:20px;color:rgba(255,255,255,.7);font-size:12px;padding:3px 10px;cursor:pointer;font-family:var(--fb);white-space:nowrap">생략</button>`;
  const body=document.createElement('div');
  body.className='cl-hw-group-body';
  body.style.cssText='display:flex;flex-direction:column;gap:6px;padding:8px 10px;background:var(--cream2)';
  group.appendChild(header);group.appendChild(body);
  if(parentEl)parentEl.appendChild(group);
  return body;
}
function clHwAddToGroup(groupEl){
  const dateStr=groupEl.dataset.date||'';
  const body=groupEl.querySelector('.cl-hw-group-body');
  addClHwRow(dateStr,true,'','','',body);
}
// '+ 공통 과제 추가' — 요일 그룹 구조를 유지한 채 추가 (그룹이 없으면 수업 요일 스캐폴드 생성)
function clHwAddCommonRow(){
  const container=document.getElementById('cl-hw-common-rows');if(!container)return;
  let groups=[...container.querySelectorAll('.cl-hw-date-group')];
  if(!groups.length){
    const classId=document.getElementById('cl-class-id')?.value;
    const c=DB.classes().find(x=>x.id===classId);
    const lessonDate=document.getElementById('cl-date')?.value||ppToday();
    (c?getClassLessonDates(c,lessonDate):[lessonDate]).forEach(d=>clHwMakeDateGroup(d,container));
    groups=[...container.querySelectorAll('.cl-hw-date-group')];
  }
  const g=groups.find(x=>x.dataset.skip!=='true')||groups[0];
  if(!g)return;
  clHwAddToGroup(g);
}
// 개별 과제: 학생을 먼저 고르고 그 아래 요일별 그룹으로 할당하는 학생 그룹 블록
function clHwAddStuGroup(sid){
  sid=sid||document.getElementById('cl-hw-stu-add')?.value||'';
  if(!sid){toast('학생을 먼저 선택해 주세요');return null;}
  const ind=document.getElementById('cl-hw-ind-rows');if(!ind)return null;
  const dup=ind.querySelector(`.cl-hw-stu-group[data-sid="${sid}"]`);
  if(dup){dup.scrollIntoView({block:'nearest'});toast('이미 추가된 학생이에요');return dup;}
  const s=DB.stus().find(x=>x.id===sid);
  const wrap=document.createElement('div');
  wrap.className='cl-hw-stu-group';wrap.dataset.sid=sid;
  wrap.style.cssText='margin-bottom:14px;border:1.5px solid rgba(15,48,74,.14);border-radius:12px;padding:10px 10px 4px;background:#fff';
  wrap.innerHTML=`<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
    <span class="badge bteal" style="font-size:13px;padding:4px 12px">${s?s.name:'?'}</span>
    <span style="font-size:12px;color:var(--slate)">이 학생에게만 배정되는 과제</span>
    <button type="button" class="btn bd bxxs" style="margin-left:auto" onclick="this.closest('.cl-hw-stu-group').remove()">학생 과제 삭제</button>
  </div><div class="cl-hw-stu-body"></div>`;
  ind.appendChild(wrap);
  // 공통 과제와 같은 요일 스캐폴드
  const body=wrap.querySelector('.cl-hw-stu-body');
  const classId=document.getElementById('cl-class-id')?.value;
  const c=DB.classes().find(x=>x.id===classId);
  const lessonDate=document.getElementById('cl-date')?.value||ppToday();
  (c?getClassLessonDates(c,lessonDate):[lessonDate]).forEach(d=>clHwMakeDateGroup(d,body));
  return wrap;
}
// 이 요일의 과제 구성을 다른 모든 요일 그룹에 복사 (대상 그룹의 기존 행은 대체)
function clHwCopyGroupToOthers(groupEl){
  const rows=[...groupEl.querySelectorAll('.cl-hw-row')].map(row=>({
    cat:row.querySelector('.cl-hw-cat')?.value||'',
    catCustom:row.querySelector('.cl-hw-cat-custom')?.value||'',
    book:row.querySelector('.cl-hw-book')?.value||'',
    range:row.querySelector('.cl-hw-range')?.value||'',
    note:row.querySelector('.cl-hw-note')?.value||''
  })).filter(r=>r.cat||r.book||r.range||r.note);
  if(!rows.length){toast('복사할 과제가 없습니다');return;}
  // 같은 컨테이너 안의 형제 요일 그룹으로만 복사 (공통 영역/학생별 영역 각각 독립), 생략된 요일 제외
  const others=[...(groupEl.parentElement?groupEl.parentElement.children:[])]
    .filter(x=>x.classList&&x.classList.contains('cl-hw-date-group')&&x!==groupEl&&x.dataset.skip!=='true');
  if(!others.length){toast('복사할 다른 요일이 없습니다 (생략된 요일 제외)');return;}
  askConfirm('다른 요일에 복사',`이 요일의 과제 ${rows.length}개 구성을 다른 ${others.length}개 요일에 복사할까요? 대상 요일의 기존 과제 행은 대체됩니다.`,'복사','bt',()=>{
    others.forEach(g=>{
      const body=g.querySelector('.cl-hw-group-body');if(!body)return;
      g.querySelectorAll('.cl-hw-row').forEach(r=>r.remove());
      const date=g.dataset.date||'';
      rows.forEach(r=>{
        addClHwRow(date,true,r.cat,r.book,r.range,body);
        const newRow=body.lastElementChild;if(!newRow)return;
        const noteEl=newRow.querySelector('.cl-hw-note');if(noteEl)noteEl.value=r.note;
        if(r.cat==='__custom__'){
          const cEl=newRow.querySelector('.cl-hw-cat-custom');
          if(cEl){cEl.style.display='';cEl.value=r.catCustom;}
        }
        clHwFillRangeDl(newRow);
      });
    });
    toast(`${others.length}개 요일에 복사했습니다 — 요일별로 범위만 조정하세요`);
  });
}
function clHwToggleSkip(groupEl){
  const skipped=groupEl.dataset.skip==='true';
  groupEl.dataset.skip=skipped?'false':'true';
  const nowSkipped=!skipped;
  const header=groupEl.querySelector('div');
  header.style.background=nowSkipped?'var(--slate)':'var(--navy)';
  const body=groupEl.querySelector('.cl-hw-group-body');
  body.style.display=nowSkipped?'none':'';
  const skipBtn=groupEl.querySelector('.cl-hw-skip-btn');
  skipBtn.style.background=nowSkipped?'#fff':'rgba(255,255,255,.1)';
  skipBtn.style.color=nowSkipped?'var(--navy)':'rgba(255,255,255,.7)';
  skipBtn.textContent=nowSkipped?'↩ 되돌리기':'생략';
  const addBtn=groupEl.querySelector('.cl-hw-add-btn');
  addBtn.style.display=nowSkipped?'none':'';
  const copyBtn=groupEl.querySelector('.cl-hw-copy-btn');
  if(copyBtn)copyBtn.style.display=nowSkipped?'none':'';
  // 생략 상태 안내 바 (되돌리기 가능함을 명확히 표시)
  let note=groupEl.querySelector('.cl-hw-skip-note');
  if(nowSkipped){
    if(!note){
      note=document.createElement('div');
      note.className='cl-hw-skip-note';
      note.style.cssText='padding:8px 14px;background:var(--cream2);color:var(--slate);font-size:13px;font-family:var(--fb);text-align:center';
      note.textContent='이 요일은 과제를 생략합니다 · 상단 [↩ 되돌리기]로 복구할 수 있어요';
      groupEl.appendChild(note);
    }
    note.style.display='';
  }else if(note){
    note.style.display='none';
  }
}
const IS='padding:6px 8px;border:1.5px solid var(--border);border-radius:var(--rs);font-family:var(--fb);font-size:13px;color:var(--navy);background:var(--cream);outline:none';

function addClHwRow(dateStr,isCommon,prefillCat='',prefillBook='',prefillRange='',targetEl=null){
  const DAYS=['일','월','화','수','목','금','토'];
  const d=dateStr?new Date(dateStr):new Date();
  const dayLabel=DAYS[d.getDay()];
  const stuOpts=isCommon?'':('<option value="">학생 선택</option>'+
    DB.stus().filter(s=>!s.inactive&&(()=>{const c=DB.classes().find(x=>x.id===document.getElementById('cl-class-id').value);return c?(c.studentIds||[]).includes(s.id):true;})())
    .map(s=>`<option value="${s.id}">${s.name}</option>`).join(''));
  const row=document.createElement('div');
  row.className='cl-hw-row';
  const rowDlId='dl-hwr-'+Math.random().toString(36).slice(2,8);
  if(targetEl){
    // 컴팩트 1줄 모드 (날짜 그룹 내부)
    row.style.cssText='display:flex;align-items:center;gap:6px;background:#fff;border-radius:var(--rs);padding:6px 8px;border:1px solid var(--border)';
    row.innerHTML=`<input type="hidden" class="cl-hw-date" value="${dateStr||''}">
      ${!isCommon?`<select class="cl-hw-ind-stu filter-sel" style="flex:0 0 auto;${IS}">${stuOpts}</select>`:''}
      <datalist id="${rowDlId}"></datalist>
      <datalist id="${rowDlId}-r" data-role="range"></datalist>
      <select class="cl-hw-cat filter-sel" style="flex:0 0 100px;${IS}" onchange="clHwCatChange(this)">${HW_CAT_SEL}</select>
      <input type="text" class="cl-hw-cat-custom" placeholder="구분 입력" style="display:none;flex:0 0 90px;${IS}">
      <input type="text" class="cl-hw-book" placeholder="교재" list="${rowDlId}" autocomplete="off" onchange="clHwBookChange(this)" style="flex:2;min-width:80px;${IS}">
      <input type="text" class="cl-hw-range" placeholder="범위/내용" list="${rowDlId}-r" autocomplete="off" style="flex:2;min-width:80px;${IS}">
      <input type="text" class="cl-hw-note" placeholder="자유 메모" style="flex:2;min-width:80px;${IS}">
      <button type="button" onclick="this.closest('.cl-hw-row').remove()" style="background:none;border:none;cursor:pointer;font-size:17px;color:var(--slate);padding:0 2px;flex-shrink:0">×</button>`;
    if(prefillCat){const catEl=row.querySelector('.cl-hw-cat');if(catEl){catEl.value=prefillCat;fillClHwRowDl(row);}}
    if(prefillBook){const bookEl=row.querySelector('.cl-hw-book');if(bookEl)bookEl.value=prefillBook;}
    if(prefillRange){const rangeEl=row.querySelector('.cl-hw-range');if(rangeEl)rangeEl.value=prefillRange;}
    clHwFillRangeDl(row); // 프리필된 책의 단원 datalist 즉시 제공
    targetEl.appendChild(row);
  }else{
    // 기존 2줄 모드 (개별 추가 시)
    row.style.cssText='background:var(--cream);border-radius:var(--rs);padding:8px 10px;margin-bottom:6px;border:1px solid var(--border)';
    row.innerHTML=`<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap">
      ${!isCommon?`<select class="cl-hw-ind-stu filter-sel" style="flex:0 0 auto">${stuOpts}</select>`:''}
      <input type="date" class="cl-hw-date" value="${dateStr||''}" style="${IS};flex:0 0 auto">
      <span class="cl-hw-day-label" style="font-size:12px;color:var(--slate)">${dateStr?dayLabel+'요일':''}</span>
      <select class="cl-hw-cat filter-sel" style="flex:0 0 auto" onchange="clHwCatChange(this)">${HW_CAT_SEL}</select>
      <input type="text" class="cl-hw-cat-custom filter-sel" placeholder="구분 입력" style="display:none;flex:0 0 100px">
      <button onclick="this.closest('.cl-hw-row').remove()" style="background:none;border:none;cursor:pointer;font-size:18px;color:var(--slate);padding:0;margin-left:auto">×</button>
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap">
      <datalist id="${rowDlId}"></datalist>
      <datalist id="${rowDlId}-r" data-role="range"></datalist>
      <input type="text" class="cl-hw-book" placeholder="교재 선택 또는 직접 입력" list="${rowDlId}" autocomplete="off" onchange="clHwBookChange(this)" style="${IS};flex:2;min-width:130px">
      <input type="text" class="cl-hw-range" placeholder="범위/내용" list="${rowDlId}-r" autocomplete="off" style="${IS};flex:2;min-width:120px">
      <input type="text" class="cl-hw-note" placeholder="자유 메모 (선택)" style="${IS};flex:2;min-width:120px">
    </div>`;
    if(prefillCat){const catEl=row.querySelector('.cl-hw-cat');if(catEl){catEl.value=prefillCat;fillClHwRowDl(row);}}
    if(prefillBook){const bookEl=row.querySelector('.cl-hw-book');if(bookEl)bookEl.value=prefillBook;}
    if(prefillRange){const rangeEl=row.querySelector('.cl-hw-range');if(rangeEl)rangeEl.value=prefillRange;}
    clHwFillRangeDl(row); // 프리필된 책의 단원 datalist 즉시 제공
    row.querySelector('.cl-hw-date').addEventListener('change',function(){
      const nd=new Date(this.value);
      row.querySelector('.cl-hw-day-label').textContent=this.value?DAYS[nd.getDay()]+'요일':'';
    });
    const target=isCommon?document.getElementById('cl-hw-common-rows'):document.getElementById('cl-hw-ind-rows');
    if(target)target.appendChild(row);
  }
}

async function saveClassLesson(){
  if(typeof clClearDirty==='function')setTimeout(clClearDirty,0);
  const classId=document.getElementById('cl-class-id').value;
  const c=DB.classes().find(x=>x.id===classId);if(!c)return;
  const date=document.getElementById('cl-date').value;
  if(!date){toast('날짜를 선택하세요');return;}
  if(date>ppToday()){toast('미래 날짜예요 — 수업 계획은 진도 캘린더의 점선(예정)으로 관리하고, 기록은 수업 당일부터 저장해 주세요');return;}
  const commonMats=getSMatsFrom('cl-subj-rows');
  const stuRows=document.querySelectorAll('.cl-stu-row');
  if(!stuRows.length){toast('학생이 없습니다');return;}
  const stuData=[];
  stuRows.forEach(row=>{
    const sid=row.dataset.sid;const s=DB.stus().find(x=>x.id===sid);
    const books=[...row.querySelectorAll('.cl-book-row')].map(br=>({
      title:br.querySelector('.cl-rd-title')?.value.trim()||'',
      series:br.querySelector('.cl-rd-series')?.value.trim()||'',
      ar:br.querySelector('.cl-rd-ar')?.value.trim()||'',
      prog:br.querySelector('.cl-rd-prog')?.value.trim()||''
    })).filter(b=>b.title);
    const _pvEl=row.querySelector('.cl-preview-cmt');
    stuData.push({sid,grade:s?.grade||s?.lv||'',att:row.querySelector('.cl-att').value,books,
      indCmt:row.querySelector('.cl-ind-cmt')?.value.trim()||'',
      previewCmt:_pvEl?.dataset?.cmt||'',previewSrc:_pvEl?.dataset?.src||''});
  });
  // 과제 rows 수집
  const collectHwRows=sel=>[...document.querySelectorAll(sel)]
    .filter(row=>row.closest('.cl-hw-date-group')?.dataset.skip!=='true')
    .map(row=>{
      let cat=row.querySelector('.cl-hw-cat')?.value||'';
      if(cat==='__custom__')cat=row.querySelector('.cl-hw-cat-custom')?.value.trim()||''; // 직접 입력 구분
      const book=row.querySelector('.cl-hw-book')?.value.trim()||'';
      const range=row.querySelector('.cl-hw-range')?.value.trim()||'';
      const note=row.querySelector('.cl-hw-note')?.value.trim()||'';
      // 클래스5 행을 비워두면 과제 미생성 (일반 '클래스5' 과제는 더 이상 만들지 않음)
      return{
        // 행 자체의 학생 select → 없으면 학생 그룹(개별 과제 새 구조)의 sid
        sid:row.querySelector('.cl-hw-ind-stu')?.value||row.closest('.cl-hw-stu-group')?.dataset.sid||null,
        due:row.querySelector('.cl-hw-date')?.value||date,
        cat,book,range,note
      };
    }).filter(r=>r.book||r.range||r.note);
  // 과제 칸은 '이번 수업 ~ 다음 수업 전날' 을 하루씩 묶음으로 보여 준다(getClassLessonDates).
  // 묶음마다 같은 교재 줄이 자동으로 채워지므로, 월·수·금 반의 금요일 수업은 같은 숙제가
  // 금·토·일 3건으로 저장됐다. 학생은 같은 숙제를 세 번 보고, 완료율은 1/3 이 됐다.
  // 내용이 똑같은 줄은 한 건으로 합치고 마감만 가장 늦은 날(= 다음 수업 전날)로 둔다.
  // 선생님이 날짜별로 내용을 다르게 적었으면 그대로 날짜별로 나간다.
  const _mergeSameHw=(rows)=>{
    const by=new Map();
    rows.forEach(r=>{
      const k=[r.sid||'',r.cat||'',(r.book||'').trim(),(r.range||'').trim(),(r.note||'').trim()].join('|');
      const prev=by.get(k);
      if(!prev){by.set(k,{...r});return;}
      if((r.due||'')>(prev.due||''))prev.due=r.due;   // 마감은 가장 늦은 날로
    });
    return [...by.values()];
  };
  const commonHws=_mergeSameHw(collectHwRows('#cl-hw-common-rows .cl-hw-row'));
  const indHws=_mergeSameHw(collectHwRows('#cl-hw-ind-rows .cl-hw-row').filter(r=>r.sid));
  const btn=document.getElementById('cl-save-btn');btn.disabled=true;
  toast('저장 중...');
  const editMode=document.getElementById('cl-class-id').dataset.editMode==='true';
  try{
    // 수정 모드: 화면에서 사라진 기존 과제는 삭제 (내용 동일한 과제는 유지 — 완료 상태 보존)
    if(editMode){
      const desired=new Set();
      const hwKey=(sid,hw)=>[sid,hw.due||date,hw.cat||'',_tbBase(hw.book||''),hw.range||'',hw.note||''].join('');
      const activeSids=stuData.filter(d=>d.att!=='absent').map(d=>d.sid);
      commonHws.forEach(hw=>activeSids.forEach(sid=>desired.add(hwKey(sid,hw))));
      indHws.forEach(hw=>desired.add(hwKey(hw.sid,hw)));
      // 정리 대상은 '이 수업 폼이 만든 과제'만: 단건 reading/textbook.
      // 스케줄형(반복·클래스5 — date가 우연히 수업일과 같을 수 있음)·미션·워크시트는 절대 건드리지 않음
      // ('앱으로 단어 20개' 반복 숙제가 date=수업일이라 수정 저장 때 통째로 삭제되던 사고 방지)
      const olds=ppLive(_cache.assignments).filter(a=>a.classId===classId&&a.date===date
        &&!(a.schedule||[]).length&&['reading','textbook'].includes(a.type||''));
      for(const a of olds){
        const key=[a.sid,a.due||date,a.category||'',_tbBase(a.bookTitle||''),a.range||'',a.note||''].join('');
        if(!desired.has(key)){
          await supaTrash('assignments',_cache.assignments,a.id).catch(()=>{}); // 휴지통 (복원 가능)
          _cache.assignments=(_cache.assignments||[]).filter(x=>x.id!==a.id);
        }
      }
    }
    for(const d of stuData){
      const cmt=d.indCmt||'';
      // 수정 모드: 기존 수업 레코드의 id를 재사용해 갱신 (중복 생성 방지)
      const existing=editMode?(_cache.lessons||[]).find(l=>l.classId===classId&&l.date===date&&l.sid===d.sid):null;
      const _newMats={...commonMats};
      (d.books||[]).forEach((b,i)=>{_newMats[`_book_${i}`]={book:b.title,unit:b.prog||''};});
      // 수정 저장이면 기존 키·필드(원서 ar 등)를 지킨다
      const mats=existing?_mergeMatsKeepKeys(existing.materials,_newMats):_newMats;
      // 학부모 코멘트: 원문이 그대로면 기존 변환문 재사용 (AI 재호출·문구 변동 방지)
      const _mt=_getMatsTextFromMaterials(mats);
      // 선생님이 코멘트를 쓴 경우에만 AI 를 부른다.
      // 전에는 코멘트가 비어도 교재만 있으면 AI 가 문장을 지어 polishedCmt 를 채웠다.
      // 쓰지 않았으면 기존 값을 그대로 두고, 없으면 빈 채로 둔다 (덮어쓰지 않는다).
      // ① 선생님이 [학부모용 미리보기] 로 확인한 문장이 있고 원문이 그대로면 그 문장을 쓴다
      // ② 아니면 기존 변환문 ③ 그것도 없으면 그때 AI 를 부른다
      const _pv=d.previewCmt&&d.previewSrc===cmt?d.previewCmt:'';
      const polishedCmt=_pv
        ? _pv
        : ((existing&&existing.cmt===cmt&&existing.polishedCmt)
          ? existing.polishedCmt
          : (String(cmt||'').trim() ? await polishCmt(cmt,_mt) : (existing?(existing.polishedCmt||''):'')));
      // 결석·병결·휴강·선생님취소 학생에게는 그날 공통 진도를 남기지 않는다.
      // 남기면 교재 여정이 올라가고, 단어장에 안 배운 단어가 들어가고,
      // 학부모 화면에 '최근 수업 · Unit 1' 로 보인다 (2026-11-06 점검).
      const _away=(typeof ppAttAway==='function')&&ppAttAway(d.att);
      const matsForStu=_away?{}:mats;
      // 학생 응원 문구(stuCmt)도 여기서 만들어 둔다 — 학생 화면은 읽기만 한다 (2026-11-08).
      // 전에는 학생이 열 때마다 AI 를 부르고 lessons 에 저장하려 했는데, 학생은 lessons 를
      // 쓸 수 없어 저장이 실패하고 매번 새 문장이 나왔다(비용).
      const _stuName=(DB.stus().find(x=>x.id===d.sid)||{}).name||'';
      const stuCmt=(existing&&existing.cmt===cmt&&existing.stuCmt)
        ? existing.stuCmt
        : (String(cmt||'').trim()&&!_away ? (await polishStuCmt_teacher(cmt,_mt,_stuName)||'') : (existing?(existing.stuCmt||''):''));
      const les={id:existing?existing.id:uid(),sid:d.sid,date,grade:d.grade,att:d.att,materials:matsForStu,cmt,polishedCmt,classId,...(stuCmt?{stuCmt}:{})};
      await supaUpsert('lessons',les.id,les,d.sid);
      if(existing){const li=_cache.lessons.findIndex(l=>l.id===existing.id);if(li>=0)_cache.lessons[li]=les;else _cache.lessons.unshift(les);}
      else _cache.lessons.unshift(les);
      if(!_away)addUnitWordsToVocab(d.sid,les.materials,date).catch(()=>{});   // 결석이면 단어장 자동 추가도 안 한다
      // 수정 모드: 이 수업분 기존 원서 기록을 지우고 현재 행으로 재생성
      if(editMode){
        const oldRds=(_cache.readings||[]).filter(r=>r.classId===classId&&r.date===date&&r.sid===d.sid);
        for(const o of oldRds)await supaDelete('readings',o.id).catch(()=>{});
        _cache.readings=(_cache.readings||[]).filter(r=>!(r.classId===classId&&r.date===date&&r.sid===d.sid));
      }
      for(const b of (d.books||[])){
        const rd={id:uid(),sid:d.sid,date,title:b.title,series:b.series,arLevel:b.ar,genre:'',progress:b.prog,classId};
        await supaUpsert('readings',rd.id,rd,d.sid);_cache.readings.unshift(rd);
        // 완독 → 완료 원서 리스트
        if((b.prog||'').trim()==='완독')
          await syncCompletedReadingToTextbooks(d.sid,b.title,date).catch(()=>{});
      }
      // 클래스 공통 교재 → 학생 개별 교재 동기화
      await syncClassTbsToStudent(d.sid).catch(()=>{});
      // 공통 과제 → 결석 제외. 수정 모드에서는 원래 이 수업의 구성원(당시 수업 기록 보유)에게만 적용 —
      // 수업 이후 반에 합류한 학생에게 지난 숙제가 백필되지 않게
      if(d.att!=='absent'&&(!editMode||existing)){
        for(const hw of commonHws){
          // 클래스5·반복 스케줄이 이 책·단원을 그날 이미 자동 할당했으면 단건으로 또 만들지 않음
          if(schedCoversHw(d.sid,hw.due||date,hw.book,hw.range))continue;
          const dup=(_cache.assignments||[]).find(x=>x.sid===d.sid&&_tbBase(x.bookTitle||'')===_tbBase(hw.book||'')&&(x.range||'')===(hw.range||'')&&x.category===hw.cat&&x.date===date&&(x.due||'')===(hw.due||'')&&(x.note||'')===(hw.note||''));
          if(dup){
            // 개별→공통으로 옮겨진 경우 출처 표식 동기화 (완료 상태 보존)
            if(dup.common!==true){dup.common=true;await supaUpsert('assignments',dup.id,dup,dup.sid).catch(()=>{});}
            continue;
          }
          const allLib=[...(_cache.library||[])];
          const isReading=allLib.some(b=>b.title===hw.book);
          const a={id:uid(),sid:d.sid,date,due:hw.due,classId,category:hw.cat,
            type:isReading?'reading':'textbook',bookTitle:hw.book,range:hw.range,note:hw.note||'',common:true};
          await supaUpsert('assignments',a.id,a,d.sid);_cache.assignments.unshift(a);
        }
      }
    }
    // 개별 과제
    for(const hw of indHws){
      if(schedCoversHw(hw.sid,hw.due||date,hw.book,hw.range))continue; // 스케줄이 이미 커버 → 중복 생성 방지
      const dup=(_cache.assignments||[]).find(x=>x.sid===hw.sid&&_tbBase(x.bookTitle||'')===_tbBase(hw.book||'')&&(x.range||'')===(hw.range||'')&&x.category===hw.cat&&x.date===date&&(x.due||'')===(hw.due||'')&&(x.note||'')===(hw.note||''));
      if(dup){
        // 공통→개별로 옮겨진 경우 출처 표식 동기화
        if(dup.common!==false){dup.common=false;await supaUpsert('assignments',dup.id,dup,dup.sid).catch(()=>{});}
        continue;
      }
      const allLib=[...(_cache.library||[])];
      const isReading=allLib.some(b=>b.title===hw.book);
      const a={id:uid(),sid:hw.sid,date,due:hw.due,classId,category:hw.cat,
        type:isReading?'reading':'textbook',bookTitle:hw.book,range:hw.range,note:hw.note||'',common:false};
      await supaUpsert('assignments',a.id,a,hw.sid);_cache.assignments.unshift(a);
    }
    closeClsRecord();
    renderLes();renderRd();renderDash();renderClassTab();
    renderClsLessons(classId); // 열려 있는 상세의 기록 목록·진도 캘린더 즉시 갱신
    toast(stuData.length+'명 수업 기록 완료');
    // 저장 직후 학부모 알림 (결석 제외)
    openNotifyParents(stuData.filter(d=>d.att!=='absent').map(d=>d.sid));
  }catch(e){
    console.error('saveClassLesson:',e);toast('저장 중 오류가 발생했습니다');
  }finally{
    btn.disabled=false;showLoading(false);
  }
}

// ── 전역 검색 (Ctrl+K) — 학생·클래스·교재·원서를 한 번에 찾아 바로 이동 ──
let _gsIdx=0,_gsItems=[];
function openGlobalSearch(){
  openM('m-gsearch');
  const q=document.getElementById('gs-q');
  if(q){q.value='';gsRender();setTimeout(()=>q.focus(),60);}
}
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&(e.key==='k'||e.key==='K')){
    if(!document.getElementById('s-teacher')?.classList.contains('active'))return;
    e.preventDefault();
    const m=document.getElementById('m-gsearch');
    if(m&&m.classList.contains('open'))closeM('m-gsearch');else openGlobalSearch();
  }
});
function gsKey(e){
  if(e.key==='Escape'){closeM('m-gsearch');return;}
  if(e.key==='ArrowDown'){e.preventDefault();_gsIdx=Math.min(_gsIdx+1,_gsItems.length-1);gsPaint();}
  else if(e.key==='ArrowUp'){e.preventDefault();_gsIdx=Math.max(_gsIdx-1,0);gsPaint();}
  else if(e.key==='Enter'){e.preventDefault();gsGo(_gsIdx);}
}
function gsRender(){
  const q=(document.getElementById('gs-q')?.value||'').trim().toLowerCase();
  _gsItems=[];_gsIdx=0;
  const N=s=>String(s||'').toLowerCase();
  const push=(icon,label,sub,run)=>_gsItems.push({icon,label,sub,run});
  if(q){
    DB.stus().filter(s=>!s.inactive&&(N(s.name).includes(q)||N(s.school).includes(q))).slice(0,6)
      .forEach(s=>push('🧑‍🎓',s.name,[s.grade||s.lv,s.school].filter(Boolean).join(' · ')||'학생',()=>openStuPanelTab(s.id,'sp-summary')));
    DB.classes().filter(c=>c.active!==false&&N(c.name).includes(q)).slice(0,4)
      .forEach(c=>push('👥',c.name,(typeof classSchedStr==='function'?classSchedStr(c):'')||'클래스',()=>{swTab('t-class');setTimeout(()=>openClsDetail(c.id),200);}));
    (_cache.globalTextbooks||[]).filter(b=>N(b.title).includes(q)).slice(0,6)
      .forEach(b=>push('📚',b.title+(b.level?` (${b.level})`:''),b.category||'교재',()=>openTbookUnits(b.id)));
    (_cache.library||[]).filter(b=>N(b.title).includes(q)||N(b.series).includes(q)).slice(0,6)
      .forEach(b=>push('📖',b.title,[(b.series||'원서'),(b.arLevel||b.ar)?'AR '+(b.arLevel||b.ar):''].filter(Boolean).join(' · '),()=>openEditLib(b.id)));
    push('📝',`어휘 DB에서 "${q}" 검색`,'단어·뜻·출처 전체에서 찾기',()=>{
      swTab('t-data');switchDataTab('word');
      setTimeout(()=>{const i=document.getElementById('wdb-q');if(i){i.value=q;wdbPage=0;renderWordDB();}},150);
    });
  }
  gsPaint();
}
function gsPaint(){
  const el=document.getElementById('gs-results');if(!el)return;
  if(!_gsItems.length){
    el.innerHTML='<div style="padding:20px;text-align:center;color:var(--slate);font-size:13px">학생·클래스·교재·원서 이름을 입력하세요<br><span style="font-size:12px">↑↓ 이동 · Enter 열기 · Esc 닫기</span></div>';
    return;
  }
  el.innerHTML=_gsItems.map((it,i)=>`<div class="gs-item${i===_gsIdx?' on':''}" onmouseenter="if(_gsIdx!==${i}){_gsIdx=${i};gsPaint();}" onclick="gsGo(${i})">
    <span style="font-size:16px;flex-shrink:0">${it.icon}</span>
    <div style="flex:1;min-width:0">
      <div style="font-size:14px;font-weight:600;color:var(--navy);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escAttr(it.label)}</div>
      <div style="font-size:12px;color:var(--slate);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escAttr(it.sub||'')}</div>
    </div>
    ${i===_gsIdx?'<span style="font-size:11.5px;color:var(--teal);flex-shrink:0">Enter ⏎</span>':''}
  </div>`).join('');
  el.querySelector('.gs-item.on')?.scrollIntoView({block:'nearest'});
}
function gsGo(i){
  const it=_gsItems[i];if(!it)return;
  closeM('m-gsearch');
  try{it.run();}catch(e){console.warn('gsGo:',e);}
}

// ── 수업 저장 후 학부모 알림 배치 모달 ──
function openNotifyParents(sids){
  const list=document.getElementById('np-list');if(!list||!sids?.length)return;
  const rows=sids.map(sid=>DB.stus().find(s=>s.id===sid)).filter(Boolean);
  if(!rows.length)return;
  list.innerHTML=rows.map(s=>`<div style="display:flex;align-items:center;gap:8px;padding:7px 4px;border-bottom:1px solid var(--border)">
    <div style="flex:1;min-width:0">
      <div style="font-size:14px;font-weight:600;color:var(--navy)">${escAttr(s.name)}</div>
      <div style="font-size:12px;color:var(--slate)">${s.parentPhone?'📱 '+escAttr(s.parentPhone):'학부모 연락처 미등록 — 문구만 복사됩니다'}</div>
    </div>
    <button class="btn bt bsm" style="flex-shrink:0" onclick="shareParentUpdateByStu('${s.id}');this.textContent='보냄 ✓';this.disabled=true">${luIcon('megaphone',15)||''} 카카오</button>
  </div>`).join('');
  openM('m-notify-parents');
}

// ── 휴지통 — _deleted 표식 행 조회·복원·영구 삭제 (30일 자동 정리) ──
const TRASH_TABLES=[['students','학생'],['lessons','수업 기록'],['tests','테스트'],['readings','원서 기록'],['logs','리딩로그'],['global_textbooks','책'],['monthly_reports','월간 리포트'],['vocab_cards','단어카드'],['textbooks','학생 교재'],['counsels','상담 기록']];
let _trashItems=[];
async function openTrash(){
  openM('m-trash');
  const el=document.getElementById('trash-list');
  if(el)el.innerHTML='<div style="padding:20px;text-align:center;color:var(--slate);font-size:13px">불러오는 중...</div>';
  _trashItems=[];
  for(const [t,label] of TRASH_TABLES){
    try{
      const r=await fetch(`${SUPA_URL}/rest/v1/${t}?select=id,data&data-%3E%3E_deleted=eq.true`,{headers:SUPA_HEADERS});
      if(!r.ok)continue;
      (await r.json()).forEach(row=>{
        const d=row.data||{};
        if(d._deletedWith)return; // 학생 삭제에 딸린 기록은 학생 항목 하나로 묶어 표시
        _trashItems.push({table:t,label,id:row.id,data:d});
      });
    }catch(e){}
  }
  _trashItems.sort((a,b)=>String(b.data._deletedAt||'').localeCompare(String(a.data._deletedAt||'')));
  renderTrash();
}
function _trashLabel(e){
  const d=e.data;
  const stu=sid=>DB.stus().find(s=>s.id===sid)?.name||'';
  if(e.table==='students')return `${d.name||'학생'} (수업·테스트·기록 포함)`;
  if(e.table==='lessons')return `${stu(d.sid)} 수업 ${d.date||''}`.trim();
  if(e.table==='tests')return `${stu(d.sid)} 테스트 ${d.date||''}`.trim();
  if(e.table==='readings')return `${stu(d.sid)} 원서 ${d.title||''}`.trim();
  if(e.table==='logs')return `${stu(d.sid)} 리딩로그 ${d.date||''}`.trim();
  if(e.table==='global_textbooks')return `${d.type==='library'?'원서':d.type==='class5'?'클래스5':'교재'} — ${d.title||''}`;
  if(e.table==='monthly_reports')return `${stu(d.sid)} ${String(d.month||'').replace('-','년 ')}월 리포트`.trim();
  if(e.table==='vocab_cards')return `${stu(d.sid)} 단어카드 ${d.word||''}`.trim();
  if(e.table==='textbooks')return `${stu(d.sid)} 교재 ${d.title||d.book||''}`.trim();
  if(e.table==='counsels')return `${stu(d.sid)} 상담 ${d.date||''}`.trim();
  return e.id;
}
function renderTrash(){
  const el=document.getElementById('trash-list');if(!el)return;
  if(!_trashItems.length){el.innerHTML='<div style="padding:24px;text-align:center;color:var(--slate);font-size:13px">휴지통이 비어 있습니다</div>';return;}
  el.innerHTML=_trashItems.map((e,i)=>`<div style="display:flex;align-items:center;gap:8px;padding:8px 4px;border-bottom:1px solid var(--border)">
    <div style="flex:1;min-width:0">
      <div style="font-size:14px;font-weight:600;color:var(--navy);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escAttr(_trashLabel(e))}</div>
      <div style="font-size:12px;color:var(--slate)">${e.label} · 삭제일 ${String(e.data._deletedAt||'').slice(0,10)}</div>
    </div>
    <button class="btn bt bsm" style="flex-shrink:0" onclick="restoreTrash(${i})">복원</button>
    <button class="btn bd bsm" style="flex-shrink:0" onclick="purgeTrash(${i})">영구 삭제</button>
  </div>`).join('');
}
async function restoreTrash(i){
  const e=_trashItems[i];if(!e)return;
  toast('복원 중...');
  const clean=o=>{const d={...o};delete d._deleted;delete d._deletedAt;delete d._deletedWith;return d;};
  try{
    await supaUpsert(e.table,e.id,clean(e.data),e.data.sid||null);
    if(e.table==='students'){
      // 함께 묶여 삭제된 연관 기록도 복원
      for(const [t] of TRASH_TABLES){
        if(t==='students'||t==='global_textbooks')continue;
        const r=await fetch(`${SUPA_URL}/rest/v1/${t}?select=id,data&data-%3E%3E_deletedWith=eq.${encodeURIComponent(e.id)}`,{headers:SUPA_HEADERS});
        if(!r.ok)continue;
        for(const row of await r.json())await supaUpsert(t,row.id,clean(row.data||{}),e.id).catch(()=>{});
      }
    }
    _trashItems.splice(i,1);renderTrash();
    await loadAllData(); // 캐시·파생 목록 전체 재정합 (복원은 드문 작업)
    if(typeof renderDash==='function')renderDash();
    if(typeof renderStus==='function')renderStus();
    if(typeof renderLes==='function')renderLes();
    if(typeof renderBookDB==='function')renderBookDB();
    toast('복원되었습니다');
  }catch(err){toast('복원 실패: '+(err.message||''));}
}
async function _hardPurge(e){
  if(e.table==='students'){
    // 학생 영구 삭제: 함께 묶인 기록 + 단어 카드까지 정리
    for(const [t] of TRASH_TABLES){
      if(t==='students'||t==='global_textbooks')continue;
      try{
        const r=await fetch(`${SUPA_URL}/rest/v1/${t}?select=id&data-%3E%3E_deletedWith=eq.${encodeURIComponent(e.id)}`,{headers:SUPA_HEADERS});
        if(r.ok)for(const row of await r.json())await supaDelete(t,row.id).catch(()=>{});
      }catch(err){}
    }
    await supaDeleteWhere('vocab_cards','sid',e.id).catch(()=>{});
    _cache.vocab_cards=(_cache.vocab_cards||[]).filter(c=>c.sid!==e.id);
  }
  if(e.table==='global_textbooks'){
    await supaDeleteWhere('vocab_cards','srcId',e.id).catch(()=>{});
    _cache.vocab_cards=(_cache.vocab_cards||[]).filter(c=>c.srcId!==e.id);
  }
  await supaDelete(e.table,e.id);
}
function purgeTrash(i){
  const e=_trashItems[i];if(!e)return;
  askConfirm('영구 삭제','복원할 수 없게 완전히 삭제할까요?'+(e.table==='global_textbooks'?' 연결된 학생 단어 카드도 함께 삭제됩니다.':e.table==='students'?' 학생의 모든 기록과 단어 카드가 함께 삭제됩니다.':''),'영구 삭제','bd',async()=>{
    await _hardPurge(e);
    _trashItems.splice(i,1);renderTrash();toast('영구 삭제되었습니다');
  });
}
// 30일 지난 휴지통 항목 자동 정리 (세션당 1회, 대시보드 진입 시)
let _trashPurgedOnce=false;
async function purgeOldTrash(){
  if(_trashPurgedOnce)return;_trashPurgedOnce=true;
  const cutoff=new Date(Date.now()-30*864e5).toISOString();
  for(const [t] of TRASH_TABLES){
    try{
      const r=await fetch(`${SUPA_URL}/rest/v1/${t}?select=id,data&data-%3E%3E_deleted=eq.true&data-%3E%3E_deletedAt=lt.${encodeURIComponent(cutoff)}`,{headers:SUPA_HEADERS});
      if(!r.ok)continue;
      for(const row of await r.json())await _hardPurge({table:t,id:row.id,data:row.data||{}}).catch(()=>{});
    }catch(e){}
  }
}

// ── 전체 백업 — 모든 테이블을 서버에서 직접 내려받아 JSON 파일로 저장 ──
// (캐시는 vocab_cards 등이 지연 로드라 불완전할 수 있어 REST로 전량 조회. 1000행 단위 페이지네이션)
async function _dumpTable(t,orderCol){
  const rows=[];let from=0;const page=1000;
  while(true){
    const r=await fetch(`${SUPA_URL}/rest/v1/${t}?select=*&order=${orderCol||'id'}`,{headers:{...SUPA_HEADERS,'Range':`${from}-${from+page-1}`}});
    if(!r.ok){
      if(!orderCol&&from===0)return _dumpTable(t,'updated_at'); // id 컬럼이 없는 테이블 폴백
      return rows; // 미생성 테이블 등은 있는 만큼만
    }
    const chunk=await r.json();rows.push(...chunk);
    if(chunk.length<page)break;
    from+=page;
  }
  return rows;
}
async function fullBackup(){
  toast('백업 수집 중... (수 초 걸릴 수 있어요)');
  try{
    const tables=['students','lessons','tests','readings','logs','notices','homeworks','assignments','textbooks','messages','global_textbooks','classes','monthly_reports','vocab_cards','worksheets'];
    const dump={_meta:{app:'page-pencil',exportedAt:new Date().toISOString()}};
    for(const t of tables)dump[t]=await _dumpTable(t);
    dump.settings=await _dumpTable('settings','key');
    const blob=new Blob([JSON.stringify(dump)],{type:'application/json'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=`pagepencil_backup_${ppToday()}.json`;
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href),5000);
    const ym=ppToday().slice(0,7);
    localStorage.setItem('pp_lastBackup',ym);
    supaSetSetting('lastBackup',ym).catch(()=>{});
    const total=tables.reduce((s,t)=>s+(dump[t]?.length||0),0);
    toast(`백업 완료 — ${total.toLocaleString()}행이 파일로 저장되었습니다`);
    if(typeof renderDash==='function')renderDash();
  }catch(e){console.warn('fullBackup:',e);toast('백업 실패: '+(e.message||''));}
}

// ── URL PARAM AUTO LOGIN ──
// 로그인 전에는 아무것도 받지 않는다 (2026-11-08). 선생님 로그인은 Auth 가 먼저고,
// 폴백이 필요할 때 checkPw 가 그때 한 번 settings.pw 를 읽는다.
function _prefetchPw(){}
document.addEventListener('DOMContentLoaded',async()=>{
  try{
    const params=new URLSearchParams(location.search);
    const pin=params.get('pin');
    const role=params.get('role');
    const qrTok=params.get('t');
    // 새 QR 링크(?t=무작위토큰) — PIN 이 주소에 실리지 않는다
    if(qrTok){
      try{history.replaceState(null,'',location.pathname+location.hash);}catch(e){}
      setToday();
      const _role=(role==='parent')?'parent':'student';
      let done=false;
      if(typeof ppLoginPin==='function'){
        const r=await ppLoginPin(_role,{qr:qrTok});
        if(r.ok){
          if(_role==='student')await ppStudentEnter(r.sid,r.name);
          else await ppParentEnter(r.sid);
          done=true;
        }else if(r.hard){toast(r.why||'링크가 더 이상 유효하지 않습니다');done=true;}
      }
      if(!done&&(typeof PP_AUTH_FALLBACK==='undefined'||PP_AUTH_FALLBACK)){
        // 함수가 아직 없는 동안은 토큰으로 캐시에서 찾아 본다 (병행 기간)
        if(!_cache.students.length)await loadAllDataFast(true);
        const st=DB.stus().find(x=>x.qrToken===qrTok&&!x.inactive);
        if(st){ if(_role==='student')await ppStudentEnter(st.id,st.name); else await ppParentEnter(st.id); }
        else toast('링크가 더 이상 유효하지 않습니다');
      }
    } else if(pin&&role&&(typeof PP_AUTH_FALLBACK==='undefined'||PP_AUTH_FALLBACK)){
      // 옛 QR 링크(?pin=). 3단계에서 PP_AUTH_FALLBACK 을 false 로 두면 이 가지가 통째로 꺼진다.
      // 주소에 PIN 이 남으면 방문 기록·화면 공유·캡처에 그대로 남고, [나가기] 뒤 새로고침에
      // 다시 자동 로그인된다. 읽자마자 지운다 (뒤로 가기 기록도 남기지 않게 replaceState)
      try{history.replaceState(null,'',location.pathname+location.hash);}catch(e){}
      setToday();
      if(!_cache.students.length)await loadAllDataFast(true);
      const matches=_cache.students.filter(s=>s.pin===pin&&!s.inactive);
      if(matches.length===1){
        if(role==='student'){
          await ppStudentEnter(matches[0].id,matches[0].name);
        } else if(role==='parent'){
          document.getElementById('pin-code').value=pin;
          document.getElementById('pin-name').value=matches[0].name;
          await checkPin();
        }
      }
    } else {
      setToday();
      const session=loadSession();
      if(session){
        if(session.role==='teacher'){
          // 폴백을 끈 뒤(3단계)에는 pp_session 만으로 선생님 화면을 열지 않는다 —
          // 선생님 토큰은 탭을 닫으면 사라지므로, 토큰이 없으면 로그인 화면으로 보낸다.
          if(typeof PP_AUTH_FALLBACK!=='undefined'&&PP_AUTH_FALLBACK===false
             &&!(typeof ppSession==='function'&&ppSession()&&ppAuthRole()==='teacher')){
            clearSession();show('s-land');
          }else{
          show('s-teacher');await initApp();}
        } else if(session.role==='student'){
          // 선생님 앱과 같은 길로 — 스냅샷으로 즉시 부팅하고 뒤에서 최신화(60KB).
          // 전에는 학생·학부모만 loadAllData() 를 직접 불러, 앱을 열 때마다 5.58MB 를 받았다.
          if(!_cache.students.length)await loadAllDataFast();
          const s=_cache.students.find(x=>x.id===session.sid&&!x.inactive);
          if(s){await loginStudent(s);}else clearSession();
        } else if(session.role==='parent'){
          if(!_cache.students.length)await loadAllDataFast();
          const s=_cache.students.find(x=>x.id===session.sid&&!x.inactive);
          if(s){loadParentWithNotice(s.id);}else clearSession();
        }
      }
    }
    const verEl=document.getElementById('app-version');
    if(verEl)verEl.textContent=APP_VERSION;
    if(!document.querySelector('.screen.active')){
      _prefetchPw();
      show('s-land');
    }
  }catch(e){
    console.error('init error:',e);
    _prefetchPw();
    show('s-land');
  }
  function showOfflineBanner(show){
    let b=document.getElementById('offline-banner');
    if(!b){
      b=document.createElement('div');
      b.id='offline-banner';
      b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99999;background:#333;color:#fff;text-align:center;padding:10px;font-size:14px;font-weight:600;transform:translateY(-100%);transition:transform .3s';
      b.textContent='📡 인터넷 연결이 끊겼습니다. 저장이 되지 않을 수 있습니다.';
      document.body.appendChild(b);
    }
    b.style.transform=show?'translateY(0)':'translateY(-100%)';
  }
  window.addEventListener('offline',()=>showOfflineBanner(true));
  window.addEventListener('online',()=>{showOfflineBanner(false);toast('인터넷 연결이 복구됐습니다 ✓');});
  if(!navigator.onLine)showOfflineBanner(true);
});

// ══════════════════════════════════════════════════════════════════════════════
// 기출·자료실 (exam_bank) — 선생님 전용
// ══════════════════════════════════════════════════════════════════════════════
// 구글 드라이브에 모아 둔 기출문제·교재 자료를 앱에서 찾고, 띄우고, 들을 수 있게 한다.
//
// 전송량 규칙 (Supabase 무료 한도가 이미 빠듯하다):
//   · 앱이 켜질 때는 받지 않는다. 이 탭을 **처음 열 때** 한 번 받는다.
//   · 목록은 files·audio 를 뺀 가벼운 뷰(exam_bank_index, 약 1.7MB)로 받는다.
//     표 전체는 6천 행 5MB 가 넘는데 그 대부분이 파일 목록이고, 목록 화면에는 필요 없다.
//   · 받은 목록은 기기(IndexedDB)에 둔다. 12시간 안에는 그대로 쓰고, 그 뒤에는
//     id·updated_at 만 비교해(약 380KB) 바뀐 행만 받는다 (_tbSyncIfChanged 와 같은 방식).
//   · 문서·mp3 는 Supabase 를 거치지 않는다 — 구글 드라이브에서 바로 연다.
//
// 비공개 자료 규칙:
//   · 드라이브 파일은 비공개다. 앱은 **파일 id 만** 알고, 공유 설정을 바꾸는 코드는 넣지 않는다.
//   · 드라이브 로그인(OAuth)을 요구하지 않는다. 브라우저에 이미 로그인된 계정으로 열린다.
//   · 학생·학부모 화면과 체험 모드에서는 이 탭도, 이 데이터도 보이지 않는다(ebMayUse).
const EB_SHEET_URL='https://docs.google.com/spreadsheets/d/1McJdpsEDSNkW9n7fGPNhUJzWniZcp2DGn9hDNkVE_rQ/edit';
const EB_IDX_KEY='pp_exam_bank_v1';
const EB_FRESH_MS=12*60*60*1000;
const EB_PAGE=100;
// 구분 — g 는 묶음(기출/교재), n 은 화면에 쓰는 이름
const EB_CATS=[
  {k:'suneung',  g:'기출', n:'수능'},
  {k:'mopyeong', g:'기출', n:'모의평가'},
  {k:'hakpyeong',g:'기출', n:'학력평가'},
  {k:'listen',   g:'기출', n:'영어듣기능력평가'},
  {k:'naea',     g:'기출', n:'학업성취도'},
  {k:'edu',      g:'기출', n:'시도교육청'},
  {k:'school',   g:'기출', n:'학교 정기고사'},
  {k:'goip',     g:'기출', n:'고입선발고사'},
  {k:'basic',    g:'기출', n:'기초학력'},
  {k:'research', g:'기출', n:'연구 자료'},
  {k:'publisher',g:'교재', n:'출판사·학원용'},
  {k:'elt',      g:'교재', n:'영어교육 출판사'},
  {k:'bookaudio',g:'교재', n:'교재 음원'},
  {k:'bookdocs', g:'교재', n:'교재 단어·워크시트'},
  {k:'audiobook',g:'원서', n:'원서 오디오'}
];
// 문서 종류 — k 값은 카탈로그 표기 그대로
const EB_KIND={q:{n:'문제지',i:'file-text'},a:{n:'정답',i:'check'},s:{n:'해설',i:'info'},sc:{n:'듣기대본',i:'file-text'},etc:{n:'기타',i:'paperclip'}};
const EB_KIND_ORDER=['q','a','s','sc','etc'];

let _ebRows=null;              // 가벼운 목록 [{id,updated_at,meta,nfiles,kinds,naudio,extaud}]
let _ebStamps={};              // id → updated_at (바뀐 행만 받기 위한 기준)
let _ebAt=0;                   // 마지막으로 받은 시각
let _ebMax='';                 // 가장 최근 updated_at — '바뀐 게 있나' 가볍게 볼 때 쓴다
let _ebSrc='view';             // 'view' = 가벼운 뷰 · 'table' = 뷰가 아직 없어 표에서 통째로
let _ebLoading=false,_ebNote='';
const _ebFull=new Map();       // 상세를 연 행의 data 전체 (이 세션 동안 메모리에만)
let _ebPage=1,_ebViewId='',_ebDetailId='';
let _ebF={cat:'',series:'',level:'',grade:'',term:'',y1:'',y2:'',region:'',city:'',school:'',audio:false,only:'',q:''};
let _ebAuIdx=-1,_ebAuList=[];  // 지금 열어 둔 드라이브 음원 (한 번에 하나)
let _ebAuLbl='다음 문항 ▶';     // 원서 오디오는 '다음 트랙'

const _ebE=x=>String(x==null?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const _ebA=x=>escAttr(_ebE(x));

// 선생님 화면에서만, 체험 모드가 아닐 때만 쓴다
function ebMayUse(){
  try{
    if(typeof ppSandbox==='function'&&ppSandbox())return false;
    const s=(typeof loadSession==='function')?loadSession():null;
    return !!(s&&s.role==='teacher');
  }catch(e){return false;}
}
// 자료 계정 — 드라이브 주소에 authuser 로 붙여 '어느 계정으로 열지'를 알려 준다
function ebAcct(){try{return String((DB&&DB.g&&DB.g('driveAcct'))||'jikgyeol@gmail.com').trim();}catch(e){return 'jikgyeol@gmail.com';}}
function _ebAu(){const a=ebAcct();return a?('&authuser='+encodeURIComponent(a)):'';}
function ebPreviewUrl(id){return 'https://drive.google.com/file/d/'+encodeURIComponent(id)+'/preview?usp=drivesdk'+_ebAu();}
function ebViewUrl(id){return 'https://drive.google.com/file/d/'+encodeURIComponent(id)+'/view?usp=drivesdk'+_ebAu();}
function ebAudioUrl(id){return 'https://drive.usercontent.google.com/download?id='+encodeURIComponent(id)+'&export=download'+_ebAu();}
function ebFolderUrl(id){return 'https://drive.google.com/drive/folders/'+encodeURIComponent(id)+'?usp=drivesdk'+_ebAu();}

// ── 받아 오기 ────────────────────────────────────────────────
async function _ebGet(q){
  const ctrl=new AbortController();const tid=setTimeout(()=>ctrl.abort(),25000);
  try{
    const r=await fetch(SUPA_URL+'/rest/v1/'+q,{headers:SUPA_HEADERS,signal:ctrl.signal});
    clearTimeout(tid);
    if(!r.ok)return {ok:false,status:r.status};
    const rows=await r.json();
    return Array.isArray(rows)?{ok:true,rows:rows}:{ok:false,status:0};
  }catch(e){clearTimeout(tid);return {ok:false,status:0};}
}
const EB_SEL='select=id,updated_at,meta,nfiles,kinds,naudio,extaud';
// 표 한 줄을 목록용 가벼운 모양으로 (뷰가 아직 없을 때)
function _ebLight(row){
  const d=(row&&row.data)||{};
  const fs=Array.isArray(d.files)?d.files:[];
  const au=(d.audio&&Array.isArray(d.audio.files))?d.audio.files:[];
  const meta={};
  ['cat','title','path','note','level','grade','term','school','region','city','year','month','round','series','_deleted']
    .forEach(k=>{const v=d[k];if(v!==''&&v!==null&&v!==undefined)meta[k]=v;});
  return {id:row.id,updated_at:row.updated_at,meta:meta,nfiles:fs.length,
    kinds:[...new Set(fs.map(f=>(f&&f.k)||'').filter(Boolean))].sort().join(','),
    naudio:au.length,extaud:!!d.extAudio};
}
function _ebAlive(r){return !!r&&!(r.meta&&r.meta._deleted);}   // 휴지통 행은 받는 쪽에서도 거른다
async function _ebFetchAll(){
  const PAGE=1000;let out=[],off=0;
  _ebSrc='view';_ebNote='';
  while(true){
    let r=null;
    if(_ebSrc==='view'){
      r=await _ebGet('exam_bank_index?'+EB_SEL+'&limit='+PAGE+'&offset='+off+'&order=id');
      if(!r.ok&&(r.status===404||r.status===400||r.status===406)){
        // 뷰가 아직 없다(SQL 실행 전) → 표에서 통째로 받고 여기서 가볍게 만든다
        _ebSrc='table';_ebNote='목록 뷰가 없어 표 전체를 받았습니다 — supabase/exam_bank.sql 을 실행하면 훨씬 가볍게 받습니다.';
        out=[];off=0;continue;
      }
    }else{
      r=await _ebGet('exam_bank?select=id,updated_at,data&limit='+PAGE+'&offset='+off+'&order=id');
    }
    if(!r.ok)return null;
    if(_ebSrc==='view')out=out.concat(r.rows.filter(_ebAlive));
    else r.rows.forEach(x=>{const L=_ebLight(x);if(_ebAlive(L)){out.push(L);_ebFull.set(x.id,x.data);}});
    if(r.rows.length<PAGE)return out;
    off+=PAGE;
  }
}
async function _ebStampRows(){
  const PAGE=1000,tbl=(_ebSrc==='view'?'exam_bank_index':'exam_bank');
  let out=[],off=0;
  while(true){
    const r=await _ebGet(tbl+'?select=id,updated_at&limit='+PAGE+'&offset='+off+'&order=id');
    if(!r.ok)return null;
    out=out.concat(r.rows);
    if(r.rows.length<PAGE)return out;
    off+=PAGE;
  }
}
async function _ebFetchByIds(ids){     // 50개 이하
  const q=ids.map(encodeURIComponent).join(',');
  if(_ebSrc==='view'){
    const r=await _ebGet('exam_bank_index?'+EB_SEL+'&id=in.('+q+')');
    return r.ok?r.rows:null;
  }
  const r=await _ebGet('exam_bank?select=id,updated_at,data&id=in.('+q+')');
  if(!r.ok)return null;
  return r.rows.map(x=>{const L=_ebLight(x);_ebFull.set(x.id,x.data);return L;});
}
async function _ebSave(){try{await idbSet(EB_IDX_KEY,{v:1,src:_ebSrc,rows:_ebRows,stamps:_ebStamps,at:_ebAt,max:_ebMax});}catch(e){}}
function _ebMaxOf(rows){let m='';rows.forEach(x=>{const u=String((x&&x.updated_at)||'');if(u>m)m=u;});return m;}
// 바뀐 게 있는지 가장 싸게 보는 법 — 맨 끝 한 줄과 전체 개수만 (헤더로 온다, 몇십 바이트)
async function _ebProbe(){
  try{
    const tbl=(_ebSrc==='view'?'exam_bank_index':'exam_bank');
    const r=await fetch(SUPA_URL+'/rest/v1/'+tbl+'?select=updated_at&order=updated_at.desc&limit=1',
      {headers:{...SUPA_HEADERS,'Prefer':'count=exact'}});
    if(!r.ok)return null;
    const cr=String(r.headers.get('content-range')||'');   // 예: "0-0/6139"
    const total=Number(cr.split('/')[1]);
    const rows=await r.json();
    return {total:isFinite(total)?total:null,max:String((rows&&rows[0]&&rows[0].updated_at)||'')};
  }catch(e){return null;}
}
function _ebStampsOf(rows){const s={};rows.forEach(x=>{if(x&&x.id)s[x.id]=x.updated_at;});return s;}

// 처음 열 때 한 번 전부, 그 뒤에는 바뀐 것만. 바뀐 게 있으면 true
async function ebLoad(force){
  if(!ebMayUse()||_ebLoading)return false;
  _ebLoading=true;
  try{
    if(_ebRows===null){
      const snap=await idbGet(EB_IDX_KEY);
      if(snap&&Array.isArray(snap.rows)&&snap.rows.length){
        _ebRows=snap.rows;_ebStamps=snap.stamps||{};_ebAt=snap.at||0;_ebSrc=snap.src||'view';_ebMax=snap.max||'';
      }
    }
    const have=!!(_ebRows&&_ebRows.length);
    if(have&&!force&&(Date.now()-_ebAt)<EB_FRESH_MS)return false;     // 아직 싱싱하다 — 받지 않는다
    if(!have){
      const all=await _ebFetchAll();
      if(!all)return false;                                           // 실패하면 그대로 둔다
      _ebRows=all;_ebStamps=_ebStampsOf(all);_ebMax=_ebMaxOf(all);_ebAt=Date.now();
      await _ebSave();
      return true;
    }
    // 끝 한 줄·개수만 먼저 본다 — 바뀐 게 없으면 여기서 끝난다 (목록 전체 대조는 500KB)
    const pr=await _ebProbe();
    if(pr&&pr.max&&pr.max===_ebMax&&pr.total!==null&&pr.total===_ebRows.length){
      _ebAt=Date.now();await _ebSave();return false;
    }
    const st=await _ebStampRows();
    if(!st||!st.length)return false;                                  // 실패·빈 응답 → 그대로 둔다
    const live=new Set(st.map(x=>x&&x.id));
    const changed=st.filter(x=>x&&x.id&&String(_ebStamps[x.id]||'')!==String(x.updated_at||'')).map(x=>x.id);
    const gone=_ebRows.filter(r=>!live.has(r.id)).map(r=>r.id);
    _ebAt=Date.now();
    if(!changed.length&&!gone.length){await _ebSave();return false;}
    const byId=new Map(_ebRows.map(r=>[r.id,r]));
    gone.forEach(id=>{byId.delete(id);_ebFull.delete(id);});
    for(let i=0;i<changed.length;i+=50){
      const part=await _ebFetchByIds(changed.slice(i,i+50));
      if(!part)return true;                                           // 반만 받은 상태로 두지 않는다 — 다음에 다시
      part.forEach(x=>{_ebFull.delete(x.id);if(_ebAlive(x))byId.set(x.id,x);else byId.delete(x.id);});
    }
    _ebRows=[...byId.values()];_ebStamps=_ebStampsOf(st);_ebMax=_ebMaxOf(st);
    await _ebSave();
    console.log('기출·자료실 변경 '+changed.length+'건 반영'+(gone.length?' · 빠짐 '+gone.length+'건':''));
    return true;
  }catch(e){return false;}
  finally{_ebLoading=false;}
}
// 상세용 — 그 행의 data 전체 한 줄 (몇 KB)
async function _ebFullRow(id){
  if(_ebFull.has(id))return _ebFull.get(id);
  const r=await _ebGet('exam_bank?select=data&id=eq.'+encodeURIComponent(id));
  const d=(r.ok&&r.rows[0]&&r.rows[0].data)||null;
  if(d)_ebFull.set(id,d);
  return d;
}

// ── 즐겨찾기 · 최근 본 (기기에만 둔다) ────────────────────────
function ebFavs(){try{return JSON.parse(localStorage.getItem('pp_eb_fav')||'[]')||[];}catch(e){return [];}}
function ebIsFav(id){return ebFavs().indexOf(id)>=0;}
function ebToggleFav(id,ev){
  if(ev)ev.stopPropagation();
  const f=ebFavs(),i=f.indexOf(id);
  if(i>=0)f.splice(i,1);else f.unshift(id);
  try{localStorage.setItem('pp_eb_fav',JSON.stringify(f.slice(0,300)));}catch(e){}
  renderBankList();_ebPaintFav();
}
function ebRecents(){try{return JSON.parse(localStorage.getItem('pp_eb_recent')||'[]')||[];}catch(e){return [];}}
function _ebRecentPush(id){
  const r=ebRecents().filter(x=>x!==id);r.unshift(id);
  try{localStorage.setItem('pp_eb_recent',JSON.stringify(r.slice(0,10)));}catch(e){}
}

// ── 거르기 ──────────────────────────────────────────────────
function _ebSaveF(){try{localStorage.setItem('pp_eb_filters',JSON.stringify(_ebF));}catch(e){}}
function _ebLoadF(){try{const s=JSON.parse(localStorage.getItem('pp_eb_filters')||'null');if(s&&typeof s==='object')_ebF={..._ebF,...s};}catch(e){}}
function ebFilterChange(){
  const v=id=>{const el=document.getElementById(id);return el?el.value:'';};
  _ebF.cat=v('eb-f-cat');_ebF.series=v('eb-f-series');_ebF.level=v('eb-f-level');_ebF.grade=v('eb-f-grade');_ebF.term=v('eb-f-term');
  _ebF.y1=v('eb-f-y1');_ebF.y2=v('eb-f-y2');
  _ebF.region=v('eb-f-region');_ebF.city=v('eb-f-city');_ebF.school=v('eb-f-school');
  const a=document.getElementById('eb-f-audio');_ebF.audio=!!(a&&a.checked);
  _ebF.q=v('eb-f-q');
  _ebPage=1;_ebPaintSeries();_ebSaveF();renderBankList();
}
function ebOnly(kind){_ebF.only=(_ebF.only===kind?'':kind);_ebPage=1;_ebSaveF();_ebPaintFilters();renderBankList();}
function ebResetFilters(){
  _ebF={cat:'',series:'',level:'',grade:'',term:'',y1:'',y2:'',region:'',city:'',school:'',audio:false,only:'',q:''};
  _ebPage=1;_ebSaveF();_ebPaintFilters();renderBankList();
}
function _ebCatName(k){const c=EB_CATS.find(x=>x.k===k);return c?c.n:(k||'');}
function _ebNum(v){if(v===''||v===null||v===undefined)return null;const n=Number(v);return isFinite(n)?n:null;}
function _ebMatch(r){
  const m=r.meta||{};
  if(_ebF.only==='fav'&&!ebIsFav(r.id))return false;
  if(_ebF.only==='recent'&&ebRecents().indexOf(r.id)<0)return false;
  if(_ebF.cat&&String(m.cat||'')!==_ebF.cat)return false;
  if(_ebF.series&&String(m.series||'')!==_ebF.series)return false;
  if(_ebF.level&&String(m.level||'')!==_ebF.level)return false;
  if(_ebF.grade&&String(m.grade||'')!==_ebF.grade)return false;
  if(_ebF.term&&String(m.term||'')!==_ebF.term)return false;
  if(_ebF.region&&String(m.region||'')!==_ebF.region)return false;
  if(_ebF.city&&String(m.city||'')!==_ebF.city)return false;
  if(_ebF.school&&String(m.school||'')!==_ebF.school)return false;
  if(_ebF.audio&&!(r.naudio>0||r.extaud))return false;
  const y=_ebNum(m.year),y1=_ebNum(_ebF.y1),y2=_ebNum(_ebF.y2);
  if(y1!==null&&(y===null||y<y1))return false;
  if(y2!==null&&(y===null||y>y2))return false;
  const q=String(_ebF.q||'').trim().toLowerCase();
  if(q){
    const hay=[m.title,m.school,m.city,m.region,m.path,m.series,m.catLabel,m.note,m.grade,m.term,m.year].join(' ').toLowerCase();
    if(q.split(/\s+/).some(w=>w&&hay.indexOf(w)<0))return false;
  }
  return true;
}
function _ebFiltered(){
  const rows=(_ebRows||[]).filter(r=>_ebAlive(r)&&_ebMatch(r));
  rows.sort((a,b)=>{
    const ay=_ebNum((a.meta||{}).year),by=_ebNum((b.meta||{}).year);
    if(ay!==by)return (by===null?-1:by)-(ay===null?-1:ay);          // 연도 내림차순, 연도 없는 것은 뒤로
    const am=_ebNum((a.meta||{}).month)||0,bm=_ebNum((b.meta||{}).month)||0;
    if(am!==bm)return bm-am;
    return String((a.meta||{}).title||'').localeCompare(String((b.meta||{}).title||''),'ko');
  });
  return rows;
}

// ── 목록 화면 ───────────────────────────────────────────────
function _ebOpts(id,label,vals,cur){
  const el=document.getElementById(id);if(!el)return;
  el.innerHTML=['<option value="">'+_ebE(label)+'</option>'].concat(vals.map(v=>
    '<option value="'+_ebA(v.v)+'"'+(String(cur)===String(v.v)?' selected':'')+'>'+_ebE(v.n)+'</option>')).join('');
}
// 시리즈 칸은 그 구분에 시리즈가 있을 때만 (출판사 자료에만 들어 있다)
function _ebPaintSeries(){
  const el=document.getElementById('eb-f-series');if(!el)return;
  const vals=_ebF.cat?[...new Set((_ebRows||[]).filter(r=>String((r.meta||{}).cat||'')===_ebF.cat)
    .map(r=>String((r.meta||{}).series||'')).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko')):[];
  if(!vals.length){el.style.display='none';el.innerHTML='';if(_ebRows&&_ebRows.length)_ebF.series='';return;}
  if(_ebF.series&&vals.indexOf(_ebF.series)<0)_ebF.series='';   // 구분을 바꾸면 안 맞는 시리즈는 푼다
  el.style.display='';
  _ebOpts('eb-f-series','시리즈 전체',vals.map(v=>({v:v,n:v})),_ebF.series);
}
function _ebPaintFilters(){
  const rows=(_ebRows||[]);
  const uniq=k=>[...new Set(rows.map(r=>String((r.meta||{})[k]||'')).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));
  const cats=[...new Set(rows.map(r=>String((r.meta||{}).cat||'')).filter(Boolean))];
  const catVals=EB_CATS.filter(c=>cats.indexOf(c.k)>=0).map(c=>({v:c.k,n:c.g+' · '+c.n}))
    .concat(cats.filter(k=>!EB_CATS.some(c=>c.k===k)).map(k=>({v:k,n:k})));
  _ebOpts('eb-f-cat','구분 전체',catVals,_ebF.cat);
  _ebPaintSeries();
  _ebOpts('eb-f-level','학교급',['초','중','고'].filter(v=>rows.some(r=>(r.meta||{}).level===v)).map(v=>({v:v,n:v})),_ebF.level);
  _ebOpts('eb-f-grade','학년',uniq('grade').map(v=>({v:v,n:v})),_ebF.grade);
  _ebOpts('eb-f-term','학기',uniq('term').map(v=>({v:v,n:v})),_ebF.term);
  _ebOpts('eb-f-region','지역',uniq('region').map(v=>({v:v,n:v})),_ebF.region);
  _ebOpts('eb-f-city','시·군',uniq('city').map(v=>({v:v,n:v})),_ebF.city);
  _ebOpts('eb-f-school','학교',uniq('school').map(v=>({v:v,n:v})),_ebF.school);
  const set=(id,v)=>{const el=document.getElementById(id);if(el&&el.value!==v)el.value=v;};
  set('eb-f-y1',_ebF.y1);set('eb-f-y2',_ebF.y2);set('eb-f-q',_ebF.q);
  const a=document.getElementById('eb-f-audio');if(a)a.checked=!!_ebF.audio;
  [['fav','즐겨찾기'],['recent','최근 본']].forEach(([k,n])=>{
    const b=document.getElementById('eb-only-'+k);
    if(b){b.className='btn bsm '+(_ebF.only===k?'bt':'bo');b.textContent=n+' '+(k==='fav'?ebFavs().length:ebRecents().length);}
  });
}
function _ebKindPills(r){
  const ks=String(r.kinds||'').split(',').filter(Boolean);
  let h=EB_KIND_ORDER.filter(k=>ks.indexOf(k)>=0)
    .map(k=>'<span class="eb-pill">'+_ebE(EB_KIND[k].n)+'</span>').join('');
  if(r.naudio>0)h+='<span class="eb-pill eb-pill-on">듣기 '+r.naudio+'</span>';
  else if(r.extaud)h+='<span class="eb-pill eb-pill-on">듣기 링크</span>';
  return h;
}
function _ebBadges(m){
  const b=[];
  if(m.cat)b.push(_ebCatName(m.cat));
  if(m.grade)b.push(m.grade);else if(m.level)b.push(m.level);
  if(m.year)b.push(String(m.year)+(m.month?('.'+m.month):'')+(m.round?(' '+m.round+'회'):''));
  if(m.term)b.push(m.term);
  if(m.school)b.push(m.school);
  return b.map(x=>'<span class="eb-badge">'+_ebE(x)+'</span>').join('');
}
function renderBankList(){
  const box=document.getElementById('eb-list');if(!box)return;
  const cnt=document.getElementById('eb-count');
  if(!ebMayUse()){box.innerHTML='<div class="eb-empty">선생님 화면에서만 보입니다.</div>';if(cnt)cnt.textContent='';return;}
  if(!_ebRows||!_ebRows.length){
    box.innerHTML='<div class="eb-empty">'+(_ebLoading?'자료실을 불러오는 중…':
      '아직 자료가 없습니다. 오른쪽 위 ⋯ 메뉴의 <b>카탈로그 가져오기</b>로 목록 파일을 올려 주세요.')+'</div>';
    if(cnt)cnt.textContent='';return;
  }
  const all=_ebFiltered();
  const show=all.slice(0,_ebPage*EB_PAGE);
  if(cnt)cnt.textContent=all.length.toLocaleString()+'개'+(all.length!==_ebRows.length?(' / 전체 '+_ebRows.length.toLocaleString()+'개'):'');
  if(!all.length){box.innerHTML='<div class="eb-empty">조건에 맞는 자료가 없습니다.</div>';return;}
  let h=show.map(r=>{
    const m=r.meta||{},fav=ebIsFav(r.id);
    return '<div class="eb-row" onclick="ebOpenDetail(\''+escJsA(r.id)+'\')">'+
      '<button class="eb-star'+(fav?' on':'')+'" title="즐겨찾기" onclick="ebToggleFav(\''+escJsA(r.id)+'\',event)">'+(fav?'★':'☆')+'</button>'+
      '<div class="eb-main"><div class="eb-title">'+_ebE(m.title||'(제목 없음)')+'</div>'+
      '<div class="eb-sub">'+_ebBadges(m)+(m.path?'<span class="eb-path">'+_ebE(m.path)+'</span>':'')+'</div></div>'+
      '<div class="eb-kinds">'+_ebKindPills(r)+'</div></div>';
  }).join('');
  if(all.length>show.length)
    h+='<div style="text-align:center;padding:14px"><button class="btn bo bsm" onclick="_ebPage++;renderBankList()">더 보기 ('+show.length.toLocaleString()+' / '+all.length.toLocaleString()+')</button></div>';
  box.innerHTML=h;
}
function _ebStamp(){
  const el=document.getElementById('eb-state');if(!el)return;
  if(_ebNote){el.textContent=_ebNote;return;}
  if(!_ebAt){el.textContent='';return;}
  const mins=Math.max(0,Math.round((Date.now()-_ebAt)/60000));
  el.textContent=mins<1?'방금 최신화':(mins<60?mins+'분 전 최신화':Math.round(mins/60)+'시간 전 최신화');
}
// 탭을 열 때 — 캐시가 있으면 먼저 그리고, 필요할 때만 받는다
function ebOpenTab(){
  _ebLoadF();_ebPaintFilters();renderBankList();
  const st=document.getElementById('eb-state');
  if(st&&!(_ebRows&&_ebRows.length))st.textContent='불러오는 중…';
  ebLoad(false).then(()=>{
    _ebPaintFilters();
    renderBankList();_ebStamp();
  });
}
async function ebRefresh(){
  _ebMenuOut();
  if(!ebMayUse())return;
  const el=document.getElementById('eb-state');if(el)el.textContent='확인 중…';
  const ch=await ebLoad(true);
  _ebPaintFilters();renderBankList();_ebStamp();
  toast(ch?'자료실을 최신화했습니다 ✓':'바뀐 자료가 없습니다');
}
async function ebCacheClear(){
  _ebMenuOut();
  try{await idbDel(EB_IDX_KEY);}catch(e){}
  _ebRows=null;_ebStamps={};_ebAt=0;_ebMax='';_ebFull.clear();
  renderBankList();
  await ebLoad(true);_ebPaintFilters();renderBankList();_ebStamp();
}

// ── ⋯ 메뉴 ──────────────────────────────────────────────────
function ebMenu(e){
  if(e)e.stopPropagation();
  const m=document.getElementById('eb-menu');if(!m)return;
  const open=m.style.display!=='none';
  m.style.display=open?'none':'';
  if(!open)setTimeout(()=>document.addEventListener('click',_ebMenuOut),0);
}
function _ebMenuOut(){
  const m=document.getElementById('eb-menu');if(m)m.style.display='none';
  document.removeEventListener('click',_ebMenuOut);
}
function ebOpenSheet(){window.open(EB_SHEET_URL,'_blank','noopener');_ebMenuOut();}

// ── 카탈로그 가져오기 ────────────────────────────────────────
// [{id, data}] 배열을 50개씩 올린다. 같은 id 는 덮어쓰고, 파일에 없는 id 는 그대로 둔다(지우지 않는다).
function ebImportPick(){_ebMenuOut();const f=document.getElementById('eb-import-file');if(f)f.click();}
async function ebImportFile(ev){
  const file=ev&&ev.target&&ev.target.files&&ev.target.files[0];
  if(ev&&ev.target)ev.target.value='';
  if(!file)return;
  if(!ebMayUse()){toast('선생님 화면에서만 가져올 수 있습니다');return;}
  let rows=null;
  try{rows=JSON.parse(await file.text());}catch(e){toast('JSON 파일을 읽지 못했습니다');return;}
  if(!Array.isArray(rows)){toast('[{id, data}] 모양의 배열이어야 합니다');return;}
  const good=rows.filter(r=>r&&typeof r.id==='string'&&r.id&&r.data&&typeof r.data==='object'&&!Array.isArray(r.data));
  if(!good.length){toast('가져올 행이 없습니다');return;}
  const skipped=rows.length-good.length;
  const prog=document.getElementById('eb-import-prog'),bar=document.getElementById('eb-import-bar');
  const close=document.getElementById('eb-import-close');
  if(close)close.style.display='none';
  const setP=(done,total,msg)=>{
    if(prog)prog.textContent=msg;
    if(bar)bar.style.width=Math.round(done/Math.max(1,total)*100)+'%';
  };
  openM('m-eb-import');
  setP(0,good.length,'모두 '+good.length.toLocaleString()+'개를 올립니다'+(skipped?(' · 모양이 안 맞는 '+skipped+'개는 건너뜁니다'):''));
  const now=new Date().toISOString();
  let done=0,fail=0;
  for(let i=0;i<good.length;i+=50){
    const batch=good.slice(i,i+50).map(r=>({id:r.id,data:r.data,updated_at:now}));
    let ok=false;
    for(let t=0;t<2&&!ok;t++){
      try{
        const h={...SUPA_HEADERS,'Prefer':'resolution=merge-duplicates,return=minimal'};
        const res=await ppFetch(SUPA_URL+'/rest/v1/exam_bank',{method:'POST',headers:h,body:JSON.stringify(batch)});
        ok=!!(res&&res.ok);
      }catch(e){ok=false;}
    }
    if(ok)done+=batch.length;else fail+=batch.length;
    setP(done+fail,good.length,'올리는 중… '+done.toLocaleString()+' / '+good.length.toLocaleString()+(fail?(' · 실패 '+fail.toLocaleString()):''));
    await new Promise(r=>setTimeout(r,0));
  }
  setP(good.length,good.length,'끝났습니다 — 올린 자료 '+done.toLocaleString()+'개'+(fail?(' · 실패 '+fail.toLocaleString()+'개'):'')+(skipped?(' · 건너뜀 '+skipped.toLocaleString()+'개'):''));
  if(close)close.style.display='';
  if(done)await ebCacheClear();
}

// ── 상세 ────────────────────────────────────────────────────
function _ebPaintFav(){
  const b=document.getElementById('eb-d-fav');if(!b||!_ebDetailId)return;
  const on=ebIsFav(_ebDetailId);
  b.className='btn bsm '+(on?'bt':'bo');
  b.textContent=(on?'★':'☆')+' 즐겨찾기';
}
function ebDetailFav(){if(_ebDetailId)ebToggleFav(_ebDetailId);}
async function ebOpenDetail(id){
  if(!ebMayUse())return;
  _ebDetailId=id;_ebAuIdx=-1;_ebAuList=[];
  const row=(_ebRows||[]).find(r=>r.id===id),m=(row&&row.meta)||{};
  const t=document.getElementById('eb-d-title');if(t)t.textContent=m.title||'자료';
  const s=document.getElementById('eb-d-sub');
  // 원서·교재 줄은 시리즈와 폴더 경로가 같은 말일 때가 많다 — 같은 말은 한 번만
  if(s)s.textContent=[...new Set([_ebCatName(m.cat),m.grade||m.level,m.year?(m.year+'년'+(m.month?(' '+m.month+'월'):'')):'',m.term,m.school,m.series,m.path].filter(Boolean))].join(' · ');
  const body=document.getElementById('eb-d-body');
  if(body)body.innerHTML='<div class="eb-empty">불러오는 중…</div>';
  _ebPaintFav();
  openM('m-eb-detail');
  _ebRecentPush(id);
  const d=await _ebFullRow(id);
  if(_ebDetailId!==id)return;                                    // 그새 다른 자료를 열었다
  if(body)body.innerHTML=d?_ebDetailHtml(d):'<div class="eb-empty">자료를 불러오지 못했습니다. 잠시 후 다시 열어 주세요.</div>';
  try{lucide.createIcons();}catch(e){}
}
function _ebDetailHtml(d){
  const files=(Array.isArray(d.files)?d.files:[]).filter(f=>f&&f.id).slice();
  files.sort((a,b)=>{
    const ai=EB_KIND_ORDER.indexOf(a.k),bi=EB_KIND_ORDER.indexOf(b.k);
    if(ai!==bi)return (ai<0?9:ai)-(bi<0?9:bi);
    return String(a.name||'').localeCompare(String(b.name||''),'ko',{numeric:true});
  });
  const main=files.filter(f=>f.k!=='etc');          // 문제지·정답·해설·듣기대본
  const etc=files.filter(f=>f.k==='etc');           // 통계·분석표 등 — 합쳐진 폴더 자료도 여기로 온다
  const cat=String(d.cat||((((_ebRows||[]).find(r=>r.id===_ebDetailId)||{}).meta)||{}).cat||'');
  const auFirst=(cat==='audiobook');   // 원서는 음원이 주 — 듣기를 문서보다 위에 둔다
  _ebAuLbl=auFirst?'다음 트랙 ▶':'다음 문항 ▶';
  const au=(d.audio&&Array.isArray(d.audio.files)?d.audio.files:[]).filter(a=>a&&a.id).slice();
  au.sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'ko',{numeric:true}));
  const fileList=list=>'<div class="eb-files">'+list.map(f=>{
      const k=EB_KIND[f.k]||EB_KIND.etc;
      return '<button class="eb-file" onclick="ebView(\'' + escJsA(f.id) + '\',\'' + escJsA(f.name||'') + '\')" title="'+_ebA(f.name||'')+'">'+
        '<i data-lucide="'+k.i+'" width="15" height="15"></i>'+
        '<span class="eb-file-k">'+_ebE(k.n)+'</span>'+
        '<span class="eb-file-n">'+_ebE(f.name||'')+'</span>'+
        (f.size?'<span class="eb-file-s">'+Math.max(1,Math.round(f.size/1024)).toLocaleString()+'KB</span>':'')+
      '</button>';
    }).join('')+'</div>';
  let hDoc='';
  // 음원만 있는 줄(원서 한 권 등)에는 '등록된 문서가 없습니다'를 띄우지 않는다
  if(main.length||(!etc.length&&!au.length&&!d.extAudio)){
    hDoc+='<div class="eb-sec"><div class="eb-sec-t">문서 '+main.length+'개</div>';
    hDoc+=main.length?fileList(main):'<div class="eb-empty">등록된 문서가 없습니다.</div>';
    hDoc+='</div>';
  }
  if(etc.length)
    hDoc+='<div class="eb-sec"><div class="eb-sec-t">기타 자료 '+etc.length+'개</div>'+fileList(etc)+'</div>';
  let hAu='';
  if(au.length||d.extAudio){
    _ebAuList=au;_ebAuIdx=-1;
    hAu+='<div class="eb-sec"><div class="eb-sec-t">듣기'+(au.length?(' '+au.length+'개'):'')+'</div>';
    if(d.extAudio)
      hAu+='<div class="eb-au"><div class="eb-au-n">바깥 음원 (EBS 등)</div>'+
         '<audio controls preload="none" src="'+_ebA(d.extAudio)+'" style="width:100%"></audio></div>';
    if(au.length){
      // 드라이브 음원은 <audio> 로 직접 받으면 쿠키가 붙지 않아 막힌다(라이브 확인) —
      // 처음부터 드라이브 재생기로 열고, 누른 것 하나만 띄운다.
      hAu+='<div class="eb-aul">'+au.map((a,i)=>
        '<div class="eb-aui"><button class="eb-aub" id="eb-aub-'+i+'" onclick="ebAuOpen('+i+')">'+
          '<span class="eb-aup">▶</span><span class="eb-aun">'+_ebE(a.name||('음원 '+(i+1)))+'</span></button>'+
          '<div class="eb-aubox" id="eb-aubox-'+i+'" style="display:none"></div></div>').join('')+'</div>';
      hAu+='<div class="eb-note" style="margin-top:8px">드라이브 음원은 누르면 재생기가 열립니다 — 한 번에 하나만 열려요.</div>';
    }
    if(d.audio&&d.audio.folderId)
      hAu+='<div style="margin-top:8px"><a class="btn bo bsm" href="'+_ebA(ebFolderUrl(d.audio.folderId))+'" target="_blank" rel="noopener">듣기 폴더 열기</a></div>';
    hAu+='</div>';
  }
  let h=auFirst?(hAu+hDoc):(hDoc+hAu);   // 원서면 듣기가 먼저
  if(d.note)h+='<div class="eb-sec"><div class="eb-sec-t">메모</div><div class="eb-memo">'+_ebE(d.note)+'</div></div>';
  h+='<div class="eb-sec" style="display:flex;gap:8px;flex-wrap:wrap">';
  if(d.folderId)h+='<a class="btn bo bsm" href="'+_ebA(ebFolderUrl(d.folderId))+'" target="_blank" rel="noopener"><i data-lucide="folder" width="15" height="15" style="vertical-align:-3px"></i> 드라이브 폴더 열기</a>';
  // 같은 시험인데 폴더가 여러 개로 흩어져 있던 것 — 합치면서 챙긴 원래 폴더들
  (Array.isArray(d.extraFolders)?d.extraFolders:[]).filter(Boolean).forEach((fid,i)=>{
    h+='<a class="btn bo bsm" href="'+_ebA(ebFolderUrl(fid))+'" target="_blank" rel="noopener">'+
      '<i data-lucide="folder" width="15" height="15" style="vertical-align:-3px"></i> 합쳐진 폴더'+(i?(' '+(i+1)):'')+' 열기</a>';
  });
  h+='<button class="btn bo bsm" onclick="ebOpenSheet()"><i data-lucide="file-text" width="15" height="15" style="vertical-align:-3px"></i> 목록 시트</button>';
  h+='</div>';
  h+='<div class="eb-note">자료 계정 <b>'+_ebE(ebAcct())+'</b> 으로 엽니다. 비공개 드라이브라 "권한이 필요합니다"가 뜨면 미리보기 창의 <b>새 탭에서 열기</b>로 그 계정에 로그인해 주세요. (설정 → 자료 계정)</div>';
  return h;
}
// 드라이브 음원 — 누른 것 하나만 드라이브 재생기로 연다
// (라이브에서 drive.usercontent 의 mp3 는 쿠키가 붙지 않아 <audio> 로는 늘 막힌다)
function ebAuClose(i){
  const box=document.getElementById('eb-aubox-'+i);
  if(box){box.innerHTML='';box.style.display='none';}
  const b=document.getElementById('eb-aub-'+i);
  if(b)b.classList.remove('on');
  if(_ebAuIdx===i)_ebAuIdx=-1;
}
function ebAuOpen(i){
  if(_ebAuIdx>=0&&_ebAuIdx!==i)ebAuClose(_ebAuIdx);
  if(_ebAuIdx===i){ebAuClose(i);return;}            // 같은 것을 다시 누르면 닫는다
  const a=_ebAuList[i];if(!a)return;
  const box=document.getElementById('eb-aubox-'+i);if(!box)return;
  box.innerHTML='<iframe class="eb-aufr" src="'+_ebA(ebPreviewUrl(a.id))+'" allow="autoplay"></iframe>'+
    '<div class="eb-aunav">'+
    (i+1<_ebAuList.length?'<button class="btn bo bsm" onclick="ebAuOpen('+(i+1)+')">'+_ebE(_ebAuLbl)+'</button>':'')+
    '<a class="btn bo bsm" href="'+_ebA(ebViewUrl(a.id))+'" target="_blank" rel="noopener">새 탭에서 열기</a></div>';
  box.style.display='';
  const b=document.getElementById('eb-aub-'+i);if(b)b.classList.add('on');
  _ebAuIdx=i;
  try{box.scrollIntoView({block:'nearest'});}catch(e){}
}
function ebCloseDetail(){
  _ebAuIdx=-1;_ebAuList=[];_ebDetailId='';
  document.querySelectorAll('#eb-d-body audio').forEach(a=>{try{a.pause();}catch(e){}});
  document.querySelectorAll('#eb-d-body .eb-aubox').forEach(b=>{b.innerHTML='';b.style.display='none';});  // 재생기를 닫는다
  closeM('m-eb-detail');
}

// ── 문서 미리보기 ───────────────────────────────────────────
function ebView(fileId,name){
  _ebViewId=fileId;
  const t=document.getElementById('eb-view-title');if(t)t.textContent=name||'문서';
  const f=document.getElementById('eb-view-frame');if(f)f.src=ebPreviewUrl(fileId);
  openM('m-eb-view');
}
function ebViewClose(){
  try{if(document.fullscreenElement)document.exitFullscreen();}catch(e){}
  const f=document.getElementById('eb-view-frame');if(f)f.src='about:blank';
  closeM('m-eb-view');
}
function ebViewNewTab(){if(_ebViewId)window.open(ebViewUrl(_ebViewId),'_blank','noopener');}
function ebViewFull(){                                   // '수업에 띄우기' — 전체 화면 (ESC 로 빠져나감)
  const box=document.getElementById('eb-view-box');if(!box)return;
  try{
    if(document.fullscreenElement)document.exitFullscreen();
    else if(box.requestFullscreen)box.requestFullscreen();
  }catch(e){}
}

// ── 설정: 자료 계정 ─────────────────────────────────────────
function ebPaintAcct(){const el=document.getElementById('cfg-drive-acct');if(el)el.value=ebAcct();}
function ebSaveAcct(){
  const el=document.getElementById('cfg-drive-acct');if(!el)return;
  try{DB.s('driveAcct',String(el.value||'').trim());}catch(e){}
  _ebFull.clear();
  toast('자료 계정을 저장했습니다 ✓');
}

document.addEventListener('DOMContentLoaded',()=>{
  const d=document.getElementById('m-eb-detail');
  if(d)d.addEventListener('click',e=>{if(e.target===d)ebCloseDetail();});
  const v=document.getElementById('m-eb-view');
  if(v)v.addEventListener('click',e=>{if(e.target===v)ebViewClose();});
  document.addEventListener('keydown',e=>{
    if(e.key!=='Escape')return;
    const vv=document.getElementById('m-eb-view');
    if(vv&&vv.classList.contains('open')&&vv.style.display!=='none'&&!document.fullscreenElement){ebViewClose();return;}
    const dd=document.getElementById('m-eb-detail');
    if(dd&&dd.classList.contains('open')&&dd.style.display!=='none')ebCloseDetail();
  });
  ebPaintAcct();
});

// ══════════════════════════════════════════════════════════════════════════
// 동형 문제 만들기 (iso*) — 기출 문항과 같은 유형·같은 출제 원리로 새 문항을 만든다
//   · 원본(이미지·붙여넣은 글)은 claude-proxy 로만 보내고 어디에도 저장하지 않는다.
//     저장되는 것은 만들어진 문항뿐이다.
//   · 선생님 화면에만 있다 (학생·학부모·체험 모드에는 없다).
//   · 듣기 유형은 대본으로 만든다 — 음원은 만들지 않는다.
// ══════════════════════════════════════════════════════════════════════════
const ISO_MODEL='claude-opus-4-8';        // 워크시트 스튜디오와 같은 모델 정책
const ISO_MAX=10;                         // 한 번에 만들 수 있는 문항 수
const ISO_CFG_KEY='pp_iso_cfg';

// ── 유형 사전 ─────────────────────────────────────────────────────────────
// n 이름 · g 묶음 · w 출제 원리(생성 프롬프트에 그대로 들어간다) · s 서술형
const ISO_TYPES={
  l_purpose  :{g:'듣기',n:'목적',w:'담화 첫머리에 상황을 깔고 중반 이후 "그래서 ~해 주세요" 자리에서 목적이 한 번만 드러난다. 오답은 배경에 나온 소재를 목적처럼 바꿔 쓴다.'},
  l_opinion  :{g:'듣기',n:'의견',w:'두 사람 대화에서 한 사람이 같은 주장을 표현만 바꿔 두세 번 반복한다. 반복되는 쪽이 정답이다.'},
  l_gist     :{g:'듣기',n:'요지',w:'한 사람의 담화(방송·강연)에서 처음과 끝에 같은 말이 다른 표현으로 놓인다.'},
  l_pic      :{g:'듣기',n:'그림 불일치',w:'그림 속 사물의 수·위치·모양·무늬를 차례로 묘사하다 한 가지만 다르게 말한다.'},
  l_todo     :{g:'듣기',n:'할 일',w:'대화 끝부분에서 화자가 직접 맡기로 한 행동 하나가 정답. 상대가 할 일이 함정이다.'},
  l_pay      :{g:'듣기',n:'금액',w:'단가×개수에 할인이나 추가 비용을 한 번 더 얹는다. 할인을 빠뜨린 값이 오답으로 들어간다.'},
  l_why      :{g:'듣기',n:'이유',w:'제안을 거절하는 쪽의 마지막 설명이 이유. 앞에서 지나가듯 말한 다른 사정이 함정이다.'},
  l_not      :{g:'듣기',n:'언급하지 않은 것',w:'한 대상에 대해 네 가지 속성을 말하고 한 가지는 말하지 않는다.'},
  l_mismatch :{g:'듣기',n:'내용 불일치',w:'안내 담화의 날짜·장소·비용·준비물 가운데 한 가지만 선택지에서 바꾼다.'},
  l_table    :{g:'듣기',n:'도표(표) 고르기',w:'네다섯 조건을 차례로 걸러 하나만 남게 한다.'},
  l_short    :{g:'듣기',n:'짧은 대화 응답',w:'마지막 말에 대한 자연스러운 한 문장 응답. 오답은 앞 문장에 어울리는 말이다.'},
  l_long     :{g:'듣기',n:'긴 대화 응답',w:'상황이 쌓인 뒤 마지막 말에 답하는 한 문장. 바로 앞 문장의 요청·제안에 대답해야 한다.'},
  l_situation:{g:'듣기',n:'상황에 맞는 말',w:'제3자가 상황을 설명한 뒤 "A가 B에게 할 말"을 고른다. 상황의 핵심 갈등을 푸는 말이 정답.'},
  l_set      :{g:'듣기',n:'세트(주제·언급)',w:'한 담화로 주제 한 문항과 언급된 것 한 문항을 낸다. 주제는 담화 첫 문장에 둔다.'},

  purpose    :{g:'읽기',n:'글의 목적',w:'편지·이메일 형식. 앞은 배경과 인사, 중반 이후 한 문장에서 목적이 드러난다. 오답은 배경에 나온 소재를 목적처럼 바꾼다.'},
  mood       :{g:'읽기',n:'심경·분위기',w:'사건 전후로 감정이 한 번 뒤집힌다. 정답은 "A → B" 두 형용사 쌍이고, 오답은 앞쪽이나 뒤쪽 한쪽만 맞다.'},
  claim      :{g:'읽기',n:'주장',w:'필자가 should·must·need to 로 한 번 못 박는다. 오답은 근거로 든 사실을 주장처럼 쓴다.'},
  implicit   :{g:'읽기',n:'함축 의미',w:'밑줄 친 비유 표현을 글 전체의 주장으로 바꿔 말한 것이 정답. 오답은 비유를 글자 그대로 푼다.'},
  gist       :{g:'읽기',n:'요지',w:'한국어 선택지. 글 전체가 말하려는 바를 한 문장으로. 오답은 한 단락만 맞다.'},
  topic      :{g:'읽기',n:'주제',w:'영어 명사구 선택지. 다루는 범위까지 맞아야 한다. 범위가 넓거나 좁은 것이 오답.'},
  title      :{g:'읽기',n:'제목',w:'주제를 함축적으로. 정답은 글 전체를 덮으면서 핵심어를 담는다. 오답은 지문 낱말을 재활용한다.'},
  chart      :{g:'읽기',n:'도표',w:'표·그래프 수치를 문장으로 옮긴 다섯 문장 가운데 하나만 수치와 어긋나게 한다(비교급·배수·증감).'},
  bio        :{g:'읽기',n:'내용 불일치(인물·대상)',w:'소개문의 연도·직업·업적 가운데 한 가지만 선택지에서 뒤집는다.'},
  notice     :{g:'읽기',n:'안내문 일치/불일치',w:'행사 안내의 일시·대상·참가비·준비물 가운데 한 줄만 바꾼다. 안내문에 없는 내용은 정답이 될 수 없다.'},
  grammar    :{g:'읽기',n:'어법',w:'밑줄 다섯 개 가운데 하나만 틀리게. 수 일치·시제·태·관계사·준동사·병렬 가운데에서 고르고, 틀린 자리는 문장 구조를 봐야 보이게 만든다.'},
  vocab      :{g:'읽기',n:'어휘 쓰임',w:'문맥상 반대말로 바꿔 넣은 한 낱말이 정답. 나머지는 문맥에 맞는 말이다.'},
  blank      :{g:'읽기',n:'빈칸 추론',w:'글의 핵심 주장을 다른 말로 바꾼 표현이 정답. 오답은 지문 낱말을 그대로 재활용한 함정이다. 빈칸은 주제문 자리에 둔다.'},
  irrelevant :{g:'읽기',n:'무관한 문장',w:'같은 소재를 쓰지만 논지의 방향이 다른 문장을 하나 끼워 넣는다. 앞뒤 연결이 어색해 보이지 않게 쓴다.'},
  order      :{g:'읽기',n:'글의 순서',w:'주어진 글 뒤에 (A)(B)(C). 지시어·연결어·정관사가 순서의 단서가 되게 한다.'},
  insert     :{g:'읽기',n:'문장 삽입',w:'주어진 문장의 지시어·연결어가 가리키는 자리 하나만 자연스럽게. 그 자리 앞뒤에 논리 공백을 만들어 둔다.'},
  summary    :{g:'읽기',n:'요약문 빈칸',w:'요약문 한 문장에 빈칸 (A)(B). 두 칸이 글의 원인과 결과를 각각 다른 말로 바꾼 표현이어야 한다.'},
  long2      :{g:'읽기',n:'장문(제목·어휘)',w:'긴 지문 하나로 제목 한 문항과 문맥상 낱말 쓰임 한 문항을 낸다.'},
  long3      :{g:'읽기',n:'장문(순서·지칭·내용)',w:'(A)~(D) 이야기 글로 순서·지칭 대상·내용 일치 세 문항을 한 지문에서 낸다.'},

  m_grammar_pick :{g:'중등·내신',n:'어법 고르기',w:'네모 안 두 형태 가운데 맞는 것 고르기, 또는 밑줄 가운데 틀린 것 찾기. 교과서에서 배운 문법 항목에서만 낸다.'},
  m_grammar_fix  :{g:'중등·내신',n:'어법 고쳐 쓰기',w:'틀린 부분을 찾아 바르게 고쳐 쓴다. 고칠 곳과 고치는 방법이 하나로 정해지게 만든다.',s:true},
  m_vocab        :{g:'중등·내신',n:'어휘 쓰임',w:'문맥에 맞지 않는 낱말 하나. 반대말이나 혼동하기 쉬운 짝을 쓴다.'},
  m_blank        :{g:'중등·내신',n:'빈칸(단어·구·문장)',w:'본문 흐름상 한 자리에만 들어갈 말. 연결어·대명사가 단서가 되게 한다.'},
  m_order        :{g:'중등·내신',n:'순서 배열',w:'본문 문장을 섞어 순서 맞추기. 시간 표현·지시어가 단서가 된다.'},
  m_insert       :{g:'중등·내신',n:'문장 삽입',w:'주어진 문장이 들어갈 자리 하나.'},
  m_topic        :{g:'중등·내신',n:'주제·제목·요지',w:'본문이 말하려는 바 한 가지. 교과서 수준 어휘로 쓴다.'},
  m_match        :{g:'중등·내신',n:'내용 일치',w:'본문에 나온 사실만 묻는다. 추측해야 하는 선택지는 넣지 않는다.'},
  m_ref          :{g:'중등·내신',n:'지칭 추론',w:'밑줄 친 대명사가 가리키는 대상. 하나만 다르게 한다.'},
  m_dialog       :{g:'중등·내신',n:'대화 응답',w:'교과서 의사소통 기능(제안·허락·길 묻기 등)에 맞는 응답.'},
  m_write_cond   :{g:'중등·내신',n:'조건 영작',w:'주어진 낱말과 문법 조건을 모두 지켜 한 문장으로 쓴다. 조건을 분명히 적어 답이 하나로 나오게 한다.',s:true},
  m_write_order  :{g:'중등·내신',n:'배열 영작',w:'주어진 낱말을 바른 순서로 배열한다. 답이 하나로만 나오게 낱말을 고른다.',s:true},
  m_summary      :{g:'중등·내신',n:'서술형 요약',w:'본문을 정해진 낱말 수로 요약한다. 핵심어를 반드시 쓰게 한다.',s:true},
  m_textbook     :{g:'중등·내신',n:'교과서 본문 변형',w:'본문 문장을 그대로 쓰되 어법·어휘·순서 가운데 한 곳만 바꿔 묻는다. 내신 대비용.'}
};
// 고등 전국 단위(2015학년도 이후 수능·모평·학평) 번호 → 유형
const ISO_HS_NO={1:'l_purpose',2:'l_opinion',3:'l_gist',4:'l_pic',5:'l_todo',6:'l_pay',7:'l_why',8:'l_not',9:'l_mismatch',10:'l_table',
  11:'l_short',12:'l_short',13:'l_long',14:'l_long',15:'l_situation',16:'l_set',17:'l_set',
  18:'purpose',19:'mood',20:'claim',21:'implicit',22:'gist',23:'topic',24:'title',25:'chart',26:'bio',27:'notice',28:'notice',
  29:'grammar',30:'vocab',31:'blank',32:'blank',33:'blank',34:'blank',35:'irrelevant',36:'order',37:'order',38:'insert',39:'insert',
  40:'summary',41:'long2',42:'long2',43:'long3',44:'long3',45:'long3'};

// ── 상태 ──────────────────────────────────────────────────────────────────
let _isoImgs=[];          // [{mime,b64,name}] — 화면에만 들고 있다가 보내고 버린다 (저장 안 함)
let _isoText='';          // 붙여넣은 원본 글 — 역시 저장하지 않는다
let _isoInfo={title:'',cat:'',grade:''};   // 자료실에서 들고 온 시험 정보 (출처 표기에만 쓴다)
let _isoItems=[];
let _isoAnalysis=null;
let _isoUse={calls:0,in:0,out:0};
let _isoBusy=false,_isoRowId='',_isoTitle='';
let _isoCfg={n:3,type:'',qno:'',diff:'same',grade:'고1',passage:'new',topic:'',tbId:'',unit:'',choices:0,rubric:true,cols:1};

function isoMayUse(){
  try{
    if(typeof ppSandbox==='function'&&ppSandbox())return false;
    const s=(typeof loadSession==='function')?loadSession():null;
    return !!(s&&s.role==='teacher');
  }catch(e){return false;}
}
function _isoSaveCfg(){try{localStorage.setItem(ISO_CFG_KEY,JSON.stringify(_isoCfg));}catch(e){}}
function _isoLoadCfg(){try{const s=JSON.parse(localStorage.getItem(ISO_CFG_KEY)||'null');if(s&&typeof s==='object')_isoCfg={..._isoCfg,...s};}catch(e){}}
function _isoTypeName(k){const t=ISO_TYPES[k];return t?(t.g+' · '+t.n):'';}
function _isoIsEssay(k){return !!(ISO_TYPES[k]&&ISO_TYPES[k].s);}
function _isoCirc(i){return '①②③④⑤⑥⑦'.charAt(i)||String(i+1);}

// ── 원본 넣기 ─────────────────────────────────────────────────────────────
function isoPickImgs(){const f=document.getElementById('iso-img-file');if(f)f.click();}
async function isoImgFiles(ev){
  const fs=[...((ev&&ev.target&&ev.target.files)||[])];
  if(ev&&ev.target)ev.target.value='';
  for(const f of fs)await isoAddImage(f);
}
async function isoAddImage(file){
  if(!file)return;
  if(file.type==='application/pdf'){
    try{
      const b64s=await pdfAllPagesToB64(file,4);
      b64s.forEach((b,i)=>_isoImgs.push({mime:'image/jpeg',b64:b,name:(file.name||'PDF')+' '+(i+1)+'쪽'}));
      _isoPaintSrc();
    }catch(e){toast('PDF를 읽지 못했어요');}
    return;
  }
  if(!file.type||!file.type.startsWith('image/')){toast('이미지 파일이 아니에요');return;}
  if(typeof checkFileSize==='function'&&!checkFileSize(file,8))return;
  if(_isoImgs.length>=6){toast('이미지는 6장까지예요');return;}
  try{
    const dataUrl=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('읽기 실패'));r.readAsDataURL(file);});
    const m=String(dataUrl).match(/^data:(image\/[\w.+-]+);base64,(.+)$/s);
    if(!m)throw new Error('형식');
    _isoImgs.push({mime:m[1],b64:m[2],name:file.name||('이미지 '+(_isoImgs.length+1))});
    _isoPaintSrc();
  }catch(e){toast('이미지를 읽지 못했어요');}
}
function isoDelImage(i){_isoImgs.splice(i,1);_isoPaintSrc();}
function isoClearSrc(){
  _isoImgs=[];_isoText='';_isoAnalysis=null;
  const t=document.getElementById('iso-text');if(t)t.value='';
  _isoPaintSrc();
}
function isoTextChange(){const t=document.getElementById('iso-text');_isoText=t?t.value:'';_isoPaintSrc();}
function _isoPaintSrc(){
  const box=document.getElementById('iso-imgs');
  if(box){
    box.innerHTML=_isoImgs.map((im,i)=>
      '<div class="iso-thumb"><img src="data:'+im.mime+';base64,'+im.b64+'" alt="">'+
      '<button class="iso-thumb-x" title="빼기" onclick="isoDelImage('+i+')">×</button></div>').join('');
    box.style.display=_isoImgs.length?'':'none';
  }
  const st=document.getElementById('iso-src-state');
  if(st){
    const bits=[];
    if(_isoImgs.length)bits.push('이미지 '+_isoImgs.length+'장');
    if((_isoText||'').trim())bits.push('붙여넣은 글 '+(_isoText.trim().length.toLocaleString())+'자');
    if(!bits.length)bits.push('원본 없음 — 유형만 골라 만들 수 있어요');
    st.textContent=bits.join(' · ');
  }
  const b=document.getElementById('iso-go');
  if(b)b.disabled=_isoBusy||!(_isoImgs.length||(_isoText||'').trim()||_isoCfg.type);
}
// 자료실 미리보기에서 바로 들어오기
function isoFromExam(){
  const row=(_ebRows||[]).find(r=>r.id===_ebDetailId),m=(row&&row.meta)||{};
  _isoInfo={title:String(m.title||''),cat:String(m.cat||''),grade:String(m.grade||m.level||'')};
  if(m.grade)_isoCfg.grade=String(m.grade);
  try{ebViewClose();ebCloseDetail();}catch(e){}
  swTab('t-data');switchDataTab('iso');
  toast('시험 정보를 가져왔어요 — 문항을 캡처해 Ctrl+V 로 붙여넣으세요');
}
function isoQnoChange(){
  const el=document.getElementById('iso-qno');
  _isoCfg.qno=el?String(el.value||'').trim():'';
  const n=parseInt(_isoCfg.qno,10);
  if(isFinite(n)&&ISO_HS_NO[n]){
    _isoCfg.type=ISO_HS_NO[n];
    const ts=document.getElementById('iso-type');if(ts)ts.value=_isoCfg.type;
    const h=document.getElementById('iso-type-hint');
    if(h)h.textContent=n+'번은 보통 「'+_isoTypeName(_isoCfg.type)+'」이에요 — 다르면 아래에서 바꾸세요.';
  }
  _isoSaveCfg();_isoPaintCfg();
}

// ── 설정 ──────────────────────────────────────────────────────────────────
function _isoOpts(id,label,vals,cur){
  const el=document.getElementById(id);if(!el)return;
  el.innerHTML=['<option value="">'+_ebE(label)+'</option>'].concat(vals.map(v=>
    '<option value="'+_ebA(v.v)+'"'+(String(cur)===String(v.v)?' selected':'')+'>'+_ebE(v.n)+'</option>')).join('');
}
function isoCfgChange(){
  const v=id=>{const el=document.getElementById(id);return el?el.value:'';};
  const c=id=>{const el=document.getElementById(id);return !!(el&&el.checked);};
  _isoCfg.n=Math.max(1,Math.min(ISO_MAX,parseInt(v('iso-n'),10)||3));
  _isoCfg.type=v('iso-type');_isoCfg.diff=v('iso-diff')||'same';_isoCfg.grade=v('iso-grade')||'고1';
  _isoCfg.passage=v('iso-passage')||'new';_isoCfg.topic=v('iso-topic');
  _isoCfg.tbId=v('iso-tb');_isoCfg.unit=v('iso-unit');
  _isoCfg.choices=parseInt(v('iso-choices'),10)||0;
  _isoCfg.rubric=c('iso-rubric');
  _isoSaveCfg();_isoPaintCfg();
}
function _isoPaintCfg(){
  const set=(id,val)=>{const el=document.getElementById(id);if(el&&el.value!==String(val))el.value=String(val);};
  set('iso-n',_isoCfg.n);set('iso-diff',_isoCfg.diff);set('iso-grade',_isoCfg.grade);
  set('iso-passage',_isoCfg.passage);set('iso-topic',_isoCfg.topic);set('iso-choices',_isoCfg.choices);set('iso-qno',_isoCfg.qno);
  const r=document.getElementById('iso-rubric');if(r)r.checked=!!_isoCfg.rubric;
  // 유형 칸
  const ts=document.getElementById('iso-type');
  if(ts&&!ts.options.length){
    const groups={};Object.keys(ISO_TYPES).forEach(k=>{const t=ISO_TYPES[k];(groups[t.g]=groups[t.g]||[]).push({k:k,n:t.n});});
    ts.innerHTML='<option value="">유형 고르기 (원본을 넣으면 자동으로 찾아요)</option>'+
      Object.keys(groups).map(g=>'<optgroup label="'+_ebA(g)+'">'+
        groups[g].map(x=>'<option value="'+_ebA(x.k)+'">'+_ebE(x.n)+'</option>').join('')+'</optgroup>').join('');
  }
  if(ts)ts.value=_isoCfg.type||'';
  // 출제 원리 미리보기
  const w=document.getElementById('iso-type-w');
  if(w){
    const t=ISO_TYPES[_isoCfg.type];
    w.innerHTML=t?('<b>'+_ebE(t.n)+'</b> — '+_ebE(t.w)):'';
    w.style.display=t?'':'none';
  }
  // 교재 본문 고르기
  const bookRow=document.getElementById('iso-book-row');
  if(bookRow)bookRow.style.display=(_isoCfg.passage==='book')?'':'none';
  const topicRow=document.getElementById('iso-topic-row');
  if(topicRow)topicRow.style.display=(_isoCfg.passage==='new')?'':'none';
  if(_isoCfg.passage==='book'){
    const tbs=(_cache.globalTextbooks||[]).filter(b=>b&&b.unitTexts&&Object.keys(b.unitTexts).some(u=>String(b.unitTexts[u]||'').trim())
      &&!(typeof ppIsSongTb==='function'&&ppIsSongTb(b)));   // 노래 교재(가사)는 빼 둔다
    const sel=document.getElementById('iso-tb');
    if(sel&&sel.options.length!==tbs.length+1)
      _isoOpts('iso-tb','교재 고르기',tbs.map(b=>({v:b.id,n:b.title||'(제목 없음)'})),_isoCfg.tbId);
    else if(sel)sel.value=_isoCfg.tbId||'';
    const tb=tbs.find(b=>b.id===_isoCfg.tbId);
    const units=tb?Object.keys(tb.unitTexts||{}).filter(u=>String(tb.unitTexts[u]||'').trim()):[];
    _isoOpts('iso-unit','단원 고르기',units.map(u=>({v:u,n:u+(tb.unitTitles&&tb.unitTitles[u]?(' '+tb.unitTitles[u]):'')})),_isoCfg.unit);
    const prev=document.getElementById('iso-book-prev');
    const txt=(tb&&_isoCfg.unit)?String(tb.unitTexts[_isoCfg.unit]||''):'';
    if(prev){prev.textContent=txt?(txt.slice(0,160)+(txt.length>160?'…':'')):'';prev.style.display=txt?'':'none';}
  }
  // 서술형 채점 기준 칸은 서술형 유형일 때만
  const rr=document.getElementById('iso-rubric-row');
  if(rr)rr.style.display=_isoIsEssay(_isoCfg.type)?'':'none';
  _isoPaintSrc();
}
let _isoBookOverride='';            // 학습 세트가 넘겨 준 본문 (있으면 이걸 쓴다)
function _isoBookText(){
  if(_isoBookOverride)return _isoBookOverride;
  const tb=(_cache.globalTextbooks||[]).find(b=>b.id===_isoCfg.tbId);
  if(!tb||!_isoCfg.unit)return '';
  return String((tb.unitTexts||{})[_isoCfg.unit]||'').trim();
}

// ── AI 호출 ───────────────────────────────────────────────────────────────
function _isoStat(msg,pct){
  const s=document.getElementById('iso-state');if(s)s.textContent=msg||'';
  const b=document.getElementById('iso-bar');if(b)b.style.width=Math.max(0,Math.min(100,pct||0))+'%';
  const w=document.getElementById('iso-prog');if(w)w.style.display=(msg?'':'none');
}
function _isoCost(){
  const el=document.getElementById('iso-cost');if(!el)return;
  if(!_isoUse.calls){el.textContent='';return;}
  el.textContent='AI 호출 '+_isoUse.calls+'회 · 보낸 토큰 약 '+_isoUse.in.toLocaleString()+
    ' · 받은 토큰 약 '+_isoUse.out.toLocaleString()+' ('+ISO_MODEL+')';
}
async function _isoCall(content,maxTok){
  const d=await callClaudeProxy({model:ISO_MODEL,max_tokens:maxTok||8000,messages:[{role:'user',content:content}]});
  try{
    _isoUse.calls++;
    _isoUse.in+=Number(d&&d.usage&&d.usage.input_tokens)||0;
    _isoUse.out+=Number(d&&d.usage&&d.usage.output_tokens)||0;
    _isoCost();
  }catch(e){}
  return String((d&&d.content&&d.content[0]&&d.content[0].text)||'');
}
function _isoJson(raw){
  let s=String(raw||'').replace(/```json|```/g,'').trim();
  const i=s.search(/[\[{]/);if(i>0)s=s.slice(i);
  const j=Math.max(s.lastIndexOf('}'),s.lastIndexOf(']'));if(j>0)s=s.slice(0,j+1);
  try{return JSON.parse(s);}catch(e){}
  try{return JSON.parse(tryRepairJSON(s));}catch(e){}
  throw new Error('AI 응답을 읽지 못했어요');
}
const ISO_RULES=
 '공통 규칙\n'+
 '- 사실 오류를 쓰지 않는다. 실존 인물·기관에 대한 없는 사실을 지어내지 않는다(가상 인물은 가상임이 드러나게).\n'+
 '- 저작권이 있는 원문을 그대로 옮기지 않는다. 지문은 새로 쓴다.\n'+
 '- 정답은 하나로만 정해져야 한다. 두 선택지가 모두 맞을 여지를 남기지 않는다.\n'+
 '- 선택지는 길이를 비슷하게 맞춘다. 정답만 유독 길거나 짧지 않게 한다.\n'+
 '- 해설은 한국어로 쓰고, 정답 근거가 되는 지문 문장을 큰따옴표로 인용한다. 네가 쓴 지문에 실제로 있는 문장만 인용한다.\n'+
 '- 듣기 유형이면 음원 대신 대본(script)을 지문 자리에 쓴다.\n';
function _isoItemShape(essay){
  return essay
    ? '{"stem":"발문(한국어)","passage":"지문 또는 조건(영어 지문은 영어로)","choices":[],"answerText":"모범 답안","rubric":"채점 기준(배점 포함)","explain":"해설(한국어)","intent":"출제 의도"}'
    : '{"stem":"발문(한국어)","passage":"지문(영어)","choices":["①에 들어갈 말","②","③","④","⑤"],"answer":0,"explain":"해설(한국어, 근거 문장 인용)","intent":"출제 의도","wrong":["①이 답이 아닌 이유","②..."]}';
}

// 호출 1 — 원본 분석
async function _isoAnalyze(){
  const content=[];
  _isoImgs.forEach(im=>content.push({type:'image',source:{type:'base64',media_type:im.mime,data:im.b64}}));
  const keys=Object.keys(ISO_TYPES).map(k=>k+'='+ISO_TYPES[k].n).join(', ');
  content.push({type:'text',text:
    '아래는 한국 영어 시험의 문항입니다'+((_isoText||'').trim()?('(이미지 아래 글도 같은 문항입니다)'):'')+'. 분석해서 JSON 으로만 답하세요.\n'+
    ((_isoText||'').trim()?('\n--- 원본 글 ---\n'+_isoText.trim()+'\n--- 끝 ---\n'):'')+
    '\n{"type":"유형키","typeName":"유형 이름","stem":"발문","passage":"지문 원문","choices":["..."],"answer":0,'+
    '"evidence":"정답 근거 문장","points":["출제 포인트"],"words":지문 단어 수,"level":"어휘 수준(예: 고1 수준)","distractors":"오답을 어떻게 만들었는지"}\n'+
    '\n유형키는 다음 가운데 하나입니다: '+keys+'\n'+
    '- answer 는 0 부터 센 정답 번호입니다. 정답을 알 수 없으면 -1.\n'+
    '- 읽을 수 없는 항목은 빈 문자열로 둡니다. JSON 외의 글자는 쓰지 마세요.'});
  const txt=await _isoCall(content,4000);
  const a=_isoJson(txt);
  if(a&&a.type&&!ISO_TYPES[a.type])a.type=_isoCfg.type||'';
  return a;
}
// 호출 2 — 생성
async function _isoCreate(n,extra){
  const key=_isoCfg.type||(_isoAnalysis&&_isoAnalysis.type)||'';
  const t=ISO_TYPES[key]||{n:'',w:''};
  const essay=_isoIsEssay(key);
  const srcW=Number(_isoAnalysis&&_isoAnalysis.words)||0;   // 원본 지문 단어 수
  const diff={same:'원본과 같은 난이도',easy:'원본보다 한 단계 쉽게',hard:'원본보다 한 단계 어렵게'}[_isoCfg.diff]||'원본과 같은 난이도';
  const lines=[];
  lines.push('너는 한국 영어 시험 출제 경험이 많은 선생님이다. 아래 조건으로 새 문항 '+n+'개를 만들어 JSON 배열로만 답하라.');
  lines.push('\n[유형] '+t.n+'\n[출제 원리] '+t.w);
  if(_isoAnalysis){
    lines.push('\n[원본 분석]\n'+JSON.stringify({
      stem:_isoAnalysis.stem||'',choices:(_isoAnalysis.choices||[]).length,
      words:_isoAnalysis.words||'',level:_isoAnalysis.level||'',
      points:_isoAnalysis.points||[],distractors:_isoAnalysis.distractors||''
    }));
    lines.push('원본과 같은 발문 형식, 같은 선택지 수로 만든다.');
  }
  lines.push('\n[설정]');
  lines.push('- 학년·수준: '+_isoCfg.grade+' 교육과정 어휘 수준 · '+diff);
  if(_isoCfg.choices)lines.push('- 선택지 수: '+_isoCfg.choices+'개');
  if(_isoCfg.passage==='keep'){
    const p=(_isoAnalysis&&_isoAnalysis.passage)||'';
    lines.push('- 지문: 아래 원본 지문을 그대로 두고 문항만 바꾼다(밑줄 위치·선택지·정답을 다르게). 내신 변형 문제 방식.');
    if(p)lines.push('\n--- 원본 지문 ---\n'+p+'\n--- 끝 ---');
  }else if(_isoCfg.passage==='book'){
    const bt=_isoBookText();
    lines.push('- 지문: 아래 교재 본문의 문장을 글자 그대로 쓴다. 낱말을 바꾸거나 문장을 새로 쓰거나 다시 풀어 쓰지 마라.');
    lines.push('  네모·밑줄·빈칸 표시만 본문 위에 얹는다. 본문이 길면 이어지는 한 토막을 그대로 잘라 쓴다.');
    lines.push('\n--- 교재 본문 ---\n'+bt+'\n--- 끝 ---');
  }else{
    lines.push('- 지문: 새로 쓴다.'+(_isoCfg.topic?(' 주제는 "'+_isoCfg.topic+'" 쪽으로.'):' 주제는 자유롭게 고르되 문항마다 다르게.'));
  }
  if(srcW&&_isoCfg.passage!=='keep'){   // 새 지문이 자꾸 20% 넘게 짧아져서 숫자로 못 박는다
    const lo=Math.round(srcW*0.9),hi=Math.round(srcW*1.1);
    lines.push('- 지문 길이: 원본은 '+srcW+'단어다. 새 지문은 '+srcW+'단어 안팎, 반드시 '+lo+'~'+hi+'단어로 쓴다.');
    lines.push('  다 쓴 뒤 단어 수를 세어 '+lo+'단어보다 짧으면 내용을 더 붙여 채운다. 요약하듯 줄이지 마라.');
  }
  lines.push('- 정답 위치는 문항마다 고르게 흩어지게 한다(모두 같은 번호가 되지 않게).');
  if(essay&&_isoCfg.rubric)lines.push('- 서술형이므로 채점 기준(배점 포함)을 반드시 쓴다.');
  if(extra)lines.push('\n[다시 만드는 이유] '+extra);
  lines.push('\n'+ISO_RULES);
  lines.push('\n[출력 형식] 아래 모양의 객체 '+n+'개를 담은 JSON 배열. JSON 외의 글자는 쓰지 마라.\n'+_isoItemShape(essay));
  const txt=await _isoCall([{type:'text',text:lines.join('\n')}],16000);
  let arr=_isoJson(txt);
  if(!Array.isArray(arr))arr=[arr];
  const sw=srcW;
  const keep=(_isoCfg.passage==='keep');   // 기출·출판사 원문 지문 — 저장하지 않고 인쇄만
  return arr.map(x=>{const it=_isoNorm(x,key);it.srcWords=sw;it.srcKeep=keep;return it;});
}
function _isoNorm(x,key){
  const essay=_isoIsEssay(key);
  const ch=Array.isArray(x.choices)?x.choices.map(c=>String(c==null?'':c)):[];
  return {
    id:uid(),type:key,typeName:_isoTypeName(key),
    stem:String(x.stem||''),passage:String(x.passage||''),
    choices:essay?[]:ch,
    answer:essay?-1:(isFinite(Number(x.answer))?Math.max(0,Math.min(ch.length-1,Number(x.answer))):0),
    answerText:String(x.answerText||''),rubric:String(x.rubric||''),
    explain:String(x.explain||''),intent:String(x.intent||''),
    wrong:Array.isArray(x.wrong)?x.wrong.map(String):[],
    check:false,checkNote:'',createdAt:Date.now()
  };
}
// 호출 3 — 검증 (정답을 숨기고 다시 풀게 한다)
async function _isoVerify(items){
  const quiz=items.map((it,i)=>({
    no:i+1,stem:it.stem,passage:it.passage,
    choices:it.choices.map((c,j)=>_isoCirc(j)+' '+c)
  }));
  const txt=await _isoCall([{type:'text',text:
    '아래 영어 문항을 학생처럼 풀어라. 정답은 주어지지 않았다. JSON 배열로만 답하라.\n'+
    '- 문항은 모두 '+items.length+'개다. 반드시 '+items.length+'개의 객체를 돌려라.\n'+
    '- 각 객체의 no 는 문제에 적힌 no 를 그대로 쓴다. 순서를 바꾸거나 빠뜨리지 마라.\n'+
    '[{"no":1,"answer":0,"evidence":"그렇게 고른 근거가 되는 지문 문장","alt":true 또는 false,"why":"복수 정답이 될 수 있다면 그 이유"}]\n'+
    '- answer 는 0 부터 센 번호다.\n- alt 는 다른 선택지도 정답이 될 수 있으면 true.\n- 서술형(선택지가 없는 문항)은 answer 를 -1 로 두고 evidence 에 모범 답안을 쓴다.\n'+
    '- JSON 외의 글자는 쓰지 마라.\n\n'+JSON.stringify(quiz)}],8000);
  const got=_isoJson(txt);
  const by={};(Array.isArray(got)?got:[]).forEach(g=>{if(g&&isFinite(Number(g.no)))by[Number(g.no)]=g;});
  items.forEach((it,i)=>{
    const g=by[i+1];
    if(!g){it.check=true;it.checkNote='검증 응답이 없어요 — 직접 확인해 주세요.';return;}
    if(it.choices.length){
      if(Number(g.answer)!==Number(it.answer)){
        it.check=true;it.checkNote='AI가 다시 풀었을 때 '+_isoCirc(Number(g.answer))+'를 골랐어요. '+(g.why||g.evidence||'');
      }else if(g.alt){
        it.check=true;it.checkNote='복수 정답 가능성: '+(g.why||'');
      }else{it.check=false;it.checkNote='';}
    }else{
      it.check=false;it.checkNote='';it.verifyAnswer=String(g.evidence||'');
    }
  });
  return items;
}

// ── 만들기 ────────────────────────────────────────────────────────────────
async function isoGenerate(){
  if(_isoBusy)return;
  if(!isoMayUse()){toast('선생님 화면에서만 쓸 수 있어요');return;}
  const hasSrc=_isoImgs.length||(_isoText||'').trim();
  if(!hasSrc&&!_isoCfg.type){toast('원본을 넣거나 유형을 골라 주세요');return;}
  if(_isoCfg.passage==='book'&&!_isoBookText()){toast('교재와 단원을 고르면 본문을 씁니다');return;}
  _isoBusy=true;_isoPaintSrc();
  let okMade=false;
  const btn=document.getElementById('iso-go');if(btn)btn.disabled=true;
  try{
    if(hasSrc){
      _isoStat('① 원본을 분석하는 중…',12);
      _isoAnalysis=await _isoAnalyze();
      if(_isoAnalysis&&_isoAnalysis.type&&!_isoCfg.type){
        _isoCfg.type=_isoAnalysis.type;
        const ts=document.getElementById('iso-type');if(ts)ts.value=_isoCfg.type;
        _isoSaveCfg();_isoPaintCfg();
      }
      _isoStat('① 분석 끝 — 「'+_isoTypeName(_isoCfg.type)+'」',35);
    }else{_isoAnalysis=null;}
    _isoStat('② 문항 '+_isoCfg.n+'개를 만드는 중…',45);
    const made=await _isoCreate(_isoCfg.n,'');
    _isoItems=made;_isoRender();                       // 검증 전이라도 먼저 보여 준다
    _isoStat('③ 만든 문항을 다시 풀어 확인하는 중…',78);
    try{await _isoVerify(_isoItems);}
    catch(e){_isoItems.forEach(it=>{it.check=true;it.checkNote='검증을 하지 못했어요 — 직접 확인해 주세요.';});}
    _isoRender();
    _isoStat('',100);
    const bad=_isoItems.filter(it=>it.check).length;
    toast(bad?('문항 '+_isoItems.length+'개 — 확인 필요 '+bad+'개'):('문항 '+_isoItems.length+'개를 만들었어요 ✓'));
    okMade=true;
  }catch(e){
    console.warn('iso:',e);
    _isoStat('',0);
    toast('만들기 실패: '+((e&&e.message)||'알 수 없는 오류'));
  }finally{
    _isoBusy=false;
    const b=document.getElementById('iso-go');if(b)b.disabled=false;
    _isoPaintSrc();_isoRender();
  }
  if(okMade){
    try{await _isoAutoSave(false);}catch(e){}   // 만든 직후 자동 저장
    _isoScrollToFirst();                        // 첫 문항 카드가 보이게 내려 준다
  }
}
async function isoRegen(i){
  if(_isoBusy)return;
  const old=_isoItems[i];if(!old)return;
  _isoBusy=true;_isoRender();
  let okRe=false;
  try{
    _isoStat('문항 '+(i+1)+'번을 다시 만드는 중…',40);
    const why=old.check?('앞서 만든 문항에 이런 문제가 있었다: '+old.checkNote+' 같은 실수를 하지 마라.')
                       :'앞서 만든 문항과 지문·정답이 겹치지 않게 다르게 만들어라.';
    const made=await _isoCreate(1,why);
    if(made&&made[0]){
      _isoStat('다시 푼 결과를 확인하는 중…',75);
      try{await _isoVerify(made);}catch(e){made[0].check=true;made[0].checkNote='검증을 하지 못했어요.';}
      _isoItems[i]=made[0];okRe=true;
    }
    _isoStat('',100);
  }catch(e){toast('다시 만들기 실패: '+((e&&e.message)||''));_isoStat('',0);}
  finally{_isoBusy=false;_isoRender();if(okRe)_isoAutoSave(false);}   // 다시 만든 뒤 자동 저장
}
function isoMove(i,d){
  const j=i+d;if(j<0||j>=_isoItems.length)return;
  const t=_isoItems[i];_isoItems[i]=_isoItems[j];_isoItems[j]=t;_isoRender();_isoAutoLater();
}
function isoDel(i){_isoItems.splice(i,1);_isoRender();_isoAutoLater();}
function isoEdit(i,field,el,ci){
  const it=_isoItems[i];if(!it)return;
  const val=String(el.innerText||'').replace(/ /g,' ').trim();
  if(field==='choice')it.choices[ci]=val;
  else it[field]=val;
  _isoAutoLater();
}
function isoSetAnswer(i,ci){const it=_isoItems[i];if(!it)return;it.answer=ci;it.check=false;it.checkNote='';_isoRender();_isoAutoLater();}

// ── 결과 화면 ─────────────────────────────────────────────────────────────
function _isoRender(){
  const box=document.getElementById('iso-list');if(!box)return;
  const foot=document.getElementById('iso-foot');
  if(!_isoItems.length){
    box.innerHTML='<div class="iso-empty">아직 만든 문항이 없어요. 위에서 원본을 넣거나 유형을 고르고 <b>동형 문제 만들기</b>를 눌러 주세요.</div>';
    if(foot)foot.style.display='none';
    return;
  }
  if(foot)foot.style.display='';
  const keepOnly=_isoItems.some(it=>it.srcKeep);        // ② 원본 지문 유지 — 서버 대신 기기에만
  const sb=document.getElementById('iso-save');if(sb)sb.style.display='';
  const ns=document.getElementById('iso-nosave');if(ns)ns.style.display=keepOnly?'':'none';
  _isoPaintToBank();
  const dist={};_isoItems.forEach(it=>{if(it.choices.length)dist[it.answer]=(dist[it.answer]||0)+1;});
  const distTxt=Object.keys(dist).sort().map(k=>_isoCirc(Number(k))+' '+dist[k]).join(' · ');
  const head=document.getElementById('iso-head');
  if(head)head.textContent='문항 '+_isoItems.length+'개'+(distTxt?(' · 정답 분포 '+distTxt):'');
  box.innerHTML=_isoItems.map((it,i)=>{
    const essay=!it.choices.length;
    const ed=(f,v,ph,ci)=>'<div class="iso-ed" contenteditable="true" data-ph="'+_ebA(ph||'')+'" '+
      'onblur="isoEdit('+i+',\''+f+'\',this'+(ci===undefined?'':(','+ci))+')">'+_ebE(v)+'</div>';
    let h='<div class="iso-card'+(it.check?' iso-warn':'')+'">';
    h+='<div class="iso-card-h"><span class="iso-no">'+(i+1)+'</span>'+
       '<span class="iso-tag">'+_ebE(it.typeName||'')+'</span>'+
       (it.check?'<span class="iso-badge">확인 필요</span>':'')+
       '<span style="flex:1"></span>'+
       '<button class="iso-ic" title="위로" onclick="isoMove('+i+',-1)">↑</button>'+
       '<button class="iso-ic" title="아래로" onclick="isoMove('+i+',1)">↓</button>'+
       '<button class="iso-ic" title="다시 만들기" onclick="isoRegen('+i+')"'+(_isoBusy?' disabled':'')+'>↻</button>'+
       '<button class="iso-ic iso-ic-d" title="삭제" onclick="isoDel('+i+')">×</button></div>';
    if(it.check&&it.checkNote)h+='<div class="iso-note">'+_ebE(it.checkNote)+'</div>';
    h+='<div class="iso-lbl">발문</div>'+ed('stem',it.stem,'발문');
    if(it.passage)h+='<div class="iso-lbl">지문</div>'+ed('passage',it.passage,'지문');
    if(!essay){
      h+='<div class="iso-lbl">선택지 <span class="iso-hint">— 번호를 누르면 정답이 바뀌어요</span></div>';
      h+='<div class="iso-ch">'+it.choices.map((c,ci)=>
        '<div class="iso-chi'+(ci===it.answer?' on':'')+'">'+
        '<button class="iso-chn" onclick="isoSetAnswer('+i+','+ci+')">'+_isoCirc(ci)+'</button>'+
        ed('choice',c,'선택지',ci)+'</div>').join('')+'</div>';
    }else{
      h+='<div class="iso-lbl">모범 답안</div>'+ed('answerText',it.answerText,'모범 답안');
      if(it.rubric||_isoCfg.rubric)h+='<div class="iso-lbl">채점 기준</div>'+ed('rubric',it.rubric,'채점 기준');
    }
    h+='<div class="iso-lbl">해설</div>'+ed('explain',it.explain,'해설');
    const pw=String(it.passage||'').trim()?String(it.passage).trim().split(/\s+/).length:0;
    if(pw){
      const off=it.srcWords?Math.round((pw-it.srcWords)/it.srcWords*100):0;
      let tag='';
      if(it.srcWords){                                   // 범위를 벗어나면 표시만 (AI 를 더 부르지 않는다)
        const lo=Math.round(it.srcWords*0.9),hi=Math.round(it.srcWords*1.1);
        if(pw<lo)tag=' <span class="iso-len">짧음</span>';
        else if(pw>hi)tag=' <span class="iso-len">김</span>';
      }
      h+='<div class="iso-meta">지문 '+pw+'단어'+(it.srcWords?(' · 원본 '+it.srcWords+'단어 ('+(off>0?'+':'')+off+'%)'):'')+tag+'</div>';
    }
    if(it.intent)h+='<div class="iso-meta">출제 의도: '+_ebE(it.intent)+'</div>';
    if(it.wrong&&it.wrong.length)h+='<div class="iso-meta">오답 해설: '+_ebE(it.wrong.join(' / '))+'</div>';
    h+='</div>';
    return h;
  }).join('');
}

// ── 인쇄 ──────────────────────────────────────────────────────────────────
function _isoSrcLabel(){
  const bits=[];
  if(_isoInfo.title)bits.push(_isoInfo.title);
  if(_isoCfg.qno)bits.push(_isoCfg.qno+'번');
  const t=ISO_TYPES[_isoCfg.type];
  if(t)bits.push(t.n+' 유형');
  if(_isoCfg.passage==='book'){
    const tb=(_cache.globalTextbooks||[]).find(b=>b.id===_isoCfg.tbId);
    if(tb)bits.push(tb.title+(_isoCfg.unit?(' '+_isoCfg.unit):''));
  }
  return bits.join(' · ');
}
function isoPrint(kind){
  if(!_isoItems.length){toast('먼저 문항을 만들어 주세요');return;}
  const cols=parseInt((document.getElementById('iso-cols')||{}).value,10)||1;
  const ans=(kind==='a');
  const title=(_isoTitle||document.getElementById('iso-title')?.value||'동형 문제').trim()||'동형 문제';
  const src=_isoSrcLabel();
  const today=(typeof ppToday==='function')?ppToday():new Date().toISOString().slice(0,10);
  const body=_isoItems.map((it,i)=>{
    let h='<div class="q">';
    h+='<div class="qs"><b>'+(i+1)+'.</b> '+_ebE(it.stem)+'</div>';
    if(it.passage)h+='<div class="qp">'+_ebE(it.passage).replace(/\n/g,'<br>')+'</div>';
    if(it.choices.length)h+='<ol class="qc">'+it.choices.map((c,ci)=>
      '<li'+(ans&&ci===it.answer?' class="ok"':'')+'>'+_isoCirc(ci)+' '+_ebE(c)+'</li>').join('')+'</ol>';
    else if(!ans)h+='<div class="qw"></div>';
    if(ans){
      h+='<div class="qa"><b>정답</b> '+(it.choices.length?_isoCirc(it.answer):_ebE(it.answerText||''))+'</div>';
      if(it.rubric)h+='<div class="qa"><b>채점 기준</b> '+_ebE(it.rubric)+'</div>';
      if(it.explain)h+='<div class="qa"><b>해설</b> '+_ebE(it.explain)+'</div>';
      if(it.wrong&&it.wrong.length)h+='<div class="qa"><b>오답</b> '+_ebE(it.wrong.join(' / '))+'</div>';
    }
    h+='</div>';
    return h;
  }).join('');
  const w=window.open('','_blank');
  if(!w){toast('팝업이 막혀 있어요 — 허용해 주세요');return;}
  w.document.write('<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>'+_ebE(title)+(ans?' — 정답·해설':'')+'</title><style>'+
'@page{size:A4;margin:14mm 12mm;}'+
'*{box-sizing:border-box}'+
'body{font-family:"Malgun Gothic","맑은 고딕",system-ui,sans-serif;color:#111;margin:0;font-size:'+(cols===2?'10.5pt':'11pt')+';line-height:1.65}'+
'h1{font-size:15pt;margin:0 0 2px}'+
'.hd{border-bottom:2px solid #111;padding-bottom:6px;margin-bottom:10px}'+
'.hd .m{font-size:9.5pt;color:#444;display:flex;gap:14px;flex-wrap:wrap}'+
'.hd .nm{margin-left:auto}'+
'.src{font-size:9pt;color:#666;margin-top:3px}'+
'.wrap{'+(cols===2?'column-count:2;column-gap:9mm;column-rule:1px solid #ddd;':'')+'}'+
'.q{break-inside:avoid;page-break-inside:avoid;margin:0 0 13px}'+
'.qs{margin-bottom:5px}'+
'.qp{border:1px solid #bbb;padding:7px 9px;margin:5px 0;text-align:justify;background:#fafafa}'+
'.qc{list-style:none;padding:0;margin:5px 0 0}'+
'.qc li{margin:2px 0}'+
'.qc li.ok{font-weight:700;background:#fff3b0}'+
'.qw{border-bottom:1px solid #999;height:22px;margin:6px 0}'+
'.qa{font-size:9.5pt;color:#333;margin-top:3px}'+
'.noprint{position:fixed;top:10px;right:10px;padding:8px 14px;font-size:13px;cursor:pointer}'+
'@media print{.noprint{display:none}}'+
'</style></head><body>'+
'<div class="hd"><h1>'+_ebE(title)+(ans?' — 정답·해설지':'')+'</h1>'+
'<div class="m"><span>직결영어</span><span>'+_ebE(today)+'</span><span class="nm">이름 ______________</span></div>'+
(src?('<div class="src">출처 · 유형: '+_ebE(src)+'</div>'):'')+'</div>'+
'<div class="wrap">'+body+'</div>'+
'<button class="noprint" onclick="print()">🖨 인쇄</button></body></html>');
  w.document.close();
}

// ── 자동 저장 · 기기 보관 ─────────────────────────────────────────────────
// 만들기·다시 만들기·고치기가 끝나면 알아서 저장한다(고치기는 1.5초 모아서 한 번).
// 기기(IndexedDB)에도 늘 한 벌 남겨 두어 서버 저장이 실패하거나 탭을 닫았다 열어도 되살아난다.
// 원본 지문 그대로(srcKeep) 묶음은 서버에 올리지 않고 기기에만 둔다.
const ISO_DEV_KEY='pp_iso_sets';     // 기기 보관함 (최근 10묶음)
const ISO_LAST_KEY='pp_iso_last';    // 마지막으로 보던 묶음 id
const ISO_DEV_MAX=10;
const ISO_AUTO_MS=1500;              // 고치기는 이만큼 모아서 한 번
let _isoAutoT=null,_isoSaving=false,_isoDirty=false;
let _isoCreatedAt=0;                 // 이 묶음을 처음 만든 때 — 고칠 때마다 새로 찍지 않는다
let _isoLegacy=false;                // 예전 묶음(itemIds 가 없는 것)을 열어 둔 상태

function _isoP2(n){return ('0'+n).slice(-2);}
function _isoHHMM(t){const d=new Date(t||Date.now());return _isoP2(d.getHours())+':'+_isoP2(d.getMinutes());}
function _isoMMDD(t){const d=new Date(t||Date.now());return _isoP2(d.getMonth()+1)+'-'+_isoP2(d.getDate());}
function _isoStatus(kind,msg){
  const el=document.getElementById('iso-stat');if(!el)return;
  el.className='iso-stat'+(kind?(' '+kind):'');
  el.textContent=msg||'';
  el.onclick=(kind==='err')?(()=>_isoAutoSave(true)):null;
  el.title=(kind==='err')?'눌러서 다시 저장':'';
}
function _isoKeepOnly(){return _isoItems.some(it=>it.srcKeep);}   // 기출·출판사 원문 지문 — 서버에 올리지 않는다
function _isoAutoTitle(){
  const t=ISO_TYPES[_isoCfg.type];
  return (t?t.n:'동형 문제')+' '+_isoItems.length+'문항 · '+_isoMMDD()+' '+_isoHHMM();
}
function _isoTitleNow(){
  const el=document.getElementById('iso-title');
  let v=String((el&&el.value)||'').trim();
  if(!v){v=_isoAutoTitle();if(el)el.value=v;}   // 비어 있으면 알아서 붙인다
  _isoTitle=v;return v;
}
// 저장하는 것은 만들어진 문항뿐이다 — 올린 이미지와 붙여넣은 원본 글은 저장하지 않는다
function _isoRec(){
  const title=_isoTitleNow();
  if(!_isoRowId)_isoRowId=uid();
  const now=Date.now();
  if(!_isoCreatedAt)_isoCreatedAt=now;
  return {
    id:_isoRowId,kind:'iso',title:title,createdAt:_isoCreatedAt,editedAt:now,
    gradeLevel:_isoCfg.grade,
    isoType:_isoCfg.type,isoTypeName:_isoTypeName(_isoCfg.type),
    source:{exam:_isoInfo.title||'',qno:_isoCfg.qno||'',passage:_isoCfg.passage,
            book:_isoCfg.passage==='book'?_isoCfg.tbId:'',unit:_isoCfg.passage==='book'?_isoCfg.unit:''},
    itemIds:_isoItems.map(it=>it.id),                  // 문제 은행의 문항을 가리킨다
    // items 도 그대로 둔다 — 학생에게 과제로 보낸 묶음은 이 줄만 보고 문제를 띄운다
    items:_isoItems.map(it=>({...it,check:undefined,checkNote:undefined,verifyAnswer:undefined})),
    usage:{calls:_isoUse.calls,inTok:_isoUse.in,outTok:_isoUse.out,model:ISO_MODEL}
  };
}
async function _isoDevPut(rec,deviceOnly){
  try{
    const old=await idbGet(ISO_DEV_KEY);
    const list=(Array.isArray(old)?old:[]).filter(x=>x&&x.id!==rec.id);
    list.unshift({...rec,deviceOnly:!!deviceOnly,savedAt:Date.now(),
      cfg:{type:_isoCfg.type,grade:_isoCfg.grade,qno:_isoCfg.qno,passage:_isoCfg.passage,
           choices:_isoCfg.choices,rubric:_isoCfg.rubric,n:_isoCfg.n},
      info:{..._isoInfo}});
    await idbSet(ISO_DEV_KEY,list.slice(0,ISO_DEV_MAX));
    await idbSet(ISO_LAST_KEY,rec.id);
  }catch(e){}
}
async function _isoDevLast(){
  try{
    const id=await idbGet(ISO_LAST_KEY);if(!id)return null;
    const list=await idbGet(ISO_DEV_KEY);
    return (Array.isArray(list)?list:[]).find(x=>x&&x.id===id)||null;
  }catch(e){return null;}
}
function _isoAutoLater(){
  if(_isoAutoT)clearTimeout(_isoAutoT);_isoAutoT=null;
  if(!_isoItems.length){_isoStatus('','');return;}   // 문항 0개는 저장하지 않는다
  _isoStatus('','고친 내용 저장 대기…');
  _isoAutoT=setTimeout(()=>{_isoAutoT=null;_isoAutoSave(false);},ISO_AUTO_MS);
}
async function _isoAutoSave(manual){
  if(_isoAutoT){clearTimeout(_isoAutoT);_isoAutoT=null;}
  if(!_isoItems.length){_isoStatus('','');if(manual)toast('먼저 문항을 만들어 주세요');return false;}
  if(typeof ppSandbox==='function'&&ppSandbox()){_isoStatus('','체험 모드 — 저장하지 않아요');return false;}
  if(_isoSaving){_isoDirty=true;return false;}
  _isoSaving=true;
  let ok=false;
  try{
    const rec=_isoRec();
    const keep=_isoKeepOnly();
    await _isoDevPut(rec,keep);                 // 기기에는 늘 먼저 남긴다
    const bank=await _isoBankSync(rec);         // 문항을 한 개씩 문제 은행에 (원문 지문은 기기에만)
    const bankTxt=(bank&&(bank.ok||bank.dev))?(' · 은행 '+(bank.ok+bank.dev)+'문항'):'';
    if(keep){
      ok=true;
      _isoStatus('ok','이 묶음은 이 기기에만 보관돼요 (원문 지문) · '+_isoHHMM()+bankTxt);
      if(manual)toast('원문 지문 묶음이라 이 기기에만 보관했어요 — 인쇄로 쓰세요');
    }else{
      _isoStatus('','저장 중…');
      ok=!!(await supaUpsert('worksheets',rec.id,rec).catch(()=>false));
      if(ok){
        _isoStatus('ok','저장됨 '+_isoHHMM()+bankTxt);
        _cache.worksheets=(_cache.worksheets||[]).filter(w=>w.id!==rec.id).concat([{rowId:rec.id,...rec}]);
        try{renderWsDB();}catch(e){}
        if(manual)toast('저장했어요 ✓ — 자료 DB → 저장된 워크시트에서 다시 열 수 있어요');
      }else{
        _isoStatus('err','저장 실패 · 다시 저장');
        if(manual)toast('저장 실패 — 잠시 뒤 다시 해 주세요');
      }
    }
  }catch(e){_isoStatus('err','저장 실패 · 다시 저장');}
  _isoSaving=false;
  if(_isoDirty){_isoDirty=false;_isoAutoLater();}
  return ok;
}
// 탭을 닫았다 열거나 새로고침했을 때 마지막 작업을 되살린다
async function _isoRestore(){
  if(_isoItems.length||_isoBusy)return;
  if(typeof ppSandbox==='function'&&ppSandbox())return;
  const d=await _isoDevLast();
  if(!d||!Array.isArray(d.items)||!d.items.length)return;
  if(_isoItems.length)return;                     // 그새 뭔가 만들었으면 건드리지 않는다
  _isoRowId=d.id;_isoTitle=d.title||'';
  _isoItems=d.items.map(it=>({...it,check:false,checkNote:''}));
  if(d.cfg)_isoCfg={..._isoCfg,...d.cfg};
  if(d.info)_isoInfo={..._isoInfo,...d.info};
  const t=document.getElementById('iso-title');if(t)t.value=_isoTitle;
  const st=document.getElementById('iso-exam');
  if(st){st.textContent=_isoInfo.title?('가져온 시험: '+_isoInfo.title):'';st.style.display=_isoInfo.title?'':'none';}
  _isoPaintCfg();_isoRender();
  _isoStatus('ok',(d.deviceOnly?'이 기기에만 보관돼요 (원문 지문) · ':'저장됨 ')+_isoHHMM(d.savedAt));
  toast('마지막 작업을 되살렸어요 — 문항 '+_isoItems.length+'개');
}
function _isoScrollToFirst(){
  try{
    const c=document.querySelector('#iso-list .iso-card');
    if(c)c.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){}
}

// ── 문제 은행에 넣기 ──────────────────────────────────────────────────────
// 만든 문항을 한 개씩 item_bank 에 넣는다. 지문을 같이 쓰는 문항(장문)은 한 묶음(setId)으로 묶는다.
async function _isoBankSync(rec){
  if(typeof ibPutItem!=='function')return null;
  if(typeof ppSandbox==='function'&&ppSandbox())return null;
  const byPass=new Map();
  _isoItems.forEach((it,i)=>{const p=String(it.passage||'').trim();if(!p)return;
    if(!byPass.has(p))byPass.set(p,[]);byPass.get(p).push(i);});
  const setOf={};let sn=0;
  byPass.forEach(idxs=>{if(idxs.length>1){sn++;const sid=rec.id+'-s'+sn;
    idxs.forEach((ix,k)=>{setOf[ix]={id:sid,order:k+1};});}});
  let ok=0,dev=0,fail=0;
  for(let i=0;i<_isoItems.length;i++){
    const s=setOf[i]||null;
    const d=_ibFromIso(_isoItems[i],_isoCfg,_isoInfo,s?s.id:'',s?s.order:(i+1));
    const r=await ibPutItem(d,true).catch(()=>false);
    if(r==='device')dev++;else if(r)ok++;else fail++;
  }
  return {ok:ok,dev:dev,fail:fail};
}
// 예전 묶음(itemIds 가 없는 것)을 열었을 때만 보이는 단추 — 원본 묶음은 그대로 두고 복사한다
function _isoPaintToBank(){
  const b=document.getElementById('iso-tobank');if(!b)return;
  b.style.display=(_isoLegacy&&_isoItems.length)?'':'none';
}
async function isoToBank(){
  if(!_isoItems.length)return;
  if(typeof ppSandbox==='function'&&ppSandbox()){toast('체험 모드에서는 저장하지 않아요');return;}
  const r=await _isoBankSync({id:_isoRowId||uid()});
  if(!r){toast('문제 은행을 쓸 수 없어요');return;}
  _isoLegacy=false;_isoPaintToBank();
  if(typeof renderItemList==='function')renderItemList();
  toast('문항 '+(r.ok+r.dev)+'개를 문제 은행으로 가져왔어요 — 원본 묶음은 그대로 둡니다'+(r.fail?(' (실패 '+r.fail+'개)'):''));
}

// ── 저장 · 다시 열기 ──────────────────────────────────────────────────────
async function isoSave(){return _isoAutoSave(true);}   // [지금 저장] — 자동 저장과 같은 길

async function isoOpenSaved(id){
  const w=(_cache.worksheets||[]).find(x=>x.id===id);
  if(!w){toast('찾지 못했어요');return;}
  _isoRowId=id;_isoTitle=w.title||'';
  _isoCreatedAt=Number(w.createdAt)||0;
  _isoLegacy=!(Array.isArray(w.itemIds)&&w.itemIds.length);   // 예전 묶음은 은행에 없다
  _isoItems=(w.items||[]).map(it=>({...it,check:false,checkNote:''}));
  if(!_isoLegacy&&typeof _ibFetchItems==='function'){
    // 은행 문항을 먼저 쓰고, 은행에 없는 것만 묶음 사본(items)으로 채운다.
    // 이 묶음을 다시 저장하면 _isoRec 이 지금 화면의 문항으로 items 를 다시 쓴다 — 사본이 은행과 맞춰진다.
    const got=await _ibFetchItems(w.itemIds);
    if(got&&got.length){
      const by={};got.forEach(it=>{by[it.id]=it;});
      const old=(w.items||[]);
      const merged=w.itemIds.map((id,i)=>by[id]||old.find(x=>x&&x.id===id)||old[i]).filter(Boolean);
      if(merged.length)_isoItems=merged.map(it=>({...it,check:false,checkNote:''}));
    }
  }
  _isoCfg.type=w.isoType||_isoCfg.type;
  _isoCfg.grade=w.gradeLevel||_isoCfg.grade;
  _isoInfo={title:(w.source&&w.source.exam)||'',cat:'',grade:w.gradeLevel||''};
  _isoCfg.qno=(w.source&&w.source.qno)||'';
  _isoUse={calls:0,in:0,out:0};
  swTab('t-data');switchDataTab('iso');
  const t=document.getElementById('iso-title');if(t)t.value=_isoTitle;
  _isoPaintCfg();_isoRender();_isoCost();_isoStatus('ok','저장됨 · 불러온 묶음');
  _isoPaintToBank();
}
function isoNew(){
  if(_isoAutoT){clearTimeout(_isoAutoT);_isoAutoT=null;}
  _isoCreatedAt=0;_isoLegacy=false;
  _isoItems=[];_isoRowId='';_isoTitle='';_isoAnalysis=null;_isoUse={calls:0,in:0,out:0};
  _isoInfo={title:'',cat:'',grade:''};_isoCfg.qno='';
  const t=document.getElementById('iso-title');if(t)t.value='';
  const h=document.getElementById('iso-type-hint');if(h)h.textContent='';
  isoClearSrc();_isoPaintCfg();_isoRender();_isoCost();
  try{idbSet(ISO_LAST_KEY,'');}catch(e){}   // 저장된 것은 지우지 않고 화면만 비운다
  _isoStatus('','');
}
function isoOpenTab(){
  _isoLoadCfg();_isoPaintCfg();_isoRender();_isoCost();
  const st=document.getElementById('iso-exam');
  if(st){
    st.textContent=_isoInfo.title?('가져온 시험: '+_isoInfo.title):'';
    st.style.display=_isoInfo.title?'':'none';
  }
  _isoRestore();   // 탭을 닫았다 열어도 마지막 작업이 되살아난다
}

// ══ 문제 은행 (item_bank) ═════════════════════════════════════════════════
// 문항 한 개 = 한 줄. 동형 문제로 만든 문항·기출 전사 문항·직접 넣은 문항이 모두 여기 모인다.
// 목록은 본문(지문·해설·오답·대본)을 뺀 가벼운 뷰 item_bank_index 로 받아 기기(IndexedDB)에 두고,
// 다시 열 때는 id·updated_at 만 대조해 바뀐 줄만 받는다 — 자료실(exam_bank)과 같은 방식.
// ⚠️ 학생·학부모 화면과 체험 모드에서는 이 탭도, 이 데이터도 보이지 않는다(ibMayUse).
// ⚠️ AI 는 부르지 않는다. 문항을 만드는 것은 '동형 문제' 탭에서 선생님이 단추를 눌렀을 때뿐이다.
const IB_IDX_KEY='pp_item_bank_v1';
const IB_FRESH_MS=12*60*60*1000;
const IB_PAGE=50;
const IB_BASKET_KEY='pp_item_basket';
const IB_F_KEY='pp_ib_filters';
const IB_DEV_KEY='pp_item_keep';     // 원문 지문 문항은 기기에만 (서버에 올리지 않는다)
// 공개 키(anon)가 열려 있는 동안에는 기출·출판사 원문 지문을 서버에 올리지 않는다.
// supabase/auth_step3_close_anon.sql 로 anon 을 닫은 뒤 이 스위치를 true 로 바꾸면 그때부터 함께 저장된다.
const ITEM_KEEP_SERVER=false;
const IB_SKILLS=[{k:'read',n:'읽기'},{k:'listen',n:'듣기'},{k:'grammar',n:'어법'},{k:'vocab',n:'어휘'},{k:'write',n:'쓰기'}];
const IB_SRCS=[{k:'iso',n:'동형'},{k:'exam',n:'기출'},{k:'book',n:'교재'},{k:'manual',n:'직접'}];
const IB_GRADES=['초5','초6','중1','중2','중3','고1','고2','고3'];
// 유형키 → 영역 (나머지는 ISO_TYPES 의 묶음으로 정한다)
const IB_SKILL_BY_TYPE={grammar:'grammar',m_grammar_pick:'grammar',m_grammar_fix:'grammar',
  vocab:'vocab',m_vocab:'vocab',m_write_cond:'write',m_write_order:'write',m_summary:'write',m_dialog:'listen'};
// 정답률이 없을 때 쓰는 유형별 기본 난도
const IB_DIFF_BY_TYPE={blank:4,implicit:4,order:4,insert:4,summary:4,grammar:4,irrelevant:3,vocab:3,
  l_purpose:2,l_opinion:2,l_gist:2,l_pic:2,l_todo:2,l_why:2,l_not:2,l_mismatch:2,l_table:2,l_short:2,l_set:2,
  l_pay:3,l_long:3,l_situation:3,                  // 듣기는 2, 금액·긴 대화 응답·상황에 맞는 말만 3
  title:3,topic:3,long2:3,long3:3,claim:2,gist:2,purpose:2,mood:2,chart:2,notice:2,bio:2,
  m_blank:3,m_order:3,m_insert:3,m_ref:3,m_topic:3,m_vocab:3,m_textbook:3,m_write_order:3,
  m_grammar_pick:4,m_grammar_fix:4,m_write_cond:4,m_summary:4,m_match:2,m_dialog:2};

let _ibRows=null;              // 가벼운 목록 [{id,updated_at,meta}]
let _ibStamps={},_ibAt=0,_ibMax='',_ibSrc='view',_ibLoading=false,_ibNote='';
const _ibFull=new Map();       // 고른 문항의 data 전체 (이 세션 동안 메모리에만)
let _ibPage=1,_ibSelId='',_ibEditing=null,_ibEditT=null,_ibEditState='';
let _ibPick=new Set();         // 여러 개 고르기
let _ibOpenSets=new Set();     // 펼쳐 둔 지문 묶음(setId)
let _ibNoTable=false;          // item_bank 표가 아직 없다 (SQL 실행 전) — 쓰기를 멈춘다
let _ibDeepIds=null;           // '본문까지 찾기' 결과 (서버가 찾아 준 id 들)
let _ibF={skill:'',type:'',grade:'',diff:'',src:'',tbId:'',unit:'',checked:'',star:false,tag:'',q:''};

function ibMayUse(){
  try{
    if(typeof ppSandbox==='function'&&ppSandbox())return false;
    const s=(typeof loadSession==='function')?loadSession():null;
    return !!(s&&s.role==='teacher');
  }catch(e){return false;}
}
// ── 문항 모양 ─────────────────────────────────────────────────────────────
function _ibSkillOf(type){
  if(IB_SKILL_BY_TYPE[type])return IB_SKILL_BY_TYPE[type];
  const t=ISO_TYPES[type];
  if(t&&t.g==='듣기')return 'listen';
  if(t&&t.s)return 'write';
  return 'read';
}
// 난도 기본값 — 정답률이 있으면 정답률로, 없으면 배점·유형 규칙으로
function _ibDiffDefault(rate,points,type){
  const r=Number(rate);
  if(isFinite(r)&&r>0){
    const d=(r>=80)?1:(r>=65)?2:(r>=50)?3:(r>=35)?4:5;
    return {diff:d,diffSrc:'rate'};
  }
  let d=IB_DIFF_BY_TYPE[type]||3;
  const p=Number(points);
  if(isFinite(p)&&p>0){if(p>=3)d+=1;else if(p<=1.5)d-=1;}
  return {diff:Math.max(1,Math.min(5,d)),diffSrc:'rule'};
}
function _ibNum(v){const n=Number(v);return isFinite(n)?n:null;}
// 어디서 온 문항이든 한 모양으로 (가져오기·직접 넣기·동형 모두 이 길을 지난다)
function _ibNorm(x,now){
  const o=x||{};
  const type=String(o.type||'');
  const ch=Array.isArray(o.choices)?o.choices.map(c=>String(c==null?'':c)):[];
  const src=(o.src&&typeof o.src==='object')?o.src:{};
  const rate=_ibNum(o.rate),points=_ibNum(o.points);
  const dd=(_ibNum(o.diff)&&String(o.diffSrc||''))?{diff:_ibNum(o.diff),diffSrc:String(o.diffSrc)}
                                                 :_ibDiffDefault(rate,points,type);
  const passage=String(o.passage||'');
  const t=Date.now();
  return {
    id:String(o.id||uid()),
    skill:String(o.skill||_ibSkillOf(type)),
    type:type,typeName:String(o.typeName||_isoTypeName(type)),
    grade:String(o.grade||''),
    diff:_ibNum(o.diff)||dd.diff,diffSrc:String(o.diffSrc||dd.diffSrc),
    rate:rate,points:points,
    stem:String(o.stem||''),passage:passage,
    choices:ch,answer:isFinite(Number(o.answer))?Number(o.answer):(ch.length?0:-1),
    answerText:String(o.answerText||''),rubric:String(o.rubric||''),
    explain:String(o.explain||''),wrong:Array.isArray(o.wrong)?o.wrong.map(String):[],
    script:String(o.script||''),
    words:_ibNum(o.words)||(passage.trim()?passage.trim().split(/\s+/).length:null),
    src:{kind:String(src.kind||'manual'),exam:String(src.exam||''),qno:String(src.qno||''),
         bankId:String(src.bankId||''),fileId:String(src.fileId||''),page:_ibNum(src.page),
         audioId:String(src.audioId||''),tbId:String(src.tbId||''),unit:String(src.unit||''),
         isoFrom:String(src.isoFrom||''),keep:!!src.keep},
    setId:String(o.setId||''),setOrder:_ibNum(o.setOrder),
    tags:Array.isArray(o.tags)?o.tags.map(String).filter(Boolean):[],
    star:!!o.star,checked:!!o.checked,note:String(o.note||''),
    createdAt:_ibNum(o.createdAt)||now||t,editedAt:_ibNum(o.editedAt)||now||t
  };
}
// 동형 문제 한 문항 → 은행 문항
function _ibFromIso(it,cfg,info,setId,order){
  return _ibNorm({
    id:it.id,type:it.type,typeName:it.typeName,grade:cfg.grade,
    stem:it.stem,passage:it.passage,choices:it.choices,answer:it.answer,
    answerText:it.answerText,rubric:it.rubric,explain:it.explain,wrong:it.wrong,
    words:it.srcWords?null:null,
    src:{kind:'iso',exam:(info&&info.title)||'',qno:cfg.qno||'',
         tbId:cfg.passage==='book'?cfg.tbId:'',unit:cfg.passage==='book'?cfg.unit:'',
         isoFrom:it.isoFrom||'',keep:!!it.srcKeep},
    setId:setId||'',setOrder:order,
    createdAt:it.createdAt,editedAt:Date.now()
  });
}
// ── 받아 오기 (자료실과 같은 길) ──────────────────────────────────────────
const IB_SEL='select=id,updated_at,meta';
function _ibLightOf(d,id,at){                       // data 전체 → 목록용 가벼운 줄
  const p=String(d.passage||d.script||'');
  return {id:id||d.id,updated_at:at||new Date().toISOString(),meta:{
    skill:d.skill,type:d.type,typeName:d.typeName,grade:d.grade,diff:d.diff,diffSrc:d.diffSrc,
    rate:d.rate,points:d.points,stem:d.stem,preview:p.slice(0,180),choices:d.choices,answer:d.answer,
    words:d.words,src:d.src,tags:d.tags,setId:d.setId,setOrder:d.setOrder,
    star:d.star||null,checked:d.checked||null,note:d.note,createdAt:d.createdAt,editedAt:d.editedAt,
    hasPassage:!!String(d.passage||''),hasScript:!!String(d.script||''),_deleted:d._deleted||undefined}};
}
// 문항의 id 는 **행 id** 가 진짜다. REST 로 바로 넣은 행이나 가져온 파일에는
// data 안에 id 가 없을 수 있고, 있어도 행 id 와 다를 수 있다 — 받는 쪽에서 늘 덮어쓴다.
function _ibWithId(data,rowId){
  if(!data||!rowId)return data||null;
  if(data.id!==rowId)data.id=rowId;
  return data;
}
function _ibAlive(r){return !!r&&!(r.meta&&r.meta._deleted);}
async function _ibFetchAll(){
  const PAGE=1000;let out=[],off=0;
  _ibSrc='view';_ibNote='';
  while(true){
    let r=null;
    if(_ibSrc==='view'){
      r=await _ebGet('item_bank_index?'+IB_SEL+'&limit='+PAGE+'&offset='+off+'&order=id');
      if(!r.ok&&(r.status===404||r.status===400||r.status===406)){
        _ibSrc='table';_ibNote='목록 뷰가 없어 표 전체를 받았습니다 — supabase/item_bank.sql 을 실행하면 훨씬 가볍게 받습니다.';
        out=[];off=0;continue;
      }
    }else r=await _ebGet('item_bank?select=id,updated_at,data&limit='+PAGE+'&offset='+off+'&order=id');
    if(!r.ok){
      if(_ibSrc==='table'&&(r.status===404||r.status===400)){
        _ibNoTable=true;_ibNote='문제 은행 표가 아직 없습니다 — supabase/item_bank.sql 을 실행해 주세요.';
      }
      return null;
    }
    if(_ibSrc==='view')out=out.concat(r.rows.filter(_ibAlive));
    else r.rows.forEach(x=>{const L=_ibLightOf(x.data||{},x.id,x.updated_at);if(_ibAlive(L)){out.push(L);_ibFull.set(x.id,_ibWithId(x.data,x.id));}});
    if(r.rows.length<PAGE)return out;
    off+=PAGE;
  }
}
async function _ibStampRows(){
  const PAGE=1000,tbl=(_ibSrc==='view'?'item_bank_index':'item_bank');
  let out=[],off=0;
  while(true){
    const r=await _ebGet(tbl+'?select=id,updated_at&limit='+PAGE+'&offset='+off+'&order=id');
    if(!r.ok)return null;
    out=out.concat(r.rows);
    if(r.rows.length<PAGE)return out;
    off+=PAGE;
  }
}
async function _ibFetchByIds(ids){
  const q=ids.map(encodeURIComponent).join(',');
  if(_ibSrc==='view'){const r=await _ebGet('item_bank_index?'+IB_SEL+'&id=in.('+q+')');return r.ok?r.rows:null;}
  const r=await _ebGet('item_bank?select=id,updated_at,data&id=in.('+q+')');
  if(!r.ok)return null;
  return r.rows.map(x=>{_ibFull.set(x.id,_ibWithId(x.data,x.id));return _ibLightOf(x.data||{},x.id,x.updated_at);});
}
async function _ibProbe(){
  try{
    const tbl=(_ibSrc==='view'?'item_bank_index':'item_bank');
    const r=await fetch(SUPA_URL+'/rest/v1/'+tbl+'?select=updated_at&order=updated_at.desc&limit=1',
      {headers:{...SUPA_HEADERS,'Prefer':'count=exact'}});
    if(!r.ok)return null;
    const cr=String(r.headers.get('content-range')||'');
    const total=Number(cr.split('/')[1]);
    const rows=await r.json();
    return {total:isFinite(total)?total:null,max:String((rows&&rows[0]&&rows[0].updated_at)||'')};
  }catch(e){return null;}
}
async function _ibSave(){try{await idbSet(IB_IDX_KEY,{v:1,src:_ibSrc,rows:_ibRows,stamps:_ibStamps,at:_ibAt,max:_ibMax});}catch(e){}}
function _ibStampsOf(rows){const s={};rows.forEach(x=>{if(x&&x.id)s[x.id]=x.updated_at;});return s;}
function _ibMaxOf(rows){let m='';rows.forEach(x=>{const u=String((x&&x.updated_at)||'');if(u>m)m=u;});return m;}
async function ibLoad(force){
  if(!ibMayUse()||_ibLoading)return false;
  _ibLoading=true;
  try{
    if(_ibRows===null){
      const snap=await idbGet(IB_IDX_KEY);
      if(snap&&Array.isArray(snap.rows)){_ibRows=snap.rows;_ibStamps=snap.stamps||{};_ibAt=snap.at||0;_ibSrc=snap.src||'view';_ibMax=snap.max||'';}
    }
    const have=!!(_ibRows&&_ibRows.length);
    if(have&&!force&&(Date.now()-_ibAt)<IB_FRESH_MS)return false;
    if(!have){
      const all=await _ibFetchAll();
      if(!all)return false;
      _ibRows=all;_ibStamps=_ibStampsOf(all);_ibMax=_ibMaxOf(all);_ibAt=Date.now();
      await _ibSave();return true;
    }
    const pr=await _ibProbe();                       // 끝 한 줄·개수만 (몇십 바이트)
    if(pr&&pr.max&&pr.max===_ibMax&&pr.total!==null&&pr.total===_ibRows.length){_ibAt=Date.now();await _ibSave();return false;}
    const st=await _ibStampRows();
    if(!st)return false;
    const live=new Set(st.map(x=>x&&x.id));
    const changed=st.filter(x=>x&&x.id&&String(_ibStamps[x.id]||'')!==String(x.updated_at||'')).map(x=>x.id);
    const gone=_ibRows.filter(r=>!live.has(r.id)).map(r=>r.id);
    _ibAt=Date.now();
    if(!changed.length&&!gone.length){await _ibSave();return false;}
    const byId=new Map(_ibRows.map(r=>[r.id,r]));
    gone.forEach(id=>{byId.delete(id);_ibFull.delete(id);});
    for(let i=0;i<changed.length;i+=50){
      const part=await _ibFetchByIds(changed.slice(i,i+50));
      if(!part)return true;
      part.forEach(x=>{_ibFull.delete(x.id);if(_ibAlive(x))byId.set(x.id,x);else byId.delete(x.id);});
    }
    _ibRows=[...byId.values()];_ibStamps=_ibStampsOf(st);_ibMax=_ibMaxOf(st);
    await _ibSave();
    return true;
  }catch(e){return false;}
  finally{_ibLoading=false;}
}
async function _ibFullRow(id){
  if(_ibFull.has(id))return _ibWithId(_ibFull.get(id),id);
  const dev=await _ibDevGet(id);                     // 기기에만 있는 원문 지문 문항
  if(dev){_ibWithId(dev,id);_ibFull.set(id,dev);return dev;}
  const r=await _ebGet('item_bank?select=data&id=eq.'+encodeURIComponent(id));
  const d=_ibWithId((r.ok&&r.rows[0]&&r.rows[0].data)||null,id);
  if(d)_ibFull.set(id,d);
  return d;
}
// ── 저장 ──────────────────────────────────────────────────────────────────
async function _ibDevAll(){try{const l=await idbGet(IB_DEV_KEY);return Array.isArray(l)?l:[];}catch(e){return [];}}
async function _ibDevGet(id){const l=await _ibDevAll();return l.find(x=>x&&x.id===id)||null;}
async function _ibDevPut(d){
  try{const l=(await _ibDevAll()).filter(x=>x&&x.id!==d.id);l.unshift(d);await idbSet(IB_DEV_KEY,l.slice(0,500));}catch(e){}
}
function _ibDevOnly(d){return !!(d&&d.src&&d.src.keep)&&!ITEM_KEEP_SERVER;}   // 원문 지문 — 기기에만
// 문항 한 개 저장 (원문 지문 문항은 기기에만)
async function ibPutItem(d,quiet){
  if(typeof ppSandbox==='function'&&ppSandbox())return false;
  if(_ibNoTable)return false;                       // 표가 없으면 헛되이 보내지 않는다
  const now=Date.now();
  d.editedAt=now;if(!d.createdAt)d.createdAt=now;
  const row=_ibLightOf(d,d.id,new Date(now).toISOString());
  if(_ibDevOnly(d)){
    await _ibDevPut(d);_ibFull.set(d.id,d);
    _ibMerge(row);
    if(!quiet)toast('원문 지문 문항이라 이 기기에만 보관했어요');
    return 'device';
  }
  const ok=await supaUpsert('item_bank',d.id,d).catch(e=>{
    if(String((e&&e.message)||'').indexOf('404')>=0){_ibNoTable=true;
      _ibNote='문제 은행 표가 아직 없습니다 — supabase/item_bank.sql 을 실행해 주세요.';_ibStampIb();}
    return false;});
  if(ok){_ibFull.set(d.id,d);_ibStamps[d.id]=row.updated_at;_ibMerge(row);}
  return !!ok;
}
function _ibMerge(row){                               // 목록에 바로 반영 (다시 받지 않는다)
  if(!Array.isArray(_ibRows))_ibRows=[];
  const i=_ibRows.findIndex(r=>r.id===row.id);
  if(i>=0)_ibRows[i]=row;else _ibRows.unshift(row);
  _ibSave();
}
// 여러 줄 한꺼번에 (가져오기 — 200개씩)
async function _ibBulkUpsert(list){
  if(typeof ppSandbox==='function'&&ppSandbox())return false;
  const body=list.map(d=>({id:d.id,data:d,updated_at:new Date().toISOString()}));
  const h={...SUPA_HEADERS,'Prefer':'resolution=merge-duplicates,return=minimal'};
  const r=await ppFetch(SUPA_URL+'/rest/v1/item_bank',{method:'POST',headers:h,body:JSON.stringify(body)});
  return r.ok;
}
// 휴지통 (하드 삭제 대신 _deleted 표식)
async function ibTrash(id,ev){
  if(ev)ev.stopPropagation();
  const d=await _ibFullRow(id);
  if(!d){toast('문항을 찾지 못했어요');return;}
  askConfirm('문항 삭제','이 문항을 휴지통으로 보낼까요?\n30일 뒤 자동으로 지워집니다.','삭제','bd',()=>_ibTrashGo(d));
}
async function _ibTrashGo(d){
  const id=d.id;
  if(_ibDevOnly(d)){
    const l=(await _ibDevAll()).filter(x=>x&&x.id!==id);try{await idbSet(IB_DEV_KEY,l);}catch(e){}
  }else{
    const ok=await supaUpsert('item_bank',id,{...d,_deleted:true,_deletedAt:new Date().toISOString()}).catch(()=>false);
    if(!ok){toast('삭제 실패 — 잠시 뒤 다시 해 주세요');return;}
  }
  _ibRows=(_ibRows||[]).filter(r=>r.id!==id);_ibFull.delete(id);_ibPick.delete(id);
  if(_ibSelId===id){_ibSelId='';_ibEditing=null;}
  _ibSave();renderItemList();_ibRenderDetail();
  toast('휴지통으로 보냈어요');
}
// ── 바구니 (기기에만 둔다) ────────────────────────────────────────────────
function ibBasket(){try{return JSON.parse(localStorage.getItem(IB_BASKET_KEY)||'[]')||[];}catch(e){return [];}}
function _ibBasketSet(a){try{localStorage.setItem(IB_BASKET_KEY,JSON.stringify(a.slice(0,500)));}catch(e){}_ibPaintBasket();}
function ibInBasket(id){return ibBasket().indexOf(id)>=0;}
function ibBasketToggle(id,ev){
  if(ev)ev.stopPropagation();
  const b=ibBasket(),i=b.indexOf(id);
  if(i>=0)b.splice(i,1);else b.push(id);
  _ibBasketSet(b);renderItemList();
}
function ibBasketClear(){_ibBasketSet([]);renderItemList();toast('바구니를 비웠어요');}
function _ibPaintBasket(){
  const el=document.getElementById('ib-basket');if(!el)return;
  const n=ibBasket().length;
  el.innerHTML='🧺 바구니 '+n+'개'+(n?' <button class="ib-bx" onclick="event.stopPropagation();ibBasketClear()" title="비우기">×</button>':'');
  el.className='ib-basket'+(n?' on':'');
  el.onclick=n?(()=>pbOpen()):null;                 // 누르면 시험지 편집
  el.style.cursor=n?'pointer':'';
  el.title=n?'시험지 만들기':'';
}
// ── 거르기 ────────────────────────────────────────────────────────────────
function _ibSaveF(){try{localStorage.setItem(IB_F_KEY,JSON.stringify(_ibF));}catch(e){}}
function _ibLoadF(){try{const s=JSON.parse(localStorage.getItem(IB_F_KEY)||'null');if(s&&typeof s==='object')_ibF={..._ibF,...s};}catch(e){}}
function ibFilterChange(){
  const v=id=>{const el=document.getElementById(id);return el?el.value:'';};
  _ibF.skill=v('ib-f-skill');_ibF.type=v('ib-f-type');_ibF.grade=v('ib-f-grade');
  _ibF.diff=v('ib-f-diff');_ibF.src=v('ib-f-src');_ibF.tbId=v('ib-f-tb');_ibF.unit=v('ib-f-unit');
  _ibF.checked=v('ib-f-checked');_ibF.tag=v('ib-f-tag');_ibF.q=v('ib-f-q');
  const st=document.getElementById('ib-f-star');_ibF.star=!!(st&&st.checked);
  _ibDeepIds=null;_ibPage=1;_ibSaveF();_ibPaintUnits();renderItemList();
}
function ibResetFilters(){
  _ibF={skill:'',type:'',grade:'',diff:'',src:'',tbId:'',unit:'',checked:'',star:false,tag:'',q:''};
  _ibDeepIds=null;_ibPage=1;_ibSaveF();_ibPaintFilters();renderItemList();
}
function _ibTypeVals(){
  const used=new Set((_ibRows||[]).map(r=>String((r.meta||{}).type||'')).filter(Boolean));
  const out=[];
  Object.keys(ISO_TYPES).forEach(k=>{
    if(!used.has(k))return;
    if(_ibF.skill&&_ibSkillOf(k)!==_ibF.skill)return;
    out.push({v:k,n:ISO_TYPES[k].g+' · '+ISO_TYPES[k].n});
  });
  return out;
}
function _ibPaintUnits(){
  // 은행에 문항이 있는 교재만, 가나다·ABC 순 (교재가 300권이라 전부 띄우면 못 고른다)
  const used=new Set((_ibRows||[]).map(r=>String(((r.meta||{}).src||{}).tbId||'')).filter(Boolean));
  const tbs=(_cache.globalTextbooks||[]).filter(b=>b&&b.id&&used.has(b.id))
    .sort((a,b)=>String(a.title||'').localeCompare(String(b.title||''),'ko'));
  const sel=document.getElementById('ib-f-tb');
  if(sel)sel.style.display=tbs.length?'':'none';
  if(sel&&sel.options.length!==tbs.length+1)
    _ebOptsIb('ib-f-tb','교재 전체',tbs.map(b=>({v:b.id,n:b.title||'(제목 없음)'})),_ibF.tbId);
  else if(sel)sel.value=_ibF.tbId||'';
  const tb=tbs.find(b=>b.id===_ibF.tbId);
  const units=tb?Object.keys(tb.unitTexts||tb.units||{}):[];
  const ue=document.getElementById('ib-f-unit');
  if(ue){ue.style.display=units.length?'':'none';_ebOptsIb('ib-f-unit','단원 전체',units.map(u=>({v:u,n:u})),_ibF.unit);}
}
function _ebOptsIb(id,label,vals,cur){               // _ebOpts 와 같은 일 (문제 은행 칸용)
  const el=document.getElementById(id);if(!el)return;
  el.innerHTML=['<option value="">'+_ebE(label)+'</option>'].concat(vals.map(v=>
    '<option value="'+_ebA(v.v)+'"'+(String(cur)===String(v.v)?' selected':'')+'>'+_ebE(v.n)+'</option>')).join('');
}
function _ibPaintFilters(){
  const rows=_ibRows||[];
  _ebOptsIb('ib-f-skill','영역 전체',IB_SKILLS.filter(s=>rows.some(r=>_ibSkillRow(r)===s.k)).map(s=>({v:s.k,n:s.n})),_ibF.skill);
  _ebOptsIb('ib-f-type','유형 전체',_ibTypeVals(),_ibF.type);
  _ebOptsIb('ib-f-grade','학년 전체',IB_GRADES.filter(g=>rows.some(r=>(r.meta||{}).grade===g)).map(g=>({v:g,n:g})),_ibF.grade);
  _ebOptsIb('ib-f-diff','난도 전체',[1,2,3,4,5].map(d=>({v:d,n:'난도 '+d+' '+_ibDots(d)})),_ibF.diff);
  _ebOptsIb('ib-f-src','출처 전체',IB_SRCS.filter(s=>rows.some(r=>((r.meta||{}).src||{}).kind===s.k)).map(s=>({v:s.k,n:s.n})),_ibF.src);
  _ebOptsIb('ib-f-checked','검수 전체',[{v:'y',n:'검수함'},{v:'n',n:'검수 전'}],_ibF.checked);
  const tags=[...new Set(rows.flatMap(r=>((r.meta||{}).tags)||[]))].sort((a,b)=>a.localeCompare(b,'ko'));
  _ebOptsIb('ib-f-tag','태그 전체',tags.map(t=>({v:t,n:t})),_ibF.tag);
  const st=document.getElementById('ib-f-star');if(st)st.checked=!!_ibF.star;
  const q=document.getElementById('ib-f-q');if(q&&q.value!==_ibF.q)q.value=_ibF.q;
  _ibPaintUnits();_ibPaintBasket();
}
// 영역이 비어 있는 줄(앱 밖에서 넣은 행)은 유형으로 따진다
function _ibTypeLabel(m){return String((m&&m.typeName)||_isoTypeName(String((m&&m.type)||''))||(m&&m.type)||'');}
function _ibSkillRow(r){const m=(r&&r.meta)||{};return String(m.skill||_ibSkillOf(String(m.type||'')));}
function _ibDots(d){const n=Math.max(1,Math.min(5,Number(d)||3));return '●'.repeat(n)+'○'.repeat(5-n);}
function _ibMatch(r){
  const m=r.meta||{},s=m.src||{};
  if(_ibF.skill&&_ibSkillRow(r)!==_ibF.skill)return false;
  if(_ibF.type&&String(m.type||'')!==_ibF.type)return false;
  if(_ibF.grade&&String(m.grade||'')!==_ibF.grade)return false;
  if(_ibF.diff&&String(m.diff||'')!==String(_ibF.diff))return false;
  if(_ibF.src&&String(s.kind||'')!==_ibF.src)return false;
  if(_ibF.tbId&&String(s.tbId||'')!==_ibF.tbId)return false;
  if(_ibF.unit&&String(s.unit||'')!==_ibF.unit)return false;
  if(_ibF.checked==='y'&&!m.checked)return false;
  if(_ibF.checked==='n'&&m.checked)return false;
  if(_ibF.star&&!m.star)return false;
  if(_ibF.tag&&(m.tags||[]).indexOf(_ibF.tag)<0)return false;
  if(_ibDeepIds&&!_ibDeepIds.has(r.id))return false;
  const q=String(_ibF.q||'').trim().toLowerCase();
  if(q&&!_ibDeepIds){   // 본문까지 찾기를 켠 동안에는 서버가 고른 줄을 그대로 믿는다
    const hay=[m.stem,m.preview,(m.choices||[]).join(' '),(m.tags||[]).join(' '),s.exam,m.typeName].join(' ').toLowerCase();
    if(hay.indexOf(q)<0)return false;
  }
  return true;
}
function _ibFiltered(){
  return (_ibRows||[]).filter(_ibMatch).sort((a,b)=>{
    const am=a.meta||{},bm=b.meta||{};
    if(am.setId&&am.setId===bm.setId)return (am.setOrder||0)-(bm.setOrder||0);
    return (bm.editedAt||bm.createdAt||0)-(am.editedAt||am.createdAt||0);
  });
}
// 지문까지 찾기 — 목록 뷰에는 본문이 없으니 서버에 id 만 물어본다 (가볍다)
async function ibDeepSearch(){
  const q=String(_ibF.q||'').trim();
  if(q.length<2){toast('두 글자 이상 넣어 주세요');return;}
  const el=document.getElementById('ib-state');if(el)el.textContent='본문에서 찾는 중…';
  const enc=encodeURIComponent('*'+q.replace(/[*,()]/g,' ')+'*');
  const r=await _ebGet('item_bank?select=id&or=(data->>passage.ilike.'+enc+',data->>script.ilike.'+enc+',data->>explain.ilike.'+enc+')&limit=2000');
  if(!r.ok){if(el)el.textContent='';toast('본문 찾기에 실패했어요');return;}
  _ibDeepIds=new Set(r.rows.map(x=>x.id));
  _ibPage=1;renderItemList();_ibStampIb();
  toast('본문에서 '+_ibDeepIds.size+'개를 찾았어요');
}
// ── 목록 ──────────────────────────────────────────────────────────────────
function _ibSrcLabel(s){
  const k=(IB_SRCS.find(x=>x.k===(s&&s.kind))||{}).n||'직접';
  const bits=[k];
  if(s&&s.exam)bits.push(s.exam+(s.qno?(' '+s.qno+'번'):''));
  else if(s&&s.tbId){
    const tb=(_cache.globalTextbooks||[]).find(b=>b.id===s.tbId);
    bits.push((tb?tb.title:'교재')+(s.unit?(' '+s.unit):''));
  }
  if(s&&s.keep)bits.push('원문 지문');
  return bits.join(' · ');
}
// 같은 지문을 쓰는 문항(setId)은 한 카드로 접어 보여 준다 — 펼치면 문항별로 고칠 수 있다
function _ibGroups(rows){
  const out=[],by=new Map();
  rows.forEach(r=>{
    const sid=String((r.meta||{}).setId||'');
    if(!sid){out.push({set:'',rows:[r]});return;}
    if(by.has(sid)){by.get(sid).rows.push(r);return;}
    const g={set:sid,rows:[r]};by.set(sid,g);out.push(g);
  });
  return out;
}
function ibSetToggle(sid,ev){
  if(ev)ev.stopPropagation();
  if(_ibOpenSets.has(sid))_ibOpenSets.delete(sid);else _ibOpenSets.add(sid);
  renderItemList();
}
function ibSetBasket(sid,ev){
  if(ev)ev.stopPropagation();
  const rows=(_ibRows||[]).filter(r=>String((r.meta||{}).setId||'')===sid);
  const b=ibBasket(),allIn=rows.length&&rows.every(r=>b.indexOf(r.id)>=0);
  rows.forEach(r=>{const i=b.indexOf(r.id);if(allIn){if(i>=0)b.splice(i,1);}else if(i<0)b.push(r.id);});
  _ibBasketSet(b);renderItemList();
}
function _ibBadges(m){
  return '<span class="ib-tag">'+_ebE(_ibTypeLabel(m))+'</span>'+
    (m.grade?'<span class="ib-g">'+_ebE(m.grade)+'</span>':'')+
    '<span class="ib-dots" title="난도 '+(m.diff||3)+(m.diffSrc==='teacher'?' (선생님)':(m.diffSrc==='rate'?(' · 정답률 '+(m.rate||'')+'%'):''))+'">'+_ibDots(m.diff)+'</span>'+
    (m.checked?'<span class="ib-ok">검수</span>':'');
}
function _ibItemBtns(r,small){
  const m=r.meta||{},id=escJsA(r.id),inB=ibInBasket(r.id),c='ib-ic'+(small?' ib-ic-s':'');
  return '<button class="'+c+(m.star?' on':'')+'" title="별표" onclick="ibStar(\''+id+'\',event)">'+(m.star?'★':'☆')+'</button>'+
    '<button class="'+c+(inB?' on':'')+'" title="시험지 바구니에 담기" onclick="ibBasketToggle(\''+id+'\',event)">🧺</button>'+
    '<button class="'+c+'" title="복제" onclick="ibDup(\''+id+'\',event)">⧉</button>'+
    '<button class="'+c+'" title="비슷한 문항 만들기" onclick="ibSimilar(\''+id+'\',event)">✏️</button>'+
    '<button class="'+c+'" title="이 지문으로 학습 세트 만들기" onclick="lkFromItem(\''+id+'\',event)">📘</button>'+
    '<button class="'+c+' ib-ic-d" title="휴지통" onclick="ibTrash(\''+id+'\',event)">×</button>';
}
function _ibCardOne(r){
  const m=r.meta||{},id=escJsA(r.id);
  return '<div class="ib-card'+(_ibSelId===r.id?' on':'')+'" onclick="ibSelect(\''+id+'\')">'+
    '<div class="ib-c-h">'+
      '<input type="checkbox" class="ib-ck" '+(_ibPick.has(r.id)?'checked ':'')+'onclick="ibPick(\''+id+'\',event)">'+
      _ibBadges(m)+'<span style="flex:1"></span>'+_ibItemBtns(r)+
    '</div>'+
    '<div class="ib-stem">'+_ebE(m.stem||'(발문 없음)')+'</div>'+
    (m.preview?'<div class="ib-prev">'+_ebE(m.preview)+'</div>':'')+
    '<div class="ib-src">'+_ebE(_ibSrcLabel(m.src))+(m.words?(' · '+m.words+'단어'):'')+
      ((typeof ibUsedCount==='function'&&ibUsedCount(r.id))?(' · 사용 '+ibUsedCount(r.id)+'회'):'')+'</div>'+
  '</div>';
}
function _ibCardSet(g){
  const open=_ibOpenSets.has(g.set),sid=escJsA(g.set);
  const m=g.rows[0].meta||{};
  let h='<div class="ib-card ib-set'+(g.rows.some(r=>_ibSelId===r.id)?' on':'')+'" onclick="ibSetToggle(\''+sid+'\',event)">'+
    '<div class="ib-c-h">'+
      '<button class="ib-ic" title="'+(open?'접기':'펼치기')+'" onclick="ibSetToggle(\''+sid+'\',event)">'+(open?'▾':'▸')+'</button>'+
      _ibBadges(m)+
      '<span class="ib-set-n">한 지문 · 문항 '+g.rows.length+'개</span>'+
      '<span style="flex:1"></span>'+
      '<button class="ib-ic" title="묶음 전체 담기" onclick="ibSetBasket(\''+sid+'\',event)">🧺</button>'+
    '</div>'+
    (m.preview?'<div class="ib-prev">'+_ebE(m.preview)+'</div>':'')+
    '<div class="ib-src">'+_ebE(_ibSrcLabel(m.src))+(m.words?(' · '+m.words+'단어'):'')+'</div>';
  if(open){
    h+='<div class="ib-sub">'+g.rows.map((r,i)=>{
      const mm=r.meta||{},id=escJsA(r.id);
      return '<div class="ib-srow'+(_ibSelId===r.id?' on':'')+'" onclick="event.stopPropagation();ibSelect(\''+id+'\')">'+
        '<input type="checkbox" class="ib-ck" '+(_ibPick.has(r.id)?'checked ':'')+'onclick="ibPick(\''+id+'\',event)">'+
        '<span class="ib-sno">'+(mm.setOrder||(i+1))+'</span>'+
        '<span class="ib-sstem">'+_ebE(mm.stem||'(발문 없음)')+'</span>'+
        '<span class="ib-dots">'+_ibDots(mm.diff)+'</span>'+
        _ibItemBtns(r,true)+'</div>';
    }).join('')+'</div>';
  }else{
    h+='<div class="ib-stem">'+_ebE(m.stem||'(발문 없음)')+'</div>';
  }
  h+='</div>';
  return h;
}
function renderItemList(){
  const box=document.getElementById('ib-list');if(!box)return;
  const cnt=document.getElementById('ib-count');
  if(!ibMayUse()){box.innerHTML='<div class="eb-empty">선생님 화면에서만 보입니다.</div>';if(cnt)cnt.textContent='';return;}
  if(!_ibRows||!_ibRows.length){
    box.innerHTML='<div class="eb-empty">'+(_ibLoading?'문제 은행을 불러오는 중…':
      '아직 문항이 없습니다. <b>동형 문제</b>로 만들거나, <b>+ 문항 추가</b>·⋯ 메뉴의 <b>JSON 가져오기</b>로 넣어 주세요.')+'</div>';
    if(cnt)cnt.textContent='';_ibPaintBulk();return;
  }
  const all=_ibFiltered();
  if(cnt)cnt.textContent=all.length.toLocaleString()+'개'+(all.length!==_ibRows.length?(' / 전체 '+_ibRows.length.toLocaleString()+'개'):'');
  if(!all.length){box.innerHTML='<div class="eb-empty">조건에 맞는 문항이 없습니다.</div>';_ibPaintBulk();return;}
  const groups=_ibGroups(all),show=groups.slice(0,_ibPage*IB_PAGE);
  const shown=show.reduce((n,g)=>n+g.rows.length,0);
  let h=show.map(g=>(g.set&&g.rows.length>1)?_ibCardSet(g):_ibCardOne(g.rows[0])).join('');
  if(groups.length>show.length)
    h+='<div style="text-align:center;padding:12px"><button class="btn bo bsm" onclick="_ibPage++;renderItemList()">더 보기 ('+shown+' / '+all.length+')</button></div>';
  box.innerHTML=h;
  _ibPaintBulk();
}
function _ibStampIb(){
  const el=document.getElementById('ib-state');if(!el)return;
  if(_ibNote){el.textContent=_ibNote;return;}
  if(_ibDeepIds){el.textContent='본문 찾기 '+_ibDeepIds.size+'개';return;}
  if(!_ibAt){el.textContent='';return;}
  const mins=Math.max(0,Math.round((Date.now()-_ibAt)/60000));
  el.textContent=mins<1?'방금 최신화':(mins<60?mins+'분 전 최신화':Math.round(mins/60)+'시간 전 최신화');
}
// ── 여러 개 고르기 ────────────────────────────────────────────────────────
function ibPick(id,ev){
  if(ev)ev.stopPropagation();
  if(_ibPick.has(id))_ibPick.delete(id);else _ibPick.add(id);
  _ibPaintBulk();
}
function ibPickAll(){
  const all=_ibFiltered().slice(0,_ibPage*IB_PAGE);
  const every=all.every(r=>_ibPick.has(r.id));
  all.forEach(r=>{if(every)_ibPick.delete(r.id);else _ibPick.add(r.id);});
  renderItemList();
}
function ibPickClear(){_ibPick.clear();renderItemList();}
function _ibPaintBulk(){
  const el=document.getElementById('ib-bulk');if(!el)return;
  const n=_ibPick.size;
  el.style.display=n?'':'none';
  if(!n)return;
  el.innerHTML='<b>'+n+'개 선택</b>'+
    '<button class="btn bo bsm" onclick="ibBulkBasket()">🧺 담기</button>'+
    '<button class="btn bo bsm" onclick="ibBulkTag()">태그</button>'+
    '<select class="filter-sel" onchange="ibBulkDiff(this.value);this.value=\'\'">'+
      '<option value="">난도 바꾸기</option>'+[1,2,3,4,5].map(d=>'<option value="'+d+'">난도 '+d+'</option>').join('')+'</select>'+
    '<button class="btn bo bsm" onclick="ibPickAll()">보이는 것 모두</button>'+
    '<button class="btn bo bsm" onclick="ibPickClear()">선택 풀기</button>';
}
function ibBulkBasket(){
  const b=ibBasket();
  _ibPick.forEach(id=>{if(b.indexOf(id)<0)b.push(id);});
  _ibBasketSet(b);renderItemList();toast(_ibPick.size+'개를 바구니에 담았어요');
}
async function ibBulkTag(){
  const t=prompt('붙일 태그 (쉼표로 여러 개 — 예: 1학기중간, 어려움)');
  if(t===null)return;
  const tags=String(t).split(',').map(s=>s.trim()).filter(Boolean);
  if(!tags.length)return;
  await _ibBulkEdit(d=>{d.tags=[...new Set([...(d.tags||[]),...tags])];});
}
async function ibBulkDiff(v){
  const d=Number(v);if(!d)return;
  await _ibBulkEdit(x=>{x.diff=d;x.diffSrc='teacher';});
}
async function _ibBulkEdit(fn){
  const ids=[..._ibPick];let done=0;
  const el=document.getElementById('ib-state');
  for(const id of ids){
    if(el)el.textContent='고치는 중… '+(done+1)+'/'+ids.length;
    const d=await _ibFullRow(id);
    if(!d)continue;
    fn(d);
    if(await ibPutItem(d,true))done++;
  }
  renderItemList();_ibRenderDetail();_ibStampIb();
  toast(done+'개를 고쳤어요');
}
// ── 고른 문항 — 미리보기·고치기 ───────────────────────────────────────────
async function ibSelect(id){
  if(_ibEditT){clearTimeout(_ibEditT);_ibEditT=null;await _ibEditSave();}
  _ibSelId=id;_ibEditing=null;_ibEditState='';
  renderItemList();_ibRenderDetail('불러오는 중…');
  const d=await _ibFullRow(id);
  if(_ibSelId!==id)return;
  _ibEditing=d?JSON.parse(JSON.stringify(d)):null;
  _ibRenderDetail();
}
function ibCloseDetail(){_ibSelId='';_ibEditing=null;renderItemList();_ibRenderDetail();}
function _ibRenderDetail(msg){
  const box=document.getElementById('ib-detail');if(!box)return;
  if(msg){box.innerHTML='<div class="eb-empty">'+_ebE(msg)+'</div>';return;}
  const d=_ibEditing;
  if(!d){box.innerHTML='<div class="eb-empty">왼쪽에서 문항을 고르면 여기서 고칠 수 있어요.</div>';return;}
  const ed=(f,v,ph,ci)=>'<div class="iso-ed" contenteditable="true" data-ph="'+_ebA(ph||'')+'" '+
    'onblur="ibItemEdit(\''+f+'\',this'+(ci===undefined?'':(','+ci))+')">'+_ebE(v||'')+'</div>';
  let h='<div class="ib-d-h"><b>문항 고치기</b><span id="ib-estat" class="iso-stat">'+_ebE(_ibEditState)+'</span>'+
    '<span style="flex:1"></span><button class="iso-ic" title="닫기" onclick="ibCloseDetail()">×</button></div>';
  h+='<div class="ib-d-row">'+
    '<select class="filter-sel" onchange="ibItemMeta(\'grade\',this.value)">'+
      ['',...IB_GRADES].map(g=>'<option value="'+_ebA(g)+'"'+(String(d.grade||'')===g?' selected':'')+'>'+(g||'학년')+'</option>').join('')+'</select>'+
    '<select class="filter-sel" onchange="ibItemMeta(\'diff\',this.value)">'+
      [1,2,3,4,5].map(x=>'<option value="'+x+'"'+(Number(d.diff)===x?' selected':'')+'>난도 '+x+'</option>').join('')+'</select>'+
    '<label class="iso-chk"><input type="checkbox" '+(d.checked?'checked':'')+' onchange="ibItemMeta(\'checked\',this.checked)"> 검수함</label>'+
    '<label class="iso-chk"><input type="checkbox" '+(d.star?'checked':'')+' onchange="ibItemMeta(\'star\',this.checked)"> 별표</label>'+
  '</div>';
  h+='<div class="ib-d-row">'+
    '<select class="filter-sel" onchange="ibItemMeta(\'type\',this.value)">'+_ibTypeOptions(d.type)+'</select>'+
    (d.type?'<span class="iso-hint">'+_ebE(IB_SKILLS.filter(s=>s.k===d.skill).map(s=>s.n)[0]||'')+'</span>'
           :'<span class="pb-warn">유형을 골라 주세요</span>')+
  '</div>';
  h+='<div class="ib-d-row"><span class="iso-hint">'+_ebE(_ibTypeLabel(d))+' · '+_ebE(_ibSrcLabel(d.src))+
     (d.diffSrc?(' · 난도 '+({rate:'정답률',rule:'유형 규칙',teacher:'선생님'}[d.diffSrc]||d.diffSrc)):'')+'</span></div>';
  h+='<div class="iso-lbl">발문</div>'+ed('stem',d.stem,'발문');
  h+='<div class="iso-lbl">지문</div>'+ed('passage',d.passage,'지문');
  if(d.script)h+='<div class="iso-lbl">듣기 대본</div>'+ed('script',d.script,'대본');
  if(d.choices&&d.choices.length){
    h+='<div class="iso-lbl">선택지 <span class="iso-hint">— 번호를 누르면 정답</span></div><div class="iso-ch">'+
      d.choices.map((c,ci)=>'<div class="iso-chi'+(ci===d.answer?' on':'')+'">'+
        '<button class="iso-chn" onclick="ibItemAnswer('+ci+')">'+_isoCirc(ci)+'</button>'+ed('choice',c,'선택지',ci)+'</div>').join('')+'</div>';
  }else{
    h+='<div class="iso-lbl">모범 답안</div>'+ed('answerText',d.answerText,'모범 답안');
    h+='<div class="iso-lbl">채점 기준</div>'+ed('rubric',d.rubric,'채점 기준');
  }
  h+='<div class="iso-lbl">해설</div>'+ed('explain',d.explain,'해설');
  h+='<div class="iso-lbl">태그 <span class="iso-hint">— 쉼표로</span></div>'+ed('tags',(d.tags||[]).join(', '),'태그');
  h+='<div class="iso-lbl">메모</div>'+ed('note',d.note,'메모');
  h+='<div class="ib-d-row" style="margin-top:10px">'+
     '<button class="btn bo bsm" onclick="ibBasketToggle(\''+escJsA(d.id)+'\')">🧺 '+(ibInBasket(d.id)?'바구니에서 빼기':'바구니에 담기')+'</button>'+
     '<button class="btn bo bsm" onclick="ibSimilar(\''+escJsA(d.id)+'\')">✏️ 비슷한 문항 만들기</button>'+
     '<button class="btn bo bsm" onclick="_ibEditSave(true)">지금 저장</button></div>';
  box.innerHTML=h;
}
function ibItemEdit(field,el,ci){
  if(!_ibEditing)return;
  const val=String(el.innerText||'').replace(/ /g,' ').trim();
  if(field==='choice')_ibEditing.choices[ci]=val;
  else if(field==='tags')_ibEditing.tags=val.split(',').map(s=>s.trim()).filter(Boolean);
  else _ibEditing[field]=val;
  if(field==='passage')_ibEditing.words=val.trim()?val.trim().split(/\s+/).length:null;
  _ibEditLater();
}
function ibItemAnswer(ci){if(!_ibEditing)return;_ibEditing.answer=ci;_ibRenderDetail();_ibEditLater();}
function ibItemMeta(field,val){
  if(!_ibEditing)return;
  if(field==='type'){
    _ibEditing.type=String(val||'');
    _ibEditing.typeName=_isoTypeName(_ibEditing.type);
    _ibEditing.skill=_ibSkillOf(_ibEditing.type);
    _ibRenderDetail();
  }
  else if(field==='diff'){_ibEditing.diff=Number(val)||3;_ibEditing.diffSrc='teacher';}
  else if(field==='checked'||field==='star')_ibEditing[field]=!!val;
  else _ibEditing[field]=val;
  _ibEditLater();
}
function _ibEditLater(){                              // 고치면 1.5초 뒤 자동 저장
  if(_ibEditT)clearTimeout(_ibEditT);
  _ibEditSetState('저장 대기…');
  _ibEditT=setTimeout(()=>{_ibEditT=null;_ibEditSave();},1500);
}
function _ibEditSetState(s){
  _ibEditState=s||'';
  const el=document.getElementById('ib-estat');if(el)el.textContent=_ibEditState;
}
async function _ibEditSave(manual){
  if(_ibEditT){clearTimeout(_ibEditT);_ibEditT=null;}
  const d=_ibEditing;if(!d)return false;
  _ibEditSetState('저장 중…');
  const r=await ibPutItem(d,true);
  _ibEditSetState(r?((r==='device'?'기기에만 보관 ':'저장됨 ')+_isoHHMM()):'저장 실패');
  renderItemList();
  if(manual)toast(r?'저장했어요 ✓':'저장 실패 — 잠시 뒤 다시 해 주세요');
  return !!r;
}
// ── 카드 단추 ─────────────────────────────────────────────────────────────
async function ibStar(id,ev){
  if(ev)ev.stopPropagation();
  const d=await _ibFullRow(id);if(!d)return;
  d.star=!d.star;
  await ibPutItem(d,true);
  if(_ibSelId===id&&_ibEditing)_ibEditing.star=d.star;
  renderItemList();_ibRenderDetail();
}
async function ibDup(id,ev){
  if(ev)ev.stopPropagation();
  const d=await _ibFullRow(id);if(!d)return;
  const copy=_ibNorm({...JSON.parse(JSON.stringify(d)),id:uid(),checked:false,
    createdAt:Date.now(),editedAt:Date.now(),note:(d.note||'')});
  copy.src={...copy.src,isoFrom:d.id};
  const r=await ibPutItem(copy,true);
  if(!r){toast('복제 실패');return;}
  renderItemList();ibSelect(copy.id);
  toast('복제했어요 — 새 문항을 고쳐 주세요');
}
// 동형 탭으로 원본 글을 넘긴다 (AI 는 거기서 단추를 눌러야 돈다)
async function ibSimilar(id,ev){
  if(ev)ev.stopPropagation();
  const d=await _ibFullRow(id);if(!d)return;
  const txt=[d.stem,'',d.passage||d.script||'',''].concat((d.choices||[]).map((c,i)=>_isoCirc(i)+' '+c)).join('\n').trim();
  isoNew();
  _isoCfg.type=d.type||'';_isoCfg.grade=d.grade||_isoCfg.grade;
  _isoInfo={title:(d.src&&d.src.exam)||'',cat:'',grade:d.grade||''};
  _isoCfg.qno=(d.src&&d.src.qno)||'';
  swTab('t-data');switchDataTab('iso');
  const t=document.getElementById('iso-text');
  if(t){t.value=txt;isoTextChange();}
  _isoPaintCfg();
  toast('원본을 동형 탭으로 옮겼어요 — [동형 문제 만들기]를 눌러 주세요');
}
// ── 문항 추가 (AI 없음) ───────────────────────────────────────────────────
function ibAddManual(){
  const d=_ibNorm({id:uid(),type:_ibF.type||'',grade:_ibF.grade||'고1',
    stem:'',passage:'',choices:['','','','',''],answer:0,src:{kind:'manual'}});
  _ibSelId=d.id;_ibEditing=d;_ibEditState='아직 저장 전';
  _ibRenderDetail();
  const box=document.getElementById('ib-detail');
  if(box){
    const pane=document.createElement('div');
    pane.className='ib-paste';
    pane.innerHTML='<div class="iso-lbl">붙여넣어 채우기 <span class="iso-hint">— 발문 / 지문 / ① ② ③ / 정답: 3 / 해설: …</span></div>'+
      '<textarea id="ib-paste" class="iso-text" rows="5" placeholder="문항을 통째로 붙여넣고 아래 단추를 누르세요"></textarea>'+
      '<div class="ib-d-row"><button class="btn bt bsm" onclick="ibParsePaste()">칸 채우기</button>'+
      '<span class="iso-hint">AI 를 부르지 않고 글만 나눕니다</span></div>';
    box.insertBefore(pane,box.children[2]||null);
  }
  renderItemList();
}
// 붙여넣은 글을 칸으로 나눈다 (규칙만 — AI 없음)
function ibParsePaste(){
  const ta=document.getElementById('ib-paste');if(!ta||!_ibEditing)return;
  const lines=String(ta.value||'').split(/\r?\n/);
  const circ='①②③④⑤⑥⑦';
  const stem=[],pass=[],ch=[];let ans=-1,exp='',mode='stem';
  lines.forEach(raw=>{
    const l=String(raw||'').trim();
    if(!l){if(mode==='stem'&&stem.length)mode='pass';return;}
    const ci=circ.indexOf(l.charAt(0));
    const mnum=l.match(/^([1-5])[).]\s+/);
    if(ci>=0){ch[ci]=l.slice(1).trim();mode='ch';return;}
    if(mnum&&mode!=='stem'){ch[Number(mnum[1])-1]=l.replace(/^([1-5])[).]\s+/,'').trim();mode='ch';return;}
    const ma=l.match(/^(정답|답)\s*[:：]?\s*([①-⑦1-5])/);
    if(ma){const c=circ.indexOf(ma[2]);ans=(c>=0?c:(Number(ma[2])-1));return;}
    const me=l.match(/^(해설|풀이)\s*[:：]?\s*(.*)$/);
    if(me){exp=me[2]||'';mode='exp';return;}
    if(mode==='exp'){exp+=(exp?'\n':'')+l;return;}
    if(mode==='stem'&&!stem.length){stem.push(l);mode='pass';return;}
    if(mode==='ch')return;
    pass.push(l);
  });
  const d=_ibEditing;
  if(stem.length)d.stem=stem.join(' ');
  if(pass.length)d.passage=pass.join('\n');
  const got=ch.filter(x=>x!==undefined&&String(x).trim());
  if(got.length){d.choices=ch.map(x=>String(x||''));}
  if(ans>=0)d.answer=ans;
  if(exp)d.explain=exp;
  d.words=String(d.passage||'').trim()?d.passage.trim().split(/\s+/).length:null;
  let guessed='';
  if(!d.type){                                       // 발문으로 유형을 찍어 준다 (규칙만)
    const g=_ibGuessType(d.stem);
    if(g){d.type=g;d.typeName=_isoTypeName(g);d.skill=_ibSkillOf(g);guessed=ISO_TYPES[g].n;}
  }
  _ibRenderDetail();
  toast('칸을 채웠어요'+(guessed?(' · 유형은 「'+guessed+'」로 찍어 뒀어요'):' — 유형을 골라 주세요')+
    ' — 확인하고 [지금 저장]을 눌러 주세요');
}
// ── JSON 가져오기 (Aside 가 만든 문항 파일) ───────────────────────────────
// 가져오기 — 기본은 '새 문항만', 고르면 '같은 id 덮어쓰기'.
// 덮어쓰기를 골라도 선생님이 손댄 문항(검수함·난도를 직접 고침·만든 뒤 고친 적 있음)은 건드리지 않는다.
let _ibImportMode='skip';
function ibImportPick(mode){
  _ibMenuOut();
  _ibImportMode=(mode==='over')?'over':'skip';
  const f=document.getElementById('ib-import-file');if(f)f.click();
}
function _ibTeacherTouched(m){
  if(!m)return false;
  return !!m.checked||m.diffSrc==='teacher'||(Number(m.editedAt||0)>Number(m.createdAt||0));
}
async function ibImportFile(ev){
  const f=(ev&&ev.target&&ev.target.files&&ev.target.files[0])||null;
  if(ev&&ev.target)ev.target.value='';
  if(!f)return;
  if(!ibMayUse()){toast('선생님 화면에서만 쓸 수 있어요');return;}
  try{
    const raw=JSON.parse(await f.text());
    const arr=Array.isArray(raw)?raw:(Array.isArray(raw&&raw.items)?raw.items:null);
    if(!arr||!arr.length){toast('문항 배열이 없는 파일이에요');return;}
    const byId=new Map((_ibRows||[]).map(r=>[r.id,r.meta||{}]));
    const over=(_ibImportMode==='over');
    const now=Date.now();
    const put=[];let nNew=0,nOver=0,nSkip=0,nKeep=0;
    arr.forEach(x=>{
      const d=_ibNorm(x,now);
      const m=byId.get(d.id);
      if(!m){byId.set(d.id,{});put.push(d);nNew++;return;}
      if(!over){nSkip++;return;}
      if(_ibTeacherTouched(m)){nSkip++;nKeep++;return;}   // 선생님이 손댄 문항은 지킨다
      d.createdAt=Number(m.createdAt)||d.createdAt;       // 처음 만든 때는 그대로
      put.push(d);nOver++;
    });
    if(!put.length){
      toast('넣을 문항이 없어요 — '+nSkip+'개 건너뜀'+(nKeep?(' (손댄 문항 '+nKeep+'개 보호)'):''));
      return;
    }
    askConfirm('문항 가져오기',
      (over?'같은 id 는 덮어씁니다.\n':'같은 id 는 건너뜁니다.\n')+
      '새로 넣음 '+nNew+' · 덮어씀 '+nOver+' · 건너뜀 '+nSkip+(nKeep?(' (손댄 문항 '+nKeep+'개 보호)'):'')+'\n'+
      '200개씩 나눠 올립니다. 정답은 0부터(① = 0) 셉니다.',
      '넣기','bt',()=>_ibImportGo(put,{nNew:nNew,nOver:nOver,nSkip:nSkip,nKeep:nKeep}));
  }catch(e){toast('읽지 못했어요: '+((e&&e.message)||''));}
}
async function _ibImportGo(list,c){
  const el=document.getElementById('ib-state');
  let done=0;
  for(let i=0;i<list.length;i+=200){                 // 200개씩 나눠 올린다
    const part=list.slice(i,i+200);
    if(el)el.textContent='올리는 중… '+(i+part.length)+'/'+list.length;
    const ok=await _ibBulkUpsert(part).catch(()=>false);
    if(!ok){toast('올리다 멈췄어요 — '+done+'개까지 들어갔습니다');break;}
    done+=part.length;
    part.forEach(d=>{_ibFull.set(d.id,d);_ibMerge(_ibLightOf(d,d.id));});
  }
  _ibPaintFilters();renderItemList();_ibStampIb();
  const msg='새로 넣음 '+c.nNew+' · 덮어씀 '+c.nOver+' · 건너뜀 '+c.nSkip+
    (c.nKeep?(' (손댄 문항 '+c.nKeep+'개 보호)'):'');
  toast(done===list.length?msg:(msg+' — '+done+'개까지 들어갔습니다'));
}
